import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for smooth_l1_loss with mean reduction
smooth_l1_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For fabsf

// CUDA kernel to compute the sum of Huber losses across all elements.
// Uses shared memory for block-wise reduction and atomicAdd for global sum.
__global__ void smooth_l1_loss_sum_kernel(const float* predictions, const float* targets, float* global_sum_ptr, int size, float beta) {
    // Declare shared memory for block-wise sum. Size is passed dynamically.
    extern __shared__ float s_sum[]; 

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float local_loss = 0.0f;

    if (idx < size) {
        float diff = predictions[idx] - targets[idx];
        float abs_diff = fabsf(diff); // Use fabsf for float absolute value

        if (abs_diff < beta) {
            local_loss = 0.5f * diff * diff;
        } else {
            local_loss = beta * abs_diff - 0.5f * beta * beta;
        }
    }

    // Store local_loss in shared memory
    s_sum[threadIdx.x] = local_loss;
    __syncthreads(); // Ensure all threads in block have written to shared memory

    // Perform reduction within the block using a parallel reduction pattern
    // This loop sums elements in shared memory
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each step of reduction
    }

    // The first thread of the block atomically adds the block's sum to the global sum
    if (threadIdx.x == 0) {
        atomicAdd(global_sum_ptr, s_sum[0]);
    }
}

// A tiny CUDA kernel to perform the final division on the GPU.
// This ensures the entire mean calculation is done on the device.
__global__ void divide_by_size_kernel(float* sum_ptr, int size) {
    // Only the first thread needs to perform this operation
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        *sum_ptr = *sum_ptr / size;
    }
}

// C++ wrapper function to expose the CUDA kernels to PyTorch
torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float beta) {
    // Input validation and device checks
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "predictions and targets must have the same shape");
    TORCH_CHECK(predictions.dtype() == torch::kFloat32, "predictions must be float32");
    TORCH_CHECK(targets.dtype() == torch::kFloat32, "targets must be float32");

    // Ensure tensors are contiguous for direct pointer access
    predictions = predictions.contiguous();
    targets = targets.contiguous();

    auto size = predictions.numel();

    // Create a scalar tensor on the GPU to store the global sum, initialized to 0.
    // This tensor will eventually hold the final mean loss.
    auto global_sum_tensor = torch::zeros({1}, predictions.options());

    // Define block and grid dimensions
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Launch the kernel to compute the sum of Huber losses
    // The third argument specifies the dynamic shared memory size in bytes.
    smooth_l1_loss_sum_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        global_sum_tensor.data_ptr<float>(),
        size,
        beta
    );

    // Launch a tiny kernel to perform the final division (sum / size) on the GPU.
    // This ensures the entire mean calculation is completed on the device.
    // We launch it with 1 block and 1 thread as it's a single operation on a scalar.
    divide_by_size_kernel<<<1, 1>>>(global_sum_tensor.data_ptr<float>(), size);

    // Return the tensor which now contains the mean smooth L1 loss.
    return global_sum_tensor;
}
"""

smooth_l1_loss_cpp_source = (
    "torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float beta);"
)

# Compile the inline CUDA code for smooth_l1_loss
smooth_l1_loss_custom = load_inline(
    name="smooth_l1_loss_custom",
    cpp_sources=smooth_l1_loss_cpp_source,
    cuda_sources=smooth_l1_loss_source,
    functions=["smooth_l1_loss_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    A model that computes Smooth L1 (Huber) Loss for regression tasks,
    optimized with a custom CUDA kernel replacing torch.nn.functional.smooth_l1_loss.
    The custom kernel implements 'mean' reduction by default.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the compiled custom CUDA function as a member
        self.smooth_l1_loss_cuda_op = smooth_l1_loss_custom.smooth_l1_loss_cuda
        # Default beta value for smooth_l1_loss, matching PyTorch's default
        self.beta = 1.0 

    def forward(self, predictions, targets):
        # Call the custom CUDA kernel to compute the smooth L1 loss with mean reduction
        return self.smooth_l1_loss_cuda_op(predictions, targets, self.beta)

