import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 2D Convolution
conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max

// Helper for calculating output dimensions
// H_out = floor((H_in + 2 * padding - K_H) / stride) + 1
inline int calculate_output_dim(int input_dim, int kernel_dim, int padding, int stride) {
    return (input_dim + 2 * padding - kernel_dim) / stride + 1;
}

__global__ void conv2d_kernel(
    const float* input,
    const float* weights,
    const float* bias,
    float* output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K_H, int K_W,
    int stride, int padding,
    int H_out, int W_out,
    long total_output_elements,
    bool use_bias) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map flat index to (n, c_out, h_out, w_out)
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out * H_out)) % C_out;
        int n = idx / (W_out * H_out * C_out);

        float sum = 0.0f;

        // Loop over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Loop over kernel dimensions
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate effective input coordinates
                    int h_in_eff = h_out * stride - padding + k_h;
                    int w_in_eff = w_out * stride - padding + k_w;

                    // Check boundary conditions (padding)
                    if (h_in_eff >= 0 && h_in_eff < H_in &&
                        w_in_eff >= 0 && w_in_eff < W_in) {

                        // Input tensor index: (N, C_in, H_in, W_in)
                        long input_idx = (long)n * C_in * H_in * W_in +
                                         (long)c_in * H_in * W_in +
                                         (long)h_in_eff * W_in +
                                         (long)w_in_eff;

                        // Weights tensor index: (C_out, C_in, K_H, K_W)
                        long weights_idx = (long)c_out * C_in * K_H * K_W +
                                           (long)c_in * K_H * K_W +
                                           (long)k_h * K_W +
                                           (long)k_w;

                        sum += input[input_idx] * weights[weights_idx];
                    }
                }
            }
        }

        // Add bias if enabled
        if (use_bias) {
            sum += bias[c_out];
        }

        // Output tensor index: (N, C_out, H_out, W_out)
        long output_idx = (long)n * C_out * H_out * W_out +
                           (long)c_out * H_out * W_out +
                           (long)h_out * W_out +
                           (long)w_out;
        output[output_idx] = sum;
    }
}

torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weights,
    torch::Tensor bias, // Bias tensor (can be undefined if no bias)
    int stride,
    int padding) {

    // Ensure input and weights are on CUDA and are float32
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor.");
    TORCH_CHECK(weights.is_cuda(), "Weights must be a CUDA tensor.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(weights.is_contiguous(), "Weights tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input must be float32.");
    TORCH_CHECK(weights.dtype() == torch::kFloat32, "Weights must be float32.");

    bool use_bias = bias.defined(); // Check if bias tensor is provided
    if (use_bias) {
        TORCH_CHECK(bias.is_cuda(), "Bias must be a CUDA tensor if provided.");
        TORCH_CHECK(bias.is_contiguous(), "Bias tensor must be contiguous if provided.");
        TORCH_CHECK(bias.dtype() == torch::kFloat32, "Bias must be float32 if provided.");
    }

    // Get dimensions from input and weights tensors
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weights.size(0);
    int K_H = weights.size(2);
    int K_W = weights.size(3);

    // Check weight dimensions consistency
    TORCH_CHECK(weights.size(1) == C_in, "Weights in_channels must match input in_channels.");
    if (use_bias) {
        TORCH_CHECK(bias.numel() == C_out, "Bias numel must match weights out_channels.");
    }

    // Calculate output dimensions
    int H_out = calculate_output_dim(H_in, K_H, padding, stride);
    int W_out = calculate_output_dim(W_in, K_W, padding, stride);

    // Create output tensor on the same device and with the same dtype as input
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    long total_output_elements = (long)N * C_out * H_out * W_out;

    // Define block size and calculate number of blocks for kernel launch
    const int block_size = 256; 
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Get bias data pointer, or nullptr if not used (kernel handles nullptr with use_bias flag)
    const float* bias_ptr = use_bias ? bias.data_ptr<float>() : nullptr;

    // Launch the CUDA kernel
    conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weights.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K_H, K_W,
        stride, padding,
        H_out, W_out,
        total_output_elements,
        use_bias);

    // Check for any CUDA errors that occurred during kernel execution
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
"""

# C++ source for the Python binding
conv2d_cpp_source = (
    "torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weights, torch::Tensor bias, int stride, int padding);"
)

# Compile the inline CUDA code for 2D convolution
# This will create a Python module that exposes the `conv2d_cuda` function.
custom_conv2d_module = load_inline(
    name="custom_conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=True, # Set to False to suppress compilation output
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Instantiate the original Conv2d layer to get its initialized parameters
        # and configuration. We will extract these and use them with our custom kernel.
        original_conv = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

        # Store the parameters (weights and bias) and configuration (stride, padding)
        # Ensure weights and bias are on the CUDA device.
        self.weights = original_conv.weight.data.clone().cuda()

        # Handle bias: if it exists, clone and move to CUDA; otherwise, create an empty tensor.
        # An empty tensor will cause `bias.defined()` to return false in the C++ code.
        self.bias = original_conv.bias.data.clone().cuda() if original_conv.bias is not None else torch.empty(0, device='cuda', dtype=torch.float32)

        # Assuming square kernel, stride, and padding as per the example architecture.
        # If they were non-square (e.g., (H, W)), we would need to store both dimensions.
        self.stride = original_conv.stride[0]
        self.padding = original_conv.padding[0]

        # Store the compiled custom CUDA module
        self.custom_conv2d = custom_conv2d_module

    def forward(self, x):
        # Ensure input tensor is on the CUDA device before passing to the kernel
        x = x.cuda()

        # Call the custom CUDA convolution function.
        # The `custom_conv2d_module` object has the `conv2d_cuda` function as an attribute.
        return self.custom_conv2d.conv2d_cuda(x, self.weights, self.bias, self.stride, self.padding)

