import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for basic matrix multiplication C = A * B
// Each thread computes one element of the output matrix C.
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Calculate the global row and column for the current thread
    // Using a 2D grid for M x N output matrix
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Check bounds to ensure threads don't go out of range
    if (row < M && col < N) {
        float sum = 0.0f;
        // Compute the dot product of A's row and B's column
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors.");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D tensors.");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32 tensors.");
    // For simplicity, we assume contiguous memory layout.
    // In a real-world scenario, you might want to handle non-contiguous tensors
    // by either making them contiguous or adjusting indexing.
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "Inputs must be contiguous.");

    int M = A.size(0);
    int K = A.size(1);
    int K_B = B.size(0); // K dimension for B
    int N = B.size(1);

    TORCH_CHECK(K == K_B, "Matrix dimensions incompatible for multiplication: A.size(1) != B.size(0)");

    // Create output tensor C with the same device and dtype as A
    auto C = torch::zeros({M, N}, A.options());

    // Define block and grid dimensions
    // A common block size for 2D operations is 16x16 or 32x32
    const int BLOCK_SIZE_X = 16; // Threads per block in X-dimension
    const int BLOCK_SIZE_Y = 16; // Threads per block in Y-dimension

    dim3 block_size(BLOCK_SIZE_X, BLOCK_SIZE_Y);

    // Calculate grid dimensions
    // Each block processes a BLOCK_SIZE_Y x BLOCK_SIZE_X tile of the output matrix C
    dim3 num_blocks(
        (N + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, // Number of blocks in X-dimension (for columns)
        (M + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y  // Number of blocks in Y-dimension (for rows)
    );

    // Launch the CUDA kernel
    matmul_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K
    );

    return C;
}
"""

# C++ header for the wrapper function
matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Compile the inline CUDA code for matrix multiplication
matmul_op = load_inline(
    name="matmul_custom",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add some optimization flags
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the loaded custom operator as a member
        self.matmul_custom_op = matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication of A and B using the custom CUDA kernel.

        Args:
            A: Input tensor of shape (M, K)
            B: Input tensor of shape (K, N)

        Returns:
            Output tensor of shape (M, N)
        """
        return self.matmul_custom_op.matmul_cuda(A, B)

