import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused BatchNorm (inference mode)
fused_batchnorm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

// CUDA kernel for fused BatchNorm in inference mode
// Applies: y = (x - running_mean) / sqrt(running_var + eps) * gamma + beta
__global__ void fused_batchnorm_kernel(
    const float* x_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    const float* running_mean_ptr,
    const float* running_var_ptr,
    float* out_ptr,
    float eps,
    int N, int C, int H, int W) {

    // Calculate total number of elements
    int total_elements = N * C * H * W;

    // Global index for the current thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate channel index 'c' for the current element
        // The input tensor is flattened, so we need to map the flat index back to (n, c, h, w)
        // For NCHW layout, the channel index for a flattened index `idx` is:
        // c = (idx / (H * W)) % C;
        int c_idx = (idx / (H * W)) % C;

        // Get per-channel parameters
        float mean_c = running_mean_ptr[c_idx];
        float var_c = running_var_ptr[c_idx];
        float gamma_c = gamma_ptr[c_idx];
        float beta_c = beta_ptr[c_idx];

        // Apply the BatchNorm formula
        float val = x_ptr[idx];
        float normalized_val = (val - mean_c) / sqrtf(var_c + eps);
        out_ptr[idx] = normalized_val * gamma_c + beta_c;
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor fused_batchnorm_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps) {

    // Ensure inputs are on CUDA and are float32
    TORCH_CHECK(x.is_cuda(), "Input x must be a CUDA tensor.");
    TORCH_CHECK(gamma.is_cuda(), "Gamma must be a CUDA tensor.");
    TORCH_CHECK(beta.is_cuda(), "Beta must be a CUDA tensor.");
    TORCH_CHECK(running_mean.is_cuda(), "Running mean must be a CUDA tensor.");
    TORCH_CHECK(running_var.is_cuda(), "Running variance must be a CUDA tensor.");

    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input x must be float32.");
    TORCH_CHECK(gamma.dtype() == torch::kFloat32, "Gamma must be float32.");
    TORCH_CHECK(beta.dtype() == torch::kFloat32, "Beta must be float32.");
    TORCH_CHECK(running_mean.dtype() == torch::kFloat32, "Running mean must be float32.");
    TORCH_CHECK(running_var.dtype() == torch::kFloat32, "Running variance must be float32.");

    // Ensure x is contiguous for direct pointer access
    // The other parameters (gamma, beta, running_mean, running_var) are typically contiguous
    // as they are 1D tensors managed by BatchNorm.
    x = x.contiguous();

    // Get dimensions
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int total_elements = N * C * H * W;

    // Create output tensor with the same properties as x
    auto out = torch::empty_like(x);

    // Define block and grid dimensions
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the kernel
    fused_batchnorm_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        out.data_ptr<float>(),
        (float)eps, // Cast double eps to float for the kernel
        N, C, H, W
    );

    // Check for CUDA errors after kernel launch
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
}
"""

fused_batchnorm_cpp_source = (
    "torch::Tensor fused_batchnorm_cuda("
    "torch::Tensor x, "
    "torch::Tensor gamma, "
    "torch::Tensor beta, "
    "torch::Tensor running_mean, "
    "torch::Tensor running_var, "
    "double eps);"
)

# Compile the inline CUDA code for fused BatchNorm
# verbose=True will print compilation output, useful for debugging
fused_batchnorm_module = load_inline(
    name="fused_batchnorm",
    cpp_sources=fused_batchnorm_cpp_source,
    cuda_sources=fused_batchnorm_source,
    functions=["fused_batchnorm_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # General optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization and fast math for CUDA compiler
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Batch Normalization using a custom CUDA kernel
    for the inference path. Falls back to PyTorch's implementation for training.
    """
    def __init__(self, num_features: int):
        """
        Initializes the BatchNorm layer and loads the custom CUDA kernel.

        Args:
            num_features (int): Number of features in the input tensor.
        """
        super(ModelNew, self).__init__()
        # We keep the original BatchNorm2d layer to manage its parameters (weight, bias)
        # and running statistics (running_mean, running_var, num_batches_tracked).
        # This ensures proper initialization, state management, and allows for
        # PyTorch's native implementation during training.
        self.bn = nn.BatchNorm2d(num_features=num_features)
        # Store a reference to the compiled custom CUDA function
        self.fused_batchnorm_cuda = fused_batchnorm_module.fused_batchnorm_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Batch Normalization to the input tensor.
        Uses a custom CUDA kernel if in evaluation mode, otherwise falls back to PyTorch's.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, num_features, *).
                              Expected to be on CUDA and float32.

        Returns:
            torch.Tensor: Output tensor with Batch Normalization applied, same shape as input.
        """
        if self.bn.training:
            # In training mode, BatchNorm calculates batch statistics and updates
            # running statistics. This involves complex reduction operations and
            # state updates that are highly optimized in PyTorch (often via cuDNN).
            # Reimplementing this efficiently in a simple custom kernel is challenging
            # and likely slower than the native PyTorch implementation.
            # Therefore, we fall back to PyTorch's native BatchNorm for training.
            return self.bn(x)
        else:
            # In evaluation mode, BatchNorm uses its stored running_mean and running_var.
            # This allows for a straightforward operator fusion of the normalization
            # formula into a single CUDA kernel, potentially offering speedups.

            # Ensure input tensor is on CUDA and contiguous.
            # The custom kernel expects CUDA tensors and contiguous memory layout.
            # If x is already CUDA and contiguous, this is a no-op.
