# Define the custom CUDA kernel for row-wise softmax
custom_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// CUDA kernel for row-wise softmax
// Each block processes one row (batch element)
__global__ void softmax_kernel(const float* input, float* output, int batch_size, int dim) {
    int row_idx = blockIdx.x;

    if (row_idx >= batch_size) {
        return;
    }

    // Pointers for the current row in global memory
    const float* row_input = input + row_idx * dim;
    float* row_output = output + row_idx * dim;

    // Shared memory for reduction (max and sum_exp)
    // Declared as extern to allow dynamic sizing at kernel launch
    extern __shared__ float s_data[]; 

    // Partition shared memory for max and sum_exp reductions
    float* s_max = s_data;
    float* s_sum_exp = s_data + blockDim.x;

    // Step 1: Find max value in the row for numerical stability
    // Each thread processes multiple elements in the row
    float max_val_thread = -FLT_MAX; // Initialize with smallest possible float
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        max_val_thread = fmaxf(max_val_thread, row_input[i]);
    }

    // Store thread's local max_val in shared memory
    s_max[threadIdx.x] = max_val_thread;
    __syncthreads(); // Synchronize to ensure all local maxes are written

    // Parallel reduction for finding the global max within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_max[threadIdx.x] = fmaxf(s_max[threadIdx.x], s_max[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The maximum for the entire row is now in s_max[0]
    float row_max = s_max[0];

    // Step 2: Compute sum of exponentials (after subtracting max for stability)
    // Each thread processes multiple elements
    float sum_exp_thread = 0.0f;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        sum_exp_thread += expf(row_input[i] - row_max);
    }

    // Store thread's local sum_exp in shared memory
    s_sum_exp[threadIdx.x] = sum_exp_thread;
    __syncthreads(); // Synchronize to ensure all local sums are written

    // Parallel reduction for finding the global sum of exponentials within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum_exp[threadIdx.x] = s_sum_exp[threadIdx.x] + s_sum_exp[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The sum of exponentials for the entire row is now in s_sum_exp[0]
    float row_sum_exp = s_sum_exp[0];

    // Step 3: Compute the final softmax output
    // Each thread processes multiple elements
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        row_output[i] = expf(row_input[i] - row_max) / row_sum_exp;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor custom_softmax_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(input.dim() == 2, "Input tensor must be 2D (batch_size, dim).");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous."); // Ensure contiguous for direct pointer access

    int batch_size = input.size(0);
    int dim = input.size(1);

    // Create an output tensor on the same device as input
    auto output = torch::empty_like(input);

    // Define kernel launch parameters
    const int block_size = 256; // Number of threads per block (can be tuned)
    const int num_blocks = batch_size; // One block per row

    // Calculate shared memory size needed for reductions:
    // 2 arrays of floats, each of size block_size (for s_max and s_sum_exp)
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    // Launch the CUDA kernel
    softmax_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        dim
    );

    // Check for any CUDA errors that occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
"""

# C++ header for the custom CUDA function
custom_softmax_cpp_source = (
    "torch::Tensor custom_softmax_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code
