import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Layer Normalization
layernorm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For rsqrtf

__global__ void layernorm_kernel(
    const float* x_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int N, // total number of elements in the normalized dimensions
    int num_groups, // number of independent normalization groups (e.g., batch size)
    float eps) {

    // Each block processes one normalization group
    int group_idx = blockIdx.x;
    if (group_idx >= num_groups) {
        return;
    }

    // Offset to the start of the current group in the input/output tensors
    const float* current_x = x_ptr + group_idx * N;
    float* current_out = out_ptr + group_idx * N;

    // Shared memory for reduction: s_sum and s_sum_sq
    // Declared as extern to allow dynamic sizing based on `shared_mem_size` in kernel launch
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x; // s_sum_sq starts after s_sum

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Phase 1: Compute sum and sum of squares for elements processed by this thread
    // Each thread processes multiple elements if N > blockDim.x
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float val = current_x[i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    // Store thread-local sums in shared memory
    s_sum[threadIdx.x] = thread_sum;
    s_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads(); // Ensure all threads have written their sums to shared memory

    // Phase 2: Perform parallel reduction in shared memory to get block-wide totals
    // This loop performs a tree reduction
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Only thread 0 has the final sum and sum_sq for the block
    // Calculate mean and inverse standard deviation
    __shared__ float s_mean_val;
    __shared__ float s_inv_std_val;

    if (threadIdx.x == 0) {
        float block_mean = s_sum[0] / N;
        float block_variance = (s_sum_sq[0] / N) - (block_mean * block_mean);
        // Ensure variance is non-negative due to potential floating point inaccuracies
        if (block_variance < 0.0f) {
            block_variance = 0.0f;
        }
        s_mean_val = block_mean;
        s_inv_std_val = rsqrtf(block_variance + eps); // rsqrtf is faster than 1.0f / sqrtf
    }
    __syncthreads(); // Ensure s_mean_val and s_inv_std_val are visible to all threads

    // Phase 3: Normalize and apply affine transformation
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float val = current_x[i];
        float normalized_val = (val - s_mean_val) * s_inv_std_val;

        // Apply gamma and beta if they exist
        // gamma_ptr and beta_ptr can be nullptr if elementwise_affine is False
        float gamma_val = (gamma_ptr != nullptr) ? gamma_ptr[i] : 1.0f;
        float beta_val = (beta_ptr != nullptr) ? beta_ptr[i] : 0.0f;

        current_out[i] = gamma_val * normalized_val + beta_val;
    }
}

torch::Tensor layernorm_cuda_forward(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    int N_dim) { // N_dim is the product of normalized_shape dimensions

    // Ensure inputs are on CUDA and are float
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");

    // Gamma and beta are optional (if elementwise_affine=False)
    // Check if they are defined before accessing properties
    const float* gamma_ptr = nullptr;
    if (gamma.defined()) {
        TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
        TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
        TORCH_CHECK(gamma.dtype() == torch::kFloat32, "gamma must be float32");
        gamma_ptr = gamma.data_ptr<float>();
    }

    const float* beta_ptr = nullptr;
    if (beta.defined()) {
        TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");
        TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
        TORCH_CHECK(beta.dtype() == torch::kFloat32, "beta must be float32");
        beta_ptr = beta.data_ptr<float>();
    }

    // Calculate num_groups (product of leading dimensions)
    // This is x.numel() / N_dim.
    int num_groups = x.numel() / N_dim;

    auto out = torch::empty_like(x);

    const int block_size = 256; // A common block size
    const int num_blocks = num_groups; // One block per group

    // Calculate dynamic shared memory size:
    // 2 * block_size * sizeof(float) for s_sum and s_sum_sq
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    layernorm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        gamma_ptr,
        beta_ptr,
        out.data_ptr<float>(),
        N_dim,
        num_groups,
        eps);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");

    return out;
}
"""

layernorm_cpp_source = (
    "torch::Tensor layernorm_cuda_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps, int N_dim);"
)

# Compile the inline CUDA code for Layer Normalization
layernorm_custom = load_inline(
    name="layernorm_custom",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layernorm_cuda_forward"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
