class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5, elementwise_affine: bool = True):
        """
        Initializes the custom LayerNorm layer.

        Args:
            normalized_shape (tuple): Shape of the input tensor to be normalized.
            eps (float): A value added to the denominator for numerical stability.
            elementwise_affine (bool): If True, this module has learnable affine parameters.
        """
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.eps = eps
        self.elementwise_affine = elementwise_affine

        # Calculate N_dim: product of dimensions in normalized_shape
        self.N_dim = 1
        for dim in normalized_shape:
            self.N_dim *= dim

        if self.elementwise_affine:
            self.weight = nn.Parameter(torch.empty(normalized_shape))
            self.bias = nn.Parameter(torch.empty(normalized_shape))
        else:
            self.register_parameter('weight', None)
            self.register_parameter('bias', None)

        self.reset_parameters()
        self.layernorm_cuda_forward = layernorm_custom.layernorm_cuda_forward

    def reset_parameters(self) -> None:
        if self.elementwise_affine:
            nn.init.ones_(self.weight)
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies custom Layer Normalization to the input tensor.

        Args:
            x (torch.Tensor): Input tensor of shape (*, normalized_shape).

        Returns:
            torch.Tensor: Output tensor with Layer Normalization applied, same shape as input.
        """
        # Pass gamma (weight) and beta (bias) to the kernel.
        # If elementwise_affine is False, self.weight/bias will be None.
        # The C++ kernel checks gamma.defined() and beta.defined().
        # An undefined torch.Tensor() will result in .defined() == False.
        gamma_tensor = self.weight if self.weight is not None else torch.Tensor()
        beta_tensor = self.bias if self.bias is not None else torch.Tensor()

        return self.layernorm_cuda_forward(
            x,
            gamma_tensor,
            beta_tensor,
            self.eps,
            self.N_dim
        )

