// Helper function to get input index
__device__ inline int get_input_idx(int n, int c_in, int h_in, int w_in, int C_in, int H_in, int W_in) {
    return n * C_in * H_in * W_in + c_in * H_in * W_in + h_in * W_in + w_in;
}

// Helper function to get depthwise weight index
__device__ inline int get_dw_weight_idx(int c_in, int k_h, int k_w, int K) {
    return c_in * K * K + k_h * K + k_w;
}

// Helper function to get pointwise weight index
__device__ inline int get_pw_weight_idx(int c_out, int c_in, int C_in) {
    return c_out * C_in + c_in;
}

// Helper function to get output index
__device__ inline int get_output_idx(int n, int c_out, int h_out, int w_out, int C_out, int H_out, int W_out) {
    return n * C_out * H_out * W_out + c_out * H_out * W_out + h_out * W_out + w_out;
}


__global__ void fused_depthwise_pointwise_conv2d_kernel(
    const float* input,
    const float* dw_weight,
    const float* pw_weight,
    float* output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int K, int S, int P, int D)
{
    // Each thread computes one output element (n, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= N * C_out * H_out * W_out) return;

    int w_out = idx % W_out;
    idx /= W_out;
    int h_out = idx % H_out;
    idx /= H_out;
    int c_out = idx % C_out;
    idx /= C_out;
    int n = idx;

    float acc_out = 0.0f;

    // For each input channel c_in
    for (int c_in = 0; c_in < C_in; ++c_in) {
        float depthwise_sum = 0.0f;

        // Calculate input spatial coordinates for the current output (h_out, w_out)
        // and current kernel position (k_h, k_w)
        int h_in_start = h_out * S - P;
        int w_in_start = w_out * S - P;

        // Perform depthwise convolution for this (n, c_in, h_out, w_out)
        for (int k_h = 0; k_h < K; ++k_h) {
            for (int k_w = 0; k_w < K; ++k_w) {
                int h_in = h_in_start + k_h * D;
                int w_in = w_in_start + k_w * D;

                // Check bounds for input
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    depthwise_sum += input[get_input_idx(n, c_in, h_in, w_in, C_in, H_in, W_in)] *
                                     dw_weight[get_dw_weight_idx(c_in, k_h, k_w, K)];
                }
            }
        }
        // Now apply pointwise convolution for this c_in
        acc_out += depthwise_sum * pw_weight[get_pw_weight_idx(c_out, c_in, C_in)];
    }

    // Store the final result
    output[get_output_idx(n, c_out, h_out, w_out, C_out, H_out, W_out)] = acc_out;
}
