    TORCH_CHECK(pw_weight.is_contiguous(), "Pointwise weight tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be float32.");
    TORCH_CHECK(dw_weight.dtype() == torch::kFloat32, "Depthwise weight tensor must be float32.");
    TORCH_CHECK(pw_weight.dtype() == torch::kFloat32, "Pointwise weight tensor must be float32.");


    // Extract dimensions
    int N = input.size(0);
