    int C_out = pw_weight.size(0); // Pointwise weight shape: (C_out, C_in, 1, 1)

    // Calculate output dimensions
    // H_out = floor((H_in + 2*P - D*(K-1) - 1)/S) + 1
    int H_out = (H_in + 2 * P - D * (K - 1) - 1) / S + 1;
    int W_out = (W_in + 2 * P - D * (K - 1) - 1) / S + 1;

    // Create output tensor
