# Helper function to normalize tuple inputs (similar to torch.nn.modules.utils._ntuple)
def _ntuple(n):
    def parse(x):
        if isinstance(x, collections.abc.Iterable):
            return tuple(x)
        return tuple(repeat(x, n))
    return parse

_triple = _ntuple(3)

# Custom CUDA kernel source for ConvTranspose3d
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// CUDA kernel for 3D Transposed Convolution
// This kernel computes each output element (n, c_out, d_out, h_out, w_out)
// by iterating over relevant input channels (c_in) and kernel spatial dimensions (kd, kh, kw).
// It handles stride, padding, output_padding, dilation, and groups.
__global__ void conv_transpose3d_kernel(const float* input, const float* weight, const float* bias, float* output,
                                        int N, int C_in, int D_in, int H_in, int W_in,
                                        int C_out, int K_D, int K_H, int K_W,
                                        int S_D, int S_H, int S_W,
                                        int P_D, int P_H, int P_W,
                                        int OP_D, int OP_H, int OP_W,
                                        int DIL_D, int DIL_H, int DIL_W,
                                        int GROUPS,
                                        int D_out, int H_out, int W_out,
                                        bool has_bias) {
    // Global index for the current output element to be computed by this thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;

    if (idx < total_output_elements) {
        // Deconstruct the global index into batch (n), output channel (c_out),
        // and spatial coordinates (d_out, h_out, w_out)
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int d_out = idx % D_out;
        idx /= D_out;
        int c_out = idx % C_out;
        idx /= C_out;
        int n = idx;

        float sum = 0.0f;

        // Add bias if present
        if (has_bias) {
            sum += bias[c_out];
        }

        // Determine the group for this output channel
        int C_in_per_group = C_in / GROUPS;
        int C_out_per_group = C_out / GROUPS;
        int group_idx = c_out / C_out_per_group; // Group index for current output channel

        // Iterate over input channels within the same group
        for (int c_in_local = 0; c_in_local < C_in_per_group; ++c_in_local) {
            int c_in = group_idx * C_in_per_group + c_in_local;

            // Iterate over kernel spatial dimensions
            for (int kd = 0; kd < K_D; ++kd) {
                for (int kh = 0; kh < K_H; ++kh) {
                    for (int kw = 0; kw < K_W; ++kw) {
                        // Calculate the corresponding input spatial coordinates (d_in, h_in, w_in)
                        // based on the output coordinates (d_out, h_out, w_out) and kernel offset (kd, kh, kw).
                        // The relationship is:
                        // d_out = d_in * S_D - P_D + kd * DIL_D + OP_D
                        // Rearranging for d_in:
                        // d_in = (d_out + P_D - OP_D - kd * DIL_D) / S_D

                        int d_in_val = d_out + P_D - OP_D - kd * DIL_D;
                        int h_in_val = h_out + P_H - OP_H - kh * DIL_H;
                        int w_in_val = w_out + P_W - OP_W - kw * DIL_W;

                        // Check if the calculated d_in_val, h_in_val, w_in_val are valid:
                        // 1. Must be non-negative.
                        // 2. Must be perfectly divisible by the stride in that dimension.
                        if (d_in_val >= 0 && (d_in_val % S_D == 0) &&
                            h_in_val >= 0 && (h_in_val % S_H == 0) &&
                            w_in_val >= 0 && (w_in_val % S_W == 0)) {

                            int d_in = d_in_val / S_D;
                            int h_in = h_in_val / S_H;
                            int w_in = w_in_val / S_W;

                            // Check if the resulting input coordinates are within the input tensor bounds
                            if (d_in >= 0 && d_in < D_in &&
                                h_in >= 0 && h_in < H_in &&
                                w_in >= 0 && w_in < W_in) {

                                // Calculate the linear offset for the input tensor element
                                // Input tensor shape: (N, C_in, D_in, H_in, W_in)
                                long long input_offset = n * (long long)C_in * D_in * H_in * W_in +
                                                         c_in * (long long)D_in * H_in * W_in +
                                                         d_in * (long long)H_in * W_in +
                                                         h_in * (long long)W_in +
                                                         w_in;

                                // Calculate the linear offset for the weight tensor element
                                // Weight tensor shape: (C_in, C_out/groups, K_D, K_H, K_W)
                                // c_out_local is the index of the output channel within its group
                                int c_out_local = c_out % C_out_per_group;

                                long long weight_offset = c_in * (long long)C_out_per_group * K_D * K_H * K_W +
                                                          c_out_local * (long long)K_D * K_H * K_W +
                                                          kd * (long long)K_H * K_W +
                                                          kh * (long long)K_W +
                                                          kw;

                                sum += input[input_offset] * weight[weight_offset];
                            }
                        }
                    }
                }
            }
        }
        // Store the computed sum into the output tensor
        output[n * (long long)C_out * D_out * H_out * W_out +
               c_out * (long long)D_out * H_out * W_out +
               d_out * (long long)H_out * W_out +
               h_out * (long long)W_out +
               w_out] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor conv_transpose3d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                                    int C_in, int C_out,
                                    int K_D, int K_H, int K_W,
                                    int S_D, int S_H, int S_W,
                                    int P_D, int P_H, int P_W,
                                    int OP_D, int OP_H, int OP_W,
                                    int DIL_D, int DIL_H, int DIL_W,
                                    int GROUPS,
                                    bool has_bias) {
    // Input tensor shape: (N, C_in, D_in, H_in, W_in)
    // Weight tensor shape: (C_in, C_out/groups, K_D, K_H, K_W)
    // Bias tensor shape: (C_out)

    // Basic tensor checks
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "Bias must be a CUDA tensor");
    }
    TORCH_CHECK(input.dim() == 5, "Input must be a 5D tensor (N, C_in, D_in, H_in, W_in)");
    TORCH_CHECK(weight.dim() == 5, "Weight must be a 5D tensor (C_in, C_out/groups, K_D, K_H, K_W)");

    // Extract dimensions from input tensor
    int N = input.size(0);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // Calculate output dimensions based on ConvTranspose3d formula:
    // D_out = (D_in - 1) * S_D - 2 * P_D + DIL_D * (K_D - 1) + OP_D + 1
    int D_out = (D_in - 1) * S_D - 2 * P_D + DIL_D * (K_D - 1) + OP_D + 1;
    int H_out = (H_in - 1) * S_H - 2 * P_H + DIL_H * (K_H - 1) + OP_H + 1;
    int W_out = (W_in - 1) * S_W - 2 * P_W + DIL_W * (K_W - 1) + OP_W + 1;

    // Create the output tensor, initialized to zeros
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr, // Pass nullptr if no bias
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, K_D, K_H, K_W,
        S_D, S_H, S_W,
        P_D, P_H, P_W,
        OP_D, OP_H, OP_W,
        DIL_D, DIL_H, DIL_W,
        GROUPS,
        D_out, H_out, W_out,
        has_bias
    );

    return output;
}
"""

# C++ header for the custom CUDA function
conv_transpose3d_cpp_source = (
    "torch::Tensor conv_transpose3d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,"
    "                                    int C_in, int C_out,"
    "                                    int K_D, int K_H, int K_W,"
    "                                    int S_D, int S_H, int S_W,"
    "                                    int P_D, int P_H, int P_W,"
    "                                    int OP_D, int OP_H, int OP_W,"
    "                                    int DIL_D, int DIL_H, int DIL_W,"
    "                                    int GROUPS,"
    "                                    bool has_bias);"
)

# Compile the inline CUDA code
conv_transpose3d_op = load_inline(
    name="conv_transpose3d_op",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable aggressive optimizations
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and a square kernel,
    using a custom CUDA kernel for potential speedups.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel.
        stride (int or tuple, optional): Stride of the convolution. Defaults to 1.
        padding (int or tuple, optional): Padding applied to the input. Defaults to 0.
        output_padding (int or tuple, optional): Additional size added to one side of each dimension in the output shape.
                                                  Defaults to 0.
        dilation (int or tuple, optional): Spacing between kernel elements. Defaults to 1.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Normalize parameters to 3-tuples for 3D operations
        self.kernel_size = _triple(kernel_size)
        self.stride = _triple(stride)
        self.padding = _triple(padding)
        self.output_padding = _triple(output_padding)
        self.dilation = _triple(dilation)
        self.groups = groups
        self.has_bias = bias

        # Store channel information
        self.in_channels = in_channels
        self.out_channels = out_channels

        # Validate groups parameter
        if not (in_channels % groups == 0 and out_channels % groups == 0):
            raise ValueError(f"in_channels ({in_channels}) and out_channels ({out_channels}) must be divisible by groups ({groups})")

        # Initialize learnable weights and bias parameters
        # Weight shape for ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        weight_shape = (self.in_channels, self.out_channels // self.groups, *self.kernel_size)
        self.weight = nn.Parameter(torch.empty(weight_shape))
        if self.has_bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter('bias', None) # Register bias as None if not used

        self.reset_parameters() # Initialize parameters

        # Store the loaded custom CUDA operator
        self.conv_transpose3d_cuda_op = conv_transpose3d_op

    def reset_parameters(self) -> None:
        # Standard initialization for ConvTranspose3d weights (Kaiming uniform)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            # Calculate fan_in for bias initialization
            # For ConvTranspose, fan_in is typically based on the input channels * kernel area
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            if fan_in > 0:
                bound = 1 / math.sqrt(fan_in)
                nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 3D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out).
        """
        # Call the custom CUDA kernel with all necessary parameters
        return self.conv_transpose3d_cuda_op.conv_transpose3d_cuda(
            x, self.weight, self.bias,
            self.in_channels, self.out_channels,
            self.kernel_size[0], self.kernel_size[1], self.kernel_size[2],
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.dilation[0], self.dilation[1], self.dilation[2],
            self.groups,
            self.has_bias
        )

