import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for matrix multiplication C = A * B
// A is M x K, B is K x N, C is M x N
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Calculate the row and column of the output matrix C that this thread is responsible for
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Check bounds to ensure thread is within the matrix dimensions
    if (row < M && col < N) {
        float sum = 0.0f;
        // Compute the dot product of row 'row' of A and column 'col' of B
        // A[row * K + k] accesses element (row, k) of A
        // B[k * N + col] accesses element (k, col) of B
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are on CUDA and are 2D matrices
    TORCH_CHECK(A.is_cuda(), "Input A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "Input B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D matrices");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible for multiplication: A.cols != B.rows");

    // Ensure inputs are contiguous for efficient memory access in the kernel
    // This might involve a copy if they are not already contiguous.
    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0); // Rows of A
    int K = A.size(1); // Cols of A (and Rows of B)
    int N = B.size(1); // Cols of B

    // Create the output tensor C, initialized to zeros, with the same options (dtype, device) as A
    auto C = torch::zeros({M, N}, A.options());

    // Define block and grid dimensions for the kernel launch
    // Using a 2D block of 16x16 threads is a common choice for matrix operations.
    // For large matrices like N=4096, a naive kernel like this will be significantly slower
    // than highly optimized cuBLAS (used by torch.matmul).
    // Achieving speedups for GEMM typically requires advanced techniques like shared memory tiling.
    const int TILE_DIM = 16;
    dim3 block_size(TILE_DIM, TILE_DIM);
    // Calculate grid dimensions based on output matrix size and block size
    dim3 grid_size((N + TILE_DIM - 1) / TILE_DIM, (M + TILE_DIM - 1) / TILE_DIM);

    // Launch the CUDA kernel
    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N
    );

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for matrix multiplication
matmul_custom = load_inline(
    name="matmul_custom",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) using a custom CUDA kernel.
    """
    def __init__(self) -> None:
        super().__init__()
        # Store the compiled custom kernel as a member of the module
        self.matmul_custom = matmul_custom

    def forward(self, A, B):
        """
        Performs matrix multiplication of two symmetric matrices using a custom CUDA kernel.

        Args:
            A (torch.Tensor): Input matrix A, shape (N, N), symmetric. Must be on CUDA.
            B (torch.Tensor): Input matrix B, shape (N, N), symmetric. Must be on CUDA.

        Returns:
            torch.Tensor: Output matrix C, shape (N, N).
        """
        # Call the custom CUDA kernel
        return self.matmul_custom.matmul_cuda(A, B)

