import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for 3D convolution (direct implementation)
# This kernel is designed for a specific set of convolution parameters to simplify
# the implementation:
#   - stride = 1
#   - padding = 0
#   - dilation = 1
#   - groups = 1
#   - bias = False
#   - float data type (torch.kFloat32)
# It is a direct convolution implementation and may not be as optimized as cuDNN
# for general cases, but serves as an example of custom kernel replacement.

conv3d_direct_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For fprintf and cudaGetErrorString

// Helper to get 1D index for a 5D input tensor (N, C_in, D_in, H_in, W_in)
__device__ __forceinline__ long long get_input_idx(int n, int c, int d, int h, int w,
                                                  int C_in, int D_in, int H_in, int W_in) {
    return (long long)n * (C_in * D_in * H_in * W_in) +
           (long long)c * (D_in * H_in * W_in) +
           (long long)d * (H_in * W_in) +
           (long long)h * W_in +
           (long long)w;
}

// Helper to get 1D index for a 5D weight tensor (C_out, C_in, K_D, K_H, K_W)
__device__ __forceinline__ long long get_weight_idx(int c_out, int c_in, int k_d, int k_h, int k_w,
                                                   int C_in, int K_D, int K_H, int K_W) {
    return (long long)c_out * (C_in * K_D * K_H * K_W) +
           (long long)c_in * (K_D * K_H * K_W) +
           (long long)k_d * (K_H * K_W) +
           (long long)k_h * K_W +
           (long long)k_w;
}

// Helper to get 1D index for a 5D output tensor (N, C_out, D_out, H_out, W_out)
__device__ __forceinline__ long long get_output_idx(int n, int c_out, int d_out, int h_out, int w_out,
                                                   int C_out, int D_out, int H_out, int W_out) {
    return (long long)n * (C_out * D_out * H_out * W_out) +
           (long long)c_out * (D_out * H_out * W_out) +
           (long long)d_out * (H_out * W_out) +
           (long long)h_out * W_out +
           (long long)w_out;
}

__global__ void conv3d_direct_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K_D, int K_H, int K_W,
    int D_out, int H_out, int W_out) {

    // Calculate total number of output elements
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;

    // Each thread computes one output element (n, oc, oz, oy, ox)
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Unflatten the 1D index to 5D output coordinates
        int ox = idx % W_out;
        idx /= W_out;
        int oy = idx % H_out;
        idx /= H_out;
        int oz = idx % D_out;
        idx /= D_out;
        int oc = idx % C_out;
        idx /= C_out;
        int n = idx; // batch index

        float sum = 0.0f;

        // Loop over input channels
        for (int ic = 0; ic < C_in; ++ic) {
            // Loop over kernel depth, height, width
            for (int kz = 0; kz < K_D; ++kz) {
                for (int ky = 0; ky < K_H; ++ky) {
                    for (int kx = 0; kx < K_W; ++kx) {
                        // Input spatial coordinates (assuming stride=1, padding=0, dilation=1)
                        int iz = oz + kz;
                        int iy = oy + ky;
                        int ix = ox + kx;

                        float input_val = input[get_input_idx(n, ic, iz, iy, ix, C_in, D_in, H_in, W_in)];
                        float weight_val = weight[get_weight_idx(oc, ic, kz, ky, kx, C_in, K_D, K_H, K_W)];
                        sum += input_val * weight_val;
                    }
                }
            }
        }
        output[get_output_idx(n, oc, oz, oy, ox, C_out, D_out, H_out, W_out)] = sum;
    }
}

torch::Tensor conv3d_direct_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int K_D, int K_H, int K_W) {

    // Ensure tensors are on CUDA and are float
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA!");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA!");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be float32!");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor must be float32!");
    TORCH_CHECK(input.dim() == 5, "Input tensor must be 5D (N, C_in, D_in, H_in, W_in)");
    TORCH_CHECK(weight.dim() == 5, "Weight tensor must be 5D (C_out, C_in, K_D, K_H, K_W)");

    // Input dimensions
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // Weight dimensions
    int C_out = weight.size(0);
    // K_D, K_H, K_W are passed explicitly

    // Check consistency
    TORCH_CHECK(C_in == weight.size(1), "Input channels must match weight input channels");
    TORCH_CHECK(K_D == weight.size(2), "Kernel depth must match weight depth");
    TORCH_CHECK(K_H == weight.size(3), "Kernel height must match weight height");
    TORCH_CHECK(K_W == weight.size(4), "Kernel width must match weight width");

    // Output dimensions (assuming stride=1, padding=0, dilation=1)
    int D_out = D_in - K_D + 1;
    int H_out = H_in - K_H + 1;
    int W_out = W_in - K_W + 1;

    // Create output tensor
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    // Calculate grid and block dimensions
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;
    const int block_size = 256; // Standard block size
