__device__ inline int get_output_idx(int n, int c_out, int h_out, int w_out,
                                     int C_out, int H_out, int W_out) {
    return n * (C_out * H_out * W_out) +
           c_out * (H_out * W_out) +
           h_out * W_out +
           w_out;
}


__global__ void simple_conv2d_kernel(const float* x, const float* w, float* y,
                                     int N, int C_in, int H_in, int W_in,
                                     int C_out, int K_H, int K_W,
                                     int H_out, int W_out) {
