    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C_out * H_out * W_out) {
        int n = idx / (C_out * H_out * W_out);
        int remaining_idx = idx % (C_out * H_out * W_out);
        int c_out = remaining_idx / (H_out * W_out);
        remaining_idx %= (H_out * W_out);
        int h_out = remaining_idx / W_out;
        int w_out = remaining_idx % W_out;

        float sum = 0.0f;

        // Loop over input channels and kernel dimensions
        for (int c_in = 0; c_in < C_in; ++c_in) {
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate input coordinates (assuming padding=0, stride=1, dilation=1)
                    int h_in = h_out + k_h;
                    int w_in = w_out + k_w;

                    sum += x[get_input_idx(n, c_in, h_in, w_in, C_in, H_in, W_in)] *
                           w[get_weight_idx(c_out, c_in, k_h, k_w, C_in, K_H, K_W)];
