import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Transposed Convolution
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for 3D Transposed Convolution
__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kernel_size, // kD, kH, kW are all kernel_size
    int stride,
    int padding,
    int groups,
    int C_in_per_group,
    int C_out_per_group
) {
    // Each thread computes one element of the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int total_output_elements = N * C_out * D_out * H_out * W_out;

    if (idx < total_output_elements) {
        // Map flat index to 5D output coordinates (n, c_out, d_out, h_out, w_out)
        int n = idx / (C_out * D_out * H_out * W_out);
        int rem = idx % (C_out * D_out * H_out * W_out);
        int c_out = rem / (D_out * H_out * W_out);
        rem = rem % (D_out * H_out * W_out);
        int d_out = rem / (H_out * W_out);
        rem = rem % (H_out * W_out);
        int h_out = rem / W_out;
        int w_out = rem % W_out;

        float sum = 0.0f;

        // Determine the group for this output channel
        int group_idx = c_out / C_out_per_group;

        // Iterate over input channels within this group
        for (int c_in_idx_in_group = 0; c_in_idx_in_group < C_in_per_group; ++c_in_idx_in_group) {
            int c_in_global = group_idx * C_in_per_group + c_in_idx_in_group;

            // Iterate over kernel elements
            for (int kd = 0; kd < kernel_size; ++kd) {
                for (int kh = 0; kh < kernel_size; ++kh) {
                    for (int kw = 0; kw < kernel_size; ++kw) {
                        // Calculate corresponding input coordinates (d_in, h_in, w_in)
                        // The relationship is: output_coord = input_coord * stride - padding + kernel_coord
                        // Rearranging for input_coord: input_coord * stride = output_coord + padding - kernel_coord
                        // input_coord = (output_coord + padding - kernel_coord) / stride

                        int d_in_candidate = (d_out + padding - kd);
                        int h_in_candidate = (h_out + padding - kh);
                        int w_in_candidate = (w_out + padding - kw);

                        // Check if the candidate input coordinates are valid:
                        // 1. Must be non-negative
                        // 2. Must be divisible by stride (since input_coord must be an integer)
                        // 3. Must be within input tensor bounds
                        if (d_in_candidate >= 0 && d_in_candidate % stride == 0 &&
                            h_in_candidate >= 0 && h_in_candidate % stride == 0 &&
                            w_in_candidate >= 0 && w_in_candidate % stride == 0) {

                            int d_in = d_in_candidate / stride;
                            int h_in = h_in_candidate / stride;
                            int w_in = w_in_candidate / stride;

                            if (d_in < D_in && h_in < H_in && w_in < W_in) {
                                // Accumulate contribution
                                // Input tensor shape: (N, C_in, D_in, H_in, W_in)
                                // Weight tensor shape: (C_in, C_out_per_group, kD, kH, kW)

                                float input_val = input[n * C_in * D_in * H_in * W_in +
                                                        c_in_global * D_in * H_in * W_in +
                                                        d_in * H_in * W_in +
                                                        h_in * W_in +
                                                        w_in];

                                float weight_val = weight[c_in_global * C_out_per_group * kernel_size * kernel_size * kernel_size +
                                                          (c_out % C_out_per_group) * kernel_size * kernel_size * kernel_size +
                                                          kd * kernel_size * kernel_size +
                                                          kh * kernel_size +
                                                          kw];

                                sum += input_val * weight_val;
                            }
                        }
                    }
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int kernel_size, // Assuming kD, kH, kW are all kernel_size
    int stride,
    int padding,
    int groups
) {
    // Input: (N, C_in, D_in, H_in, W_in)
    // Weight: (C_in, C_out_per_group, kD, kH, kW)

    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "Input must be 5D (N, C_in, D_in, H_in, W_in)");
    TORCH_CHECK(weight.dim() == 5, "Weight must be 5D (C_in, C_out_per_group, kD, kH, kW)");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight must be float32");

    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int C_in_weight = weight.size(0);
    int C_out_per_group_weight = weight.size(1);
    int kD_weight = weight.size(2);
    int kH_weight = weight.size(3);
    int kW_weight = weight.size(4);

    TORCH_CHECK(C_in == C_in_weight, "Input channels must match weight input channels");
    TORCH_CHECK(C_in % groups == 0, "Input channels must be divisible by groups");
    TORCH_CHECK(kD_weight == kernel_size && kH_weight == kernel_size && kW_weight == kernel_size,
                "Weight kernel dimensions must match provided kernel_size");

    int C_in_per_group = C_in / groups;
    int C_out = C_out_per_group_weight * groups; // Total output channels

    // Calculate output dimensions (assuming output_padding = 0, as per default in original model)
    // output_size = (input_size - 1) * stride - 2 * padding + kernel_size + output_padding
    // With output_padding = 0:
    int D_out = (D_in - 1) * stride - 2 * padding + kernel_size;
    int H_out = (H_in - 1) * stride - 2 * padding + kernel_size;
    int W_out = (W_in - 1) * stride - 2 * padding + kernel_size;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    const int total_output_elements = N * C_out * D_out * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kernel_size,
        stride, padding, groups,
        C_in_per_group, C_out_per_group_weight // Pass C_out_per_group_weight as C_out_per_group
    );

    return output;
}
