import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for batched matrix multiplication (N, M, K) @ (K, L) -> (N, M, L)
batched_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void batched_matmul_kernel(const float* A, const float* B, float* C, int N, int M, int K, int L) {
    // Calculate a unique global index for each element in the output tensor C
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of elements in the output tensor C
    int total_elements = N * M * L;

    if (global_idx < total_elements) {
        // Decompose global_idx into (n, m, l) coordinates for C
        // C is (N, M, L)
        int l = global_idx % L;
        int m = (global_idx / L) % M;
        int n = global_idx / (M * L);

        float sum = 0.0f;
        // Perform the dot product for C[n, m, l]
        // C[n, m, l] = sum_{k=0}^{K-1} A[n, m, k] * B[k, l]
        for (int k = 0; k < K; ++k) {
            // A is (N, M, K)
            // B is (K, L)
            sum += A[n * M * K + m * K + k] * B[k * L + l];
        }
        C[n * M * L + m * L + l] = sum;
    }
}

torch::Tensor batched_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are on CUDA
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    // Get dimensions
    auto A_sizes = A.sizes(); // (N, M, K)
    auto B_sizes = B.sizes(); // (K, L)

    TORCH_CHECK(A_sizes.size() == 3, "A must be a 3D tensor");
    TORCH_CHECK(B_sizes.size() == 2, "B must be a 2D tensor");

    int N = A_sizes[0];
    int M = A_sizes[1];
    int K = A_sizes[2];
    int K_B = B_sizes[0];
    int L = B_sizes[1];

