import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for depthwise 2D convolution
depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max, std::min

// Helper function to get an element from a 4D tensor with bounds checking
// Assumes NCHW layout
__device__ float get_input_pixel(const float* input, int N, int C, int H_in, int W_in, int n, int c, int h, int w) {
    if (h >= 0 && h < H_in && w >= 0 && w < W_in) {
        return input[n * (C * H_in * W_in) + c * (H_in * W_in) + h * W_in + w];
    }
    return 0.0f; // Padding value
}

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int K_H, int K_W,
    int S_H, int S_W,
    int P_H, int P_W,
    int D_H, int D_W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    int total_output_elements = N * C * H_out * W_out;

    if (idx >= total_output_elements) {
        return;
    }

    // Decompose idx into (n, c, h_out, w_out)
    // N, C, H_out, W_out
    int n = idx / (C * H_out * W_out);
    int rem = idx % (C * H_out * W_out);
    int c = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    float acc = 0.0f;

    // Iterate over kernel dimensions
    for (int k_h = 0; k_h < K_H; ++k_h) {
        for (int k_w = 0; k_w < K_W; ++k_w) {
            // Calculate input coordinates considering stride, dilation, and padding
            int h_in = h_out * S_H + k_h * D_H - P_H;
            int w_in = w_out * S_W + k_w * D_W - P_W;

            // Get input pixel value (handles padding implicitly by returning 0.0f for out-of-bounds)
            float input_val = get_input_pixel(input, N, C, H_in, W_in, n, c, h_in, w_in);

            // Get weight value. For depthwise conv, weight shape is (C, 1, K_H, K_W).
            // The '1' dimension is effectively skipped in indexing.
            // weight[c * (1 * K_H * K_W) + 0 * (K_H * K_W) + k_h * K_W + k_w]
            float weight_val = weight[c * (K_H * K_W) + k_h * K_W + k_w];

            acc += input_val * weight_val;
        }
    }

    // Store the result in the output tensor
    // output[n * C * H_out * W_out + c * H_out * W_out + h_out * W_out + w_out]
    output[n * (C * H_out * W_out) + c * (H_out * W_out) + h_out * W_out + w_out] = acc;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int K_H, int K_W,
    int S_H, int S_W,
    int P_H, int P_W,
    int D_H, int D_W) {

    // Ensure inputs are on CUDA, are float32, and are contiguous
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(weight.is_contiguous(), "Weight tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be float32.");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor must be float32.");

    // Get input dimensions
    int N = input.size(0);
    int C = input.size(1); // in_channels (and also out_channels for depthwise)
    int H_in = input.size(2);
    int W_in = input.size(3);

    // Calculate output dimensions based on standard convolution formulas
    // H_out = floor((H_in + 2 * padding_h - dilation_h * (kernel_size_h - 1) - 1) / stride_h) + 1
    // W_out = floor((W_in + 2 * padding_w - dilation_w * (kernel_size_w - 1) - 1) / stride_w) + 1
    int H_out = (H_in + 2 * P_H - D_H * (K_H - 1) - 1) / S_H + 1;
    int W_out = (W_in + 2 * P_W - D_W * (K_W - 1) - 1) / S_W + 1;

    // Create output tensor with the same options (device, dtype) as input
    auto output = torch::zeros({N, C, H_out, W_out}, input.options());

    // Total number of output elements to process
    int total_output_elements = N * C * H_out * W_out;

    // Launch configuration: 1D grid, each thread computes one output element
    const int block_size = 256; // A common block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H_in, W_in,
        H_out, W_out,
        K_H, K_W,
        S_H, S_W,
        P_H, P_W,
        D_H, D_W);

    // Check for any CUDA errors that might have occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
"""

depthwise_conv2d_cpp_source = (
    "torch::Tensor depthwise_conv2d_cuda("
    "torch::Tensor input, "
    "torch::Tensor weight, "
    "int K_H, int K_W, "
    "int S_H, int S_W, "
    "int P_H, int P_W, "
    "int D_H, int D_W);"
)

# Compile the inline CUDA code
depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d_module",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for better performance
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with asymmetric input and asymmetric kernel,
    optimized by replacing the PyTorch nn.Conv2d operator with a custom CUDA kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
                            (For depthwise, this is typically equal to in_channels).
        kernel_size_h (int): Height of the convolution kernel.
        kernel_size_w (int): Width of the convolution kernel.
        stride_h (int, optional): Stride of the convolution in height dimension. Defaults to 1.
        stride_w (int, optional): Stride of the convolution in width dimension. Defaults to 1.
        padding_h (int, optional): Padding applied to the input in height dimension. Defaults to 0.
        padding_w (int, optional): Padding applied to the input in width dimension. Defaults to 0.
        dilation_h (int, optional): Spacing between kernel elements in height dimension. Defaults to 1.
        dilation_w (int, optional): Spacing between kernel elements in width dimension. Defaults to 1.
        groups (int, optional): Number of blocked connections from input channels to output channels.
                                (Must be equal to in_channels for depthwise). Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size_h: int, kernel_size_w: int, stride_h: int = 1, stride_w: int = 1, padding_h: int = 0, padding_w: int = 0, dilation_h: int = 1, dilation_w: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store convolution parameters for the custom kernel call
        self.K_H = kernel_size_h
        self.K_W = kernel_size_w
        self.S_H = stride_h
        self.S_W = stride_w
        self.P_H = padding_h
        self.P_W = padding_w
        self.D_H = dilation_h
        self.D_W = dilation_w

        # The original model uses nn.Conv2d to initialize weights.
        # We create a dummy nn.Conv2d layer to get a properly initialized weight tensor
        # and then register it as a parameter of ModelNew.
        # For depthwise convolution, out_channels for nn.Conv2d is typically in_channels,
        # and groups must be equal to in_channels.
        if groups != in_channels:
            raise ValueError("For depthwise convolution, 'groups' must be equal to 'in_channels'.")
        if out_channels != in_channels:
            # While the original model's Conv2d uses in_channels for its out_channels,
            # the ModelNew constructor still receives the original out_channels parameter.
            # We ensure the internal dummy_conv matches the depthwise requirement.
            print(f"Warning: For depthwise convolution, out_channels ({out_channels}) is typically equal to in_channels ({in_channels}). "
                  f"The internal weight will be shaped as (in_channels, 1, K_H, K_W).")

        dummy_conv = nn.Conv2d(in_channels, in_channels, (kernel_size_h, kernel_size_w), 
                               stride=(stride_h, stride_w), padding=(padding_h, padding_w), 
                               dilation=(dilation_h, dilation_w), groups=in_channels, bias=bias)

        # Register the weight tensor as a learnable parameter of this module
        self.weight = nn.Parameter(dummy_conv.weight.data)

        # Store the compiled custom CUDA function
        self.depthwise_conv2d_cuda = depthwise_conv2d_module.depthwise_conv2d_cuda

        # The custom kernel currently does not implement bias.
        if bias:
            raise NotImplementedError("Bias is not implemented in the custom depthwise_conv2d_cuda kernel for this example.")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the depthwise 2D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        # Ensure the input tensor is on the CUDA device before passing to the kernel
        x = x.cuda()

        # Call the custom CUDA kernel function
        return self.depthwise_conv2d_cuda(
            x,
            self.weight,
            self.K_H, self.K_W,
            self.S_H, self.S_W,
            self.P_H, self.P_W,
            self.D_H, self.D_W
        )

