from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused GELU activation function
fused_gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For M_PI, sqrtf, tanhf, powf

// CUDA kernel to compute the GELU approximation:
// 0.5 * x * (1.0 + tanh(sqrt(2.0 / pi) * (x + 0.044715 * x^3)))
__global__ void fused_gelu_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];

        // Pre-calculated constants for the GELU approximation
        // M_SQRT2_OVER_PI_F = sqrtf(2.0f / M_PI) = 0.7978845608028654f
        // C_044715 = 0.044715f
        // C_0_5 = 0.5f

        // Calculate x^3
        float x_cubed = val * val * val; 

        // Calculate (x + 0.044715 * x^3)
        float inner_term = val + (0.044715f * x_cubed);

        // Calculate sqrt(2.0 / pi) * (x + 0.044715 * x^3)
        float tanh_arg = 0.7978845608028654f * inner_term;

        // Calculate tanh(...)
        float tanh_val = tanhf(tanh_arg);

        // Calculate 0.5 * x * (1.0 + tanh_val)
        out[idx] = 0.5f * val * (1.0f + tanh_val);
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor fused_gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");

    auto size = x.numel();
    auto out = torch::empty_like(x); // Allocate output tensor with the same shape and dtype

    // Define block and grid dimensions
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Launch the CUDA kernel
    fused_gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

fused_gelu_cpp_source = (
    "torch::Tensor fused_gelu_cuda(torch::Tensor x);"
)

# Compile the inline CUDA code for the fused GELU
fused_gelu = load_inline(
    name="fused_gelu",
    cpp_sources=fused_gelu_cpp_source,
    cuda_sources=fused_gelu_source,
    functions=["fused_gelu_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Add optimization flags for CUDA compiler, including fast math
)


