import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Max Pooling 3D
max_pool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Helper function to calculate output dimension
// This function is called from the C++ wrapper (host code)
int calculate_output_dim(int input_dim, int kernel_size, int stride, int padding, int dilation, bool ceil_mode) {
    int effective_kernel_size = (kernel_size - 1) * dilation + 1;
    int numerator = input_dim + 2 * padding - effective_kernel_size;
    if (ceil_mode) {
        // Equivalent to ceil(numerator / stride) + 1
        return (numerator + stride - 1) / stride + 1;
    } else {
        // Equivalent to floor(numerator / stride) + 1
        return numerator / stride + 1;
    }
}

__global__ void max_pool3d_kernel(
    const float* x,
    float* out,
    int N, int C, int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kernel_size, int stride, int padding, int dilation) {

    // Calculate total number of output elements
    int total_output_elements = N * C * D_out * H_out * W_out;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map linear idx to 5D output coordinates (n, c, d_out, h_out, w_out)
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int d_out = (idx / (W_out * H_out)) % D_out;
        int c = (idx / (W_out * H_out * D_out)) % C;
        int n = idx / (W_out * H_out * D_out * C);

        float max_val = -FLT_MAX; // Initialize with a very small number

        // Calculate input window start coordinates
        // These are the top-left-front corner of the kernel window in the padded input space
        int d_start = d_out * stride - padding;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        // Iterate over kernel window
        for (int kd = 0; kd < kernel_size; ++kd) {
            int d_in = d_start + kd * dilation;
            // Check if current input depth coordinate is within bounds of the actual input tensor
            if (d_in < 0 || d_in >= D_in) continue;

            for (int kh = 0; kh < kernel_size; ++kh) {
                int h_in = h_start + kh * dilation;
                // Check if current input height coordinate is within bounds
                if (h_in < 0 || h_in >= H_in) continue;

                for (int kw = 0; kw < kernel_size; ++kw) {
                    int w_in = w_start + kw * dilation;
                    // Check if current input width coordinate is within bounds
                    if (w_in < 0 || w_in >= W_in) continue;

                    // Calculate linear index for input tensor (N, C, D_in, H_in, W_in)
                    // Assuming row-major order
                    int input_idx = n * (C * D_in * H_in * W_in) +
                                    c * (D_in * H_in * W_in) +
                                    d_in * (H_in * W_in) +
                                    h_in * W_in +
                                    w_in;

                    max_val = fmaxf(max_val, x[input_idx]);
                }
            }
        }
        out[idx] = max_val;
    }
}

torch::Tensor max_pool3d_cuda(
    torch::Tensor x,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool ceil_mode) {

