    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat, "Input tensor must be float32");
    TORCH_CHECK(x.dim() == 5, "Input tensor must be 5D (N, C, D, H, W)");

    // Get input dimensions
    int N = x.size(0);
    int C = x.size(1);
    int D_in = x.size(2);
    int H_in = x.size(3);
    int W_in = x.size(4);

    // Calculate output dimensions using the helper function
    int D_out = calculate_output_dim(D_in, kernel_size, stride, padding, dilation, ceil_mode);
    int H_out = calculate_output_dim(H_in, kernel_size, stride, padding, dilation, ceil_mode);
    int W_out = calculate_output_dim(W_in, kernel_size, stride, padding, dilation, ceil_mode);

    // Create output tensor with the same options (device, dtype) as input
    auto out = torch::empty({N, C, D_out, H_out, W_out}, x.options());

    // Calculate total number of output elements for kernel launch configuration
    int total_output_elements = N * C * D_out * H_out * W_out;

    // Define block and grid dimensions
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
