kl_div_elementwise_terms_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For logf

__global__ void kl_div_elementwise_terms_kernel(const float* predictions, const float* targets, float* out, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        float p = predictions[idx];
        float q = targets[idx];

        // The formula for a single KL divergence term is q * (log(q) - log(p)).
        // Since the inputs (predictions and targets) are generated using softmax,
        // they are guaranteed to be strictly positive. This means logf(p) and logf(q)
        // will always be finite, simplifying error handling for log(0) or 0 * (-inf).
        out[idx] = q * (logf(q) - logf(p));
    }
}

