    // Input validation: ensure tensors are on CUDA, are floating point, and have matching shapes.
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.is_floating_point(), "predictions must be a floating point tensor");
    TORCH_CHECK(targets.is_floating_point(), "targets must be a floating point tensor");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "predictions and targets must have the same shape");

    auto N = predictions.numel(); // Total number of elements
    auto out = torch::empty_like(predictions); // Output tensor will have the same shape as inputs

    // Configure kernel launch parameters
    const int block_size = 256; // A common block size, can be tuned for optimal performance
    const int num_blocks = (N + block_size - 1) / block_size;

    // Launch the CUDA kernel
    kl_div_elementwise_terms_kernel<<<num_blocks, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        N
    );

    return out;
}
"""

