import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Cross Entropy Loss
fused_cross_entropy_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat> // For FLT_MAX
#include <algorithm> // For std::min

// CUDA kernel for fused LogSoftmax and NLLLoss per sample
// Each block processes one sample (row) from the predictions tensor.
// It computes the numerically stable log-softmax for the target class
// and stores the negative log-likelihood for that sample.
__global__ void fused_cross_entropy_kernel(const float* predictions, const long* targets, float* losses_per_sample, int batch_size, int num_classes) {
    // Get the index of the current sample (row) to process
    int sample_idx = blockIdx.x;

    // Guard against out-of-bounds access if gridDim.x > batch_size
    if (sample_idx >= batch_size) {
        return;
    }

    // Dynamically allocated shared memory for reduction within a block.
    // It will be used for both max_val and sum_exp reductions.
    extern __shared__ float s_data[];

    // Initialize max_val for this thread's portion of the row
    float max_val_thread = -FLT_MAX;

    // First pass: Find the maximum value in the current row (sample)
    // Each thread processes a subset of the `num_classes` elements.
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        float val = predictions[sample_idx * num_classes + i];
        max_val_thread = fmaxf(max_val_thread, val);
    }

    // Reduce max_val across all threads in the block using shared memory
    s_data[threadIdx.x] = max_val_thread;
    __syncthreads(); // Ensure all threads have written their partial max_val

    // Tree reduction for max_val
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each reduction step
    }
    float max_val_row = s_data[0]; // Thread 0 now holds the maximum value for the entire row

    // Second pass: Compute the sum of exponentials (sum_exp) for the current row
    // using the numerically stable `max_val_row`.
    float sum_exp_thread = 0.0f;
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        float val = predictions[sample_idx * num_classes + i];
        sum_exp_thread += expf(val - max_val_row);
    }

    // Reduce sum_exp across all threads in the block using shared memory
    s_data[threadIdx.x] = sum_exp_thread;
    __syncthreads(); // Ensure all threads have written their partial sum_exp

    // Tree reduction for sum_exp
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }
    float sum_exp_row = s_data[0]; // Thread 0 now holds the sum of exponentials for the entire row

    // Only thread 0 of the block computes the final loss for the sample
    if (threadIdx.x == 0) {
        // Compute the log-sum-exp for the row
        float log_sum_exp_row = logf(sum_exp_row) + max_val_row;

        // Get the target class index for this sample
        long target_class = targets[sample_idx];
        // Get the prediction score for the target class
        float target_prediction = predictions[sample_idx * num_classes + target_class];

        // Compute the negative log-likelihood for this sample: -(target_prediction - log_sum_exp_row)
        losses_per_sample[sample_idx] = -(target_prediction - log_sum_exp_row);
    }
}

// CUDA kernel for final reduction (sum) across all samples' losses
// This kernel sums up the individual sample losses computed by the previous kernel.
__global__ void sum_reduction_kernel(const float* input, float* output, int size) {
    extern __shared__ float s_sum[]; // Shared memory for reduction within a block

    float sum_thread = 0.0f;
    // Grid-stride loop: Each thread processes multiple elements from the input array
    // to ensure all elements are covered by the grid.
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < size; i += gridDim.x * blockDim.x) {
        sum_thread += input[i];
    }
    s_sum[threadIdx.x] = sum_thread;
    __syncthreads(); // Ensure all threads have written their partial sums

    // Tree reduction within the block to get the block's total sum
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Only thread 0 of the block atomically adds its block's sum to the global output.
    // This handles summing results from multiple blocks safely.
    if (threadIdx.x == 0) {
        atomicAdd(output, s_sum[0]);
    }
}


// C++ wrapper function to launch the CUDA kernels
torch::Tensor fused_cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Input validation
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.dtype() == torch::kFloat, "predictions must be float32");
    TORCH_CHECK(targets.dtype() == torch::kLong, "targets must be long");
    TORCH_CHECK(predictions.dim() == 2, "predictions must be 2D (batch_size, num_classes)");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1D (batch_size)");
    TORCH_CHECK(predictions.size(0) == targets.size(0), "batch sizes must match");

    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    // Create an output tensor to store the NLL loss for each sample
    auto losses_per_sample = torch::empty({batch_size}, predictions.options());

    // --- Launch fused_cross_entropy_kernel ---
    // Each block processes one sample.
    const int block_size_per_sample = 256; // Number of threads per block for processing a sample
    // Shared memory size required for the reduction within each block.
    const int shared_mem_size_per_block = block_size_per_sample * sizeof(float);

    fused_cross_entropy_kernel<<<batch_size, block_size_per_sample, shared_mem_size_per_block>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<long>(),
        losses_per_sample.data_ptr<float>(),
        batch_size,
        num_classes
    );
    // Check for CUDA errors after kernel launch
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA error after fused_cross_entropy_kernel: ", cudaGetErrorString(err));


    // --- Launch sum_reduction_kernel to sum up losses_per_sample ---
    // Create a scalar tensor to store the total loss (sum of all sample losses)
    auto total_loss_tensor = torch::zeros({1}, predictions.options());

    const int block_size_reduction = 256;
    // Determine the number of blocks for reduction. Cap it to a reasonable maximum
    // to avoid launching too many blocks if batch_size is extremely large.
    const int max_blocks_reduction = 512;
    const int num_blocks_reduction = std::min((batch_size + block_size_reduction - 1) / block_size_reduction, max_blocks_reduction);
    const int shared_mem_size_reduction = block_size_reduction * sizeof(float);

    sum_reduction_kernel<<<num_blocks_reduction, block_size_reduction, shared_mem_size_reduction>>>(
        losses_per_sample.data_ptr<float>(),
        total_loss_tensor.data_ptr<float>(),
        batch_size
    );
    // Check for CUDA errors after kernel launch
    err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA error after sum_reduction_kernel: ", cudaGetErrorString(err));

    // The final loss is the mean, so divide the total sum by the batch size.
    return total_loss_tensor / batch_size;
}
