#include <torch/extension.h>
#include <cuda_runtime.h>
#include <limits> // For std::numeric_limits

__global__ void mean_kernel(const float* in_data, float* out_data,
                            const long* in_sizes_ptr, const long* in_strides_ptr, int in_dims,
                            int reduce_dim, long output_numel, long reduce_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < output_numel) {
        float sum = 0.0f;

        long base_in_linear_idx = 0;
        long output_idx_temp = idx;

        for (int d = in_dims - 1; d >= 0; --d) {
            if (d == reduce_dim) {
                continue;
            }
            long current_coord = output_idx_temp % in_sizes_ptr[d];
            base_in_linear_idx += current_coord * in_strides_ptr[d];
            output_idx_temp /= in_sizes_ptr[d];
        }

        long reduce_stride = in_strides_ptr[reduce_dim];
        for (int j = 0; j < reduce_size; ++j) {
            sum += in_data[base_in_linear_idx + j * reduce_stride];
        }

        out_data[idx] = sum / reduce_size;
    }
}

torch::Tensor mean_cuda(torch::Tensor x, int dim) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32");

    int in_dims = x.dim();
    TORCH_CHECK(dim >= 0 && dim < in_dims, "Reduction dimension out of bounds");

    std::vector<long> output_shape_vec;
    long output_numel = 1;
    for (int d = 0; d < in_dims; ++d) {
        if (d != dim) {
            output_shape_vec.push_back(x.size(d));
            output_numel *= x.size(d);
        }
    }

    long reduce_size = x.size(dim);
    if (reduce_size == 0) {
        auto out = torch::empty(output_shape_vec, x.options());
        out.fill_(std::numeric_limits<float>::quiet_NaN());
        return out;
    }

    auto out = torch::zeros(output_shape_vec, x.options());

    auto in_sizes_tensor = torch::empty({in_dims}, torch::kLong).cuda();
    auto in_strides_tensor = torch::empty({in_dims}, torch::kLong).cuda();

    for (int d = 0; d < in_dims; ++d) {
        in_sizes_tensor[d] = x.size(d);
        in_strides_tensor[d] = x.stride(d);
    }

    const int block_size = 256;
    const int num_blocks = (output_numel + block_size - 1) / block_size;

    mean_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        in_sizes_tensor.data_ptr<long>(),
        in_strides_tensor.data_ptr<long>(),
        in_dims,
        dim,
        output_numel,
        reduce_size
    );

