import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for batched matrix multiplication
bmm_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for batched matrix multiplication (C = A * B)
// A: (batch_size, m, k)
// B: (batch_size, k, n)
// C: (batch_size, m, n)
__global__ void bmm_kernel(const float* A, const float* B, float* C,
                           int batch_size, int m, int k, int n) {
    // Calculate global indices for batch, row, and column
    // Each thread computes one element C[b, row, col]
    int b = blockIdx.z;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Check bounds to ensure threads don't access out-of-range memory
    if (b < batch_size && row < m && col < n) {
        float sum = 0.0f;
        // Perform dot product for C[b, row, col]
        for (int p = 0; p < k; ++p) {
            // A[b, row, p]
            float a_val = A[b * m * k + row * k + p];
            // B[b, p, col]
            float b_val = B[b * k * n + p * n + col];
            sum += a_val * b_val;
        }
        // Store the result in C[b, row, col]
        C[b * m * n + row * n + col] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor bmm_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation
    TORCH_CHECK(A.is_cuda(), "Input tensor A must be a CUDA tensor.");
    TORCH_CHECK(B.is_cuda(), "Input tensor B must be a CUDA tensor.");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "Input tensor A must be of float32 type.");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "Input tensor B must be of float32 type.");
    TORCH_CHECK(A.dim() == 3, "Input tensor A must be 3-dimensional (batch_size, m, k).");
    TORCH_CHECK(B.dim() == 3, "Input tensor B must be 3-dimensional (batch_size, k, n).");

    // Get dimensions from input tensors
    int batch_size = A.size(0);
    int m = A.size(1);
    int k_A = A.size(2);
    int k_B = B.size(1);
    int n = B.size(2);

    TORCH_CHECK(k_A == k_B, "Matrix inner dimensions (k) must match for multiplication.");
    TORCH_CHECK(batch_size == B.size(0), "Batch sizes of input tensors must match.");

    // Create the output tensor C with the same options (device, dtype) as A
    auto C = torch::zeros({batch_size, m, n}, A.options());

    // Define block and grid dimensions for kernel launch
    // Using a 2D block for (row, col) and a 3D grid for (batch, m_blocks, n_blocks)
    const int BLOCK_DIM_X = 32; // Threads per block in X-dimension (for columns)
    const int BLOCK_DIM_Y = 32; // Threads per block in Y-dimension (for rows)

    dim3 block_dims(BLOCK_DIM_X, BLOCK_DIM_Y);
    dim3 grid_dims(
        (n + BLOCK_DIM_X - 1) / BLOCK_DIM_X, // Number of blocks in X-dimension
        (m + BLOCK_DIM_Y - 1) / BLOCK_DIM_Y, // Number of blocks in Y-dimension
        batch_size                           // Number of blocks in Z-dimension (for batches)
    );

    // Launch the CUDA kernel
    bmm_kernel<<<grid_dims, block_dims>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        batch_size, m, k_A, n
    );

    // Check for any CUDA errors after kernel launch (optional, but good for debugging)
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in bmm_cuda: %s\\n", cudaGetErrorString(err));
    }

    return C;
}
"""

