import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for RMS Normalization
rms_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For rsqrtf

// Helper for block-wise reduction (summation)
// Assumes blockDim.x is a power of 2 and <= 1024
__device__ float block_sum_reduce(float val) {
    // Use shared memory for reduction within the block
    __shared__ float s_data[1024]; 
    s_data[threadIdx.x] = val;
    __syncthreads();

    // Perform parallel reduction
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }
    return s_data[0]; // The sum is in s_data[0]
}

__global__ void rms_norm_kernel(const float* x_ptr, float* out_ptr, int B, int C, int D1, int D2, float eps) {
    // Each block is responsible for one (batch, dim1, dim2) group.
    // This means each block calculates the RMS for x[:, :, d1, d2] and normalizes it.
    int group_idx = blockIdx.x; 

    // Check if the group_idx is within bounds
    if (group_idx >= B * D1 * D2) {
        return;
    }

    // Map group_idx back to (b, d1, d2) coordinates
    int b = group_idx / (D1 * D2);
    int d1 = (group_idx % (D1 * D2)) / D2;
    int d2 = (group_idx % (D1 * D2)) % D2;

    float sum_sq_thread = 0.0f;

    // Each thread processes a portion of the C (num_features) dimension for its group.
    // This loop ensures all C elements are covered, even if C > blockDim.x.
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        // Calculate the linear index for x[b, c_idx, d1, d2]
        // Assuming x is contiguous and stored in row-major order
        int x_idx = b * (C * D1 * D2) + c_idx * (D1 * D2) + d1 * D2 + d2;
        float val = x_ptr[x_idx];
        sum_sq_thread += val * val; // Accumulate sum of squares
    }

    // Reduce the partial sum_sq_thread values across all threads in the block
    // to get the total sum of squares for this (b, d1, d2) group.
    float total_sum_sq = block_sum_reduce(sum_sq_thread);

    // Only thread 0 calculates the inverse RMS and broadcasts it to other threads.
    __shared__ float s_rms_inv; // Shared memory to store the inverse RMS
    if (threadIdx.x == 0) {
        float mean_sq = total_sum_sq / C; // Calculate mean square
        // Use rsqrtf for 1/sqrt(x) which is often faster than sqrtf then 1/x
        s_rms_inv = rsqrtf(mean_sq + eps); 
    }
    __syncthreads(); // Ensure s_rms_inv is available to all threads in the block

    float rms_inv = s_rms_inv; // Each thread gets the inverse RMS

    // Normalize and write the output for the current (b, d1, d2) group.
    // Each thread processes a portion of the C dimension.
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int x_idx = b * (C * D1 * D2) + c_idx * (D1 * D2) + d1 * D2 + d2;
        out_ptr[x_idx] = x_ptr[x_idx] * rms_inv; // x / rms = x * (1/rms)
    }
}

// PyTorch C++ wrapper for the CUDA kernel
torch::Tensor rms_norm_cuda(torch::Tensor x, int num_features, float eps) {
    // Input tensor validation
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(x.dim() == 4, "Input tensor must be 4-dimensional (B, C, D1, D2).");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");

    // Extract dimensions
    int B = x.size(0);
    int C = x.size(1);
    int D1 = x.size(2);
    int D2 = x.size(3);

    // Ensure the num_features argument matches the tensor's C dimension
    TORCH_CHECK(C == num_features, "num_features argument must match x.size(1).");

    // Create an output tensor of the same shape and type as input
    auto out = torch::empty_like(x);

    // Define kernel launch parameters
    const int block_size = 256; // A common and efficient block size
    const int num_groups = B * D1 * D2; // Number of (b, d1, d2) groups to process
    const int num_blocks = num_groups;  // Launch one block per group

    // Launch the CUDA kernel
    rms_norm_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), // Pointer to input data
        out.data_ptr<float>(), // Pointer to output data
        B, C, D1, D2, eps // Dimensions and epsilon value
    );

    // Check for any CUDA errors that occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
}
"""

# C++ source for the PyTorch extension (declares the function)
rms_norm_cpp_source = (
    "torch::Tensor rms_norm_cuda(torch::Tensor x, int num_features, float eps);"
)

# Compile the inline CUDA code using torch.utils.cpp_extension.load_inline
rms_norm_op = load_inline(
    name="rms_norm_op",
    cpp_sources=rms_norm_cpp_source,
    cuda_sources=rms_norm_source,
    functions=["rms_norm_cuda"],
    verbose=False, # Set to True for compilation output
    extra_cflags=["-O3"], # Optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization flags for CUDA compiler, --use_fast_math can improve performance
)


class ModelNew(nn.Module):
    """
    Optimized model that performs RMS Normalization using a custom CUDA kernel.
    This implementation fuses the squaring, mean reduction, epsilon addition,
    square root, and division operations into a single CUDA kernel for efficiency.
