import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math # For kaiming_uniform_ initialization

# Define the custom CUDA kernel for direct 2D convolution
# This kernel is specialized for:
# - stride=1
# - padding=0
# - dilation=1
# - groups=1
# - bias=False
# It directly implements the sliding window operation.
direct_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for direct 2D convolution
// Each thread computes one output pixel (n, c_out, h_out, w_out).
__global__ void direct_conv2d_kernel(const float* x, const float* w, float* out,
                                     int N, int C_in, int H_in, int W_in,
                                     int C_out, int K_H, int K_W,
                                     int H_out, int W_out) {
    int total_output_elements = N * C_out * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map 1D thread index to 4D output coordinates (n, c_out, h_out, w_out)
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out * H_out)) % C_out;
        int n = idx / (W_out * H_out * C_out);

        float sum = 0.0f;

        // Iterate over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel height
            for (int k_h = 0; k_h < K_H; ++k_h) {
                // Iterate over kernel width
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate input feature map coordinates for stride=1, padding=0, dilation=1
                    int h_in = h_out + k_h;
                    int w_in = w_out + k_w;

                    // Input tensor index: (n, c_in, h_in, w_in)
                    // x[n * C_in * H_in * W_in + c_in * H_in * W_in + h_in * W_in + w_in]
                    int x_idx = n * (C_in * H_in * W_in) +
                                c_in * (H_in * W_in) +
                                h_in * W_in +
                                w_in;

                    // Weight tensor index: (c_out, c_in, k_h, k_w)
                    // w[c_out * C_in * K_H * K_W + c_in * K_H * K_W + k_h * K_W + k_w]
                    int w_idx = c_out * (C_in * K_H * K_W) +
                                c_in * (K_H * K_W) +
                                k_h * K_W +
                                k_w;

                    sum += x[x_idx] * w[w_idx];
                }
            }
        }
        // Output tensor index: (n, c_out, h_out, w_out)
        // out[n * C_out * H_out * W_out + c_out * H_out * W_out + h_out * W_out + w_out]
        out[idx] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor direct_conv2d_cuda(torch::Tensor x, torch::Tensor w) {
    // Input x: (N, C_in, H_in, W_in)
    // Weights w: (C_out, C_in, K_H, K_W)

    TORCH_CHECK(x.is_cuda(), "Input tensor x must be a CUDA tensor");
    TORCH_CHECK(w.is_cuda(), "Weight tensor w must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "Input tensor x must be 4D (N, C_in, H_in, W_in)");
    TORCH_CHECK(w.dim() == 4, "Weight tensor w must be 4D (C_out, C_in, K_H, K_W)");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor x must be float32");
    TORCH_CHECK(w.dtype() == torch::kFloat32, "Weight tensor w must be float32");


    int N = x.size(0);
    int C_in = x.size(1);
