#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel for masked cumulative sum along dimension 1 (columns)
// Each block processes one row.
// Inside each block, thread 0 performs a sequential cumulative sum for that row.
__global__ void masked_cumsum_kernel(const float* x_ptr, const unsigned char* mask_ptr, float* out_ptr, int rows, int cols) {
    int row_idx = blockIdx.x; // Each block is responsible for one row

    if (row_idx < rows) {
        // Only the first thread in the block performs the sequential scan for the entire row.
        // This is a simple fusion strategy. For very long rows, a parallel scan within the row
        // (potentially multi-block) would be faster, but significantly more complex to implement.
        if (threadIdx.x == 0) {
            float current_sum = 0.0f;
            int row_start_idx = row_idx * cols;
            for (int col_idx = 0; col_idx < cols; ++col_idx) {
                int global_idx = row_start_idx + col_idx;
                // Apply mask: if mask is true (non-zero), use x[idx], otherwise use 0.0f
                float val = mask_ptr[global_idx] ? x_ptr[global_idx] : 0.0f;
                current_sum += val;
                out_ptr[global_idx] = current_sum;
            }
        }
    }
}

