conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove

// Helper function to get 5D index from linear index
// This assumes row-major order (N, C, D, H, W)
__device__ void get_indices_5d(long linear_idx,
                               long N, long C, long D, long H, long W,
                               long* n, long* c, long* d, long* h, long* w) {
    *w = linear_idx % W;
    linear_idx /= W;
    *h = linear_idx % H;
    linear_idx /= H;
    *d = linear_idx % D;
    linear_idx /= D;
    *c = linear_idx % C;
    linear_idx /= C;
    *n = linear_idx;
}

// Helper function to get linear index from 5D index
__device__ long get_linear_idx_5d(long n, long c, long d, long h, long w,
                                  long N, long C, long D, long H, long W) {
    return n * C * D * H * W + c * D * H * W + d * H * W + h * W + w;
}


__global__ void conv_transpose3d_kernel(const float* input_data,
                                        const float* weight_data,
                                        float* output_data,
                                        long N, long C_in, long D_in, long H_in, long W_in,
                                        long C_out, long K_D, long K_H, long K_W,
                                        long D_out, long H_out, long W_out) {
    long idx = blockIdx.x * blockDim.x + threadIdx.x;

    long total_output_elements = N * C_out * D_out * H_out * W_out;

    if (idx < total_output_elements) {
        long n_out, c_out, d_out, h_out, w_out;
        get_indices_5d(idx, N, C_out, D_out, H_out, W_out, &n_out, &c_out, &d_out, &h_out, &w_out);

        float sum = 0.0f;

        // Iterate over input channels
        for (long c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel dimensions
            for (long kd = 0; kd < K_D; ++kd) {
                for (long kh = 0; kh < K_H; ++kh) {
                    for (long kw = 0; kw < K_W; ++kw) {
                        // Calculate corresponding input coordinates
                        // For ConvTranspose3d (stride=1, padding=0, output_padding=0),
                        // an output pixel (d_out, h_out, w_out) receives contributions
                        // from input pixels (d_in, h_in, w_in) such that:
                        // d_out = d_in + kd
                        // h_out = h_in + kh
                        // w_out = w_in + kw
                        // So, d_in = d_out - kd, etc.
                        long d_in = d_out - kd;
                        long h_in = h_out - kh;
                        long w_in = w_out - kw;

                        // Check if input coordinates are within bounds
                        if (d_in >= 0 && d_in < D_in &&
                            h_in >= 0 && h_in < H_in &&
                            w_in >= 0 && w_in < W_in) {

                            // Get input value
                            long input_linear_idx = get_linear_idx_5d(n_out, c_in, d_in, h_in, w_in,
                                                                      N, C_in, D_in, H_in, W_in);
                            float input_val = input_data[input_linear_idx];

                            // Get weight value
                            // Weight tensor layout for ConvTranspose3d (groups=1): (C_in, C_out, K_D, K_H, K_W)
                            long weight_linear_idx = c_in * C_out * K_D * K_H * K_W +
                                                     c_out * K_D * K_H * K_W +
                                                     kd * K_H * K_W +
                                                     kh * K_W +
                                                     kw;
                            float weight_val = weight_data[weight_linear_idx];

                            sum += input_val * weight_val;
                        }
                    }
                }
            }
        }
        output_data[idx] = sum;
    }
}

torch::Tensor conv_transpose3d_cuda_forward(torch::Tensor input, torch::Tensor weight) {
    // Ensure tensors are on CUDA and are float32
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
