import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for a simplified ConvTranspose3d.
# This kernel implements a ConvTranspose3d with the following assumptions:
# - stride=(1, 1, 1)
# - padding=(0, 0, 0)
# - output_padding=(0, 0, 0)
# - groups=1
# - bias=False
# It computes each output element by iterating over input channels and kernel elements.
# This is a direct, naive implementation and is unlikely to outperform cuDNN for general cases.
simplified_conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper function to get 5D tensor element from input
__device__ float get_input_val(const float* input, int n, int c_in, int d_in, int h_in, int w_in,
                               int C_in, int D_in, int H_in, int W_in) {
    if (d_in >= 0 && d_in < D_in &&
        h_in >= 0 && h_in < H_in &&
        w_in >= 0 && w_in < W_in) {
        return input[n * (C_in * D_in * H_in * W_in) +
                     c_in * (D_in * H_in * W_in) +
                     d_in * (H_in * W_in) +
                     h_in * W_in +
                     w_in];
    }
    return 0.0f; // Out of bounds input contributes zero
}

// Helper function to get 5D weight element
__device__ float get_weight_val(const float* weight, int c_in, int c_out, int k_d, int k_h, int k_w,
                                int C_out, int K_d, int K_h, int K_w) {
    // PyTorch's ConvTranspose3d weight layout for groups=1: (C_in, C_out, K_d, K_h, K_w)
    return weight[c_in * (C_out * K_d * K_h * K_w) +
                  c_out * (K_d * K_h * K_w) +
                  k_d * (K_h * K_w) +
                  k_h * K_w +
                  k_w];
}


__global__ void simplified_conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K_d, int K_h, int K_w) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= N * C_out * D_out * H_out * W_out) {
        return;
    }

    // Deconstruct idx to output coordinates (N, C_out, D_out, H_out, W_out)
    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int d_out = (idx / (W_out * H_out)) % D_out;
    int c_out = (idx / (W_out * H_out * D_out)) % C_out;
    int n = idx / (W_out * H_out * D_out * C_out);

    float sum = 0.0f;

    // Iterate over input channels and kernel dimensions
    // For ConvTranspose3d (stride=1, padding=0), an output element (d_out, h_out, w_out)
    // receives contributions from input elements (d_in, h_in, w_in)
    // where d_in = d_out - k_d, h_in = h_out - k_h, w_in = w_out - k_w
    // and k_d, k_h, k_w are kernel indices.
    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int k_d = 0; k_d < K_d; ++k_d) {
            for (int k_h = 0; k_h < K_h; ++k_h) {
                for (int k_w = 0; k_w < K_w; ++k_w) {
                    int d_in = d_out - k_d;
                    int h_in = h_out - k_h;
                    int w_in = w_out - k_w;

                    sum += get_input_val(input, n, c_in, d_in, h_in, w_in, C_in, D_in, H_in, W_in) *
                           get_weight_val(weight, c_in, c_out, k_d, k_h, k_w, C_out, K_d, K_h, K_w);
                }
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor simplified_conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int K_d, int K_h, int K_w,
    int D_out, int H_out, int W_out) {

    // Input shape: (N, C_in, D_in, H_in, W_in)
    // Weight shape: (C_in, C_out, K_d, K_h, K_w)
    // Output shape: (N, C_out, D_out, H_out, W_out)

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
