    - output_padding=(0, 0, 0)
    - groups=1
    - bias=False
    For other configurations, the original nn.ConvTranspose3d should be used or
    the custom kernel needs significant generalization.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        # kernel_size is (kernel_depth, kernel_width, kernel_height)
        self.kernel_depth, self.kernel_width, self.kernel_height = kernel_size

        # Assertions for the simplified kernel's assumptions
        if stride != (1, 1, 1):
            raise ValueError("Custom kernel only supports stride=(1, 1, 1)")
        if padding != (0, 0, 0):
