        if bias:
            raise ValueError("Custom kernel does not support bias")

        # Initialize weights similar to nn.ConvTranspose3d
        # PyTorch ConvTranspose3d weight shape: (in_channels, out_channels // groups, kernel_depth, kernel_height, kernel_width)
        # For groups=1, this is (in_channels, out_channels, kernel_depth, kernel_height, kernel_width)
        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels, self.kernel_depth, self.kernel_height, self.kernel_width
        ))
        nn.init.kaiming_uniform_(self.weight, a=5**0.5) # Initialize weights

        self.simplified_conv_transpose3d_cuda = simplified_conv_transpose3d.simplified_conv_transpose3d_cuda

