        D_out = D_in + self.kernel_depth - 1
        H_out = H_in + self.kernel_height - 1
        W_out = W_in + self.kernel_width - 1

        # Ensure input and weight are on CUDA and contiguous
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        return self.simplified_conv_transpose3d_cuda(
            x,
            weight,
            self.kernel_depth, self.kernel_height, self.kernel_width, # K_d, K_h, K_w
            D_out, H_out, W_out
        )

