conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove in final version

// Helper for 4D tensor indexing (N, C, H, W)
// Input: (N, C_in, H_in, W_in)
__device__ __forceinline__ int get_input_idx(int n, int c, int h, int w,
                                             int C_in, int H_in, int W_in) {
    return n * C_in * H_in * W_in + c * H_in * W_in + h * W_in + w;
}

// Helper for 4D weight indexing (C_in, C_out, K_H, K_W)
__device__ __forceinline__ int get_weight_idx(int c_in, int c_out, int k_h, int k_w,
                                              int C_out, int K_H, int K_W) {
    return c_in * C_out * K_H * K_W + c_out * K_H * K_W + k_h * K_W + k_w;
}

// Helper for 4D output indexing (N, C_out, H_out, W_out)
__device__ __forceinline__ int get_output_idx(int n, int c, int h, int w,
                                              int C_out, int H_out, int W_out) {
    return n * C_out * H_out * W_out + c * H_out * W_out + h * W_out + w;
}


__global__ void conv_transpose2d_kernel(const float* input,
                                        const float* weight,
                                        const float* bias,
                                        float* output,
                                        int N, int C_in, int H_in, int W_in,
                                        int C_out, int K_H, int K_W,
                                        int S_H, int S_W, int P_H, int P_W,
                                        int H_out, int W_out,
                                        bool has_bias) {
    // Each thread computes one output pixel (n, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int total_output_elements = N * C_out * H_out * W_out;
    if (idx >= total_output_elements) {
        return;
    }

    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c_out = (idx / (W_out * H_out)) % C_out;
    int n = idx / (W_out * H_out * C_out);

    float sum = 0.0f;

    // Iterate over input channels and kernel spatial dimensions
    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int k_h = 0; k_h < K_H; ++k_h) {
            for (int k_w = 0; k_w < K_W; ++k_w) {
                // Calculate corresponding input spatial coordinates
                // h_out = h_in * S_H - P_H + k_h
                // w_out = w_in * S_W - P_W + k_w
                // So, h_in = (h_out + P_H - k_h) / S_H
                // w_in = (w_out + P_W - k_w) / S_W

                int h_in_candidate = h_out + P_H - k_h;
                int w_in_candidate = w_out + P_W - k_w;

                // Check if the candidate input coordinates are valid and align with stride
                // For stride=1, % S_H == 0 is always true.
                // For stride > 1, this check is crucial.
                if (h_in_candidate >= 0 && h_in_candidate % S_H == 0 &&
                    w_in_candidate >= 0 && w_in_candidate % S_W == 0) {

                    int h_in = h_in_candidate / S_H;
                    int w_in = w_in_candidate / S_W;

                    // Check if input coordinates are within bounds
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        sum += input[get_input_idx(n, c_in, h_in, w_in, C_in, H_in, W_in)] *
                               weight[get_weight_idx(c_in, c_out, k_h, k_w, C_out, K_H, K_W)];
                    }
                }
            }
        }
    }

    if (has_bias) {
        sum += bias[c_out];
    }

    output[get_output_idx(n, c_out, h_out, w_out, C_out, H_out, W_out)] = sum;
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input,
                                    torch::Tensor weight,
                                    torch::Tensor bias_opt, // Use _opt for optional
                                    int stride_h, int stride_w,
                                    int padding_h, int padding_w) {
    // Ensure input is on CUDA and is float
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
