        TORCH_CHECK(bias_opt.is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias_opt.dtype() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias_opt.numel() == weight.size(1), "bias size must match out_channels");
    }

