    // Ensure output dimensions are positive
    TORCH_CHECK(H_out > 0 && W_out > 0, "Calculated output dimensions must be positive.");

    // Create output tensor
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    int total_output_elements = N * C_out * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

