from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication (C = A.T @ B)
# A is expected to be of shape (K, M)
# B is expected to be of shape (K, N)
# The result C will be of shape (M, N)
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for C = A.T @ B
// A_ptr: pointer to tensor A (K, M)
// B_ptr: pointer to tensor B (K, N)
// C_ptr: pointer to tensor C (M, N)
// M_dim: number of rows in A.T (and C)
// K_dim: number of columns in A.T (and rows in B)
// N_dim: number of columns in B (and C)
__global__ void matmul_kernel(const float* A_ptr, const float* B_ptr, float* C_ptr, int M_dim, int K_dim, int N_dim) {
    // Calculate global row and column indices for the output matrix C
    int row = blockIdx.y * blockDim.y + threadIdx.y; // Global row index for C
    int col = blockIdx.x * blockDim.x + threadIdx.x; // Global col index for C

    if (row < M_dim && col < N_dim) {
        float sum = 0.0f;
        for (int k = 0; k < K_dim; ++k) {
            // C[row, col] = sum(A.T[row, k] * B[k, col])
            // A.T[row, k] is equivalent to A[k, row]
            // Assuming A_ptr is a row-major tensor of shape (K_dim, M_dim),
            // A[k, row] is accessed at A_ptr[k * M_dim + row]
            // Assuming B_ptr is a row-major tensor of shape (K_dim, N_dim),
            // B[k, col] is accessed at B_ptr[k * N_dim + col]
            sum += A_ptr[k * M_dim + row] * B_ptr[k * N_dim + col];
        }
        // Assuming C_ptr is a row-major tensor of shape (M_dim, N_dim),
        // C[row, col] is stored at C_ptr[row * N_dim + col]
        C_ptr[row * N_dim + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous and on CUDA device.
    // The example's get_inputs function places tensors on CUDA,
    // so we primarily ensure contiguity here.
    A = A.contiguous();
    B = B.contiguous();

