    // A has shape (K_orig, M_orig)
    // B has shape (K_orig, N_orig)
    // The operation is A.T @ B, which means (M_orig, K_orig) @ (K_orig, N_orig)
    // The output C will have shape (M_orig, N_orig)

    int M_dim = A.size(1); // M_orig: rows of A.T (and C)
    int K_dim = A.size(0); // K_orig: columns of A.T (and rows of B)
    int N_dim = B.size(1); // N_orig: columns of B (and C)

