    auto C = torch::zeros({M_dim, N_dim}, A.options());

    // Define grid and block dimensions for the kernel launch.
    // We use a 2D grid and 2D block, where each thread computes one element of C.
    const int TILE_DIM = 32; // A common block dimension size, e.g., 32x32 threads per block
    dim3 block_size(TILE_DIM, TILE_DIM);

    // Calculate grid dimensions to cover the entire output matrix C (M_dim, N_dim)
    dim3 grid_size((N_dim + block_size.x - 1) / block_size.x, (M_dim + block_size.y - 1) / block_size.y);

    // Launch the custom CUDA kernel
    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M_dim, K_dim, N_dim
    );

    return C;
}
