# Define the custom CUDA kernel for ConvTranspose2d
conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove in production

// CUDA kernel for ConvTranspose2d
// This kernel computes each output pixel by iterating over relevant input pixels and kernel elements.
// It handles stride, padding, dilation, and groups.
// It assumes no bias is used, consistent with the provided model architecture.
__global__ void conv_transpose2d_kernel(
    const float* x_data, const float* w_data, float* out_data,
    int N, int C_in, int H_in, int W_in,
    int C_out_total, int K_H, int K_W,
    int S_H, int S_W, int P_H, int P_W, int D_H, int D_W, int G,
    int H_out, int W_out) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of elements in the output tensor
    long long num_elements = (long long)N * C_out_total * H_out * W_out;

    // Check if thread index is within bounds
    if (idx >= num_elements) {
        return;
    }

    // Deconstruct global index to batch (n), output channel (c_out), output height (h_out), output width (w_out)
    int n = idx / (C_out_total * H_out * W_out);
    int rem = idx % (C_out_total * H_out * W_out);
    int c_out = rem / (H_out * W_out);
    rem %= (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    float sum = 0.0f;

    // Determine group for this output channel
    // C_out_per_group is the number of output channels handled by each group
    int C_out_per_group = C_out_total / G;
    int group_idx = c_out / C_out_per_group; // Which group this output channel belongs to
    int c_out_in_group = c_out % C_out_per_group; // Index of this output channel within its group

    // Iterate over kernel dimensions (k_h, k_w)
    for (int k_h = 0; k_h < K_H; ++k_h) {
        for (int k_w = 0; k_w < K_W; ++k_w) {
            // Calculate the corresponding input coordinates (h_in, w_in)
            // The relationship for ConvTranspose2d is:
            // h_out = h_in * S_H - P_H + k_h * D_H
            // w_out = w_in * S_W - P_W + k_w * D_W
            // We need to find h_in, w_in given h_out, w_out, k_h, k_w.
            // Rearranging:
            // h_in_candidate_num = h_out + P_H - k_h * D_H
            // w_in_candidate_num = w_out + P_W - k_w * D_W

            int h_in_candidate_num = h_out + P_H - k_h * D_H;
            int w_in_candidate_num = w_out + P_W - k_w * D_W;

            // Check if the candidate input coordinates are valid:
            // 1. Must be non-negative.
            // 2. Must be perfectly divisible by the stride (S_H, S_W).
            if (h_in_candidate_num >= 0 && h_in_candidate_num % S_H == 0 &&
                w_in_candidate_num >= 0 && w_in_candidate_num % S_W == 0) {

                int h_in = h_in_candidate_num / S_H;
                int w_in = w_in_candidate_num / S_W;

                // Check if the calculated input coordinates are within the actual input tensor bounds
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    // Iterate over input channels for this specific group
                    int C_in_per_group = C_in / G;
                    for (int c_in_in_group = 0; c_in_in_group < C_in_per_group; ++c_in_in_group) {
                        // Calculate the global input channel index
                        int c_in = group_idx * C_in_per_group + c_in_in_group;

                        // Get input value: x[n, c_in, h_in, w_in]
                        // Input tensor layout: (N, C_in, H_in, W_in)
                        long long x_offset = (long long)n * C_in * H_in * W_in +
                                             (long long)c_in * H_in * W_in +
                                             (long long)h_in * W_in +
                                             (long long)w_in;
                        float input_val = x_data[x_offset];

                        // Get weight value: weight[c_in, c_out_in_group, k_h, k_w]
                        // Weight tensor layout (PyTorch's ConvTranspose2d): (C_in, C_out_per_group, K_H, K_W)
                        long long w_offset = (long long)c_in * C_out_per_group * K_H * K_W +
                                             (long long)c_out_in_group * K_H * K_W +
                                             (long long)k_h * K_W +
                                             (long long)k_w;
                        float weight_val = w_data[w_offset];

                        sum += input_val * weight_val;
                    }
                }
            }
        }
    }
    out_data[idx] = sum;
