// C++ wrapper function to be called from Python
torch::Tensor conv_transpose2d_cuda(
    const torch::Tensor& x, const torch::Tensor& weight,
    int S_H, int S_W, int P_H, int P_W, int D_H, int D_W, int G,
    int C_out_total) { // C_out_total is the total number of output channels

    // Basic input validation
    TORCH_CHECK(x.is_cuda(), "Input tensor x must be on CUDA!");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA!");
    TORCH_CHECK(x.is_floating_point(), "Input tensor x must be of float type!");
    TORCH_CHECK(weight.is_floating_point(), "Weight tensor must be of float type!");
    TORCH_CHECK(x.dim() == 4, "Input tensor x must be 4D (N, C_in, H_in, W_in)!");
    TORCH_CHECK(weight.dim() == 4, "Weight tensor must be 4D (C_in, C_out_per_group, K_H, K_W)!");

    // Extract input dimensions
    int N = x.size(0);
    int C_in = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    // Extract weight dimensions
    // weight.size(0) corresponds to C_in
    // weight.size(1) corresponds to C_out_per_group
    int K_H = weight.size(2);
    int K_W = weight.size(3);

    // Validate group parameters and tensor shapes
    TORCH_CHECK(C_in % G == 0, "Input channels (C_in) must be divisible by groups (G)!");
    TORCH_CHECK(C_out_total % G == 0, "Total output channels (C_out_total) must be divisible by groups (G)!");
    TORCH_CHECK(weight.size(0) == C_in, "Weight tensor's C_in dimension mismatch with input C_in!");
    TORCH_CHECK(weight.size(1) == (C_out_total / G), "Weight tensor's C_out_per_group dimension mismatch!");

    // Calculate output dimensions (assuming output_padding = 0, which is PyTorch's default if not specified)
    // Formula: H_out = (H_in - 1) * S_H - 2 * P_H + D_H * (K_H - 1) + output_padding_H + 1
    // With output_padding_H = 0:
    int H_out = (H_in - 1) * S_H - 2 * P_H + D_H * (K_H - 1) + 1;
    int W_out = (W_in - 1) * S_W - 2 * P_W + D_W * (K_W - 1) + 1;

    // Create the output tensor, ensuring it's on the same device and has the same dtype as the input
    auto out = torch::zeros({N, C_out_total, H_out, W_out}, x.options());

    // Configure kernel launch parameters
    const int block_size = 256; // A common block size for CUDA kernels
    long long num_elements = (long long)N * C_out_total * H_out * W_out;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), weight.data_ptr<float>(), out.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out_total, K_H, K_W,
        S_H, S_W, P_H, P_W, D_H, D_W, G,
        H_out, W_out);

    // Check for any CUDA errors that might have occurred during kernel execution
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in conv_transpose2d_kernel: %s\\n", cudaGetErrorString(err));
    }

    return out;
}
"""

conv_transpose2d_cpp_source = (
    "torch::Tensor conv_transpose2d_cuda("
    "const torch::Tensor& x, const torch::Tensor& weight,"
    "int S_H, int S_W, int P_H, int P_W, int D_H, int D_W, int G,"
