from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for lower triangular matrix multiplication
lower_triangular_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// TILE_DIM must be a multiple of warp size (32) for optimal performance
#define TILE_DIM 32

__global__ void lower_triangular_matmul_tiled_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    // Thread coordinates within the block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column for C element computed by this thread
    int row = blockIdx.y * TILE_DIM + ty;
    int col = blockIdx.x * TILE_DIM + tx;

    float sum = 0.0f;

    // Only compute if the target C[row][col] is within bounds and in the lower triangular part
    if (row < N && col < N && row >= col) {
        // Iterate over blocks in the K dimension
        // k_block iterates from 0 to N/TILE_DIM - 1
        for (int k_block = 0; k_block < (N + TILE_DIM - 1) / TILE_DIM; ++k_block) {
            // Global indices for loading A_ik and B_kj
            int a_row_global = row;
            int a_col_global = k_block * TILE_DIM + tx; // k for A
            int b_row_global = k_block * TILE_DIM + ty; // k for B
            int b_col_global = col;

            // Load A tile into shared memory
            // A_ik is non-zero only if k <= i (a_col_global <= a_row_global)
            if (a_row_global < N && a_col_global < N && a_col_global <= a_row_global) {
                sA[ty][tx] = A[a_row_global * N + a_col_global];
            } else {
                sA[ty][tx] = 0.0f; // Out of bounds or upper triangular part of A
            }

            // Load B tile into shared memory
            // B_kj is non-zero only if k >= j (b_row_global >= b_col_global)
            if (b_row_global < N && b_col_global < N && b_row_global >= b_col_global) {
                sB[ty][tx] = B[b_row_global * N + b_col_global];
            } else {
                sB[ty][tx] = 0.0f; // Out of bounds or upper triangular part of B
            }

            __syncthreads();

            // Perform the dot product for the current tile
            for (int k_local = 0; k_local < TILE_DIM; ++k_local) {
                int current_k_global = k_block * TILE_DIM + k_local;

                // Only add to sum if current_k_global is within the valid range [col, row]
                // This is the core optimization for lower triangular matmul, reducing FLOPs.
                if (current_k_global >= col && current_k_global <= row) {
                    sum += sA[ty][k_local] * sB[k_local][tx];
                }
            }
            __syncthreads(); // Synchronize before next tile load
        }
        C[row * N + col] = sum;
    }
    // If row < col, C[row][col] remains 0 (as C is initialized to zeros)
}
"""

