import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source for custom 1D convolution
custom_conv1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper macro for 3D tensor indexing (N, C, L)
// Assumes row-major order, which PyTorch tensors are typically in for C++ access
#define IDX3D(dim0, dim1, dim2, D1, D2) ((dim0) * (D1) * (D2) + (dim1) * (D2) + (dim2))

__global__ void custom_conv1d_kernel(
    const float* x_ptr,
    const float* weight_ptr,
    const float* bias_ptr, // Can be nullptr if no bias
    float* out_ptr,
    int N, // batch_size
    int C_in,
    int L_in,
    int C_out,
    int K, // kernel_size
    int L_out,
    int stride,
    int dilation
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Each thread computes one element in the output tensor (N, C_out, L_out)
    if (idx >= N * C_out * L_out) {
        return;
    }

    // Map linear index to 3D output coordinates (n, c_out, l_out)
    int n = idx / (C_out * L_out);
    int rem = idx % (C_out * L_out);
    int c_out = rem / L_out;
    int l_out = rem % L_out;

    float sum = 0.0f;

    // Iterate over input channels
    for (int c_in = 0; c_in < C_in; ++c_in) {
        // Iterate over kernel elements
        for (int k = 0; k < K; ++k) {
            // Calculate the corresponding input index
            // For Conv1d with padding=0, l_in = l_out * stride + k * dilation
            int l_in = l_out * stride + k * dilation;

            // Check if input index is within bounds (no padding assumed, so only check upper bound)
            if (l_in >= 0 && l_in < L_in) {
                sum += x_ptr[IDX3D(n, c_in, l_in, C_in, L_in)] *
                       weight_ptr[IDX3D(c_out, c_in, k, C_in, K)];
            }
        }
    }

    // Add bias if present
    if (bias_ptr != nullptr) {
        sum += bias_ptr[c_out];
    }

    out_ptr[IDX3D(n, c_out, l_out, C_out, L_out)] = sum;
