import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with implicit transposes
matmul_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Define the tile dimension for shared memory
#define TILE_DIM 32

__global__ void matmul_transpose_tiled_kernel(const float* A, const float* B, float* C,
                                              int M_out, int K_dim, int N_out,
                                              int A_stride_0, int A_stride_1,
                                              int B_stride_0, int B_stride_1)
{
    // Shared memory for tiles of A and B.
    // sA will temporarily store a TILE_DIM x TILE_DIM tile of A_T (which corresponds to A[k, m]).
    // sB will temporarily store a TILE_DIM x TILE_DIM tile of B_T (which corresponds to B[n, k]).
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    // C is the output matrix of shape (M_out, N_out).
    // Each thread computes one element C[m, n].
    int m = blockIdx.y * TILE_DIM + threadIdx.y; // Global row index in C (0 to M_out-1)
    int n = blockIdx.x * TILE_DIM + threadIdx.x; // Global column index in C (0 to N_out-1)

    float sum = 0.0f;

    // Loop over tiles along the K_dim (the common dimension for matrix multiplication).
    // K_dim is the dimension K from A.T (M, K) and B.T (K, N).
    for (int tile_k = 0; tile_k < (K_dim + TILE_DIM - 1) / TILE_DIM; ++tile_k) {
        // Load a tile of A_T into shared memory (sA).
        // sA[threadIdx.y][threadIdx.x] corresponds to A_T[m, k_local],
        // which means it stores A[k_global_A, m] from the original A tensor.
        int k_global_A = tile_k * TILE_DIM + threadIdx.x; // Global K index for A
        if (m < M_out && k_global_A < K_dim) {
            // Access A[k_global_A, m] using original A's strides
            sA[threadIdx.y][threadIdx.x] = A[k_global_A * A_stride_0 + m * A_stride_1];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros for out-of-bounds access
        }

        // Load a tile of B_T into shared memory (sB).
        // sB[threadIdx.y][threadIdx.x] corresponds to B_T[k_local, n],
        // which means it stores B[n, k_global_B] from the original B tensor.
        int k_global_B = tile_k * TILE_DIM + threadIdx.y; // Global K index for B
        if (n < N_out && k_global_B < K_dim) {
            // Access B[n, k_global_B] using original B's strides
            sB[threadIdx.y][threadIdx.x] = B[n * B_stride_0 + k_global_B * B_stride_1];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros for out-of-bounds access
        }
        __syncthreads(); // Synchronize threads to ensure all data is loaded into shared memory

        // Compute the dot product for the current tile.
        // Each thread computes its part of the sum for C[m, n].
        for (int k_local = 0; k_local < TILE_DIM; ++k_local) {
            sum += sA[threadIdx.y][k_local] * sB[k_local][threadIdx.x];
        }
        __syncthreads(); // Synchronize threads before loading the next tile
    }

    // Write the final computed sum to the global output matrix C.
    if (m < M_out && n < N_out) {
        C[m * N_out + n] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B) {
    // A: Input tensor of shape (K_dim, M_out)
    // B: Input tensor of shape (N_out, K_dim)
    // Output C: Tensor of shape (M_out, N_out)
    int K_dim = A.size(0); // K dimension (common for A.T and B.T)
    int M_out = A.size(1); // M dimension (rows of A.T, rows of C)
    int N_out = B.size(0); // N dimension (rows of B, columns of C)

    // Input validation
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat, "A must be of float32 type");
    TORCH_CHECK(B.scalar_type() == torch::kFloat, "B must be of float32 type");

    // Check for dimension compatibility for A.T @ B.T
    // A.T has shape (M_out, K_dim)
    // B.T has shape (K_dim, N_out)
    // The inner dimension K_dim must match.
    TORCH_CHECK(A.size(0) == B.size(1), "Dimension mismatch: A.size(0) (K) must be equal to B.size(1) (K)");

    // Allocate output tensor C on the GPU, initialized to zeros
    auto C = torch::zeros({M_out, N_out}, A.options());

    // Get strides for the original tensors A (K_dim, M_out) and B (N_out, K_dim).
    // PyTorch tensors are typically row-major.
    int A_stride_0 = A.stride(0); // Stride for the first dimension (K_dim)
    int A_stride_1 = A.stride(1); // Stride for the second dimension (M_out)
    int B_stride_0 = B.stride(0); // Stride for the first dimension (N_out)
    int B_stride_1 = B.stride(1); // Stride for the second dimension (K_dim)

    // Define block and grid dimensions for the kernel launch
    const int TILE_DIM = 32;
    dim3 block_dim(TILE_DIM, TILE_DIM); // Each block is TILE_DIM x TILE_DIM threads
    dim3 grid_dim(
        (N_out + TILE_DIM - 1) / TILE_DIM, // Grid X dimension for N_out (columns of C)
        (M_out + TILE_DIM - 1) / TILE_DIM  // Grid Y dimension for M_out (rows of C)
    );

    // Launch the CUDA kernel
    matmul_transpose_tiled_kernel<<<grid_dim, block_dim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        M_out, K_dim, N_out,
        A_stride_0, A_stride_1,
        B_stride_0, B_stride_1
    );

    return C;
}
"""

# C++ source for the inline compilation, declaring the CUDA function
matmul_transpose_cpp_source = (
    "torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
matmul_transpose_op = load_inline(
    name="matmul_transpose_op",
    cpp_sources=matmul_transpose_cpp_source,
    cuda_sources=matmul_transpose_source,
    functions=["matmul_transpose_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A.T @ B.T)
    using a custom tiled CUDA kernel, fusing the transpose operations
    directly into the matrix multiplication.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the compiled custom CUDA operator as a member
        self.matmul_transpose_op = matmul_transpose_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication A.T @ B.T using the custom CUDA kernel.

        Args:
            A: Input tensor of shape (K, M).
            B: Input tensor of shape (N, K).
               Both A and B must be CUDA float32 tensors.

        Returns:
            Output tensor of shape (M, N).
        """
        # Call the custom CUDA function
        return self.matmul_transpose_op.matmul_transpose_cuda(A, B)

