# Define the custom CUDA kernel for 3D convolution
# This kernel implements a direct 3D convolution.
# It supports arbitrary kernel_size, stride, and padding.
# For simplicity and to keep the kernel manageable, it assumes:
# - Dilation = (1, 1, 1)
# - Groups = 1
# - No bias (bias is ignored even if provided in __init__)
#
# While this custom kernel demonstrates the process of replacing a PyTorch operator,
# it is generally unlikely to outperform highly optimized cuDNN implementations
# for general-purpose convolutions. Potential speedups might be found in very
# specific, constrained scenarios or through operator fusion with subsequent operations.
conv3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, if needed

// CUDA kernel for 3D convolution (direct implementation)
// Assumes dilation=1, groups=1, no bias
__global__ void conv3d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K_d, int K_h, int K_w,
    int S_d, int S_h, int S_w, // Stride
    int P_d, int P_h, int P_w, // Padding
    int D_out, int H_out, int W_out // Output dimensions
) {
    // Each thread computes one output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    long long total_output_elements = (long long)N * C_out * D_out * H_out * W_out;

    if (idx < total_output_elements) {
        // Deconstruct idx to N, C_out, D_out, H_out, W_out indices
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int d_out = idx % D_out;
        idx /= D_out;
        int c_out = idx % C_out;
        idx /= C_out;
        int n = idx;

        float acc = 0.0f;

        // Iterate over input channels and kernel dimensions
        for (int c_in = 0; c_in < C_in; ++c_in) {
            for (int k_d = 0; k_d < K_d; ++k_d) {
                for (int k_h = 0; k_h < K_h; ++k_h) {
                    for (int k_w = 0; k_w < K_w; ++k_w) {
                        // Calculate input indices with stride and padding
                        // d_in = d_out * S_d + k_d * D_d - P_d (for dilation D_d)
                        // Since dilation is assumed 1:
                        int d_in = d_out * S_d + k_d - P_d;
                        int h_in = h_out * S_h + k_h - P_h;
                        int w_in = w_out * S_w + k_w - P_w;

                        // Check bounds for input (handle padding by skipping out-of-bounds reads)
                        if (d_in >= 0 && d_in < D_in &&
                            h_in >= 0 && h_in < H_in &&
                            w_in >= 0 && w_in < W_in) {
                            // Input tensor index: N, C_in, D_in, H_in, W_in
                            // Assuming NCHWD memory layout
                            long long input_idx = (long long)n * (C_in * D_in * H_in * W_in) +
                                                  (long long)c_in * (D_in * H_in * W_in) +
                                                  (long long)d_in * (H_in * W_in) +
                                                  (long long)h_in * (W_in) +
                                                  (long long)w_in;

                            // Weight tensor index: C_out, C_in, K_d, K_h, K_w
                            // Assuming OICDHW memory layout
                            long long weight_idx = (long long)c_out * (C_in * K_d * K_h * K_w) +
                                                   (long long)c_in * (K_d * K_h * K_w) +
                                                   (long long)k_d * (K_h * K_w) +
                                                   (long long)k_h * (K_w) +
                                                   (long long)k_w;

                            acc += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
            }
        }
        // Store the result
        long long output_store_idx = (long long)n * (C_out * D_out * H_out * W_out) +
                                     (long long)c_out * (D_out * H_out * W_out) +
                                     (long long)d_out * (H_out * W_out) +
                                     (long long)h_out * (W_out) +
                                     (long long)w_out;
        output[output_store_idx] = acc;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor conv3d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int K_d, int K_h, int K_w,
