    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    // Configure kernel launch parameters
    const int block_size = 256; // Standard block size
    long long num_elements = (long long)N * C_out * D_out * H_out * W_out;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv3d_kernel<<<num_blocks, block_size>>>(
