#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min

// Helper function for checking CUDA errors
#define CUDA_CHECK(call)                                                                 \\
    do {                                                                                 \\
        cudaError_t err = call;                                                          \\
        if (err != cudaSuccess) {                                                        \\
            fprintf(stderr, "CUDA error at %s:%d: %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(1);                                                                     \\
        }                                                                                \\
    } while (0)

// Kernel for cumulative product along dimension 1 (columns) for a 2D tensor.
// This kernel implements a parallel prefix product (scan) for each row.
// It handles rows larger than blockDim.x by iterating through segments and
// carrying over the product from previous segments.
__global__ void cumprod_dim1_kernel(const float* x_ptr, float* out_ptr, int M, int N) {
    // Each block processes one row
    int row_idx = blockIdx.x;

    if (row_idx < M) {
        // Pointers to the start of the current row in global memory
        const float* row_in_ptr = x_ptr + row_idx * N;
        float* row_out_ptr = out_ptr + row_idx * N;

        // Shared memory for block-local prefix product.
        // s_data[0...blockDim.x-1] for segment data, s_data[blockDim.x] for carry-over product.
        extern __shared__ float s_data[]; 

        // Initialize the carry-over product for the first segment
        if (threadIdx.x == 0) {
            s_data[blockDim.x] = 1.0f; 
        }
        __syncthreads(); // Ensure initialization is complete before any thread proceeds

        // Loop through segments of the row
        for (int segment_start_col = 0; segment_start_col < N; segment_start_col += blockDim.x) {
            int tid = threadIdx.x;
            int current_col = segment_start_col + tid;

            // Load data into shared memory.
            // Pad with 1.0f (identity for product) for elements outside the row bounds.
            float val = 1.0f; 
            if (current_col < N) {
                val = row_in_ptr[current_col];
            }
            s_data[tid] = val;
            __syncthreads(); // Ensure all threads have loaded their data into shared memory

            // Perform in-block prefix product (Hillis-Steele variant).
            // After this loop, s_data[tid] will hold the prefix product up to tid
            // within the current segment (relative to the segment start).
            for (int offset = 1; offset < blockDim.x; offset *= 2) {
                if (tid >= offset) {
                    s_data[tid] *= s_data[tid - offset];
                }
                __syncthreads(); // Synchronize after each step of the scan
            }

            // Get the carried product from previous segments.
            // This value was updated by thread 0 in the previous iteration and is in shared memory.
            float carried_product = s_data[blockDim.x]; 
            __syncthreads(); // Ensure all threads read the same, up-to-date carried_product

            // Combine the carried product with the current segment's prefix products.
            if (current_col < N) {
                row_out_ptr[current_col] = carried_product * s_data[tid];
            }
            __syncthreads(); // Ensure all global memory writes are complete before updating the carry-over product

            // Update the carry-over product for the next segment.
            // The total product of the current segment is s_data[blockDim.x - 1]
            // (due to padding with 1.0f, this will correctly represent the product of valid elements).
            // Only thread 0 updates the shared carry-over product.
            if (tid == 0) {
                s_data[blockDim.x] *= s_data[blockDim.x - 1];
            }
            __syncthreads(); // Ensure the carry-over product is updated and visible for the next iteration
        }
    }
}

torch::Tensor cumprod_cuda_forward(torch::Tensor x, int dim) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
