// CUDA kernel for fused L1 normalization
__global__ void l1_norm_kernel(const float* x_ptr, float* out_ptr, int batch_size, int dim) {
    // Each block processes one row
    int row_idx = blockIdx.x;

    if (row_idx >= batch_size) {
        return;
    }

    // Shared memory for reduction within the block
    // Declared as extern __shared__ to allow dynamic sizing at kernel launch
    extern __shared__ float s_partial_sums[]; 

    float thread_row_sum = 0.0f;

    // Phase 1: Compute partial sum of absolute values for the row
    // Each thread processes multiple elements if dim > blockDim.x
    for (int col_idx = threadIdx.x; col_idx < dim; col_idx += blockDim.x) {
        thread_row_sum += fabsf(x_ptr[row_idx * dim + col_idx]);
    }

    // Store thread's partial sum in shared memory
    s_partial_sums[threadIdx.x] = thread_row_sum;
    __syncthreads(); // Synchronize to ensure all partial sums are written

    // Phase 2: Perform reduction in shared memory
    // This is a standard tree reduction pattern
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_partial_sums[threadIdx.x] += s_partial_sums[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each step of reduction
    }

    // The total sum for the row is now in s_partial_sums[0]
    float total_row_sum = s_partial_sums[0];

    // Calculate the mean for the row
    float mean_val = total_row_sum / dim;

    // Phase 3: Perform element-wise division
    // Each thread processes multiple elements if dim > blockDim.x
    for (int col_idx = threadIdx.x; col_idx < dim; col_idx += blockDim.x) {
