# Define the custom CUDA kernel for Group Normalization
group_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For rsqrtf and fmaxf

// Define block size for reduction kernels. Must be a power of 2.
#define GN_BLOCK_SIZE 256

// Kernel 1: Compute mean and inverse standard deviation for each group
// Each block processes one (batch_idx, group_idx) pair.
__global__ void group_norm_mean_var_kernel(
    const float* x,
    float* mean_buffer,
    float* rstd_buffer,
    int N, int C, int H, int W, int G, float epsilon) {

    // Linear index for (batch_idx, group_idx)
    int group_batch_idx = blockIdx.x; 
    int batch_idx = group_batch_idx / G;
    int group_idx = group_batch_idx % G;

    int C_per_G = C / G;
    long long group_elements = (long long)C_per_G * H * W;

    // Shared memory for reduction within the block
    // Assumes blockDim.x <= GN_BLOCK_SIZE
    __shared__ float s_sum[GN_BLOCK_SIZE];
    __shared__ float s_sum_sq[GN_BLOCK_SIZE];

    float current_sum = 0.0f;
    float current_sum_sq = 0.0f;

    // Each thread processes multiple elements in a grid-stride loop
    // to cover all elements within its assigned group.
    for (long long offset = threadIdx.x; offset < group_elements; offset += blockDim.x) {
        long long c_offset = offset / ((long long)H * W);
        long long h_offset = (offset / W) % H;
        long long w_offset = offset % W;

        long long current_c = (long long)group_idx * C_per_G + c_offset;

        // Calculate global index for x (x is (N, C, H, W))
        long long x_idx = (long long)batch_idx * C * H * W + current_c * H * W + h_offset * W + w_offset;
        float x_val = x[x_idx];

        current_sum += x_val;
        current_sum_sq += x_val * x_val;
    }

    s_sum[threadIdx.x] = current_sum;
    s_sum_sq[threadIdx.x] = current_sum_sq;
    __syncthreads();

    // Parallel reduction in shared memory to sum up contributions from all threads in the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Only the first thread in the block writes the final mean and rstd to global memory
    if (threadIdx.x == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];

        float mean = total_sum / group_elements;
        float variance = (total_sum_sq / group_elements) - (mean * mean);

        // Ensure variance is non-negative due to potential floating point inaccuracies
        variance = fmaxf(0.0f, variance);

        float rstd = rsqrtf(variance + epsilon);

        mean_buffer[group_batch_idx] = mean;
        rstd_buffer[group_batch_idx] = rstd;
    }
}

// Kernel 2: Normalize and apply affine transform
// Each thread processes one element of the output tensor.
__global__ void group_norm_normalize_kernel(
    const float* x,
    const float* mean_buffer,
    const float* rstd_buffer,
    const float* gamma,
    const float* beta,
    float* out,
    int N, int C, int H, int W, int G) {

    long long total_elements = (long long)N * C * H * W;
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate N, C, H, W indices from the linear global index
        long long n = idx / ((long long)C * H * W);
        long long c = (idx / ((long long)H * W)) % C;
        long long h = (idx / W) % H;
        long long w = idx % W;

        int C_per_G = C / G;
        int group_idx = c / C_per_G;

        // Index into the mean/rstd buffers
        int group_buffer_idx = n * G + group_idx;

        float mean = mean_buffer[group_buffer_idx];
        float rstd = rstd_buffer[group_buffer_idx];

        float x_val = x[idx];
        float gamma_val = gamma[c]; // gamma and beta are per-channel
        float beta_val = beta[c];

        float normalized_val = (x_val - mean) * rstd;
        out[idx] = gamma_val * normalized_val + beta_val;
    }
}

// C++ wrapper function to call the CUDA kernels
torch::Tensor group_norm_cuda_forward(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    int N, int C, int H, int W, int G, float epsilon) {

