                    // Check bounds for input coordinates (handle padding implicitly by skipping out-of-bounds)
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        // Input tensor layout: (N, C_in, H_in, W_in)
                        // input[n, c_in, h_in, w_in]
                        int input_idx = n * (C_in * H_in * W_in) +
                                        c_in * (H_in * W_in) +
                                        h_in * W_in +
                                        w_in;

                        // Weight tensor layout: (C_out, C_in, K_H, K_W)
                        // weight[c_out, c_in, k_h, k_w]
                        int weight_idx = c_out * (C_in * K_H * K_W) +
                                         c_in * (K_H * K_W) +
                                         k_h * K_W +
                                         k_w;

                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        // Add bias if enabled
        if (has_bias) {
            sum += bias[c_out];
        }

        // Output tensor layout: (N, C_out, H_out, W_out)
        // output[n, c_out, h_out, w_out]
        int output_idx = n * (C_out * H_out * W_out) +
                         c_out * (H_out * W_out) +
                         h_out * W_out +
                         w_out;

