    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    const int block_size = 256; // Standard block size for CUDA kernels
    int total_output_elements = N * C_out * H_out * W_out;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    bool has_bias = bias_tensor.numel() > 0;
    const float* bias_ptr = has_bias ? bias_tensor.data_ptr<float>() : nullptr;

    // Launch the CUDA kernel
    conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K_H, K_W,
        H_out, W_out,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        has_bias
    );

    return output;
}
