// CUDA kernel for 3D Average Pooling
__global__ void avg_pool3d_kernel(
    const float* input,
    float* output,
    int N, int C,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kernel_size,
    int stride,
    int padding,
    float inv_kernel_volume) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure thread index is within the bounds of the total output elements
    if (idx < N * C * D_out * H_out * W_out) {
        // Convert flat idx to 5D output coordinates (n, c, d_out, h_out, w_out)
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int d_out = (idx / (W_out * H_out)) % D_out;
        int c = (idx / (W_out * H_out * D_out)) % C;
        int n = idx / (W_out * H_out * D_out * C);

        // Calculate the starting coordinates of the receptive field in the input tensor
        // These coordinates are relative to the padded input, so they can be negative
        int d_start = d_out * stride - padding;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        float sum = 0.0f;
        // Iterate over the kernel window
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int d_in = d_start + kd;
                    int h_in = h_start + kh;
                    int w_in = w_start + kw;

                    // Check if the current kernel position is within the bounds of the original input tensor
                    if (d_in >= 0 && d_in < D_in &&
                        h_in >= 0 && h_in < H_in &&
                        w_in >= 0 && w_in < W_in) {
                        // Calculate linear index for input: input[n, c, d_in, h_in, w_in]
                        // Assuming NCHWD memory layout (PyTorch default for 5D tensors)
                        int input_idx = n * (C * D_in * H_in * W_in) +
                                        c * (D_in * H_in * W_in) +
                                        d_in * (H_in * W_in) +
                                        h_in * W_in +
                                        w_in;
                        sum += input[input_idx];
                    }
                }
            }
        }
        // Calculate linear index for output: output[n, c, d_out, h_out, w_out]
        // Assuming NCHWD memory layout
        int output_idx = n * (C * D_out * H_out * W_out) +
                         c * (D_out * H_out * W_out) +
                         d_out * (H_out * W_out) +
                         h_out * W_out +
                         w_out;

        // Store the averaged result. PyTorch's AvgPool3d divides by kernel_size^3
        // even at borders (when count_include_pad=True, which is the default).
        output[output_idx] = sum * inv_kernel_volume;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor avg_pool3d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride_val,
    int padding) {

    // Input validation checks
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input tensor must be of float32 type.");
    TORCH_CHECK(input.dim() == 5, "Input tensor must be 5-dimensional (N, C, D, H, W).");

    // Extract input tensor dimensions
    int N = input.size(0);
    int C = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // Calculate output dimensions based on PyTorch's AvgPool3d formula
    // (input_dim + 2 * padding - kernel_size) / stride + 1
    // Integer division naturally handles the floor operation for positive results.
    int D_out = (D_in + 2 * padding - kernel_size) / stride_val + 1;
    int H_out = (H_in + 2 * padding - kernel_size) / stride_val + 1;
    int W_out = (W_in + 2 * padding - kernel_size) / stride_val + 1;

    // Create the output tensor with the same device and data type as the input
    auto output = torch::zeros({N, C, D_out, H_out, W_out}, input.options());

    // Calculate the inverse of the kernel volume for averaging.
    // This is the divisor for each output element.
    float inv_kernel_volume = 1.0f / (static_cast<float>(kernel_size) * kernel_size * kernel_size);

    // Determine grid and block dimensions for the CUDA kernel launch
    int total_output_elements = N * C * D_out * H_out * W_out;
    const int block_size = 256; // A common block size for CUDA kernels
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    avg_pool3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),    // Pointer to input data
        output.data_ptr<float>(),   // Pointer to output data
        N, C, D_in, H_in, W_in,     // Input dimensions
        D_out, H_out, W_out,        // Output dimensions
        kernel_size, stride_val, padding, // Pooling parameters
        inv_kernel_volume           // Pre-calculated inverse kernel volume
    );

    return output;
}
