conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max

// CUDA kernel for 2D convolution
// This kernel computes a 2D convolution operation with support for
// padding, stride, and dilation. It assumes NCHW input and OIKH weights layout.
// Each thread computes one output element (batch, out_channel, out_height, out_width).
__global__ void conv2d_forward_kernel(
    const float* input,
    const float* weights,
    float* output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K_h, int K_w,
    int S_h, int S_w, // Stride (height, width)
    int P_h, int P_w, // Padding (height, width)
    int D_h, int D_w, // Dilation (height, width)
    int H_out, int W_out // Pre-calculated output dimensions
) {
    // Calculate global index for the current thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of elements in the output tensor
    int total_output_elements = N * C_out * H_out * W_out;

    // Ensure thread operates within bounds of the output tensor
    if (idx < total_output_elements) {
        // Decompose the global index into (batch, out_channel, out_height, out_width) coordinates
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out * H_out)) % C_out;
        int n = idx / (W_out * H_out * C_out);

        float sum = 0.0f; // Accumulator for the current output element

        // Iterate over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel height
            for (int k_h = 0; k_h < K_h; ++k_h) {
                // Iterate over kernel width
                for (int k_w = 0; k_w < K_w; ++k_w) {
                    // Calculate the corresponding input coordinates (h_in, w_in)
                    // considering stride, dilation, and padding.
                    // h_in = h_out * S_h + k_h * D_h - P_h;
                    // w_in = w_out * S_w + k_w * D_w - P_w;
                    int h_in = h_out * S_h + k_h * D_h - P_h;
                    int w_in = w_out * S_w + k_w * D_w - P_w;

                    // Check if the calculated input coordinates are within the valid input tensor bounds.
                    // This implicitly handles zero-padding for elements outside the bounds.
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        // Calculate the linear offset for the input element (NCHW layout)
                        int input_offset = n * (C_in * H_in * W_in) +
                                           c_in * (H_in * W_in) +
                                           h_in * W_in +
                                           w_in;

                        // Calculate the linear offset for the weight element (OIKH layout)
                        int weight_offset = c_out * (C_in * K_h * K_w) +
                                            c_in * (K_h * K_w) +
                                            k_h * K_w +
                                            k_w;

                        // Perform the multiply-add operation
                        sum += input[input_offset] * weights[weight_offset];
                    }
                }
            }
        }
        // Store the accumulated sum into the output tensor at the current thread's index
        output[idx] = sum;
    }
