import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 1D convolution
conv1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max, std::min

// Helper function to calculate output length
// L_out = floor((L_in + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1)
__host__ __device__
int calculate_conv_output_length(int L_in, int K, int S, int P, int D) {
    return (L_in + 2 * P - D * (K - 1) - 1) / S + 1;
}

__global__ void conv1d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int L_in,
    int C_out, int K,
    int S, int P, int D,
    int L_out
) {
    // Each thread computes one element of the output tensor
    int total_elements = N * C_out * L_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) {
        return;
    }

    // Map flat index to (n, c_out, l_out)
    int n = idx / (C_out * L_out);
    int c_out = (idx / L_out) % C_out;
    int l_out = idx % L_out;

    float sum = 0.0f;

    // Iterate over input channels and kernel elements
    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int k = 0; k < K; ++k) {
            // Calculate corresponding input position
            int l_in = l_out * S + k * D - P;

            // Check bounds for l_in (handle padding implicitly by skipping out-of-bounds)
            if (l_in >= 0 && l_in < L_in) {
                // Access input: input[n, c_in, l_in]
                // input tensor layout: N, C_in, L_in
                // flat index: n * (C_in * L_in) + c_in * L_in + l_in
                const float input_val = input[n * C_in * L_in + c_in * L_in + l_in];

                // Access weight: weight[c_out, c_in, k]
                // weight tensor layout: C_out, C_in, K (assuming groups=1)
                // flat index: c_out * (C_in * K) + c_in * K + k
                const float weight_val = weight[c_out * C_in * K + c_in * K + k];

                sum += input_val * weight_val;
            }
        }
    }

    // Store the result in the output tensor
    // output tensor layout: N, C_out, L_out
    // flat index: n * (C_out * L_out) + c_out * L_out + l_out
    output[n * C_out * L_out + c_out * L_out + l_out] = sum;
}

torch::Tensor conv1d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation
) {
    // Ensure tensors are on CUDA and are float
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(input.is_floating_point(), "Input must be a floating point tensor");
    TORCH_CHECK(weight.is_floating_point(), "Weight must be a floating point tensor");
    TORCH_CHECK(input.dim() == 3, "Input must be 3D (N, C_in, L_in)");
    TORCH_CHECK(weight.dim() == 3, "Weight must be 3D (C_out, C_in, K)");

    int N = input.size(0);
    int C_in = input.size(1);
    int L_in = input.size(2);

    int C_out = weight.size(0);
    int K = weight.size(2); // Kernel size

    // For groups=1, weight.size(1) should be C_in
    TORCH_CHECK(weight.size(1) == C_in, "Weight's C_in dimension must match input's C_in for groups=1");

    // Calculate output length
    int L_out = calculate_conv_output_length(L_in, K, stride, padding, dilation);
    TORCH_CHECK(L_out > 0, "Calculated output length is not positive. Check input dimensions and convolution parameters.");

    // Create output tensor
    auto output = torch::zeros({N, C_out, L_out}, input.options());

    // Configure kernel launch
    int total_elements = N * C_out * L_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the kernel
    conv1d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, L_in,
        C_out, K,
        stride, padding, dilation,
        L_out
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
"""

conv1d_cpp_source = (
    "torch::Tensor conv1d_cuda(torch::Tensor input, torch::Tensor weight, int stride, int padding, int dilation);"
)

# Compile the inline CUDA code for 1D convolution
