# Define the custom CUDA kernel for ConvTranspose3d
# This kernel implements a direct computation of ConvTranspose3d.
# Each thread computes one element in the output tensor.
# It iterates through all possible input channels and kernel elements
# to sum up contributions to its assigned output element.
# This is a naive implementation and may not outperform highly optimized
# library implementations (e.g., cuDNN) for all cases, but it demonstrates
# the replacement of the PyTorch operator with a custom CUDA kernel.
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For ceil

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weights,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K_D, int K_H, int K_W,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int dilation_d, int dilation_h, int dilation_w,
    const float* bias_ptr, bool use_bias) {

    // Each thread computes one element in the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C_out * D_out * H_out * W_out) {
        // Deconstruct idx to (n, c_out, d_out, h_out, w_out)
        // This converts a 1D global thread index into 5D tensor coordinates.
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int d_out = idx % D_out;
        idx /= D_out;
        int c_out = idx % C_out;
        idx /= C_out;
        int n = idx;

        float sum = 0.0f;

        // Iterate over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel dimensions
            for (int k_d = 0; k_d < K_D; ++k_d) {
                for (int k_h = 0; k_h < K_H; ++k_h) {
                    for (int k_w = 0; k_w < K_W; ++k_w) {
                        // Calculate corresponding input coordinates (d_in, h_in, w_in)
                        // based on output coordinates (d_out, h_out, w_out) and kernel (k_d, k_h, k_w).
                        // The relationship is:
                        // d_out = d_in * stride_d - padding_d + k_d * dilation_d
                        // Rearranging for d_in:
                        // d_in = (d_out + padding_d - k_d * dilation_d) / stride_d

                        int d_in_candidate = d_out + padding_d - k_d * dilation_d;
                        int h_in_candidate = h_out + padding_h - k_h * dilation_h;
                        int w_in_candidate = w_out + padding_w - k_w * dilation_w;

                        // Check if the candidate input coordinates align with the stride.
                        // If not, this kernel element does not contribute to this output element
                        // from an input element at integer coordinates.
                        if (d_in_candidate % stride_d == 0 &&
                            h_in_candidate % stride_h == 0 &&
                            w_in_candidate % stride_w == 0) {

                            int d_in = d_in_candidate / stride_d;
                            int h_in = h_in_candidate / stride_h;
                            int w_in = w_in_candidate / stride_w;

                            // Check if the calculated input coordinates are within the input tensor bounds.
                            if (d_in >= 0 && d_in < D_in &&
                                h_in >= 0 && h_in < H_in &&
                                w_in >= 0 && w_in < W_in) {

                                // Accumulate contribution: input_value * weight_value
                                // Weights shape: (C_in, C_out, K_D, K_H, K_W)
                                size_t weight_idx = c_in * (C_out * K_D * K_H * K_W) +
                                                    c_out * (K_D * K_H * K_W) +
                                                    k_d * (K_H * K_W) +
                                                    k_h * K_W +
                                                    k_w;

                                // Input shape: (N, C_in, D_in, H_in, W_in)
                                size_t input_idx = n * (C_in * D_in * H_in * W_in) +
                                                   c_in * (D_in * H_in * W_in) +
                                                   d_in * (H_in * W_in) +
                                                   h_in * W_in +
                                                   w_in;

                                sum += input[input_idx] * weights[weight_idx];
                            }
                        }
                    }
                }
            }
        }

        // Add bias if applicable
        if (use_bias) {
