        }

        // Store the computed sum into the output tensor.
        // Output shape: (N, C_out, D_out, H_out, W_out)
        size_t output_idx = n * (C_out * D_out * H_out * W_out) +
                           c_out * (D_out * H_out * W_out) +
                           d_out * (H_out * W_out) +
                           h_out * W_out +
                           w_out;

