#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for upper triangular matrix multiplication
// C = A * B, where A, B, C are N x N upper triangular matrices.
// This kernel computes C[row][col] only for row <= col.
// For each C[row][col], the sum for the dot product is optimized to iterate
// 'k' from 'row' to 'col' because A[row][k] is zero if k < row,
// and B[k][col] is zero if k > col, given that A and B are upper triangular.
__global__ void upper_triangular_matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Calculate global row and column indices for the output matrix C
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Check bounds to ensure we are within the matrix dimensions
    if (row < N && col < N) {
        // If the current element is in the lower triangular part (row > col),
        // its value should be 0 for an upper triangular matrix.
        // The output tensor 'C' is initialized with zeros, so this explicit assignment
        // primarily serves to clarify the logic and ensure correctness if 'C'
        // were not pre-zeroed or if we were writing to a pre-existing tensor.
        if (row > col) {
            C[row * N + col] = 0.0f;
        } else {
            // For elements in the upper triangular part (row <= col), compute the dot product.
            float sum = 0.0f;
            for (int k = row; k <= col; ++k) {
                sum += A[row * N + k] * B[k * N + col];
            }
            C[row * N + col] = sum;
        }
    }
}

