import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for LogSoftmax
# This kernel processes each row (batch item) independently using one CUDA block.
# Within each block, threads cooperate to find the maximum value and the sum of exponentials
# for numerical stability and then compute the final log_softmax values.
log_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat> // For FLT_MAX
#include <cmath>  // For expf, logf, fmaxf

// CUDA kernel for LogSoftmax operation.
// Each CUDA block is responsible for computing the LogSoftmax for one row (batch item).
// The 'dim' parameter refers to the size of the dimension along which LogSoftmax is applied.
__global__ void log_softmax_kernel(const float* input, float* output, int dim) {
    // blockIdx.x maps to the batch index, meaning each block handles a unique row.
    int batch_idx = blockIdx.x;

    // Calculate pointers to the start of the current row in input and output tensors.
    const float* row_input = input + batch_idx * dim;
    float* row_output = output + batch_idx * dim;

    // Declare shared memory. Its size is dynamically allocated at kernel launch.
    // This memory will be used for intra-block reductions (finding max and sum_exp).
    extern __shared__ float s_data[];

    // --- Step 1: Find the maximum value in the current row for numerical stability ---
    // Each thread initializes its local maximum to the smallest possible float value.
    float thread_max = -FLT_MAX;
    // Threads iterate over the row in a strided fashion (grid-stride loop)
    // to cover all elements in the row.
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        thread_max = fmaxf(thread_max, row_input[i]);
    }

    // Store each thread's local maximum into shared memory.
    s_data[threadIdx.x] = thread_max;
    // Synchronize all threads in the block to ensure all local maxima are written to shared memory.
    __syncthreads();

    // Perform a parallel reduction in shared memory to find the global maximum for the row.
    // This loop repeatedly halves the active threads, combining results.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each reduction step.
    }

    // The maximum value for the entire row is now stored in s_data[0].
    float row_max = s_data[0];

    // --- Step 2: Compute the sum of exponentials (after subtracting row_max) ---
    // Each thread initializes its local sum of exponentials to zero.
    float thread_sum_exp = 0.0f;
    // Threads again iterate over the row in a strided fashion.
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        thread_sum_exp += expf(row_input[i] - row_max);
    }

    // Store each thread's local sum of exponentials into shared memory (reusing s_data).
    s_data[threadIdx.x] = thread_sum_exp;
    // Synchronize all threads.
    __syncthreads();

    // Perform a parallel reduction in shared memory to find the global sum of exponentials for the row.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step.
    }

    // The sum of exponentials for the entire row is now in s_data[0].
    float row_sum_exp = s_data[0];
    // Compute the logarithm of the sum of exponentials.
    float row_log_sum_exp = logf(row_sum_exp);

    // --- Step 3: Compute the final LogSoftmax values for each element ---
    // Threads iterate over the row one last time to compute the final output.
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        row_output[i] = (row_input[i] - row_max) - row_log_sum_exp;
    }
}

// C++ wrapper function that PyTorch will call.
// It handles tensor checks, memory allocation, and kernel launch configuration.
torch::Tensor log_softmax_cuda(torch::Tensor input, int dim_idx) {
    // Input tensor validation checks.
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input tensor must be of float32 type.");
    TORCH_CHECK(input.dim() == 2, "Input tensor must be 2D (batch_size, dim).");
    // This kernel is specifically designed for reduction along the last dimension (dim=1 for a 2D tensor).
    TORCH_CHECK(dim_idx == 1, "Only dim=1 (reduction along columns) is supported for this kernel.");

    // Extract batch_size and the dimension size from the input tensor.
    int batch_size = input.size(0);
    int dim = input.size(1);

    // Create an output tensor on the CUDA device with the same shape and type as the input.
    auto output = torch::empty_like(input);

    // Define CUDA kernel launch parameters.
    // A common block size is 256 threads. This can be tuned for performance.
    const int block_size = 256;
    // Each block processes one row, so the number of blocks equals the batch size.
    const int num_blocks = batch_size;

    // Calculate the required shared memory size for the kernel.
    // It needs to be large enough to hold 'block_size' float values for the reduction.
    size_t smem_size = block_size * sizeof(float);

    // Launch the CUDA kernel.
    // The triple angle brackets specify the launch configuration:
