# Define the maximum number of dimensions supported by the kernel.
# This is used for stack-allocated arrays in the kernel.
# PyTorch tensors typically don't exceed 8 dimensions.
MAX_DIMS = 8

# Define the custom CUDA kernel for general sum reduction.
# This kernel computes the sum of elements along a specified dimension,
# keeping the reduced dimension as a singleton (size 1).
sum_reduction_source = f"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define MAX_DIMS {MAX_DIMS}

// Helper device function to calculate the linear memory index
// from a multi-dimensional index and strides.
__device__ long get_linear_index(const long* multi_dim_idx, int ndim, const long* strides) {
    long linear_idx = 0;
    for (int i = 0; i < ndim; ++i) {
        linear_idx += multi_dim_idx[i] * strides[i];
    }
    return linear_idx;
}

// CUDA kernel for general sum reduction.
// Each thread is responsible for computing one element of the output tensor.
__global__ void sum_reduction_general_kernel(
    const float* in_data,       // Pointer to the input tensor's data
    float* out_data,            // Pointer to the output tensor's data
    int in_ndim,                // Number of dimensions of the input tensor
    const long* in_sizes,       // Array of input tensor's dimension sizes (on device)
    const long* in_strides,     // Array of input tensor's strides (on device)
    int reduce_dim,             // The dimension along which to perform the reduction
    long output_numel,          // Total number of elements in the output tensor
    long reduction_size         // Size of the dimension being reduced (e.g., if summing along dim 1 of (B, D1, D2), this is D1)
) {
    // Calculate the global linear index for the current output element this thread will compute.
    int out_linear_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure the thread is within the bounds of the output tensor.
    if (out_linear_idx < output_numel) {
        float sum_val = 0.0f;
        // Stack-allocated array to hold the multi-dimensional index for the input tensor.
        // This will be modified to iterate through the reduction dimension.
        long current_in_multi_dim_idx[MAX_DIMS]; 

        // Reconstruct the multi-dimensional index for the *output* tensor
        // and use it to build the base multi-dimensional index for the *input* tensor.
        // We iterate from the rightmost dimension to the leftmost to correctly
        // decompose the linear output index.
        long temp_linear_idx = out_linear_idx;
        for (int d = in_ndim - 1; d >= 0; --d) {
            if (d == reduce_dim) {
                // This dimension is being reduced. Its index in the output is always 0 (due to keepdim=True).
                // For the input, this index will vary from 0 to reduction_size-1.
                // Initialize it to 0 for the loop below.
                current_in_multi_dim_idx[d] = 0; 
            } else {
                // For non-reduced dimensions, calculate the index from the linear output index.
                // The size of this dimension in the output is the same as in the input.
                long dim_size = in_sizes[d];
                current_in_multi_dim_idx[d] = temp_linear_idx % dim_size;
                temp_linear_idx /= dim_size;
            }
        }

        // Now, `current_in_multi_dim_idx` holds the base indices for the input slice
        // (i.e., all dimensions except `reduce_dim` are fixed).
        // We need to sum over the `reduce_dim`.
        for (int r = 0; r < reduction_size; ++r) {
            current_in_multi_dim_idx[reduce_dim] = r; // Set the index for the current element in the reduction dimension
            // Calculate the linear index for this specific input element.
            long in_linear_idx = get_linear_index(current_in_multi_dim_idx, in_ndim, in_strides);
            sum_val += in_data[in_linear_idx];
        }

        // Store the final sum in the output tensor.
        // Since `out` is created as contiguous, its linear index is simply `out_linear_idx`.
        out_data[out_linear_idx] = sum_val;
    }
}
"""

# Define the C++ wrapper for the CUDA kernel.
# This handles tensor checks, memory allocation for device-side arrays (sizes/strides),
# kernel launch configuration, and error checking.
sum_reduction_cpp_source = f"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define MAX_DIMS {MAX_DIMS}

// Declare the kernel function (defined in the .cu source)
__global__ void sum_reduction_general_kernel(
    const float* in_data,
    float* out_data,
