conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max

// Helper to calculate output dimensions for ConvTranspose2d
// H_out = (H_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1
// For this problem, output_padding is 0.
// H_out = (H_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1
inline int calculate_output_dim(int input_dim, int kernel_dim, int stride, int padding, int dilation) {
    return (input_dim - 1) * stride - 2 * padding + dilation * (kernel_dim - 1) + 1;
}

__global__ void conv_transpose2d_kernel(
    const float* input_ptr,
    const float* weight_ptr,
    const float* bias_ptr,
    float* output_ptr,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K_H, int K_W,
    int S, int P, int D, bool has_bias,
    int H_out, int W_out) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    long long total_output_elements = (long long)N * C_out * H_out * W_out;

    if (idx >= total_output_elements) {
        return;
    }

    // Decompose idx into (n, c_out, h_out, w_out)
    int n = idx / (C_out * H_out * W_out);
    int rem = idx % (C_out * H_out * W_out);
    int c_out = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    float sum = has_bias ? bias_ptr[c_out] : 0.0f;

    // Iterate over kernel dimensions and input channels
    for (int k_h = 0; k_h < K_H; ++k_h) {
        for (int k_w = 0; k_w < K_W; ++k_w) {
            for (int c_in = 0; c_in < C_in; ++c_in) {
                // Calculate candidate input coordinates
                // h_in_candidate = h_out + P - D * k_h
                // w_in_candidate = w_out + P - D * k_w
                // These must be non-negative and divisible by S
                // And the resulting h_in, w_in must be within input bounds

                int h_in_candidate = h_out + P - D * k_h;
                int w_in_candidate = w_out + P - D * k_w;

                // Check if candidate coordinates are valid for input tensor
                // h_in_candidate must be >= 0 and divisible by S
                // w_in_candidate must be >= 0 and divisible by S
                // The resulting h_in, w_in must be within [0, H_in) and [0, W_in)

                if (h_in_candidate >= 0 && (h_in_candidate % S == 0) &&
                    w_in_candidate >= 0 && (w_in_candidate % S == 0)) {

                    int h_in = h_in_candidate / S;
                    int w_in = w_in_candidate / S;

                    if (h_in < H_in && w_in < W_in) {
                        // Accumulate contribution
                        // Input: (N, C_in, H_in, W_in)
                        // Weight: (C_in, C_out, K_H, K_W)
                        sum += input_ptr[n * C_in * H_in * W_in + c_in * H_in * W_in + h_in * W_in + w_in] *
                               weight_ptr[c_in * C_out * K_H * K_W + c_out * K_H * K_W + k_h * K_W + k_w];
                    }
                }
            }
        }
    }

    // Store the result
    output_ptr[idx] = sum;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
