        TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    }

    // Extract dimensions
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int K_H = weight.size(2);
    int K_W = weight.size(3);
    int C_out = weight.size(1); // Note: ConvTranspose2d weight shape is (in_channels, out_channels, kH, kW)

    TORCH_CHECK(C_in == weight.size(0), "input channels must match weight in_channels");
    if (has_bias) {
        TORCH_CHECK(C_out == bias.size(0), "bias size must match out_channels");
    }

    // Calculate output dimensions
    int H_out = calculate_output_dim(H_in, K_H, stride, padding, dilation);
    int W_out = calculate_output_dim(W_in, K_W, stride, padding, dilation);

    // Ensure output dimensions are positive
    TORCH_CHECK(H_out > 0 && W_out > 0, "Calculated output dimensions are non-positive. Check parameters.");

    // Create output tensor
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Get raw pointers
    const float* input_ptr = input.data_ptr<float>();
    const float* weight_ptr = weight.data_ptr<float>();
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;
