// Kernel for reverse cumulative sum along a specified dimension for a 2D tensor.
// Each block processes one row (if target_dim=1) or one column (if target_dim=0)
// using a single thread to perform a sequential scan. This approach is chosen
// for its simplicity and to avoid complex parallel scan algorithms for large
// dimension sizes that exceed shared memory limits, while still parallelizing
// across the independent slices.
__global__ void reverse_cumsum_kernel_2d(
    const float* input_ptr,
    float* output_ptr,
    int size0, // size of dimension 0
    int size1, // size of dimension 1
    long stride0, // stride for dimension 0
    long stride1, // stride for dimension 1
    int target_dim)
{
    if (target_dim == 1) { // Sum along dimension 1 (columns)
        int row_idx = blockIdx.x; // Each block handles one row

        if (row_idx < size0) {
            // Base pointer for the current row
            const float* base_input_row = input_ptr + row_idx * stride0;
            float* base_output_row = output_ptr + row_idx * stride0;

            // Perform reverse cumulative sum for the current row
            // S_i = x_i + S_{i+1} for i from M-2 down to 0, S_{M-1} = x_{M-1}
            if (size1 > 0) {
                // Last element in the row: x[row_idx, size1-1]
                base_output_row[(size1 - 1) * stride1] = base_input_row[(size1 - 1) * stride1];
                for (int i = size1 - 2; i >= 0; --i) {
                    base_output_row[i * stride1] =
                        base_input_row[i * stride1] +
                        base_output_row[(i + 1) * stride1];
                }
            }
        }
    } else if (target_dim == 0) { // Sum along dimension 0 (rows)
        int col_idx = blockIdx.x; // Each block handles one column

        if (col_idx < size1) {
            // Base pointer for the current column (effectively, the first element of the column)
            const float* base_input_col = input_ptr + col_idx * stride1;
            float* base_output_col = output_ptr + col_idx * stride1;

            // Perform reverse cumulative sum for the current column
            // S_i = x_i + S_{i+1} for i from N-2 down to 0, S_{N-1} = x_{N-1}
            if (size0 > 0) {
                // Last element in the column: x[size0-1, col_idx]
                base_output_col[(size0 - 1) * stride0] = base_input_col[(size0 - 1) * stride0];
                for (int i = size0 - 2; i >= 0; --i) {
                    base_output_col[i * stride0] =
                        base_input_col[i * stride0] +
                        base_output_col[(i + 1) * stride0];
                }
            }
        }
    }
