#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

// CUDA kernel for L2 normalization along dimension 1
// Fuses element-wise square, sum reduction, square root, and element-wise division.
__global__ void l2_norm_kernel(const float* x, float* out, int dim) {
    // Each block processes one row (batch element)
    int row_idx = blockIdx.x;

    // Dynamically allocated shared memory for reduction within the block.
    // The size is passed during kernel launch (blockDim.x * sizeof(float)).
    extern __shared__ float s_sum_sq[];

    float thread_partial_sum_sq = 0.0f;

    // Grid-stride loop for each thread to process multiple elements in the row.
    // This ensures all 'dim' elements of the row are processed by the block.
    for (int col_idx = threadIdx.x; col_idx < dim; col_idx += blockDim.x) {
        float val = x[row_idx * dim + col_idx];
        thread_partial_sum_sq += val * val; // Accumulate sum of squares
    }

    // Store each thread's partial sum into shared memory.
    s_sum_sq[threadIdx.x] = thread_partial_sum_sq;
    __syncthreads(); // Synchronize to ensure all partial sums are written to shared memory

    // Perform parallel reduction in shared memory to get the total sum of squares for the row.
    // This loop assumes blockDim.x is a power of 2.
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    float row_norm = 0.0f;
    if (threadIdx.x == 0) {
        // Only thread 0 computes the final L2 norm for the row.
        row_norm = sqrtf(s_sum_sq[0]);
        // Store the computed norm back into shared memory for other threads to read.
        s_sum_sq[0] = row_norm;
    }
    __syncthreads(); // Synchronize to ensure thread 0 has written the norm to shared memory

    // All threads read the final row_norm from shared memory.
    row_norm = s_sum_sq[0];

    // Perform element-wise division by the computed L2 norm and store results.
    // Another grid-stride loop to write the output, ensuring coalesced memory access.
    for (int col_idx = threadIdx.x; col_idx < dim; col_idx += blockDim.x) {
        float val = x[row_idx * dim + col_idx];
        out[row_idx * dim + col_idx] = val / row_norm;
    }
}

