    const int block_size = 256; // Number of threads per block (must be a power of 2 for reduction)
    const int num_blocks = batch_size; // One block per row for independent processing

    // Calculate dynamic shared memory size required for the reduction (block_size floats)
    size_t shared_mem_size = block_size * sizeof(float);

    // Launch the CUDA kernel
    l2_norm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(), // Pointer to input data
        out.data_ptr<float>(), // Pointer to output data
        dim // Dimension of each row
    );

    // Check for any CUDA errors that occurred during kernel execution
