__global__ void conv_transpose2d_kernel(
    const float* input_data,
    const float* weight_data,
    float* output_data,
    int N, int C_in, int C_out, int H_in, int W_in, int K_H, int K_W,
    int H_out, int W_out) {

    // Calculate global index for the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total elements in the output tensor
    int total_out_elements = N * C_out * H_out * W_out;

    if (idx < total_out_elements) {
        // Deconstruct idx into (n, co, h_out, w_out)
        // Assuming NCHW memory layout
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int co = (idx / (W_out * H_out)) % C_out;
        int n = idx / (W_out * H_out * C_out);

        float sum = 0.0f;

        // Loop over input channels
        for (int ci = 0; ci < C_in; ++ci) {
            // Loop over kernel dimensions
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate corresponding input coordinates for ConvTranspose2d
                    // For stride=1, padding=0, output_padding=0:
                    // h_in = h_out - k_h
                    // w_in = w_out - k_w
                    int h_in = h_out - k_h;
                    int w_in = w_out - k_w;

                    // Check if input coordinates are within bounds
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        // Access input_data[n, ci, h_in, w_in]
                        // Access weight_data[ci, co, k_h, k_w] (PyTorch ConvTranspose2d weight layout)
                        sum += input_data[n * C_in * H_in * W_in + ci * H_in * W_in + h_in * W_in + w_in] *
                               weight_data[ci * C_out * K_H * K_W + co * K_H * K_W + k_h * K_W + k_w];
                    }
                }
            }
        }
        output_data[idx] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor conv_transpose2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int N, int C_in, int C_out, int H_in, int W_in, int K_H, int K_W,
