    TORCH_CHECK(weight.is_contiguous(), "Weight tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be float32.");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor must be float32.");

    // Create output tensor initialized to zeros
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Configure kernel launch parameters
    const int block_size = 256; // Standard block size
    const int total_out_elements = N * C_out * H_out * W_out;
    const int num_blocks = (total_out_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, C_out, H_in, W_in, K_H, K_W, H_out, W_out);

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in conv_transpose2d_cuda_forward: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
