    Optimized model that replaces nn.ConvTranspose2d with a custom CUDA kernel
    for specific configurations (stride=1, padding=0, output_padding=0, groups=1, bias=False).
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store parameters for the custom kernel.
        # The custom kernel is designed for stride=1, padding=0, output_padding=0, groups=1, bias=False.
        # These are the default parameters for nn.ConvTranspose2d, so the custom kernel will be used
        # for the given architecture's default configuration.
        if not (stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias == False):
            raise ValueError(
                "ModelNew's custom ConvTranspose2d kernel currently only supports "
                "stride=1, padding=0, output_padding=0, groups=1, and bias=False. "
                "Please adjust model parameters or implement a more general custom kernel."
            )

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias # Bias is False by default and not handled by this kernel

        # The custom kernel directly uses the weight tensor.
        # We need to create a learnable weight parameter with the correct shape.
        # PyTorch ConvTranspose2d weight shape: (in_channels, out_channels/groups, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size))

        # Initialize weight similar to PyTorch's default for ConvTranspose2d
        # using Kaiming uniform initialization.
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

