# Define the custom CUDA kernel for Instance Normalization
instance_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For fmaxf

__global__ void instance_norm_kernel(const float* x, float* y, int N, int C, int H, int W, float eps) {
    // Each block processes one (N, C) slice
    int nc_idx = blockIdx.x; // Index for the N*C dimension

    int n = nc_idx / C;
    int c = nc_idx % C;

    // Calculate the starting offset for the current (n, c) slice
    // x is (N, C, H, W)
    // offset = n * (C*H*W) + c * (H*W)
    int spatial_size = H * W;
    int offset_nc = n * C * spatial_size + c * spatial_size;

    // Shared memory for reduction: s_sum and s_sum_sq
    extern __shared__ float s_data[]; 
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Loop through the H*W elements, each thread processing multiple elements
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = x[offset_nc + i];
        local_sum += val;
        local_sum_sq += val * val;
    }

    // Store local sums in shared memory
    s_sum[threadIdx.x] = local_sum;
    s_sum_sq[threadIdx.x] = local_sum_sq;
    __syncthreads();

    // Parallel reduction in shared memory
    // This loop assumes blockDim.x is a power of 2 for efficient reduction.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Thread 0 computes mean and inverse standard deviation and stores them in shared memory for broadcast
    float mean_nc;
    float inv_std;

    if (threadIdx.x == 0) {
        mean_nc = s_sum[0] / spatial_size;
        float var_nc = s_sum_sq[0] / spatial_size - mean_nc * mean_nc;
        // Ensure variance is non-negative
        var_nc = fmaxf(0.0f, var_nc);
        inv_std = rsqrtf(var_nc + eps); // Use rsqrtf for performance

        // Store for broadcast to all threads in the block
        s_sum[0] = mean_nc;
        s_sum_sq[0] = inv_std;
    }
    __syncthreads(); // Ensure mean_nc and inv_std are available to all threads

    // All threads read the broadcasted values
    mean_nc = s_sum[0];
    inv_std = s_sum_sq[0];

    // Apply normalization
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = x[offset_nc + i];
        y[offset_nc + i] = (val - mean_nc) * inv_std;
    }
}

torch::Tensor instance_norm_cuda(torch::Tensor x, float eps) {
    // Input checks
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 4, "x must be a 4D tensor (N, C, H, W)");
    TORCH_CHECK(x.dtype() == torch::kFloat, "x must be of float type");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto y = torch::empty_like(x);

    const int block_size = 256; // Number of threads per block
    const int num_blocks = N * C; // One block per (N, C) slice

    // Shared memory size: 2 * block_size * sizeof(float) for s_sum and s_sum_sq
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    instance_norm_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(), y.data_ptr<float>(), N, C, H, W, eps
    );

    return y;
}
"""

instance_norm_cpp_source = (
    "torch::Tensor instance_norm_cuda(torch::Tensor x, float eps);"
)

# Compile the inline CUDA code for Instance Normalization
instance_norm_module = load_inline(
    name="instance_norm_module",
    cpp_sources=instance_norm_cpp_source,
    cuda_sources=instance_norm_source,
    functions=["instance_norm_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Instance Normalization using a custom CUDA kernel.
    """
    def __init__(self, num_features: int) -> None:
        """
        Initializes the custom InstanceNorm layer.

        Args:
            num_features (int): Number of features in the input tensor.
                                This parameter is kept for API compatibility but not
                                directly used by the custom kernel as it infers C from input.
        """
        super(ModelNew, self).__init__()
        # Store the custom kernel function
        self.instance_norm_cuda_op = instance_norm_module.instance_norm_cuda
        # Default eps for nn.InstanceNorm2d is 1e-5
        self.eps = 1e-5

