# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Define BLOCK_SIZE for shared memory tiling
#define BLOCK_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // M, K for A (A_rows, A_cols)
    // K, N for B (B_rows, B_cols)
    // M, N for C (C_rows, C_cols)

    // Block and thread indices
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column for the current thread in C
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Shared memory for tiles of A and B
    // Each block loads a BLOCK_SIZE x BLOCK_SIZE tile
    __shared__ float sA[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float sB[BLOCK_SIZE][BLOCK_SIZE];

    float Cvalue = 0.0f; // Accumulator for the C element this thread computes

    // Loop over the K dimension (inner product dimension) in tiles
    // Each tile iteration computes a partial sum for Cvalue
    for (int tile_idx = 0; tile_idx < (K + BLOCK_SIZE - 1) / BLOCK_SIZE; ++tile_idx) {
        // Load tiles from global memory to shared memory
        // Each thread loads one element into shared memory
        int A_global_row = row;
        int A_global_col = tile_idx * BLOCK_SIZE + tx;
        if (A_global_row < M && A_global_col < K) {
            sA[ty][tx] = A[A_global_row * K + A_global_col];
        } else {
            sA[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        int B_global_row = tile_idx * BLOCK_SIZE + ty;
        int B_global_col = col;
        if (B_global_row < K && B_global_col < N) {
            sB[ty][tx] = B[B_global_row * N + B_global_col];
        } else {
            sB[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }
        __syncthreads(); // Wait for all threads in the block to load their data

        // Perform dot product for the current tile
        // Each thread computes one element of the C tile
        for (int k_inner = 0; k_inner < BLOCK_SIZE; ++k_inner) {
            Cvalue += sA[ty][k_inner] * sB[k_inner][tx];
        }
        __syncthreads(); // Wait for all threads to finish computation for this tile before next tile load
    }

    // Write the accumulated result to global memory
    if (row < M && col < N) {
        C[row * N + col] = Cvalue;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Input tensors must be 2D matrices.");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible for multiplication.");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Input tensors must be CUDA tensors.");
    TORCH_CHECK(A.scalar_type() == torch::kFloat && B.scalar_type() == torch::kFloat, "Input tensors must be float32.");

    int M = A.size(0);
    int K = A.size(1); // A.cols, B.rows
    int N = B.size(1);

    // Create output tensor C on the same device as A
    auto C = torch::zeros({M, N}, A.options());

    // Define grid and block dimensions
    // Each block computes a BLOCK_SIZE x BLOCK_SIZE tile of C
    dim3 dimGrid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);

    // Launch the CUDA kernel
    matmul_kernel<<<dimGrid, dimBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
