import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Hinge Loss calculation
hinge_loss_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf

// CUDA kernel to compute partial sums of max(0, 1 - pred * target) with broadcasting
// predictions: 2D tensor (B, D)
// targets: 1D tensor (B,)
// partial_sums: 1D tensor to store sum from each block
// B: batch size (first dimension of predictions, and size of targets)
// D: feature dimension (second dimension of predictions)
__global__ void hinge_loss_sum_kernel(const float* predictions, const float* targets, float* partial_sums, int B, int D) {
    extern __shared__ float sdata[]; // Shared memory for block-wise reduction

    int tid = threadIdx.x;
    int block_idx = blockIdx.x;
    int block_dim = blockDim.x;
    int grid_dim = gridDim.x;

    float thread_sum = 0.0f;
    int N = B * D; // Total number of elements in the conceptual (B, D) output of pred * target

    // Grid-stride loop to process all elements
    for (int global_idx = block_idx * block_dim + tid; global_idx < N; global_idx += grid_dim * block_dim) {
        int row_idx = global_idx / D; // Current batch index
        // int col_idx = global_idx % D; // Current feature index (not explicitly needed for indexing predictions)

        // Perform the broadcasted multiplication: predictions[row_idx, col_idx] * targets[row_idx]
        // predictions is flattened in row-major order, so predictions[global_idx] is predictions[row_idx][col_idx]
        float pred_val = predictions[global_idx];
        float target_val = targets[row_idx]; // targets is 1D, indexed by row_idx

        float val = 1.0f - pred_val * target_val;
        thread_sum += fmaxf(0.0f, val); // fmaxf for float max
    }

    // Store thread_sum in shared memory
    sdata[tid] = thread_sum;
    __syncthreads();

    // Perform reduction in shared memory
    // This loop assumes block_dim is a power of 2
    for (unsigned int s = block_dim / 2; s > 0; s /= 2) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // The block's total sum is in sdata[0]
    if (tid == 0) {
        partial_sums[block_idx] = sdata[0];
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure inputs are contiguous and on CUDA
    predictions = predictions.contiguous();
    targets = targets.contiguous();

    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.scalar_type() == torch::kFloat, "predictions must be float32");
    TORCH_CHECK(targets.scalar_type() == torch::kFloat, "targets must be float32");
    TORCH_CHECK(predictions.dim() == 2, "predictions must be 2D (batch_size, feature_dim)");
    TORCH_CHECK(targets.dim() == 1, "targets must be 1D (batch_size,)");
    TORCH_CHECK(predictions.size(0) == targets.size(0), "Batch sizes of predictions and targets must match");

    int B = predictions.size(0); // Batch size
    int D = predictions.size(1); // Feature dimension
    int N = B * D;               // Total number of elements after broadcasting

    const int block_size = 256; // Threads per block (must be a power of 2 for efficient shared memory reduction)
    const int num_blocks = (N + block_size - 1) / block_size; // Number of blocks needed to cover all elements

    // Allocate output tensor for partial sums (one element per block)
    auto partial_sums = torch::zeros({num_blocks}, predictions.options());

    // Launch the kernel
    // The third argument to <<<>>> is shared memory size in bytes.
    // We need block_size * sizeof(float) for the sdata array.
    hinge_loss_sum_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        partial_sums.data_ptr<float>(),
        B, D
    );

    // Sum the partial sums on the GPU and divide by N to get the mean.
    // Using torch.sum() for the final reduction of partial_sums is efficient on the GPU.
    return partial_sums.sum() / N;
}
