    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements (N * C_out * D * H * W)
    long long total_output_elements = (long long)N * C_out * D * H * W;

    if (idx < total_output_elements) {
        // Deconstruct the linear index into N, C_out, D, H, W coordinates
        // This is done by repeatedly taking modulo and division by the dimension size
        int w = idx % W;
        idx /= W;
        int h = idx % H;
        idx /= H;
        int d = idx % D;
        idx /= D;
        int c_out = idx % C_out;
        idx /= C_out;
        int n = idx;

        float sum = 0.0f;

        // Perform sum-reduction over input channels (C_in)
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Calculate input tensor index: input[n, c_in, d, h, w]
            // Input tensor layout: (N, C_in, D, H, W)
            long long input_idx = (long long)n * C_in * D * H * W +
                                  (long long)c_in * D * H * W +
                                  (long long)d * H * W +
                                  (long long)h * W +
                                  (long long)w;

            // Calculate weight tensor index: weight[c_out, c_in, 0, 0, 0]
            // Weight tensor layout: (C_out, C_in, 1, 1, 1). We flatten the last three dimensions.
            long long weight_idx = (long long)c_out * C_in + c_in;

            sum += input[input_idx] * weight[weight_idx];
        }

        // Add bias if the convolution has a bias term
        if (has_bias) {
            sum += bias[c_out];
        }

        // Calculate output tensor index: output[n, c_out, d, h, w]
        // Output tensor layout: (N, C_out, D, H, W)
        long long output_idx = (long long)n * C_out * D * H * W +
                               (long long)c_out * D * H * W +
                               (long long)d * H * W +
                               (long long)h * W +
