# Define the custom CUDA kernels for Frobenius norm calculation and normalization
frobenius_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For std::sqrt

// Kernel 1: Computes partial sum of squares for elements processed by each block.
// Uses shared memory for intra-block reduction and a grid-stride loop for global coverage.
// Accumulates sums in double precision to maintain accuracy.
__global__ void frobenius_norm_partial_sum_sq_kernel(const float* x_ptr, double* partial_sums_sq_ptr, int num_elements) {
    extern __shared__ double sdata[]; // Shared memory for reduction within a block, using double for precision

    int tid = threadIdx.x;
    int global_idx_start = blockIdx.x * blockDim.x + tid;
    int grid_stride = gridDim.x * blockDim.x;

    double block_local_sum_sq = 0.0; // Use double for accumulation

    // Grid-stride loop to ensure all elements are processed by the grid
    for (int i = global_idx_start; i < num_elements; i += grid_stride) {
        float val = x_ptr[i];
        block_local_sum_sq += static_cast<double>(val) * val; // Cast to double before squaring and summing
    }

    sdata[tid] = block_local_sum_sq;
    __syncthreads();

    // Reduce within block using shared memory (assumes blockDim.x is a power of 2)
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Only thread 0 of each block writes the block's total sum of squares to global memory
    if (tid == 0) {
        partial_sums_sq_ptr[blockIdx.x] = sdata[0];
    }
}

// Kernel 2: Performs element-wise division of the input tensor by a scalar norm value.
__global__ void frobenius_normalize_kernel(const float* x_in, float* x_out, float norm_val, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        x_out[idx] = x_in[idx] / norm_val;
    }
}

// C++ wrapper function that orchestrates the kernel launches and CPU aggregation.
torch::Tensor frobenius_norm_and_normalize_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat, "Input tensor must be of float32 type.");

    int num_elements = x.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256; // Standard block size for CUDA kernels
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Allocate a temporary tensor on the GPU to store partial sums of squares from each block.
    // Using double precision for these sums to maintain accuracy.
    auto partial_sums_sq = torch::zeros({num_blocks}, x.options().dtype(torch::kDouble));

    // Launch Kernel 1: Compute partial sums of squares across all blocks.
    // The third argument specifies the amount of shared memory to allocate per block.
    frobenius_norm_partial_sum_sq_kernel<<<num_blocks, block_size, block_size * sizeof(double)>>>(
        x.data_ptr<float>(),          // Pointer to input tensor data (float)
        partial_sums_sq.data_ptr<double>(), // Pointer to output partial sums data (double)
        num_elements                  // Total number of elements in the input tensor
    );

    // Aggregate the partial sums on the GPU using PyTorch's optimized `sum()` reduction.
    // Then, copy the final scalar sum to the CPU using `item<double>()`.
    double total_sum_sq = partial_sums_sq.sum().item<double>();

    // Calculate the Frobenius norm (square root of the total sum of squares).
    // Cast to float for the division kernel, as the input/output tensors are float.
    float norm_val = static_cast<float>(std::sqrt(total_sum_sq));

    // Handle the edge case where the norm is zero (input tensor is all zeros).
    // In this case, the output should also be all zeros to avoid division by zero.
    if (norm_val == 0.0f) {
        return torch::zeros_like(x);
    }

    // Launch Kernel 2: Perform element-wise division of the input tensor by the calculated norm.
    frobenius_normalize_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), // Pointer to input tensor data (float)
        out.data_ptr<float>(), // Pointer to output tensor data (float)
        norm_val,            // The scalar Frobenius norm
        num_elements         // Total number of elements in the input tensor
    );

    return out;
}
