matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Define a tile dimension for shared memory and block size
// A common choice for TILE_DIM is 32, leading to 32x32 = 1024 threads per block.
#define TILE_DIM 32

__global__ void matmul_kernel(const float* A, const float* B, float* C,
                              int M, int K, int N) {
    // Block and thread indices
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Calculate the row and column of the C element this thread is responsible for
    int row = blockRow * TILE_DIM + threadRow;
    int col = blockCol * TILE_DIM + threadCol;

    float C_value = 0;

    // Loop over K dimension in tiles
    // Each iteration processes a TILE_DIM x TILE_DIM tile of A and B
    for (int tile_k = 0; tile_k < (K + TILE_DIM - 1) / TILE_DIM; ++tile_k) {
        // Shared memory for tiles of A and B
        // TILE_DIM x TILE_DIM for As and Bs
        __shared__ float As[TILE_DIM][TILE_DIM];
        __shared__ float Bs[TILE_DIM][TILE_DIM];

        // Load tiles from global memory to shared memory
        // Each thread loads one element from A and one from B
        int A_global_row = row;
        int A_global_col = tile_k * TILE_DIM + threadCol;
        if (A_global_row < M && A_global_col < K) {
            As[threadRow][threadCol] = A[A_global_row * K + A_global_col];
        } else {
            As[threadRow][threadCol] = 0.0f; // Pad with zeros if out of bounds
        }

        int B_global_row = tile_k * TILE_DIM + threadRow;
        int B_global_col = col;
        if (B_global_row < K && B_global_col < N) {
            Bs[threadRow][threadCol] = B[B_global_row * N + B_global_col];
        } else {
            Bs[threadRow][threadCol] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads(); // Wait for all threads in the block to load their data

        // Perform dot product for the current tile
        // Each thread computes one element of the C tile
        for (int k_idx = 0; k_idx < TILE_DIM; ++k_idx) {
            C_value += As[threadRow][k_idx] * Bs[k_idx][threadCol];
        }

        __syncthreads(); // Wait for all threads to finish computation for this tile
    }

    // Write the final accumulated result to global memory
    if (row < M && col < N) {
        C[row * N + col] = C_value;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input types and dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat, "Input A must be float tensor");
    TORCH_CHECK(B.scalar_type() == torch::kFloat, "Input B must be float tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match for matmul: A.size(1) != B.size(0)");

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    // Create output tensor on the same device and dtype as A
    auto C = torch::zeros({M, N}, A.options());

    // Grid and block dimensions
    // Each block computes a TILE_DIM x TILE_DIM portion of C
    dim3 block_size(TILE_DIM, TILE_DIM);
    dim3 grid_size((N + TILE_DIM - 1) / TILE_DIM, (M + TILE_DIM - 1) / TILE_DIM);

    // Launch the CUDA kernel
    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        M, K, N
    );

    return C;
