import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for preparing the exclusive cumulative sum input.
# This kernel fuses the `torch.cat`, `torch.zeros_like`, and the batch dimension slicing (`[:-1]`)
# from the original model's forward pass into a single GPU operation.
prepare_exclusive_cumsum_input_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA error checking macro for robust kernel launches
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error at %s:%d - %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(1); \\
        } \\
    } while (0)

__global__ void prepare_exclusive_cumsum_input_kernel(const float* x_ptr, float* out_ptr, int B, int L) {
    // B: original batch size (number of rows in x)
    // L: original sequence length (number of columns in x)
    // The output tensor will have (B-1) rows and (L+1) columns, replicating the original model's logic.
    int output_num_rows = B - 1;
    int output_num_cols = L + 1;

    // Calculate the global index for the current thread within the flattened output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure the thread operates within the bounds of the output tensor
    if (idx < output_num_rows * output_num_cols) {
        int row = idx / output_num_cols; // Row index in the output tensor
        int col = idx % output_num_cols; // Column index in the output tensor

        if (col == 0) {
            // The first column of each row in the intermediate tensor is always 0.
            // This corresponds to the `torch.zeros_like` part of the original model.
            out_ptr[idx] = 0.0f;
        } else {
            // For other columns (col > 0), the value comes from the original 'x' tensor.
            // Specifically, `out[row, col]` gets `x[row, col-1]`.
            // The `row` index here directly corresponds to the row in the input `x` tensor.
            // The `output_num_rows = B - 1` implicitly handles the `[:-1]` slicing on the batch dimension,
            // as we only compute for `row` from `0` to `B-2`.
            out_ptr[idx] = x_ptr[row * L + (col - 1)];
        }
    }
}

torch::Tensor prepare_exclusive_cumsum_input_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 2, "Input tensor 'x' must be a 2D tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous for efficient memory access.");

    int B = x.size(0); // Original batch size (number of rows)
    int L = x.size(1); // Original sequence length (number of columns)

    // Calculate the dimensions of the intermediate tensor that will be passed to torch.cumsum.
    // This replicates the behavior of the original model's `[:-1]` (batch truncation) and `cat` (column padding).
    int output_num_rows = B - 1;
    int output_num_cols = L + 1;

    // Handle edge case where B is 1 or less, which would result in 0 or negative output rows.
    // In such cases, the original model would produce an empty tensor or an error.
    // We return an empty tensor with the correct number of columns.
    if (output_num_rows <= 0) {
        return torch::empty({0, output_num_cols}, x.options());
    }

    // Create the output tensor on the GPU with the determined dimensions and data type.
    auto out = torch::empty({output_num_rows, output_num_cols}, x.options());

    // Define CUDA kernel launch parameters
    const int block_size = 256; // A common block size for good occupancy
    const int num_elements = output_num_rows * output_num_cols;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel to fill the intermediate tensor
    prepare_exclusive_cumsum_input_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), // Pointer to input data
        out.data_ptr<float>(), // Pointer to output data
        B, // Original batch size
        L  // Original sequence length
    );
    CUDA_CHECK(cudaGetLastError()); // Check for any errors during kernel execution

    return out;
}
"""

prepare_exclusive_cumsum_input_cpp_source = (
    "torch::Tensor prepare_exclusive_cumsum_input_cuda(torch::Tensor x);"
)

# Compile the inline CUDA code using torch.utils.cpp_extension.load_inline
prepare_exclusive_cumsum_input = load_inline(
    name="prepare_exclusive_cumsum_input",
    cpp_sources=prepare_exclusive_cumsum_input_cpp_source,
    cuda_sources=prepare_exclusive_cumsum_input_source,
    functions=["prepare_exclusive_cumsum_input_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[""],
)


