depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can be removed

// CUDA kernel for depthwise 2D convolution
__global__ void depthwise_conv2d_kernel(
    const float* x,          // Input tensor (N, C, H_in, W_in)
    const float* weight,     // Weight tensor (C, 1, K, K)
    const float* bias,       // Bias tensor (C) or nullptr
    float* out,              // Output tensor (N, C, H_out, W_out)
    int N, int C, int H_in, int W_in, // Input dimensions
    int K, int S, int P,             // Kernel size, Stride, Padding
    int H_out, int W_out,           // Output dimensions
    bool has_bias)
{
    // Each thread computes one output pixel (n, c, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H_out * W_out) {
        // Decompose flat index into (n, c, h_out, w_out)
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c = (idx / (W_out * H_out)) % C;
        int n = idx / (C * H_out * W_out);

        float sum = 0.0f;

        // Iterate over kernel dimensions
        for (int r_k = 0; r_k < K; ++r_k) {
            for (int c_k = 0; c_k < K; ++c_k) {
                // Calculate corresponding input coordinates
                int h_in = h_out * S + r_k - P;
                int w_in = w_out * S + c_k - P;

                // Check bounds for padding
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    // Access input x[n, c, h_in, w_in]
                    // x is (N, C, H_in, W_in)
                    // weight is (C, 1, K, K)
                    sum += x[n * C * H_in * W_in + c * H_in * W_in + h_in * W_in + w_in] *
                           weight[c * K * K + r_k * K + c_k]; // weight[c, 0, r_k, c_k]
                }
            }
        }

        // Add bias if present
        if (has_bias) {
            sum += bias[c]; // Bias is (C)
        }

        // Store result in output out[n, c, h_out, w_out]
        // out is (N, C, H_out, W_out)
        out[n * C * H_out * W_out + c * H_out * W_out + h_out * W_out + w_out] = sum;
    }
}

// C++ wrapper function to call the CUDA kernel
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
