    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32");

    // Weight tensor checks
    TORCH_CHECK(weight.dim() == 4, "Weight must be 4D (C, 1, K, K)");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(weight.is_contiguous(), "Weight tensor must be contiguous");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor must be float32");
    TORCH_CHECK(weight.size(1) == 1, "Weight's second dimension must be 1 for depthwise conv");

    bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "Bias must be a CUDA tensor");
        TORCH_CHECK(bias.is_contiguous(), "Bias tensor must be contiguous");
        TORCH_CHECK(bias.dtype() == torch::kFloat32, "Bias tensor must be float32");
        TORCH_CHECK(bias.dim() == 1, "Bias must be 1D");
        TORCH_CHECK(bias.size(0) == x.size(1), "Bias size must match input channels");
    }

    // Extract dimensions
    int N = x.size(0);
    int C = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    int K = weight.size(2); // Assuming square kernel KxK

    int S = stride;
    int P = padding;

    // Calculate output dimensions
    int H_out = (H_in + 2 * P - K) / S + 1;
    int W_out = (W_in + 2 * P - K) / S + 1;

    // Create output tensor
    auto out = torch::zeros({N, C, H_out, W_out}, x.options());

    // Configure kernel launch parameters
    const int total_elements = N * C * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr, // Pass nullptr if no bias
        out.data_ptr<float>(),
        N, C, H_in, W_in,
        K, S, P,
        H_out, W_out,
        has_bias);

    return out;
