// Helper function to get linear index for a 3D tensor
__device__ __forceinline__ int get_linear_idx(int d0, int d1, int d2, int D1, int D2) {
    return d0 * D1 * D2 + d1 * D2 + d2;
}

__global__ void max_reduction_kernel(const float* in_data, float* out_data, int D0, int D1, int D2, int reduce_dim) {
    // Each block computes one output element.
    // blockIdx.y maps to the first output dimension, blockIdx.x maps to the second.
    int out_coord0 = blockIdx.y;
    int out_coord1 = blockIdx.x;

    // Determine the length of the dimension being reduced
    int reduce_len;
    if (reduce_dim == 0) reduce_len = D0;
    else if (reduce_dim == 1) reduce_len = D1;
    else reduce_len = D2;

    // Shared memory for reduction within the block
    // The size of s_max should be at least blockDim.x.
    // Max threads per block is typically 1024.
    __shared__ float s_max[1024]; 

    float thread_max = -FLT_MAX; // Initialize with the smallest possible float value

    // Each thread loads multiple elements from the reduction dimension
    // and computes a partial max.
    for (int k = threadIdx.x; k < reduce_len; k += blockDim.x) {
        int in_d0, in_d1, in_d2;

        if (reduce_dim == 0) { // Reduce D0 (batch_size)
            in_d0 = k;
            in_d1 = out_coord0; // This is D1
            in_d2 = out_coord1; // This is D2
        } else if (reduce_dim == 1) { // Reduce D1
            in_d0 = out_coord0; // This is D0
            in_d1 = k;
            in_d2 = out_coord1; // This is D2
        } else { // reduce_dim == 2
            in_d0 = out_coord0; // This is D0
            in_d1 = out_coord1; // This is D1
            in_d2 = k;
        }
        thread_max = fmaxf(thread_max, in_data[get_linear_idx(in_d0, in_d1, in_d2, D1, D2)]);
    }

    s_max[threadIdx.x] = thread_max;
    __syncthreads();

    // Perform reduction in shared memory (tree reduction)
    // This loop assumes blockDim.x is a power of 2.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_max[threadIdx.x] = fmaxf(s_max[threadIdx.x], s_max[threadIdx.x + s]);
        }
        __syncthreads();
    }

    // Write the final result to global memory (only by thread 0 of the block)
    if (threadIdx.x == 0) {
        // Determine the actual dimensions of the output tensor
        int out_D_dim0_val, out_D_dim1_val;
        if (reduce_dim == 0) { out_D_dim0_val = D1; out_D_dim1_val = D2; }
        else if (reduce_dim == 1) { out_D_dim0_val = D0; out_D_dim1_val = D2; }
        else { out_D_dim0_val = D0; out_D_dim1_val = D1; }

        // Calculate linear index for output tensor
        out_data[out_coord0 * out_D_dim1_val + out_coord1] = s_max[0];
    }
