    TORCH_CHECK(reduce_dim >= 0 && reduce_dim <= 2, "reduce_dim must be 0, 1, or 2.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor 'x' must be of type float32.");

    // Get dimensions of the input tensor
