avg_pool1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // Required for std::max

// CUDA kernel for 1D Average Pooling
__global__ void avg_pool1d_kernel(
    const float* input,
    float* output,
    int N, int C, int L_in,
    int L_out,
    int kernel_size,
    int stride,
    int padding) {

    // Calculate global index for the output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Check if the index is within the bounds of the output tensor
    if (idx < N * C * L_out) {
        // De-flatten the index to N, C, L_out coordinates
        int n = idx / (C * L_out);
        int c = (idx / L_out) % C;
        int j = idx % L_out; // Output length index

        float sum = 0.0f;
        int count = 0;

        // Calculate the start and end indices of the pooling window in the input
        int input_start_idx = j * stride - padding;
        int input_end_idx = input_start_idx + kernel_size;

        // Iterate over the window in the input tensor
        for (int k = input_start_idx; k < input_end_idx; ++k) {
            // Check for boundary conditions (padding)
            if (k >= 0 && k < L_in) {
                // Accumulate sum for valid elements
                // input tensor is (N, C, L_in)
                sum += input[n * C * L_in + c * L_in + k];
                count++;
            }
        }

        // Store the average in the output tensor
        // output tensor is (N, C, L_out)
        if (count > 0) {
            output[n * C * L_out + c * L_out + j] = sum / count;
        } else {
            // If no elements in the window (e.g., kernel entirely outside input due to padding), output 0
            output[n * C * L_out + c * L_out + j] = 0.0f;
        }
    }
}

