    // L_out = floor((L_in + 2 * padding - kernel_size) / stride) + 1
    // And ensure L_out is non-negative.
    int L_out_val = (L_in + 2 * padding - kernel_size) / stride + 1;
    int L_out = std::max(0, L_out_val);

