    // Calculate total number of elements in the output tensor
    int total_output_elements = N * C * L_out;

    // Configure kernel launch parameters
    const int block_size = 256; // A common block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the kernel
    avg_pool1d_kernel<<<num_blocks, block_size>>>(
        input_data, output_data,
        N, C, L_in,
        L_out,
