    int c_out_l_out_flat = idx % (C_out * L_out);
    int c_out = c_out_l_out_flat / L_out;
    int l_out = c_out_l_out_flat % L_out;

    float sum = 0.0f;

    // Iterate over input channels
    for (int c_in = 0; c_in < C_in; ++c_in) {
        // Iterate over kernel elements
        for (int k = 0; k < K; ++k) {
            // Calculate the corresponding input position in the *upsampled* space.
            // This is the position in the conceptual "dilated and padded" output feature map
            // that corresponds to the current kernel element and output position.
            // To find the actual input index, we need to reverse the stride.
            int l_in_candidate = l_out + padding - k * dilation;

            // Check if l_in_candidate is valid and corresponds to an actual input element.
            // It must be non-negative and divisible by the stride.
            if (l_in_candidate >= 0 && (l_in_candidate % stride == 0)) {
