# CUDA kernel source for Dilated Conv1D (stride=1)
# This kernel implements a standard dilated convolution with stride 1.
# The ConvTranspose1d operation with stride=1, padding=0, dilation=D, kernel_size=K
# can be re-expressed as a standard Conv1d with stride=1, dilation=D, kernel_size=K,
# and a specific padding P_conv = D * (K - 1), applied to a transformed weight.
# The weight transformation involves permuting input/output channels and flipping the kernel.
dilated_conv1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper function to get 1D index from 3D coordinates (N, C, L)
// C_dim is the size of the C dimension, L_dim is the size of the L dimension
__device__ int get_idx_3d(int n, int c, int l, int C_dim, int L_dim) {
    return n * C_dim * L_dim + c * L_dim + l;
}

// Helper function to get 1D index from 3D coordinates (C_out, C_in, K) for weights
// C_in_dim is the size of the C_in dimension, K_dim is the size of the K dimension
__device__ int get_idx_weight(int c_out, int c_in, int k, int C_in_dim, int K_dim) {
    return c_out * C_in_dim * K_dim + c_in * K_dim + k;
}


__global__ void dilated_conv1d_kernel(
    const float* x, const float* w, const float* b, float* out,
    int N, int C_in, int L_in, int C_out, int K, int D, int P_conv, int L_out, bool has_bias) {

    // Each thread computes one element of the output tensor (n, c_out, l_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C_out * L_out) {
        int n = idx / (C_out * L_out);
        int c_out = (idx / L_out) % C_out;
        int l_out = idx % L_out;

        float sum = 0.0f;
        // Iterate over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel elements
            for (int k = 0; k < K; ++k) {
                // Calculate the corresponding index in the original (unpadded) input tensor
                // For a standard Conv1D with stride=1, dilation=D, padding=P_conv:
                // out[l_out] = sum_{k} x_padded[l_out + k * D] * w[k]
                // x_padded[idx_padded] corresponds to x[idx_padded - P_conv]
                // So, the index in the original input is (l_out + k * D - P_conv)
                int l_in_original_idx = l_out + k * D - P_conv;

                // Check if the calculated input index is within the bounds of the original input tensor
                if (l_in_original_idx >= 0 && l_in_original_idx < L_in) {
                    sum += x[get_idx_3d(n, c_in, l_in_original_idx, C_in, L_in)] *
                           w[get_idx_weight(c_out, c_in, k, C_in, K)];
                }
                // If l_in_original_idx is out of bounds, it means it falls into the padded region,
                // which implicitly contributes 0.0, so no addition is needed.
            }
        }

        // Add bias if present
        if (has_bias) {
            sum += b[c_out];
        }
        out[idx] = sum;
    }
