    // This is important for correct pointer arithmetic in the kernel
    x = x.contiguous().cuda();
    w = w.contiguous().cuda();
    if (has_bias) {
        b = b.contiguous().cuda();
    }

    // Allocate output tensor on CUDA device
    auto out = torch::zeros({N, C_out, L_out}, x.options());

    // Configure kernel launch parameters
    const int total_elements = N * C_out * L_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    dilated_conv1d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        has_bias ? b.data_ptr<float>() : nullptr, // Pass nullptr if no bias
        out.data_ptr<float>(),
        N, C_in, L_in, C_out, K, D, P_conv, L_out, has_bias
    );

    return out;
}
