    The ConvTranspose1d operation (with stride=1, padding=0) is re-expressed
    as a standard dilated Conv1d with transformed weights and specific padding.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store original parameters
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # Validate parameters for this specific optimization
        # The current custom kernel implementation is equivalent to ConvTranspose1d
        # only when stride=1 and padding=0.
        if self.stride != 1 or self.padding != 0:
            raise ValueError(
                "Custom kernel currently only supports ConvTranspose1d with stride=1 and padding=0. "
                f"Received stride={self.stride}, padding={self.padding}."
            )

        # Instantiate a dummy ConvTranspose1d to get the learnable weights and bias.
        # This ensures that the initial weights are the same as a standard PyTorch ConvTranspose1d
        # and allows for proper parameter management (e.g., moving to device, optimizer updates).
        dummy_conv_transpose = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias)

        # Transform weights for the equivalent dilated Conv1d.
        # PyTorch ConvTranspose1d weight shape: (in_channels, out_channels // groups, kernel_size)
        # (Assuming groups=1, so (in_channels, out_channels, kernel_size))
        # For the equivalent Conv1d, the weight shape should be (out_channels, in_channels, kernel_size).
        # Additionally, the kernel needs to be flipped along the kernel_size dimension.

        # 1. Permute dimensions: (in_channels, out_channels, kernel_size) -> (out_channels, in_channels, kernel_size)
        weight_transformed = dummy_conv_transpose.weight.permute(1, 0, 2).contiguous()
        # 2. Flip the kernel along the kernel_size dimension (last dimension)
        weight_transformed = torch.flip(weight_transformed, dims=[2]).contiguous()

        # Register the transformed weight as a learnable parameter
        self.weight = nn.Parameter(weight_transformed)

        # Register bias as a learnable parameter if it exists
        if self.has_bias:
            self.bias = nn.Parameter(dummy_conv_transpose.bias)
        else:
            self.register_parameter('bias', None)

        # Store the custom CUDA module function
        self.dilated_conv1d_cuda_op = dilated_conv1d_module.dilated_conv1d_cuda

        # Calculate the padding parameter (P_conv) for the equivalent Conv1d kernel.
        # For ConvTranspose1d with stride=1, padding=0, dilation=D, kernel_size=K,
        # the output length is L_out = L_in + D * (K - 1).
        # For a standard Conv1d with stride=1, dilation=D, kernel_size=K, and padding=P_conv,
        # the output length is L_out = L_in + 2 * P_conv - D * (K - 1).
        # Equating these, we get P_conv = D * (K - 1).
        self.P_conv = self.dilation * (self.kernel_size - 1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x shape: (batch_size, in_channels, length)
        N, C_in, L_in = x.shape

        # Calculate the output length based on the ConvTranspose1d formula
        # L_out = (L_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1
        # Given stride=1, padding=0, output_padding=0:
        L_out = (L_in - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + 1

        # Call the custom CUDA kernel
        return self.dilated_conv1d_cuda_op(
            x, self.weight, self.bias,
            N, C_in, L_in, self.out_channels, self.kernel_size, self.dilation, self.P_conv, L_out, self.has_bias
        )

