# CUDA kernel for matrix multiplication with B transposed
# This kernel computes C = A @ B.T
# A is an M x K matrix
# B is an N x K matrix (so B.T is K x N)
# C will be an M x N matrix
matmul_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel to compute C = A @ B.T
// A is M x K, B is N x K (thus B.T is K x N)
// C is M x N
__global__ void matmul_transpose_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Calculate the global row and column for the output matrix C
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Check if the current thread is within the bounds of the output matrix C
    if (row < M && col < N) {
        float sum = 0.0f;
        // Iterate over the K dimension to compute the dot product
        for (int k = 0; k < K; ++k) {
            // A[row, k] * B_T[k, col]
            // In row-major order, A[row, k] is A[row * K + k]
            // B_T[k, col] is equivalent to B[col, k] in row-major order, which is B[col * K + k]
            sum += A[row * K + k] * B[col * K + k];
        }
        // Store the computed sum in the output matrix C
        C[row * N + col] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation: ensure tensors are on CUDA, contiguous, and float32
    TORCH_CHECK(A.is_cuda(), "Input tensor A must be a CUDA tensor.");
    TORCH_CHECK(B.is_cuda(), "Input tensor B must be a CUDA tensor.");
    TORCH_CHECK(A.is_contiguous(), "Input tensor A must be contiguous.");
    TORCH_CHECK(B.is_contiguous(), "Input tensor B must be contiguous.");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "Input tensor A must be of float32 type.");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "Input tensor B must be of float32 type.");

    // Get dimensions from input tensors
    int M = A.size(0); // Number of rows in A
    int K = A.size(1); // Number of columns in A (and rows in B.T)
    int N = B.size(0); // Number of rows in B (and columns in B.T)

    // Create the output tensor C with shape (M, N)
    auto C = torch::zeros({M, N}, A.options());

    // Define block and grid dimensions for the kernel launch
    // Using a 2D block size for efficient 2D grid mapping
    const int BLOCK_SIZE_X = 32; // Threads per block along the N dimension
    const int BLOCK_SIZE_Y = 32; // Threads per block along the M dimension

    dim3 block_dim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 grid_dim(
        (N + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, // Number of blocks along the N dimension
        (M + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y  // Number of blocks along the M dimension
    );

    // Launch the CUDA kernel
    matmul_transpose_kernel<<<grid_dim, block_dim>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N
    );

    return C;
}
"""

# C++ source for the function declaration
matmul_transpose_cpp_source = (
    "torch::Tensor matmul_transpose_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
matmul_transpose_module = load_inline(
    name="matmul_transpose_module",
    cpp_sources=matmul_transpose_cpp_source,
    cuda_sources=matmul_transpose_source,
    functions=["matmul_transpose_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
