    Optimized model that replaces torch.matmul(A, B.T) with a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the compiled custom CUDA operator as a member
        self.matmul_transpose_op = matmul_transpose_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication using the custom CUDA kernel.

        Args:
            A: Input tensor of shape (M, K).
            B: Input tensor of shape (N, K).

        Returns:
            Output tensor of shape (M, N).
        """
        # Ensure input tensors are on the CUDA device before calling the custom kernel
        A_cuda = A.cuda()
        B_cuda = B.cuda()
