import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 1D convolution.
# This kernel will be used to implement ConvTranspose1d for specific parameters
# (stride=1, padding=0, output_padding=0, groups=1, bias=False).
# In this specific configuration, ConvTranspose1d is equivalent to a Conv1d
# with a flipped kernel and padding = kernel_size - 1.
conv1d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for 1D convolution with stride=1, groups=1, and no bias.
// Padding is handled by implicitly treating out-of-bounds input as zero.
// Each thread computes one element of the output tensor.
__global__ void conv1d_kernel(const float* x_ptr, const float* W_ptr, float* y_ptr,
                              int N, int C_in, int L_in, int C_out, int K, int P, int L_out) {
    // Calculate total number of output elements
    long long total_output_elements = (long long)N * C_out * L_out;

    // Each thread computes one output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Deconstruct the global index 'idx' into batch (n), output channel (c_out), and output length (l_out)
        int n = idx / (C_out * L_out);
        int c_out = (idx % (C_out * L_out)) / L_out;
        int l_out = idx % L_out;

        float sum = 0.0f;
        // Iterate over input channels
        for (int c_in = 0; c_in < C_in; ++c_in) {
            // Iterate over kernel elements
            for (int k = 0; k < K; ++k) {
                // Calculate the corresponding input index in the original (unpadded) input.
                // For Conv1d with stride=1, the input index l_in_actual is related to l_out, k, and padding P.
                // l_in_actual = l_out + k - P
                int l_in_actual = l_out + k - P;

                // Check if l_in_actual is within the valid range of the input tensor's length.
                // If it's out of bounds, it means the conceptual padded input is zero at this position.
                if (l_in_actual >= 0 && l_in_actual < L_in) {
                    // Calculate memory offsets for x and W.
                    // x is (N, C_in, L_in)
                    // W is (C_out, C_in, K)
                    // Using long long for intermediate products to prevent overflow with large dimensions.
                    sum += x_ptr[n * (long long)C_in * L_in + c_in * (long long)L_in + l_in_actual] *
                           W_ptr[c_out * (long long)C_in * K + c_in * (long long)K + k];
                }
            }
        }
        y_ptr[idx] = sum;
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor conv1d_cuda_forward(torch::Tensor x, torch::Tensor W,
                                  int K, int P) {
    // Input x: (N, C_in, L_in)
    // Weight W: (C_out, C_in, K) - pre-processed from ConvTranspose1d weights

    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(W.is_cuda(), "Weight tensor 'W' must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 3, "Input tensor 'x' must be 3D (N, C_in, L_in).");
    TORCH_CHECK(W.dim() == 3, "Weight tensor 'W' must be 3D (C_out, C_in, K).");

    int N = x.size(0);
    int C_in = x.size(1);
    int L_in = x.size(2);
    int C_out = W.size(0);
    // K (kernel_size) and P (padding) are passed as arguments.

    TORCH_CHECK(C_in == W.size(1), "Input channels of 'x' and 'W' must match.");
    TORCH_CHECK(K == W.size(2), "Kernel size 'K' must match W's last dimension.");

    // Calculate output length for Conv1d with stride=1
    // L_out = (L_in + 2 * P - K) / 1 + 1
    int L_out = L_in + 2 * P - K + 1;
    TORCH_CHECK(L_out > 0, "Calculated output length L_out must be positive.");

    // Create the output tensor, ensuring it's on the same device and has the same dtype as input x.
    auto y = torch::zeros({N, C_out, L_out}, x.options());

    // Configure CUDA kernel launch parameters
    long long total_output_elements = (long long)N * C_out * L_out;
    const int block_size = 256; // A common block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv1d_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), W.data_ptr<float>(), y.data_ptr<float>(),
        N, C_in, L_in, C_out, K, P, L_out
    );

    // Check for any CUDA errors after kernel execution
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA error in conv1d_kernel: ", cudaGetErrorString(err));

    return y;
}
"""

# C++ header for the inline compilation
conv1d_cpp_source = (
    "torch::Tensor conv1d_cuda_forward(torch::Tensor x, torch::Tensor W, int K, int P);"
)

# Compile the inline CUDA code
conv1d_custom = load_inline(
    name="conv1d_custom",
    cpp_sources=conv1d_cpp_source,
    cuda_sources=conv1d_cuda_source,
    functions=["conv1d_cuda_forward"],
    verbose=True,
    extra_cflags=["-O3"],  # Add optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"],  # Add optimization flags for CUDA compiler
)


class ModelNew(nn.Module):
    """
    Optimized version of ConvTranspose1d for specific parameters using a custom CUDA kernel.
    This custom kernel is designed for:
    - stride=1
    - padding=0
    - output_padding=0
    - groups=1
    - bias=False

    Under these conditions, ConvTranspose1d(in_channels, out_channels, kernel_size)
    is equivalent to a Conv1d operation with:
    - input: original input x
    - weights: original ConvTranspose1d weights, flipped along the kernel dimension, and then permuted
               from (C_in, C_out, K) to (C_out, C_in, K).
    - stride=1
    - padding=kernel_size - 1
    - groups=1
    - bias=False
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store original parameters for validation and reference
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Validate that the custom kernel can handle the provided parameters
        if not (stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias == False):
            raise ValueError(
                "Custom ConvTranspose1d kernel in ModelNew only supports "
                "stride=1, padding=0, output_padding=0, groups=1, and bias=False. "
                "For other parameters, the original PyTorch operator should be used."
            )

        # Initialize a dummy ConvTranspose1d layer to get its default initialized weight tensor.
        # This ensures our custom kernel uses the same initial weights as the PyTorch operator.
        dummy_conv = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, 
                                        stride=stride, padding=padding, 
                                        output_padding=output_padding, groups=groups, bias=bias)

        # Pre-process the weight for the custom Conv1d kernel:
        # 1. Flip the kernel along the last dimension (kernel_size dimension).
        #    PyTorch's ConvTranspose1d weights are (in_channels, out_channels // groups, kernel_size).
        weight_flipped = dummy_conv.weight.flip(dims=[-1])

        # 2. Permute dimensions from (C_in, C_out, K) to (C_out, C_in, K).
        #    This is because our custom Conv1d kernel (like F.conv1d) expects weights in this format.
        self.weight_preprocessed = nn.Parameter(weight_flipped.permute(1, 0, 2))

        # Store kernel_size and padding for the custom Conv1d kernel.
        # For ConvTranspose1d with stride=1, padding=0, output_padding=0,
        # the equivalent Conv1d requires padding = kernel_size - 1.
        self.custom_kernel_size = kernel_size
        self.custom_padding = kernel_size - 1

        # Store the compiled custom CUDA kernel module
        self.conv1d_custom = conv1d_custom

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 1D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, length).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, length_out).
        """
        # Ensure input tensor is on the CUDA device before passing to the kernel
        x = x.cuda()

        # Call the custom CUDA kernel with the pre-processed weights and parameters
        return self.conv1d_custom.conv1d_cuda_forward(
            x,
            self.weight_preprocessed,
            self.custom_kernel_size,
            self.custom_padding
        )

