import math

# Define the custom CUDA kernel for ConvTranspose2d
conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrt

// CUDA kernel definition for ConvTranspose2d
// This kernel implements a direct gather-style computation for ConvTranspose2d.
// It supports arbitrary kernel sizes, strides, padding, and dilation,
// but is limited to groups=1 and no bias.
__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K_H, int K_W,
    int H_out, int W_out,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    // Each thread computes one output element (n, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C_out * H_out * W_out) {
        // Decompose linear index into 4D output coordinates
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int c_out = idx % C_out;
        idx /= C_out;
        int n = idx;

        float sum = 0.0f;

        // Iterate over input channels and kernel dimensions
        // For each output pixel (h_out, w_out), we find all contributing
        // input pixels (h_in, w_in) and kernel elements (k_h, k_w).
        // The relationship is:
        // h_out = h_in * stride_h - padding_h + k_h * dilation_h
        // w_out = w_in * stride_w - padding_w + k_w * dilation_w
        //
        // From this, we derive h_in and w_in:
        // h_in = (h_out + padding_h - k_h * dilation_h) / stride_h
        // w_in = (w_out + padding_w - k_w * dilation_w) / stride_w
        //
        // We must ensure that h_in and w_in are integers (divisible by stride)
        // and within the bounds of the input tensor.

        for (int c_in = 0; c_in < C_in; ++c_in) {
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    int h_in_candidate_num = h_out + padding_h - k_h * dilation_h;
                    int w_in_candidate_num = w_out + padding_w - k_w * dilation_w;

                    // Check if the candidate numerator is non-negative and perfectly divisible by stride
                    if (h_in_candidate_num >= 0 && h_in_candidate_num % stride_h == 0 &&
                        w_in_candidate_num >= 0 && w_in_candidate_num % stride_w == 0) {

                        int h_in = h_in_candidate_num / stride_h;
                        int w_in = w_in_candidate_num / stride_w;

                        // Check if the derived input coordinates are within the input tensor bounds
                        if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                            // Input tensor layout: (N, C_in, H_in, W_in)
                            // Weight tensor layout: (C_in, C_out, K_H, K_W)
                            // Output tensor layout: (N, C_out, H_out, W_out)

                            // Calculate linear indices for input and weight
                            size_t input_idx = n * C_in * H_in * W_in +
                                               c_in * H_in * W_in +
                                               h_in * W_in +
                                               w_in;

                            size_t weight_idx = c_in * C_out * K_H * K_W +
                                                c_out * K_H * K_W +
                                                k_h * K_W +
                                                k_w;

                            sum += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
            }
        }
        // Store the computed sum in the output tensor
        size_t output_idx = n * C_out * H_out * W_out +
                             c_out * H_out * W_out +
                             h_out * W_out +
                             w_out;
        output[output_idx] = sum;
    }
}
