conv_transpose2d_cpp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrt

// C++ wrapper function to launch the CUDA kernel
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int output_padding_h, int output_padding_w
) {
    // Input tensor shape: (N, C_in, H_in, W_in)
    // Weight tensor shape: (C_in, C_out, K_H, K_W)

    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA device.");
    TORCH_CHECK(input.dim() == 4, "Input tensor must be 4D (N, C_in, H_in, W_in).");
    TORCH_CHECK(weight.dim() == 4, "Weight tensor must be 4D (C_in, C_out, K_H, K_W).");

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weight.size(1);
    int K_H = weight.size(2);
    int K_W = weight.size(3);

    TORCH_CHECK(C_in == weight.size(0), "Input channels must match weight's in_channels dimension.");

    // Calculate the output dimensions based on ConvTranspose2d formula
    // H_out = (H_in - 1) * stride_h - 2 * padding_h + dilation_h * (K_H - 1) + output_padding_h + 1
    // W_out = (W_in - 1) * stride_w - 2 * padding_w + dilation_w * (K_W - 1) + output_padding_w + 1
    int H_out = (H_in - 1) * stride_h - 2 * padding_h + dilation_h * (K_H - 1) + output_padding_h + 1;
    int W_out = (W_in - 1) * stride_w - 2 * padding_w + dilation_w * (K_W - 1) + output_padding_w + 1;

    // Create the output tensor, ensuring it's on the same device and has the same dtype as input
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Calculate grid and block dimensions for kernel launch
    const int total_elements = N * C_out * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K_H, K_W,
        H_out, W_out,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w
    );

    // Check for any CUDA errors after kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
