# Compile the inline CUDA code for ConvTranspose2d
conv_transpose2d_custom = load_inline(
    name="conv_transpose2d_custom",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
