import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 4D tensor-matrix multiplication
# C[b, i, j, k] = sum_l A[b, i, j, l] * B[l, k]
tensor_matrix_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel for 4D tensor-matrix multiplication: C[b, i, j, k] = sum_l A[b, i, j, l] * B[l, k]
__global__ void tensor_matrix_mul_kernel(
    const float* A_ptr, const float* B_ptr, float* C_ptr,
    int b_dim, int i_dim, int j_dim, int l_dim, int k_dim) {

    // Calculate total number of output elements
    // Use long long for total_elements and offsets to prevent overflow for large dimensions
    long long total_elements = (long long)b_dim * i_dim * j_dim * k_dim;

    // Global thread index
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Map global index to (b, i, j, k) coordinates
        int k_idx = idx % k_dim;
        long long temp = idx / k_dim;
        int j_idx = temp % j_dim;
        temp /= j_dim;
        int i_idx = temp % i_dim;
        int b_idx = temp / i_dim;

        float sum = 0.0f;

        // Iterate over 'l' dimension to compute the dot product
        for (int l_idx = 0; l_idx < l_dim; ++l_idx) {
            // Access A[b_idx, i_idx, j_idx, l_idx]
            // A is row-major: A[b][i][j][l]
            long long A_offset = (long long)b_idx * i_dim * j_dim * l_dim +
                                 (long long)i_idx * j_dim * l_dim +
                                 (long long)j_idx * l_dim +
                                 l_idx;
            float val_A = A_ptr[A_offset];

            // Access B[l_idx, k_idx]
            // B is row-major: B[l][k]
            long long B_offset = (long long)l_idx * k_dim + k_idx;
            float val_B = B_ptr[B_offset];

            sum += val_A * val_B;
        }

        // Store result in C[b_idx, i_idx, j_idx, k_idx]
        // C is row-major: C[b][i][j][k]
        long long C_offset = (long long)b_idx * i_dim * j_dim * k_dim +
                             (long long)i_idx * j_dim * k_dim +
                             (long long)j_idx * k_dim +
                             k_idx;
        C_ptr[C_offset] = sum;
    }
}

torch::Tensor tensor_matrix_mul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation
    TORCH_CHECK(A.is_cuda(), "Input tensor A must be on CUDA");
    TORCH_CHECK(B.is_cuda(), "Input tensor B must be on CUDA");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "Input tensor A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "Input tensor B must be float32");
    TORCH_CHECK(A.dim() == 4, "Input tensor A must be a 4D tensor");
    TORCH_CHECK(B.dim() == 2, "Input tensor B must be a 2D tensor");

    // Get dimensions from input tensors
    int b_dim = A.size(0);
    int i_dim = A.size(1);
    int j_dim = A.size(2);
    int l_dim_A = A.size(3); // 'l' dimension from A
    int l_dim_B = B.size(0); // 'l' dimension from B
    int k_dim = B.size(1);   // 'k' dimension from B

    // Check for dimension compatibility
    TORCH_CHECK(l_dim_A == l_dim_B, "Dimension mismatch: A's last dimension (l) must match B's first dimension (l)");

    // Create the output tensor C with the appropriate shape and options (device, dtype)
    torch::Tensor C = torch::zeros({b_dim, i_dim, j_dim, k_dim}, A.options());

    // Calculate total number of output elements for kernel launch configuration
    long long total_elements = (long long)b_dim * i_dim * j_dim * k_dim;

    // Configure kernel launch parameters
    const int block_size = 256; // A common block size for CUDA kernels
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    tensor_matrix_mul_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        b_dim, i_dim, j_dim, l_dim_A, k_dim);

    // Check for any CUDA errors that might have occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return C;
}
