# Define the custom CUDA kernel for matrix-vector multiplication
matvec_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for matrix-vector multiplication (C = A * B)
// A: (M, K) matrix
// B: (K, 1) vector (treated as a 1D array of K elements)
// C: (M, 1) output vector
__global__ void matvec_mul_kernel(const float* A, const float* B, float* C, int M, int K) {
    // Each block is responsible for computing one element of the output vector C.
    // blockIdx.x corresponds to the row index in A and C.
    int row_idx = blockIdx.x;

    if (row_idx < M) {
        // Dynamically allocated shared memory for partial sums within the block.
        // This is used for the parallel reduction.
        extern __shared__ float s_partial_sums[];

        float thread_sum = 0.0f;

        // Each thread in the block computes a partial sum for its assigned row.
        // Threads process elements of A and B in a strided fashion to ensure
        // all K elements are covered by the block and to potentially improve
        // memory coalescing for A.
        for (int k = threadIdx.x; k < K; k += blockDim.x) {
            thread_sum += A[row_idx * K + k] * B[k];
        }

        // Store the thread's partial sum in shared memory.
        s_partial_sums[threadIdx.x] = thread_sum;
        __syncthreads(); // Synchronize to ensure all partial sums are written before reduction.

        // Perform a parallel reduction (tree reduction) in shared memory
        // to sum up all partial sums from threads in the block.
        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_partial_sums[threadIdx.x] += s_partial_sums[threadIdx.x + s];
            }
            __syncthreads(); // Synchronize after each reduction step.
        }

        // The first thread in the block writes the final sum for the row
        // to the global output vector C.
        if (threadIdx.x == 0) {
            C[row_idx] = s_partial_sums[0];
        }
    }
}

// Wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor matvec_mul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation: ensure tensors are on CUDA and are float32.
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    // Get dimensions from input tensors.
    int M = A.size(0);
    int K = A.size(1);

    // Validate dimensions of B.
    TORCH_CHECK(B.size(0) == K, "Dimension mismatch: B.size(0) must be K");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be a column vector (K, 1)");

    // Create the output tensor C with the same options (device, dtype) as A.
    auto C = torch::zeros({M, 1}, A.options());

    // Define kernel launch parameters.
    // We use 256 threads per block, a common and efficient block size.
    const int block_size = 256;
    // We launch one block for each row of the output matrix C.
    const int num_blocks = M;

    // Calculate the size of dynamically allocated shared memory required per block.
    // Each thread needs space for its partial sum (float).
    size_t shared_mem_bytes = block_size * sizeof(float);

    // Launch the CUDA kernel.
    // The third argument to <<<>>> specifies dynamic shared memory size.
    matvec_mul_kernel<<<num_blocks, block_size, shared_mem_bytes>>>(
        A.data_ptr<float>(), // Pointer to A's data
        B.data_ptr<float>(), // Pointer to B's data
        C.data_ptr<float>(), // Pointer to C's data
        M,                   // M dimension
        K                    // K dimension
    );

    // Check for any CUDA errors that might have occurred during kernel execution.
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return C;
}
"""

# C++ header for the CUDA function
matvec_mul_cpp_source = (
    "torch::Tensor matvec_mul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
