#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, fmaxf

// CUDA kernel to compute Triplet Margin Loss for each triplet in the batch.
// Each thread block processes one triplet (one row from anchor, positive, negative).
// Threads within a block compute squared differences and perform a parallel reduction
// to get the squared L2 norms.
__global__ void triplet_margin_loss_kernel(
    const float* anchor, const float* positive, const float* negative,
    float* output_losses, int batch_size, int embedding_dim, float margin) {

    int batch_idx = blockIdx.x; // Each block handles one triplet from the batch

    // Guard against out-of-bounds block indices if num_blocks > batch_size (not the case here)
    if (batch_idx >= batch_size) {
        return;
    }

    // Dynamically allocated shared memory for reduction within the block.
    // It will store thread-local sums for both positive and negative differences.
    extern __shared__ float s_data[];
    float* s_sum_sq_pos = s_data;
    float* s_sum_sq_neg = s_data + blockDim.x; // Offset for the second array

    float thread_sum_sq_pos = 0.0f;
    float thread_sum_sq_neg = 0.0f;

    // Calculate starting pointers for the current triplet's data in global memory
    const float* current_anchor = anchor + batch_idx * embedding_dim;
    const float* current_positive = positive + batch_idx * embedding_dim;
    const float* current_negative = negative + batch_idx * embedding_dim;

    // Each thread processes multiple elements along the embedding_dim
    // This loop ensures all elements of the embedding are covered by the block's threads.
    for (int i = threadIdx.x; i < embedding_dim; i += blockDim.x) {
        float diff_pos = current_anchor[i] - current_positive[i];
        float diff_neg = current_anchor[i] - current_negative[i];
        thread_sum_sq_pos += diff_pos * diff_pos;
        thread_sum_sq_neg += diff_neg * diff_neg;
    }

    // Store thread-local sums into shared memory
    s_sum_sq_pos[threadIdx.x] = thread_sum_sq_pos;
    s_sum_sq_neg[threadIdx.x] = thread_sum_sq_neg;
    __syncthreads(); // Synchronize to ensure all writes to shared memory are visible

    // Perform parallel reduction in shared memory to get the total sum of squares for the triplet.
    // This loop assumes blockDim.x is a power of 2 for optimal performance.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum_sq_pos[threadIdx.x] += s_sum_sq_pos[threadIdx.x + s];
            s_sum_sq_neg[threadIdx.x] += s_sum_sq_neg[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Thread 0 in the block computes the final loss for this triplet
    if (threadIdx.x == 0) {
        // Calculate L2 norms (distances)
        float dist_pos = sqrtf(s_sum_sq_pos[0]);
        float dist_neg = sqrtf(s_sum_sq_neg[0]);

        // Apply the Triplet Margin Loss formula: max(0, dist_pos - dist_neg + margin)
        output_losses[batch_idx] = fmaxf(0.0f, dist_pos - dist_neg + margin);
    }
