    TORCH_CHECK(anchor.is_contiguous() && positive.is_contiguous() && negative.is_contiguous(), "All inputs must be contiguous.");
    TORCH_CHECK(anchor.dtype() == torch::kFloat32, "Inputs must be float32.");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(), "Input tensors must have the same shape.");
