#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min, though we'll do it manually

// Max number of dimensions supported. PyTorch tensors can have up to 64, but
// for practical purposes and stack allocation, a smaller number (e.g., 10) is usually sufficient.
// The example input has 3 dimensions.
#define MAX_DIMS 10

__global__ void argmin_kernel(
    const float* x_data,
    long* out_data,
    int dim_to_reduce,
    int num_dims,
    int out_num_dims,
    const long* x_sizes,
    const long* x_strides,
    const long* out_sizes) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Calculate total number of elements in the output tensor
    // This is needed to check if 'idx' is within bounds.
    long total_out_elements = 1;
    for (int d = 0; d < out_num_dims; ++d) {
        total_out_elements *= out_sizes[d];
    }
    // If out_num_dims is 0 (scalar output), the loop won't run, and total_out_elements remains 1, which is correct.

    if (idx >= total_out_elements) {
        return;
    }

    long x_base_offset = 0;

    // If the output is not a scalar (i.e., out_num_dims > 0),
    // we need to map the linear output index 'idx' to a multi-dimensional index
    // and use it to calculate the base offset for the input tensor.
    if (out_num_dims > 0) {
        long out_multi_idx[MAX_DIMS]; // Stack array for multi-dimensional index
        long current_idx_for_multi = idx;
        for (int d = out_num_dims - 1; d >= 0; --d) {
            out_multi_idx[d] = current_idx_for_multi % out_sizes[d];
            current_idx_for_multi /= out_sizes[d];
        }

        int current_out_dim_idx = 0; // Index for out_multi_idx
        for (int d = 0; d < num_dims; ++d) {
            if (d == dim_to_reduce) {
                // This dimension will be iterated over in the loop below
                continue;
            }
            // Add the contribution of this dimension to the base offset
            x_base_offset += out_multi_idx[current_out_dim_idx] * x_strides[d];
            current_out_dim_idx++;
        }
    }
    // If out_num_dims is 0 (scalar output), x_base_offset remains 0, which is correct.

    // Find the minimum value and its index along 'dim_to_reduce'
    long dim_size = x_sizes[dim_to_reduce];

    // Initialize min_val with the first element along the dimension
    // This assumes dim_size > 0, which is handled by the wrapper's empty tensor checks.
    float min_val = x_data[x_base_offset + 0 * x_strides[dim_to_reduce]];
    long min_idx_in_dim = 0;

    for (long i = 1; i < dim_size; ++i) {
        float current_val = x_data[x_base_offset + i * x_strides[dim_to_reduce]];
        if (current_val < min_val) {
            min_val = current_val;
            min_idx_in_dim = i;
        }
    }

    // Store the found index in the output tensor
    out_data[idx] = min_idx_in_dim;
