// B: (K_dim, N_cols)
// C: (M_rows, N_cols)

__global__ void matmul_tiled_kernel(const float* A, const float* B, float* C, int M_rows, int K_dim, int N_cols) {
    // Define block dimensions. These are chosen to be 32x32, a common size for CUDA blocks.
    // BLOCK_SIZE_X corresponds to the N_cols dimension of C.
    // BLOCK_SIZE_Y corresponds to the M_rows dimension of C.
    const int BLOCK_SIZE_X = 32;
    const int BLOCK_SIZE_Y = 32;

    // Calculate the global row and column index for the element of C that this thread computes.
    int row = blockIdx.y * BLOCK_SIZE_Y + threadIdx.y; // Global row index in C
    int col = blockIdx.x * BLOCK_SIZE_X + threadIdx.x; // Global column index in C

    // Shared memory for a tile of B.
    // This tile will hold K_dim rows and BLOCK_SIZE_X columns of B.
    // For the given problem (K_dim=32, BLOCK_SIZE_X=32), this is a 32x32 tile.
    // Each thread (threadIdx.y, threadIdx.x) will load one element into sB_tile.
    // sB_tile[threadIdx.y][threadIdx.x] will store B[threadIdx.y, C_start + threadIdx.x].
    // This strategy requires BLOCK_SIZE_Y to be at least K_dim for threadIdx.y to cover all K_dim rows.
    // Since K_dim is 32 in the example, BLOCK_SIZE_Y = 32 is a perfect match.
    __shared__ float sB_tile[32][32]; // Max K_dim x Max BLOCK_SIZE_X

    // Load a tile of B from global memory into shared memory.
    // Each thread in the block loads one element.
    // threadIdx.y is used for the row index of B (which corresponds to the K_dim index).
    // threadIdx.x is used for the column index of B within the current tile.
    if (threadIdx.y < K_dim && (blockIdx.x * BLOCK_SIZE_X + threadIdx.x) < N_cols) {
        // Calculate the global column index for B
        int global_b_col = blockIdx.x * BLOCK_SIZE_X + threadIdx.x;
        sB_tile[threadIdx.y][threadIdx.x] = B[threadIdx.y * N_cols + global_b_col];
    } else {
        // Pad with zeros if the access is out of bounds for B.
        // This ensures correctness when N_cols is not a multiple of BLOCK_SIZE_X,
        // or if K_dim is smaller than BLOCK_SIZE_Y (though not in this specific example).
        sB_tile[threadIdx.y][threadIdx.x] = 0.0f;
    }
    __syncthreads(); // Ensure all threads have finished loading their part of sB_tile before computation begins.

    float sum = 0.0f;
    // Perform the matrix multiplication for the element C[row, col]
    if (row < M_rows && col < N_cols) {
        for (int k = 0; k < K_dim; ++k) {
            // A[row, k] is accessed from global memory. For a given 'row', this is a coalesced access.
            // B[k, col] is accessed from shared memory (sB_tile[k][threadIdx.x]).
            // This optimizes the strided global memory access pattern of B.
            sum += A[row * K_dim + k] * sB_tile[k][threadIdx.x];
        }
        C[row * N_cols + col] = sum;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Input validation
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");

    int M_rows = A.size(0);
    int K_dim_A = A.size(1);
    int K_dim_B = B.size(0);
    int N_cols = B.size(1);

    TORCH_CHECK(K_dim_A == K_dim_B, "Matrix dimensions incompatible for multiplication");

    int K_dim = K_dim_A; // The common inner dimension

    // This kernel is optimized for K_dim <= 32 due to the fixed shared memory tile size.
    // For larger K_dim, a different tiling strategy (iterating over K_dim in chunks) would be needed.
    TORCH_CHECK(K_dim <= 32, "K_dim must be <= 32 for this specialized kernel.");

    // Create the output tensor C on the same device as inputs
    auto C = torch::zeros({M_rows, N_cols}, A.options());

    // Define block and grid dimensions for kernel launch
    const int BLOCK_SIZE_X = 32;
    const int BLOCK_SIZE_Y = 32; // Must be >= K_dim for the shared memory loading strategy

    dim3 block_dim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 grid_dim(
        (N_cols + block_dim.x - 1) / block_dim.x, // Number of blocks in X-dimension
        (M_rows + block_dim.y - 1) / block_dim.y  // Number of blocks in Y-dimension
    );

    // Launch the CUDA kernel
    matmul_tiled_kernel<<<grid_dim, block_dim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M_rows,
        K_dim,
        N_cols
    );

    // Check for any CUDA errors that occurred during kernel execution
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return C;
}
"""

# C++ header for the CUDA function
matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
matmul_custom = load_inline(
    name="matmul_custom",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that replaces torch.matmul with a custom CUDA kernel
    specialized for "tall and skinny" matrix multiplications where the inner
    dimension (K) is small.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the compiled custom CUDA function as a member of the module
        self.matmul_custom = matmul_custom

    def forward(self, A, B):
        """
        Performs the matrix multiplication using the custom CUDA kernel.

        Args:
            A (torch.Tensor): Input matrix of shape (M, K).
            B (torch.Tensor): Input matrix of shape (K, N).

        Returns:
            torch.Tensor: Output matrix of shape (M, N).
        """
        return self.matmul_custom.matmul_cuda(A, B)

