import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels and the C++ wrapper function for fused MSE calculation
mse_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // Required for std::min

// CUDA kernel to compute partial sums of squared differences.
// It uses a grid-stride loop to process all elements and shared memory for block-wise reduction.
// Accumulators are double precision to maintain accuracy for large sums.
__global__ void mse_reduction_kernel(const float* predictions, const float* targets, double* partial_sums, long long N) {
    // Shared memory for block-wise reduction, declared dynamically
    extern __shared__ double sdata[]; 

    int tid = threadIdx.x;
    // Calculate global index start for this thread
    long long global_idx_start = (long long)blockIdx.x * blockDim.x + tid;
    // Calculate the total number of threads in the grid
    long long grid_stride = (long long)gridDim.x * blockDim.x;

    double block_sum = 0.0; // Accumulate sum in double precision

    // Grid-stride loop: each thread processes multiple elements if N is larger than grid size
    for (long long i = global_idx_start; i < N; i += grid_stride) {
        // Calculate difference and square it, casting to double for precision
        double diff = (double)predictions[i] - (double)targets[i];
        block_sum += diff * diff;
    }

    // Store thread's partial sum in shared memory
    sdata[tid] = block_sum;
    __syncthreads(); // Synchronize threads within the block

    // Perform reduction within the block using shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The first thread in the block writes the block's total sum to global memory
    if (tid == 0) {
        partial_sums[blockIdx.x] = sdata[0];
    }
}

// CUDA kernel to sum the partial sums computed by the first kernel.
// It also uses a grid-stride loop and shared memory reduction.
// An atomicAdd is used for the final sum across blocks to ensure correctness.
__global__ void final_sum_kernel(const double* partial_sums, double* total_sum_out, int num_partial_sums) {
    // Shared memory for block-wise reduction, declared dynamically
    extern __shared__ double sdata[]; 

    int tid = threadIdx.x;
    // Calculate global index start for this thread
    int global_idx_start = blockIdx.x * blockDim.x + tid;
    // Calculate the total number of threads in the grid
    int grid_stride = gridDim.x * blockDim.x;

    double block_sum = 0.0; // Accumulate sum in double precision

    // Grid-stride loop: each thread processes multiple partial sums
    for (int i = global_idx_start; i < num_partial_sums; i += grid_stride) {
        block_sum += partial_sums[i];
    }

    // Store thread's partial sum in shared memory
    sdata[tid] = block_sum;
    __syncthreads(); // Synchronize threads within the block

    // Perform reduction within the block using shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The first thread in the block atomically adds the block's total sum to the final result.
    // atomicAdd for double requires compute capability 6.0 (Pascal) or higher.
    if (tid == 0) {
        atomicAdd(total_sum_out, sdata[0]);
    }
}

// C++ wrapper function callable from Python
torch::Tensor mse_cuda(torch::Tensor predictions, torch::Tensor targets) {
    // Input validation checks
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.is_contiguous(), "predictions must be contiguous");
    TORCH_CHECK(targets.is_contiguous(), "targets must be contiguous");
    TORCH_CHECK(predictions.scalar_type() == torch::kFloat, "predictions must be float32");
    TORCH_CHECK(targets.scalar_type() == torch::kFloat, "targets must be float32");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "predictions and targets must have the same shape");

    long long N = predictions.numel(); // Total number of elements

    const int block_size = 256; // Standard block size for CUDA kernels

    // --- First kernel launch: Compute partial sums of squared differences ---
    // Determine grid size for the first kernel. Cap it to avoid excessive blocks,
    // relying on the grid-stride loop within the kernel to cover all elements.
    int grid_size_1 = std::min((int)((N + block_size - 1) / block_size), 8192); 

    // Allocate a tensor on the GPU for storing partial sums.
    // Using double precision (kDouble) for accuracy.
    auto partial_sums = torch::zeros({grid_size_1}, torch::TensorOptions().dtype(torch::kDouble).device(predictions.device()));

    // Launch the mse_reduction_kernel.
    // The third argument specifies dynamic shared memory size per block.
    mse_reduction_kernel<<<grid_size_1, block_size, block_size * sizeof(double)>>>(
        predictions.data_ptr<float>(), // Pointer to predictions data
        targets.data_ptr<float>(),     // Pointer to targets data
        partial_sums.data_ptr<double>(), // Pointer to partial sums output buffer
        N                              // Total number of elements
    );

    // --- Second kernel launch: Sum the partial sums ---
    int num_partial_sums_for_final = grid_size_1;
    // Determine grid size for the second kernel, capped similarly.
    int grid_size_2 = std::min((num_partial_sums_for_final + block_size - 1) / block_size, 8192);

    // Allocate a scalar tensor on the GPU for the final total sum.
    // Initialized to 0 and using double precision.
    auto total_sum_out = torch::zeros({1}, torch::TensorOptions().dtype(torch::kDouble).device(predictions.device()));

    // Launch the final_sum_kernel.
    // The third argument specifies dynamic shared memory size per block.
    final_sum_kernel<<<grid_size_2, block_size, block_size * sizeof(double)>>>(
        partial_sums.data_ptr<double>(), // Pointer to partial sums input
        total_sum_out.data_ptr<double>(), // Pointer to final total sum output
        num_partial_sums_for_final     // Number of partial sums to process
    );

    // Final division to get the mean. The result is a double precision scalar tensor.
    return total_sum_out / (double)N;
}
"""

# C++ header for the Python-callable function
mse_cpp_source = (
    "torch::Tensor mse_cuda(torch::Tensor predictions, torch::Tensor targets);"
)

# Compile the inline CUDA code for MSE calculation
mse_custom_op = load_inline(
    name="mse_custom_op",
    cpp_sources=mse_cpp_source,
    cuda_sources=mse_source,
    functions=["mse_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # C++ compiler optimization flags
