# Define the custom CUDA kernel for depthwise 2D convolution
depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For debugging, can remove

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias, // Can be nullptr if no bias
    float* output,
    int B, int C_in, int H_in, int W_in,
    int C_out, int K, int S, int P,
    int H_out, int W_out,
    bool use_bias) {

    // Each thread computes one output pixel (b, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < B * C_out * H_out * W_out) {
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out * H_out)) % C_out;
        int b = idx / (C_out * H_out * W_out);

        // For depthwise convolution with groups=in_channels and out_channels=in_channels,
        // each input channel corresponds to one output channel.
        int c_in = c_out; 

        float acc = 0.0f;

        for (int k_h = 0; k_h < K; ++k_h) {
            for (int k_w = 0; k_w < K; ++k_w) {
                int h_in = h_out * S + k_h - P;
                int w_in = w_out * S + k_w - P;

                // Check bounds for input
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    // Input tensor: (B, C_in, H_in, W_in)
                    // Index: b * C_in*H_in*W_in + c_in*H_in*W_in + h_in*W_in + w_in
                    long long input_offset = (long long)b * C_in * H_in * W_in +
                                             (long long)c_in * H_in * W_in +
                                             (long long)h_in * W_in +
                                             (long long)w_in;

                    // Weight tensor: (C_out, 1, K, K)
                    // Index: c_out * 1*K*K + 0*K*K + k_h*K + k_w
                    long long weight_offset = (long long)c_out * K * K +
                                              (long long)k_h * K +
                                              (long long)k_w;

                    acc += input[input_offset] * weight[weight_offset];
                }
            }
        }

        if (use_bias) {
            acc += bias[c_out]; // Bias is (C_out,)
        }

        // Output tensor: (B, C_out, H_out, W_out)
        // Index: b * C_out*H_out*W_out + c_out*H_out*W_out + h_out*W_out + w_out
        long long output_offset = (long long)b * C_out * H_out * W_out +
                                  (long long)c_out * H_out * W_out +
                                  (long long)h_out * W_out +
                                  (long long)w_out;
        output[output_offset] = acc;
    }
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias_tensor, // Pass as tensor, check if it's empty
    int K, int S, int P) {

    // Input: (B, C_in, H_in, W_in)
    // Weight: (C_out, 1, K, K)
    // Bias: (C_out,) or empty

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    if (bias_tensor.defined()) {
        TORCH_CHECK(bias_tensor.is_cuda(), "bias must be a CUDA tensor");
    }

    TORCH_CHECK(input.dim() == 4, "input must be 4D (B, C_in, H_in, W_in)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (C_out, 1, K, K)");
    TORCH_CHECK(weight.size(1) == 1, "weight second dim must be 1 for depthwise");
    TORCH_CHECK(weight.size(2) == K && weight.size(3) == K, "weight kernel size mismatch");

    int B = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weight.size(0); 
    // For the given architecture (groups=in_channels, out_channels=in_channels),
    // C_out will be equal to C_in.

    // Calculate output dimensions
    int H_out = (H_in + 2 * P - K) / S + 1;
    int W_out = (W_in + 2 * P - K) / S + 1;

    TORCH_CHECK(H_out > 0 && W_out > 0, "Output dimensions must be positive");

    auto output = torch::zeros({B, C_out, H_out, W_out}, input.options());

    const int total_elements = B * C_out * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* bias_ptr = bias_tensor.defined() ? bias_tensor.data_ptr<float>() : nullptr;
    bool use_bias = bias_tensor.defined();

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        B, C_in, H_in, W_in,
        C_out, K, S, P,
        H_out, W_out,
        use_bias);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
"""

depthwise_conv2d_cpp_source = (
    "torch::Tensor depthwise_conv2d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias_tensor, int K, int S, int P);"
)

# Compile the inline CUDA code
depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d_module",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
