    """
    Performs a depthwise 2D convolution with asymmetric input and square kernel
    using a custom CUDA kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel.
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.use_bias = bias

        # Initialize weights and bias similar to nn.Conv2d
        # For depthwise convolution with groups=in_channels, the weight shape is (out_channels, 1, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.empty(out_channels, 1, kernel_size, kernel_size))
        if self.use_bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

        self.depthwise_conv2d_cuda = depthwise_conv2d_module.depthwise_conv2d_cuda

    def reset_parameters(self) -> None:
        # Initialize weights and bias using Kaiming uniform, similar to PyTorch's Conv2d
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the depthwise 2D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height_in, width_in).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        # Ensure input is on CUDA, as the custom kernel expects CUDA tensors
        x = x.cuda()

        # Pass an empty tensor if bias is not used, as the C++ function expects a tensor object
        bias_tensor = self.bias if self.bias is not None else torch.empty(0, device=x.device, dtype=x.dtype)

        return self.depthwise_conv2d_cuda(
            x,
            self.weight,
            bias_tensor,
            self.kernel_size,
            self.stride,
            self.padding
        )

