import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Max Pooling 2D
max_pool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX
#include <algorithm> // For std::max

// CUDA kernel for Max Pooling 2D
__global__ void max_pool2d_kernel(
    const float* input,
    float* output,
    int N, int C, int H, int W, // Input dimensions
    int out_H, int out_W,       // Output dimensions
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    int total_output_elements = N * C * out_H * out_W;

    if (idx >= total_output_elements) {
        return;
    }

    // De-linearize index to N, C, out_H, out_W
    int w_out = idx % out_W;
    int h_out = (idx / out_W) % out_H;
    int c = (idx / (out_W * out_H)) % C;
    int n = idx / (C * out_W * out_H);

    // Calculate the input region for this output element
    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    float max_val = -FLT_MAX; // Initialize with smallest possible float value

    // Iterate over the kernel window
    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int h_in = h_start + kh * dilation;
            int w_in = w_start + kw * dilation;

            // Check boundary conditions (padding)
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                // Access input element: input[n, c, h_in, w_in]
                // Linear index: n * (C*H*W) + c * (H*W) + h_in * W + w_in
                int input_idx = n * (C * H * W) + c * (H * W) + h_in * W + w_in;
                max_val = fmaxf(max_val, input[input_idx]);
            }
        }
    }

    // Store the result
    // Output index is already 'idx' because we mapped it linearly
    output[idx] = max_val;
