import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cumulative sum (prefix sum)
# This implementation uses a multi-pass block-local scan for large arrays.
# Each block processes an independent segment (e.g., a row or a column).
# Within each block, threads first compute local prefix sums for their assigned elements.
# Then, a block-wide prefix sum is performed on the last elements of these local sums
# using shared memory. Finally, these block-wide prefix sums are added to the local
# prefix sums to get the global prefix sum for the segment.
cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min

// Define a block size. Must be a power of 2 for efficient parallel scan.
#define BLOCK_SIZE 256

// CUDA kernel for cumulative sum along dimension 1 (rows)
// This kernel is optimized for row-major contiguous data access.
__global__ void cumsum_kernel_dim1(const float* input, float* output, int N, int M) {
    // N: number of rows (batch_size)
    // M: number of columns (size of each row)

    int row_idx = blockIdx.x; // Each block handles one row
    if (row_idx >= N) {
        return;
    }

    int row_offset = row_idx * M; // Starting global memory offset for the current row

    // Shared memory for block-local prefix sum on thread-segment sums.
    // This will store the sum of each thread's segment, which is then transformed
    // into prefix sums of these segment sums.
    __shared__ float s_data[BLOCK_SIZE];

    // Calculate elements per thread for the current row.
    // This ensures all elements in the row are covered, even if M is not a multiple of BLOCK_SIZE.
    const int elements_per_thread = (M + BLOCK_SIZE - 1) / BLOCK_SIZE;

    float thread_local_sum = 0.0f;

    // Step 1: Each thread computes a sequential prefix sum for its assigned segment of the row.
    for (int i = 0; i < elements_per_thread; ++i) {
        int col_idx = threadIdx.x + i * BLOCK_SIZE;
        if (col_idx < M) { // Boundary check for elements within the row
            thread_local_sum += input[row_offset + col_idx];
            output[row_offset + col_idx] = thread_local_sum;
        }
    }

    // Store the total sum of this thread's segment into shared memory.
    s_data[threadIdx.x] = thread_local_sum;
    __syncthreads(); // Synchronize to ensure all s_data values are written before next step

    // Step 2: Perform a block-wide inclusive prefix sum on `s_data`.
    // This uses a standard work-efficient parallel scan (Blelloch's algorithm variant).
    // After this step, `s_data[threadIdx.x]` will contain the sum of all `thread_local_sum`
    // values from `threadIdx.x = 0` up to the current `threadIdx.x`.
    for (int offset = 1; offset < BLOCK_SIZE; offset *= 2) {
        __syncthreads(); // Synchronize before each step of the scan
        if (threadIdx.x >= offset) {
            s_data[threadIdx.x] += s_data[threadIdx.x - offset];
        }
    }
    __syncthreads(); // Synchronize to ensure s_data contains final prefix sums

    // Step 3: Add the block-wide prefix sums to the elements computed in Step 1.
    // The `block_prefix_sum_to_add` is the sum of all segments *before* the current thread's segment.
    float block_prefix_sum_to_add = 0.0f;
    if (threadIdx.x > 0) {
        block_prefix_sum_to_add = s_data[threadIdx.x - 1];
    }

    for (int i = 0; i < elements_per_thread; ++i) {
        int col_idx = threadIdx.x + i * BLOCK_SIZE;
        if (col_idx < M) { // Boundary check
            // Add the sum of all previous threads' segments to all elements processed by the current thread.
            // This correctly adjusts the local prefix sums to global prefix sums within the row.
            output[row_offset + col_idx] += block_prefix_sum_to_add;
        }
    }
}

// CUDA kernel for cumulative sum along dimension 0 (columns)
// This kernel handles strided memory access for column-wise operations.
// It follows the same multi-pass block-local scan logic as dim1, but with different indexing.
__global__ void cumsum_kernel_dim0(const float* input, float* output, int N, int M) {
    // N: number of rows
    // M: number of columns

    int col_idx = blockIdx.x; // Each block handles one column
    if (col_idx >= M) {
        return;
    }

    // Shared memory for block-local prefix sum on thread-segment sums
    __shared__ float s_data[BLOCK_SIZE];

    // Calculate elements per thread for the current column
    const int elements_per_thread = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;

    float thread_local_sum = 0.0f;

    // Step 1: Each thread computes a sequential prefix sum for its segment
    for (int i = 0; i < elements_per_thread; ++i) {
        int row_idx = threadIdx.x + i * BLOCK_SIZE;
        if (row_idx < N) { // Boundary check
            // Strided access for column-wise operation: input[row_idx * M + col_idx]
            thread_local_sum += input[row_idx * M + col_idx];
            output[row_idx * M + col_idx] = thread_local_sum;
        }
    }

    // Store the total sum of this thread's segment into shared memory
    s_data[threadIdx.x] = thread_local_sum;
    __syncthreads();

    // Step 2: Perform a block-wide inclusive prefix sum on `s_data`
    for (int offset = 1; offset < BLOCK_SIZE; offset *= 2) {
        __syncthreads();
        if (threadIdx.x >= offset) {
            s_data[threadIdx.x] += s_data[threadIdx.x - offset];
        }
    }
    __syncthreads();

    // Step 3: Add the block-wide prefix sums to the elements computed in Step 1.
    float block_prefix_sum_to_add = 0.0f;
    if (threadIdx.x > 0) {
        block_prefix_sum_to_add = s_data[threadIdx.x - 1];
    }

    for (int i = 0; i < elements_per_thread; ++i) {
        int row_idx = threadIdx.x + i * BLOCK_SIZE;
        if (row_idx < N) { // Boundary check
            output[row_idx * M + col_idx] += block_prefix_sum_to_add;
        }
    }
}

// C++ wrapper function to launch the appropriate CUDA kernel
torch::Tensor cumsum_cuda_wrapper(torch::Tensor x, int dim) {
    // Ensure input tensor is on CUDA and has float32 data type
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");

    // For simplicity and performance, this custom kernel assumes contiguous memory layout.
    // If the input tensor is not contiguous, it should be made contiguous before calling this wrapper.
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous for custom cumsum kernel.");

    // Create an output tensor of the same shape and type, initialized to zeros.
    auto output = torch::zeros_like(x);

    // Get dimensions of the input tensor. This kernel is designed for 2D tensors.
    int N = x.size(0); // Number of rows
    int M = x.size(1); // Number of columns

    if (dim == 1) {
        // For cumsum along dimension 1 (rows), launch N blocks. Each block processes one row.
        const int num_blocks = N;
        cumsum_kernel_dim1<<<num_blocks, BLOCK_SIZE>>>(
            x.data_ptr<float>(), output.data_ptr<float>(), N, M
        );
    } else if (dim == 0) {
        // For cumsum along dimension 0 (columns), launch M blocks. Each block processes one column.
        const int num_blocks = M;
        cumsum_kernel_dim0<<<num_blocks, BLOCK_SIZE>>>(
            x.data_ptr<float>(), output.data_ptr<float>(), N, M
        );
    } else {
        // Throw an error for unsupported dimensions.
        TORCH_CHECK(false, "Unsupported dimension for cumsum_cuda_wrapper. Only dim=0 or dim=1 supported for 2D tensors.");
    }

    // Check for any CUDA errors that might have occurred during kernel execution.
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in cumsum_cuda_wrapper: ", cudaGetErrorString(err));
    }

    return output;
}
"""

# C++ header for the wrapper function
cumsum_cpp_source = (
    "torch::Tensor cumsum_cuda_wrapper(torch::Tensor x, int dim);"
)

# Compile the inline CUDA code for cumulative sum
cumsum_module = load_inline(
    name="cumsum_custom",
    cpp_sources=cumsum_cpp_source,
    cuda_sources=cumsum_source,
    functions=["cumsum_cuda_wrapper"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Add optimization flags for CUDA compiler
)


class ModelNew(nn.Module):
    """
    A model that performs a cumulative sum (prefix sum) operation along a specified dimension,
    using a custom CUDA kernel for potential speedups.
    """

    def __init__(self, dim: int) -> None:
        """
        Initialize the ModelNew.

        Args:
            dim (int): The dimension along which to perform the cumulative sum.
        """
        super(ModelNew, self).__init__()
        self.dim = dim
        # Store the compiled custom CUDA operator
        self.cumsum_op = cumsum_module.cumsum_cuda_wrapper

    def forward(self, x: torch.Tensor) -> torch.Tensor:
