# Define the custom CUDA kernel for pointwise 2D convolution
pointwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for pointwise 2D convolution
// This kernel computes the output for a 1x1 convolution.
// Each thread computes one element of the output tensor.
__global__ void pointwise_conv2d_kernel(
    const float* x,    // Input tensor (N, C_in, H, W)
    const float* w,    // Weight tensor (C_out, C_in, 1, 1) - conceptually flattened to (C_out, C_in)
    const float* b,    // Bias tensor (C_out) - can be nullptr if no bias
    float* out,        // Output tensor (N, C_out, H, W)
    int N, int C_in, int C_out, int H, int W,
    bool has_bias) {

    // Each thread computes one output element (n, c_out, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    int total_out_elements = N * C_out * H * W;

    if (idx < total_out_elements) {
        // Deconstruct idx to (n, c_out, h, w)
        // The output tensor is (N, C_out, H, W)
        int n_stride = C_out * H * W;
        int c_out_stride = H * W;
        int h_stride = W;

        int n = idx / n_stride;
        int rem_n = idx % n_stride;
        int c_out = rem_n / c_out_stride;
        int rem_c_out = rem_n % c_out_stride;
        int h = rem_c_out / h_stride;
        int w = rem_c_out % h_stride;

        float sum_val = 0.0f;

        // Calculate base pointers for efficient memory access within the loop
        // x_base_n_hw points to the start of the (n, :, h, w) slice in x
        // w_base_c_out points to the start of the (c_out, :) slice in w (flattened)
        const float* x_base_n_hw = x + n * (C_in * H * W) + (h * W + w);
        const float* w_base_c_out = w + c_out * C_in;

        // Perform the dot product: sum_{c_in} (x[n, c_in, h, w] * w[c_out, c_in])
        for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
            // x[n, c_in_idx, h, w] is accessed by adding c_in_idx * (H * W) to x_base_n_hw
            float x_val = x_base_n_hw[c_in_idx * (H * W)];
            // w[c_out, c_in_idx] is accessed by adding c_in_idx to w_base_c_out
            float w_val = w_base_c_out[c_in_idx];
            sum_val += x_val * w_val;
        }

        // Add bias if present
        if (has_bias) {
            sum_val += b[c_out];
        }

        // Store the result in the output tensor
        out[idx] = sum_val;
    }
}

// C++ wrapper function to be called from Python
torch::Tensor pointwise_conv2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias_opt, // Optional bias tensor
    bool has_bias_flag) {

    // Input validation
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor 'weight' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(weight.is_contiguous(), "Weight tensor 'weight' must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor 'x' must be float32.");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "Weight tensor 'weight' must be float32.");

    if (has_bias_flag) {
        TORCH_CHECK(bias_opt.is_cuda(), "Bias tensor 'bias_opt' must be a CUDA tensor if present.");
        TORCH_CHECK(bias_opt.is_contiguous(), "Bias tensor 'bias_opt' must be contiguous if present.");
        TORCH_CHECK(bias_opt.dtype() == torch::kFloat32, "Bias tensor 'bias_opt' must be float32 if present.");
    }

    // Get dimensions from input tensors
    int N = x.size(0);
    int C_in = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int C_out = weight.size(0); // Weight shape is (C_out, C_in, 1, 1)

    // Create the output tensor with the same options (device, dtype) as x
    auto out = torch::zeros({N, C_out, H, W}, x.options());

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    int total_out_elements = N * C_out * H * W;
    const int num_blocks = (total_out_elements + block_size - 1) / block_size;

    // Get raw data pointers for kernel arguments
    const float* x_ptr = x.data_ptr<float>();
    const float* w_ptr = weight.data_ptr<float>();
    // Pass nullptr for bias if not present
    const float* b_ptr = has_bias_flag ? bias_opt.data_ptr<float>() : nullptr;
    float* out_ptr = out.data_ptr<float>();

    // Launch the CUDA kernel
    pointwise_conv2d_kernel<<<num_blocks, block_size>>>(
        x_ptr, w_ptr, b_ptr, out_ptr,
        N, C_in, C_out, H, W,
        has_bias_flag);

    // Synchronize and check for CUDA errors (optional, but good for debugging)
    // cudaError_t err = cudaGetLastError();
    // if (err != cudaSuccess) {
    //     fprintf(stderr, "CUDA error in pointwise_conv2d_kernel: %s\\n", cudaGetErrorString(err));
    // }

    return out;
}
"""

# C++ header for the inline compilation
pointwise_conv2d_cpp_source = (
    "torch::Tensor pointwise_conv2d_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias_opt, bool has_bias_flag);"
)

# Compile the inline CUDA code
pointwise_conv2d_module = load_inline(
    name="pointwise_conv2d_module",
    cpp_sources=pointwise_conv2d_cpp_source,
    cuda_sources=pointwise_conv2d_source,
    functions=["pointwise_conv2d_cuda"],
    verbose=False, # Set to True for compilation output
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[],
