class ModelNew(nn.Module):
    """
    Performs a pointwise 2D convolution operation using a custom CUDA kernel.
    This replaces the functionality of nn.Conv2d(in_channels, out_channels, kernel_size=1).

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.has_bias = bias

        # Reference to the compiled custom CUDA function
        self.pointwise_conv2d_cuda = pointwise_conv2d_module.pointwise_conv2d_cuda

        # Define weight and bias parameters, mimicking nn.Conv2d
        # Weight shape: (out_channels, in_channels, 1, 1)
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, 1, 1))
        if self.has_bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            # Register bias as None if not used, consistent with nn.Conv2d
            self.register_parameter('bias', None)

        self._reset_parameters()

    def _reset_parameters(self):
        # Initialize weights using Kaiming uniform initialization,
        # which is standard for convolutional layers.
        # For a 1x1 convolution, fan_in is in_channels * 1 * 1 = in_channels.
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            # Initialize bias using a uniform distribution based on fan_in.
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the pointwise 2D convolution using the custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height, width).
        """
        # Pass a dummy empty tensor for bias_opt if bias is not enabled.
        # This ensures the C++ function always receives a torch::Tensor object,
        # but the kernel will only use its data_ptr if has_bias_flag is true.
        bias_tensor = self.bias if self.has_bias else torch.empty(0, device=x.device, dtype=x.dtype)

        return self.pointwise_conv2d_cuda(x, self.weight, bias_tensor, self.has_bias)

