import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for fused scaling and softmax
fused_scale_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h> // For half precision

// Helper for block-wise reduction (max and sum)
// Assumes blockDim.x is power of 2 and <= 1024
// s_data is a shared memory array of size blockDim.x
__device__ float block_reduce_max(float val, volatile float* s_data) {
    int tid = threadIdx.x;
    s_data[tid] = val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] = fmaxf(s_data[tid], s_data[tid + s]);
        }
        __syncthreads();
    }
    return s_data[0];
}

__device__ float block_reduce_sum(float val, volatile float* s_data) {
    int tid = threadIdx.x;
    s_data[tid] = val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    return s_data[0];
}


__global__ void fused_scale_softmax_kernel(
    const half* attn_scores_ptr, half* softmax_out_ptr,
    int B, int H, int S, float inv_sqrt_D) {

    // Each thread block handles one (batch, head, query_row)
    // blockIdx.z: batch_idx
    // blockIdx.y: head_idx
    // blockIdx.x: query_row_idx (i)

    int b = blockIdx.z;
    int h = blockIdx.y;
    int i = blockIdx.x; // current query row

    int tid = threadIdx.x; // key_col_idx (j) within the block

    // Pointers for current (b, h, i) row
    // Calculate the linear offset for the start of the current row
    // (b * H * S + h * S + i) * S
    long long row_offset = (static_cast<long long>(b) * H * S + static_cast<long long>(h) * S + i) * S;
    const half* current_row_in_ptr = attn_scores_ptr + row_offset;
    half* current_row_out_ptr = softmax_out_ptr + row_offset;

    // Each thread computes one scaled score for the current row
    float scaled_score_val = -INFINITY; // Initialize with negative infinity for max reduction
    if (tid < S) { // Ensure threads don't go out of bounds if S is not a multiple of blockDim.x
        scaled_score_val = __half2float(current_row_in_ptr[tid]) * inv_sqrt_D;
    }

    // Use dynamic shared memory for reduction.
    // The size is passed at kernel launch (shmem_size = S * sizeof(float)).
    extern __shared__ float s_data[]; 

    // 1. Find max for numerical stability across the row
    float row_max = block_reduce_max(scaled_score_val, s_data);

    // 2. Compute exp(score - max)
    float exp_val = 0.0f;
    if (tid < S) {
        exp_val = expf(scaled_score_val - row_max);
    }

    // 3. Compute sum of exp values across the row
    float row_sum_exp = block_reduce_sum(exp_val, s_data); // Reuse s_data for sum reduction

    // 4. Compute softmax
    if (tid < S) {
        current_row_out_ptr[tid] = __float2half(exp_val / row_sum_exp);
    }
}

torch::Tensor fused_scale_softmax_cuda(torch::Tensor attn_scores, float inv_sqrt_D) {
    // attn_scores: (B, H, S, S)
    // Output: (B, H, S, S)

    TORCH_CHECK(attn_scores.is_cuda(), "attn_scores must be a CUDA tensor");
    TORCH_CHECK(attn_scores.dtype() == torch::kFloat16, "attn_scores must be float16");
    TORCH_CHECK(attn_scores.dim() == 4, "attn_scores must be 4D (B, H, S, S)");

    auto sizes = attn_scores.sizes();
    int B = sizes[0];
    int H = sizes[1];
    int S = sizes[2]; // Query sequence length, also key sequence length

    // The reduction strategy in the kernel assumes S <= blockDim.x (max 1024)
    TORCH_CHECK(S > 0 && S <= 1024, "Sequence length S must be > 0 and <= 1024 for this kernel's shared memory reduction strategy.");

    auto softmax_out = torch::empty_like(attn_scores);

    // Grid dimensions: (S, H, B)
    // Each block handles one (batch, head, query_row)
    dim3 blocks(S, H, B);
    // Block dimensions: S (for threads to cover the S elements of a row)
    dim3 threads(S); 

    // Calculate dynamic shared memory size required for the s_data array
    // We need S * sizeof(float) for the s_data array used in reductions
    size_t shmem_size = S * sizeof(float);

    fused_scale_softmax_kernel<<<blocks, threads, shmem_size>>>(
        attn_scores.data_ptr<half>(),
        softmax_out.data_ptr<half>(),
        B, H, S, inv_sqrt_D
    );
    // Check for CUDA errors
    C10_CUDA_CHECK(cudaGetLastError());

    return softmax_out;
}
"""

fused_scale_softmax_cpp_source = (
    "torch::Tensor fused_scale_softmax_cuda(torch::Tensor attn_scores, float inv_sqrt_D);"
)

# Compile the inline CUDA code for fused scaling and softmax
fused_scale_softmax_module = load_inline(
    name="fused_scale_softmax",
    cpp_sources=fused_scale_softmax_cpp_source,
    cuda_sources=fused_scale_softmax_source,
    functions=["fused_scale_softmax_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math", "-arch=sm_70"], # Adjust arch based on your GPU
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Store the compiled custom CUDA operator
        self.fused_scale_softmax_op = fused_scale_softmax_module

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Calculate inverse square root of the head dimension (D_k)
        # D_k is the last dimension of Q, K, V
        D_k = Q.size(-1)
        inv_sqrt_D_k = 1.0 / math.sqrt(D_k)

        # Step 1: Compute Q @ K.transpose(-2, -1)
        # This remains a standard PyTorch matmul, which is highly optimized (e.g., uses cuBLAS).
        attn_scores = torch.matmul(Q, K.transpose(-2, -1))

        # Step 2: Apply fused scaling and softmax using the custom CUDA kernel
