        softmax_attn_weights = self.fused_scale_softmax_op.fused_scale_softmax_cuda(attn_scores, inv_sqrt_D_k)

        # Step 3: Compute softmax_output @ V
        # This remains a standard PyTorch matmul, which is highly optimized.
        out = torch.matmul(softmax_attn_weights, V)
        return out

