import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for matrix multiplication (C = A * B)
// A: M x K, B: K x N, C: M x N
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Tile dimensions for the output matrix C computed by each block
    const int BLOCK_M = 128; // Height of C tile
    const int BLOCK_N = 128; // Width of C tile
    const int BLOCK_K = 64;  // Inner dimension tile (K). For this problem, K=64, so we use it directly.

    // Thread block dimensions
    const int THREADS_X = 16; // Threads per block in x-dimension
    const int THREADS_Y = 16; // Threads per block in y-dimension
    // Total threads per block = THREADS_X * THREADS_Y = 256

    // Each thread computes a sub-tile of C
    const int C_TILE_M_PER_THREAD = BLOCK_M / THREADS_Y; // 128 / 16 = 8
    const int C_TILE_N_PER_THREAD = BLOCK_N / THREADS_X; // 128 / 16 = 8

    // Shared memory for A and B tiles
    // sA will hold a BLOCK_M x BLOCK_K portion of A
    // sB will hold a BLOCK_K x BLOCK_N portion of B
    __shared__ float sA[BLOCK_M][BLOCK_K]; // 128 * 64 * 4 bytes = 32KB
    __shared__ float sB[BLOCK_K][BLOCK_N]; // 64 * 128 * 4 bytes = 32KB

    // Accumulators for the C sub-tile computed by this thread
    float C_sub_tile[C_TILE_M_PER_THREAD][C_TILE_N_PER_THREAD];

    // Initialize accumulators to zero
    for (int i = 0; i < C_TILE_M_PER_THREAD; ++i) {
        for (int j = 0; j < C_TILE_N_PER_THREAD; ++j) {
            C_sub_tile[i][j] = 0.0f;
        }
    }

    // Global indices for the current block's C tile
    int global_block_row = blockIdx.y * BLOCK_M;
    int global_block_col = blockIdx.x * BLOCK_N;

    // Global indices for the current thread within the block
    int thread_row_in_block = threadIdx.y;
    int thread_col_in_block = threadIdx.x;

    // Load A tile into shared memory
    // Each thread loads multiple elements of A.
    // sA has dimensions BLOCK_M x BLOCK_K.
    // Iterate over rows of sA (BLOCK_M)
    for (int m_idx = thread_row_in_block; m_idx < BLOCK_M; m_idx += THREADS_Y) {
        // Iterate over columns of sA (BLOCK_K)
        for (int k_idx = thread_col_in_block; k_idx < BLOCK_K; k_idx += THREADS_X) {
            // Check bounds for A
            if (global_block_row + m_idx < M && k_idx < K) {
                sA[m_idx][k_idx] = A[(global_block_row + m_idx) * K + k_idx];
            } else {
                sA[m_idx][k_idx] = 0.0f; // Pad with zeros if out of bounds
            }
        }
    }

    // Load B tile into shared memory
    // sB has dimensions BLOCK_K x BLOCK_N.
    // Iterate over rows of sB (BLOCK_K)
    for (int k_idx = thread_row_in_block; k_idx < BLOCK_K; k_idx += THREADS_Y) {
        // Iterate over columns of sB (BLOCK_N)
        for (int n_idx = thread_col_in_block; n_idx < BLOCK_N; n_idx += THREADS_X) {
            // Check bounds for B
            if (k_idx < K && global_block_col + n_idx < N) {
                sB[k_idx][n_idx] = B[k_idx * N + (global_block_col + n_idx)];
            } else {
                sB[k_idx][n_idx] = 0.0f; // Pad with zeros if out of bounds
            }
        }
    }

    __syncthreads(); // Ensure all shared memory loads are complete

    // Perform the matrix multiplication for the current block
    // Each thread computes its C_sub_tile
    for (int k_idx = 0; k_idx < BLOCK_K; ++k_idx) { // Iterate over K dimension
        for (int m_sub_idx = 0; m_sub_idx < C_TILE_M_PER_THREAD; ++m_sub_idx) {
            for (int n_sub_idx = 0; n_sub_idx < C_TILE_N_PER_THREAD; ++n_sub_idx) {
                // Calculate the actual row and column in the shared memory tile for this thread's C element
                int m_in_block = thread_row_in_block * C_TILE_M_PER_THREAD + m_sub_idx;
                int n_in_block = thread_col_in_block * C_TILE_N_PER_THREAD + n_sub_idx;

                C_sub_tile[m_sub_idx][n_sub_idx] += sA[m_in_block][k_idx] * sB[k_idx][n_in_block];
            }
        }
    }

    // Write the results from accumulators to global memory
    for (int m_sub_idx = 0; m_sub_idx < C_TILE_M_PER_THREAD; ++m_sub_idx) {
        for (int n_sub_idx = 0; n_sub_idx < C_TILE_N_PER_THREAD; ++n_sub_idx) {
            int global_m = global_block_row + thread_row_in_block * C_TILE_M_PER_THREAD + m_sub_idx;
            int global_n = global_block_col + thread_col_in_block * C_TILE_N_PER_THREAD + n_sub_idx;

            if (global_m < M && global_n < N) {
                C[global_m * N + global_n] = C_sub_tile[m_sub_idx][n_sub_idx];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
