import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for argmax along different dimensions
# These kernels implement a parallel reduction within each thread block
# to find the maximum value and its index along the specified dimension.
# They handle ties by returning the index of the first occurrence,
# consistent with PyTorch's torch.argmax behavior.
argmax_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Kernel for dim=0: input (B, D1, D2), output (D1, D2)
// Each block computes argmax for a unique (d1_idx, d2_idx) pair.
__global__ void argmax_dim0_kernel(const float* input, long* output, int B, int D1, int D2) {
    // global_idx maps to a unique (d1_idx, d2_idx) pair in the output tensor
    int global_idx = blockIdx.x; 

    int d1_idx = global_idx / D2;
    int d2_idx = global_idx % D2;

    // Shared memory for parallel reduction: stores value and index for each thread
    extern __shared__ float s_val[]; 
    extern __shared__ int s_idx[];   

    float max_val = -FLT_MAX; // Initialize with smallest possible float
    int max_idx = -1;         // Initialize with an invalid index

    // Each thread processes multiple elements in a strided loop along the reduction dimension (B)
    for (int i = threadIdx.x; i < B; i += blockDim.x) {
        // Calculate global index for input element: input[i][d1_idx][d2_idx]
        // Stride for B is D1 * D2
        // Stride for D1 is D2
        // Stride for D2 is 1
        int input_global_idx = i * (D1 * D2) + d1_idx * D2 + d2_idx;
        float current_val = input[input_global_idx];

        if (current_val > max_val) {
            max_val = current_val;
            max_idx = i;
        } else if (current_val == max_val) {
            // If values are equal, choose the smaller index (PyTorch's argmax behavior)
            if (i < max_idx) { 
                max_idx = i;
            }
        }
    }

    // Store thread-local max_val and max_idx in shared memory
    s_val[threadIdx.x] = max_val;
    s_idx[threadIdx.x] = max_idx;
    __syncthreads(); // Synchronize threads before reduction

    // Perform parallel reduction in shared memory (tree reduction)
    // This assumes blockDim.x is a power of 2
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            if (s_val[threadIdx.x + s] > s_val[threadIdx.x]) {
                s_val[threadIdx.x] = s_val[threadIdx.x + s];
                s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
            } else if (s_val[threadIdx.x + s] == s_val[threadIdx.x]) {
                // If values are equal, choose the smaller index
                if (s_idx[threadIdx.x + s] < s_idx[threadIdx.x]) {
                    s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
                }
            }
        }
        __syncthreads(); // Synchronize threads after each reduction step
    }

    // The block's final result (argmax index) is in s_idx[0]
    if (threadIdx.x == 0) {
        output[global_idx] = s_idx[0];
    }
}

// Kernel for dim=1: input (B, D1, D2), output (B, D2)
// Each block computes argmax for a unique (b_idx, d2_idx) pair.
__global__ void argmax_dim1_kernel(const float* input, long* output, int B, int D1, int D2) {
    int global_idx = blockIdx.x; // Ranges from 0 to B*D2 - 1

    int b_idx = global_idx / D2;
    int d2_idx = global_idx % D2;

    extern __shared__ float s_val[];
    extern __shared__ int s_idx[];

    float max_val = -FLT_MAX;
    int max_idx = -1;

    for (int i = threadIdx.x; i < D1; i += blockDim.x) {
        // input[b_idx][i][d2_idx]
        int input_global_idx = b_idx * (D1 * D2) + i * D2 + d2_idx;
        float current_val = input[input_global_idx];

        if (current_val > max_val) {
            max_val = current_val;
            max_idx = i;
        } else if (current_val == max_val) {
            if (i < max_idx) {
                max_idx = i;
            }
        }
    }

    s_val[threadIdx.x] = max_val;
    s_idx[threadIdx.x] = max_idx;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            if (s_val[threadIdx.x + s] > s_val[threadIdx.x]) {
                s_val[threadIdx.x] = s_val[threadIdx.x + s];
                s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
            } else if (s_val[threadIdx.x + s] == s_val[threadIdx.x]) {
                if (s_idx[threadIdx.x + s] < s_idx[threadIdx.x]) {
                    s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
                }
            }
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[global_idx] = s_idx[0];
    }
}

// Kernel for dim=2: input (B, D1, D2), output (B, D1)
// Each block computes argmax for a unique (b_idx, d1_idx) pair.
__global__ void argmax_dim2_kernel(const float* input, long* output, int B, int D1, int D2) {
    int global_idx = blockIdx.x; // Ranges from 0 to B*D1 - 1

    int b_idx = global_idx / D1;
    int d1_idx = global_idx % D1;

    extern __shared__ float s_val[];
    extern __shared__ int s_idx[];

    float max_val = -FLT_MAX;
    int max_idx = -1;

    for (int i = threadIdx.x; i < D2; i += blockDim.x) {
        // input[b_idx][d1_idx][i]
        int input_global_idx = b_idx * (D1 * D2) + d1_idx * D2 + i;
        float current_val = input[input_global_idx];

        if (current_val > max_val) {
            max_val = current_val;
            max_idx = i;
        } else if (current_val == max_val) {
            if (i < max_idx) {
                max_idx = i;
            }
        }
    }

    s_val[threadIdx.x] = max_val;
    s_idx[threadIdx.x] = max_idx;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            if (s_val[threadIdx.x + s] > s_val[threadIdx.x]) {
                s_val[threadIdx.x] = s_val[threadIdx.x + s];
                s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
            } else if (s_val[threadIdx.x + s] == s_val[threadIdx.x]) {
                if (s_idx[threadIdx.x + s] < s_idx[threadIdx.x]) {
                    s_idx[threadIdx.x] = s_idx[threadIdx.x + s];
                }
            }
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[global_idx] = s_idx[0];
    }
}
"""

# C++ wrapper for the CUDA kernels
# This function dispatches to the appropriate kernel based on the 'dim' argument.
argmax_cpp_source = """
#include <torch/extension.h>
#include <vector>

// Declare the CUDA kernels defined in argmax_cuda_source
__global__ void argmax_dim0_kernel(const float* input, long* output, int B, int D1, int D2);
__global__ void argmax_dim1_kernel(const float* input, long* output, int B, int D1, int D2);
__global__ void argmax_dim2_kernel(const float* input, long* output, int B, int D1, int D2);


torch::Tensor argmax_cuda(torch::Tensor input, int dim) {
    // Input validation
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input tensor must be of float32 type.");
    TORCH_CHECK(input.dim() == 3, "This custom argmax implementation currently supports only 3D tensors.");

    // Get dimensions of the input tensor
    int B = input.size(0);
    int D1 = input.size(1);
    int D2 = input.size(2);

    std::vector<long int> output_shape;
    int num_blocks; // Total number of independent argmax operations

    // Determine output shape and number of blocks based on the reduction dimension
    if (dim == 0) {
        output_shape = {D1, D2};
        num_blocks = D1 * D2;
    } else if (dim == 1) {
        output_shape = {B, D2};
        num_blocks = B * D2;
    } else if (dim == 2) {
        output_shape = {B, D1};
        num_blocks = B * D1;
    } else {
        TORCH_CHECK(false, "Dimension 'dim' must be 0, 1, or 2 for a 3D tensor.");
    }

    // Create the output tensor on the same device as input, with long (int64) dtype
    auto output = torch::empty(output_shape, input.options().dtype(torch::kLong));

    const int block_size = 256; // Standard block size for CUDA kernels
    // Calculate shared memory size required for value and index arrays for all threads in a block
    size_t shared_mem_size = block_size * (sizeof(float) + sizeof(int));

    // Dispatch to the appropriate kernel based on the 'dim' argument
    if (dim == 0) {
        argmax_dim0_kernel<<<num_blocks, block_size, shared_mem_size>>>(
            input.data_ptr<float>(), output.data_ptr<long>(), B, D1, D2
        );
    } else if (dim == 1) {
        argmax_dim1_kernel<<<num_blocks, block_size, shared_mem_size>>>(
            input.data_ptr<float>(), output.data_ptr<long>(), B, D1, D2
        );
    } else if (dim == 2) {
        argmax_dim2_kernel<<<num_blocks, block_size, shared_mem_size>>>(
            input.data_ptr<float>(), output.data_ptr<long>(), B, D1, D2
        );
    }

    // Check for any CUDA errors that might have occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
"""

# Compile the inline CUDA code for argmax
# The compiled functions will be available via the 'argmax_op' object.
argmax_op = load_inline(
    name="argmax_custom",
    cpp_sources=argmax_cpp_source,
    cuda_sources=argmax_cuda_source,
    functions=["argmax_cuda"], # List of C++ functions to expose to Python
    verbose=True,              # Print compilation output
    extra_cflags=["-O3"],      # Add optimization flag for C++ compilation
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Argmax over a specified dimension using custom CUDA kernels.
    This model replaces the standard torch.argmax operator with a custom, potentially faster,
    CUDA implementation for 3D tensors.
    """
    def __init__(self, dim: int):
        """
        Initializes the model with the dimension to perform argmax.

        Args:
            dim (int): The dimension to perform argmax over.
        """
        super(ModelNew, self).__init__()
        self.dim = dim
        # Assign the compiled custom operator to an instance variable
        self.argmax_custom_op = argmax_op 

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies the custom CUDA argmax over the specified dimension to the input tensor.

        Args:
            x (torch.Tensor): Input tensor. Expected to be a 3D CUDA float32 tensor.

        Returns:
            torch.Tensor: Output tensor with argmax applied, with the specified dimension removed.
                          The output tensor will be of type torch.long.
        """
        # Call the custom CUDA kernel through the compiled operator
        return self.argmax_custom_op.argmax_cuda(x, self.dim)

