import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for ConvTranspose3d (simplified for stride=1, padding=0, output_padding=0, groups=1, no bias)
conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdio> // For fprintf

// CUDA kernel for 3D Transposed Convolution (direct implementation)
// This kernel assumes specific configurations for simplicity and demonstration:
//   - stride=1
//   - padding=0
//   - output_padding=0
//   - groups=1
//   - no bias
// Input tensor shape: (N, C_in, D_in, H_in, W_in)
// Weight tensor shape: (C_in, C_out, K_D, K_H, K_W) (PyTorch stores ConvTranspose weights as (in_channels, out_channels/groups, kD, kH, kW))
// Output tensor shape: (N, C_out, D_out, H_out, W_out)
__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K_D, int K_H, int K_W,
    int D_out, int H_out, int W_out)
{
    // Each thread computes one output voxel (n, c_out, d_out, h_out, w_out)
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    size_t total_output_elements = (size_t)N * C_out * D_out * H_out * W_out;

    if (idx >= total_output_elements) {
        return;
    }

    // Decompose idx into (n, c_out, d_out, h_out, w_out)
    size_t w_out = idx % W_out;
    idx /= W_out;
    size_t h_out = idx % H_out;
    idx /= H_out;
    size_t d_out = idx % D_out;
    idx /= D_out;
    size_t c_out = idx % C_out;
    idx /= C_out;
    size_t n = idx;

    float acc = 0.0f;

    // Loop over input channels
    for (int c_in = 0; c_in < C_in; ++c_in) {
        // Loop over kernel dimensions
        for (int k_d = 0; k_d < K_D; ++k_d) {
            for (int k_h = 0; k_h < K_H; ++k_h) {
                for (int k_w = 0; k_w < K_W; ++k_w) {
                    // Calculate corresponding input coordinates
                    // For stride=1, padding=0, output_padding=0:
                    // d_out = d_in + k_d  => d_in = d_out - k_d
                    // h_out = h_in + k_h  => h_in = h_out - k_h
                    // w_out = w_in + k_w  => w_in = w_out - k_w
                    int d_in = d_out - k_d;
                    int h_in = h_out - k_h;
                    int w_in = w_out - k_w;

                    // Check bounds for input coordinates
                    if (d_in >= 0 && d_in < D_in &&
                        h_in >= 0 && h_in < H_in &&
                        w_in >= 0 && w_in < W_in)
                    {
                        // Input tensor: (N, C_in, D_in, H_in, W_in)
                        // Weight tensor: (C_in, C_out, K_D, K_H, K_W)

                        // Calculate indices for input and weight
                        size_t input_idx = n * (size_t)C_in * D_in * H_in * W_in +
                                           c_in * (size_t)D_in * H_in * W_in +
                                           d_in * (size_t)H_in * W_in +
                                           h_in * (size_t)W_in +
                                           w_in;

                        size_t weight_idx = c_in * (size_t)C_out * K_D * K_H * K_W +
                                            c_out * (size_t)K_D * K_H * K_W +
                                            k_d * (size_t)K_H * K_W +
                                            k_h * (size_t)K_W +
                                            k_w;

                        acc += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    // Output tensor: (N, C_out, D_out, H_out, W_out)
    size_t output_idx = n * (size_t)C_out * D_out * H_out * W_out +
                        c_out * (size_t)D_out * H_out * W_out +
                        d_out * (size_t)H_out * W_out +
                        h_out * (size_t)W_out +
                        w_out;
    output[output_idx] = acc;
}

// C++ wrapper for the CUDA kernel
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int K_D, int K_H, int K_W,
    int D_out, int H_out, int W_out)
{
    // Ensure tensors are contiguous and on CUDA.
    // .contiguous() creates a copy if the tensor is not already contiguous,
    // which might incur a performance overhead. For correctness, it's often necessary.
    input = input.contiguous();
    weight = weight.contiguous();

    // Calculate output shape
    auto output_shape = torch::IntArrayRef({N, C_out, D_out, H_out, W_out});
    // Create output tensor on the same device and with the same dtype as input
    auto output = torch::zeros(output_shape, input.options());

    size_t total_elements = (size_t)N * C_out * D_out * H_out * W_out;
    const int block_size = 256; // A common block size for CUDA kernels
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, K_D, K_H, K_W,
        D_out, H_out, W_out
    );

    // Check for CUDA errors after kernel launch
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in conv_transpose3d_cuda: %s\\n", cudaGetErrorString(err));
        TORCH_CHECK(false, "CUDA error in conv_transpose3d_cuda: ", cudaGetErrorString(err));
    }

    return output;
}
"""

# C++ header for the CUDA function
conv_transpose3d_cpp_source = (
    "torch::Tensor conv_transpose3d_cuda("
    "torch::Tensor input, torch::Tensor weight,"
    "int N, int C_in, int D_in, int H_in, int W_in,"
    "int C_out, int K_D, int K_H, int K_W,"
    "int D_out, int H_out, int W_out);"
)

# Compile the inline CUDA code for ConvTranspose3d
# verbose=False to avoid cluttering output during compilation, can be set to True for debugging
conv_transpose3d_custom = load_inline(
    name="conv_transpose3d_custom",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
    extra_cflags=["-O3"], # Optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"] # Optimization flags for CUDA compiler
)


class ModelNew(nn.Module):
    """
    Optimized version of ConvTranspose3d using a custom CUDA kernel.
    This custom kernel is a direct implementation and currently supports
    only specific configurations to keep the kernel manageable:
    stride=1, padding=0, output_padding=0, groups=1, and no bias.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Store parameters for kernel launch and validation
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size # Assuming square kernel (kD, kH, kW are all kernel_size)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Validate supported configurations for the custom kernel
        if not (self.stride == 1 and self.padding == 0 and self.output_padding == 0 and self.groups == 1 and self.bias == False):
            raise NotImplementedError(
                "Custom ConvTranspose3d kernel only supports: "
                "stride=1, padding=0, output_padding=0, groups=1, and bias=False. "
                f"Received: stride={stride}, padding={padding}, output_padding={output_padding}, groups={groups}, bias={bias}"
            )

        # Create learnable weight parameter, similar to nn.ConvTranspose3d
        # PyTorch ConvTranspose3d weight shape: (in_channels, out_channels // groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size
        ))
        # Initialize weights using Kaiming uniform initialization, a common practice for Conv layers
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        # Assign the loaded custom CUDA operator
        self.conv_transpose3d_cuda_op = conv_transpose3d_custom

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on CUDA device and is float type, as the kernel expects float*
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float32:
            x = x.to(torch.float32)

        # Input shape: (N, C_in, D_in, H_in, W_in)
        N, C_in, D_in, H_in, W_in = x.shape

        # Calculate output dimensions for the supported configuration (stride=1, padding=0, output_padding=0)
        # The formula for output size is:
        # D_out = (D_in - 1) * stride - 2 * padding + kernel_size + output_padding
        # With current constraints: D_out = (D_in - 1) * 1 - 2 * 0 + self.kernel_size + 0
        D_out = D_in - 1 + self.kernel_size
        H_out = H_in - 1 + self.kernel_size
        W_out = W_in - 1 + self.kernel_size

        # Call the custom CUDA kernel
        # Ensure self.weight is also float32, as the kernel expects float*
        return self.conv_transpose3d_cuda_op.conv_transpose3d_cuda(
