import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for a simplified ConvTranspose2d.
# This kernel implements ConvTranspose2d for the specific case where:
# stride=1, padding=0, output_padding=0, groups=1, and bias=False.
# It computes the output by iterating over each output pixel and summing
# contributions from relevant input pixels based on the kernel weights.
# This can be considered an "algorithmic change" or a specialized replacement
# for a common configuration of ConvTranspose2d.
conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K_H, int K_W,
    int H_out, int W_out
) {
    // Each thread computes one output element (n, c_out, h_out, w_out)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= N * C_out * H_out * W_out) {
        return;
    }

    int w_out = idx % W_out;
    idx /= W_out;
    int h_out = idx % H_out;
    idx /= H_out;
    int c_out = idx % C_out;
    idx /= C_out;
    int n = idx;

    float sum = 0.0f;

    // Iterate over input channels and kernel dimensions
    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int k_h = 0; k_h < K_H; ++k_h) {
            for (int k_w = 0; k_w < K_W; ++k_w) {
                // For ConvTranspose2d (with stride=1, padding=0), an output pixel (h_out, w_out)
                // receives contributions from input pixels (h_in, w_in) such that
                // h_out = h_in + k_h and w_out = w_in + k_w.
                // Therefore, h_in = h_out - k_h and w_in = w_out - k_w.
                int h_in = h_out - k_h;
                int w_in = w_out - k_w;

                // Check if input coordinates are within bounds.
                // This implicitly handles zero-padding for the "transposed" convolution,
                // as out-of-bounds input values are effectively treated as zero.
                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    // Access input tensor: input[n, c_in, h_in, w_in]
                    int input_idx = n * C_in * H_in * W_in + c_in * H_in * W_in + h_in * W_in + w_in;
                    // Access weight tensor: weight[c_in, c_out, k_h, k_w]
                    int weight_idx = c_in * C_out * K_H * K_W + c_out * K_H * K_W + k_h * K_W + k_w;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    // Store the computed sum in the output tensor
    output[n * C_out * H_out * W_out + c_out * H_out * W_out + h_out * W_out + w_out] = sum;
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight) {
    // Input tensor shape: (N, C_in, H_in, W_in)
    // Weight tensor shape: (C_in, C_out, K_H, K_W)
    // (Note: PyTorch's nn.ConvTranspose2d weight is (C_in, C_out/groups, K_H, K_W).
    // For groups=1, this simplifies to (C_in, C_out, K_H, K_W), which is used here.)

    TORCH_CHECK(input.dim() == 4, "Input must be a 4D tensor (N, C_in, H_in, W_in)");
    TORCH_CHECK(weight.dim() == 4, "Weight must be a 4D tensor (C_in, C_out, K_H, K_W)");
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on a CUDA device");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on a CUDA device");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "Weight tensor must be contiguous");

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_in_weight = weight.size(0);
    int C_out = weight.size(1);
    int K_H = weight.size(2);
    int K_W = weight.size(3);

    TORCH_CHECK(C_in == C_in_weight, "Input channels (input.size(1)) must match weight's input channels (weight.size(0))");

    // Calculate output dimensions for stride=1, padding=0, output_padding=0.
    // H_out = (H_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1
    // With stride=1, padding=0, output_padding=0, dilation=1:
    // H_out = (H_in - 1) * 1 - 0 + 1 * (K_H - 1) + 0 + 1 = H_in - 1 + K_H - 1 + 1 = H_in + K_H - 1
    int H_out = H_in + K_H - 1;
    int W_out = W_in + K_W - 1;

    // Create the output tensor, initialized to zeros
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    const int num_elements = N * C_out * H_out * W_out;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    conv_transpose2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K_H, K_W,
        H_out, W_out
    );

    return output;
}
"""

conv_transpose2d_cpp_source = (
    "torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight);"
