        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # The custom CUDA kernel currently only supports a specific configuration
        if not (stride == 1 and padding == 0 and output_padding == 0 and groups == 1 and bias == False):
            raise ValueError(
                "The custom ConvTranspose2d kernel in ModelNew currently only supports: "
                "stride=1, padding=0, output_padding=0, groups=1, bias=False. "
                "Please adjust the model's initialization parameters or extend the custom kernel. "
                f"Provided parameters: stride={stride}, padding={padding}, output_padding={output_padding}, "
                f"groups={groups}, bias={bias}"
            )

        # Initialize weights for the custom kernel.
