fused_batchnorm_gelu_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For erff, fmaxf, sqrtf

// Define M_SQRT1_2F if not already defined (e.g., in older CUDA versions or specific headers)
#ifndef M_SQRT1_2F
#define M_SQRT1_2F 0.707106781186547572936f // 1/sqrt(2)
#endif

__global__ void fused_batchnorm_gelu_relu_kernel(
    const float* x_ptr,
    const float* weight_ptr,
    const float* bias_ptr,
    const float* running_mean_ptr,
    const float* running_var_ptr,
    float eps,
    float* out_ptr,
    int total_elements,
    int out_features) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate the feature index for accessing BatchNorm parameters
        int feature_idx = idx % out_features;

        float val = x_ptr[idx];

        // BatchNorm1d transformation
        float mean = running_mean_ptr[feature_idx];
        float var = running_var_ptr[feature_idx];
        float w = weight_ptr[feature_idx]; // gamma
        float b = bias_ptr[feature_idx];   // beta

        float normalized_val = (val - mean) / sqrtf(var + eps);
        float scaled_shifted_val = w * normalized_val + b;

        // GELU activation (using erf approximation)
        // Formula: 0.5 * x * (1 + erf(x / sqrt(2)))
        float gelu_val = 0.5f * scaled_shifted_val * (1.0f + erff(scaled_shifted_val * M_SQRT1_2F));

        // ReLU activation
        out_ptr[idx] = fmaxf(0.0f, gelu_val);
    }
}

