import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernels
fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat> // For FLT_MAX
#include <cmath>  // For logf, expf, tanhf, fmaxf, fminf

// --- Fused Scale, Residual (2*x), Clamp Kernel ---
// Fuses: x = x * scale_factor; x = x + x; x = torch.clamp(x, min, max)
__global__ void fused_scale_residual_clamp_kernel(const float* in, float* out, float scale_factor, float clamp_min, float clamp_max, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        val = val * scale_factor;
        val = val * 2.0f; // Equivalent to val + val
        val = fmaxf(val, clamp_min);
        val = fminf(val, clamp_max);
        out[idx] = val;
    }
}

torch::Tensor fused_scale_residual_clamp_cuda(torch::Tensor in, float scale_factor, float clamp_min, float clamp_max) {
    TORCH_CHECK(in.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(in.is_contiguous(), "input must be contiguous"); 

    auto out = torch::empty_like(in);
    int size = in.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_scale_residual_clamp_kernel<<<num_blocks, block_size>>>(
        in.data_ptr<float>(), out.data_ptr<float>(), scale_factor, clamp_min, clamp_max, size
    );
    return out;
}

// --- Fused LogSumExp, Mish, Multiply Kernel ---

// Helper functions for Mish activation
__device__ float softplus_cuda(float x) {
    return logf(1.0f + expf(x));
}

__device__ float mish_cuda(float x) {
    return x * tanhf(softplus_cuda(x));
}

// Fuses: x = torch.logsumexp(x, dim=1, keepdim=True); x = x * torch.nn.functional.mish(x)
// This kernel performs a row-wise reduction for LogSumExp, then applies Mish and multiplication.
// Each block processes one row.
__global__ void fused_logsumexp_mish_mul_kernel(const float* in, float* out, int batch_size, int hidden_size) {
    int row_idx = blockIdx.x; // Each block processes one row
    if (row_idx < batch_size) {
        const float* row_ptr = in + row_idx * hidden_size;

        // Find max value for numerical stability in LogSumExp
        float max_val = -FLT_MAX;
        for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
            max_val = fmaxf(max_val, row_ptr[i]);
        }
        // Reduce max_val across threads in the block using shared memory
        extern __shared__ float s_max[];
        s_max[threadIdx.x] = max_val;
        __syncthreads();

        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_max[threadIdx.x] = fmaxf(s_max[threadIdx.x], s_max[threadIdx.x + s]);
            }
            __syncthreads();
        }
        max_val = s_max[0]; // Max value for the current row

        // Compute sum of exponentials for LogSumExp
        float sum_exp = 0.0f;
        for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
            sum_exp += expf(row_ptr[i] - max_val);
        }
        // Reduce sum_exp across threads in the block using shared memory
        extern __shared__ float s_sum_exp[];
        s_sum_exp[threadIdx.x] = sum_exp;
        __syncthreads();

        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_sum_exp[threadIdx.x] = s_sum_exp[threadIdx.x] + s_sum_exp[threadIdx.x + s];
            }
            __syncthreads();
        }
        sum_exp = s_sum_exp[0]; // Sum of exponentials for the current row

        // Only the first thread writes the final result for the row
        if (threadIdx.x == 0) {
            float lse_val = logf(sum_exp) + max_val;
            // Apply x * mish(x) to the LogSumExp result
            out[row_idx] = lse_val * mish_cuda(lse_val);
        }
    }
}

torch::Tensor fused_logsumexp_mish_mul_cuda(torch::Tensor in) {
    TORCH_CHECK(in.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(in.dim() == 2, "input must be 2D");
    TORCH_CHECK(in.is_contiguous(), "input must be contiguous"); 

    int batch_size = in.size(0);
    int hidden_size = in.size(1);

