# Define the custom CUDA kernel for fused operations:
# BatchNorm1d (inference mode) + Bias Add + Scalar Division + Swish Activation
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, sqrtf, rsqrtf

// Fused kernel for BatchNorm1d (inference), Bias Add, Scalar Division, and Swish
__global__ void fused_bn_bias_div_swish_kernel(
    const float* input,
    const float* bn_weight,
    const float* bn_bias,
    const float* running_mean,
    const float* running_var,
    float bn_eps,
    const float* custom_bias, // self.bias (assumed to be (1,))
    float divide_value,      // self.divide_value
    float* output,
    int total_elements,
    int out_features // Number of features (C in BatchNorm1d)
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate feature_idx from global index
        // input is (batch_size, out_features)
        // bn_params are (out_features,)
        int feature_idx = idx % out_features;

        float x_val = input[idx];

        // BatchNorm1d (inference mode)
        float mean_val = running_mean[feature_idx];
        float var_val = running_var[feature_idx];
        float gamma_val = bn_weight[feature_idx];
        float beta_val = bn_bias[feature_idx];

        float inv_std = rsqrtf(var_val + bn_eps); // 1 / sqrt(var + eps)
        float normalized_x = (x_val - mean_val) * inv_std;
        float bn_out_val = normalized_x * gamma_val + beta_val;

        // Custom Bias Addition (assuming custom_bias is (1,) and applied to all features)
        float add_bias_out_val = bn_out_val + custom_bias[0];

        // Scalar Division
        float div_out_val = add_bias_out_val / divide_value;

        // Swish Activation: x * sigmoid(x) = x * (1 / (1 + exp(-x)))
        float swish_out_val = div_out_val * (1.0f / (1.0f + expf(-div_out_val)));

        output[idx] = swish_out_val;
    }
}

