import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# This kernel fuses:
# 1. nn.AdaptiveAvgPool3d((1, 1, 1))
# 2. Element-wise division by a constant (x / self.divisor)
# 3. Element-wise addition with a bias (x + self.bias)
# 4. torch.sum(x, dim=self.sum_dim) where sum_dim is 1
fused_pool_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Fused kernel for AdaptiveAvgPool3d + Div + AddBias + SumAlongDim1
// Each block processes one (batch_idx, channel_idx) pair.
// Threads within the block perform parallel reduction for spatial average.
// Block leader performs div/bias and atomic add to the final batch sum.
__global__ void fused_pool_ops_kernel(
    const float* x_ptr,
    const float* bias_ptr,
    float divisor_val,
    float* out_ptr, // Output shape (B, 1, 1)
    int B, int C, int D_mp, int H_mp, int W_mp)
{
    // Map blockIdx.x to (b, c)
    int bc_idx = blockIdx.x;
    if (bc_idx >= B * C) return;

    int b = bc_idx / C;
    int c = bc_idx % C;

    // Calculate total number of spatial elements for averaging
    long long num_spatial_elements = (long long)D_mp * H_mp * W_mp;

    // Pointer to the start of the current channel's data for batch 'b' and channel 'c'
    // x_ptr is (B, C, D_mp, H_mp, W_mp)
    long long offset = (long long)b * C * D_mp * H_mp * W_mp + (long long)c * D_mp * H_mp * W_mp;
    const float* current_channel_ptr = x_ptr + offset;

    // Perform parallel reduction for spatial sum within the block
    // Each thread sums a portion of the spatial elements
    float thread_sum = 0.0f;
    for (long long i = threadIdx.x; i < num_spatial_elements; i += blockDim.x) {
        thread_sum += current_channel_ptr[i];
    }

    // Reduce thread_sum to get block_sum (spatial sum for this (b, c) pair)
    // Using shared memory for reduction
    extern __shared__ float s_data[]; // Declared as extern to use dynamic shared memory

    s_data[threadIdx.x] = thread_sum;
    __syncthreads();

    // Perform reduction in shared memory (tree reduction)
    // This loop is efficient for blockDim.x being a power of 2, which is common.
    for (unsigned int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Block leader (thread 0) finalizes the calculation for this (b, c) pair
    if (threadIdx.x == 0) {
        float block_spatial_sum = s_data[0];
        float avg_val = block_spatial_sum / num_spatial_elements;

        // Apply division and bias
        // bias_ptr is (C, 1, 1, 1), so bias_ptr[c] correctly accesses the bias for channel 'c'
        float bias_val = bias_ptr[c];
        float temp_val = (avg_val / divisor_val) + bias_val;

        // Atomically add to the final batch sum
        // out_ptr is (B, 1, 1), so out_ptr[b] is the correct location for the batch's final scalar sum
        atomicAdd(&out_ptr[b], temp_val);
    }
}

torch::Tensor fused_pool_ops_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float divisor_val,
    int sum_dim) // sum_dim is passed for context, but hardcoded to 1 in kernel
{
    // Input x: (B, C, D_mp, H_mp, W_mp) - output of MaxPool3d
    // Input bias: (C, 1, 1, 1)
    // Output: (B, 1, 1) - after global avg pool, div, add bias, and sum along dim 1

    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(bias.is_cuda(), "Bias tensor 'bias' must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 5, "Input tensor 'x' must be 5D (B, C, D, H, W).");
    TORCH_CHECK(bias.dim() == 4, "Bias tensor 'bias' must be 4D (C, 1, 1, 1).");
    TORCH_CHECK(bias.size(1) == 1 && bias.size(2) == 1 && bias.size(3) == 1, "Bias tensor 'bias' must have shape (C, 1, 1, 1).");
    TORCH_CHECK(sum_dim == 1, "This fused kernel is specialized for sum_dim = 1.");

    int B = x.size(0);
    int C = x.size(1);
    int D_mp = x.size(2);
    int H_mp = x.size(3);
    int W_mp = x.size(4);

    // The output tensor will have shape (B, 1, 1)
    // It needs to be initialized to zeros because atomicAdd accumulates values.
    auto out = torch::zeros({B, 1, 1}, x.options());

    const int block_size = 256; // Number of threads per block
    const int num_blocks = B * C; // One block per (batch, channel) pair

    // Calculate dynamic shared memory size required for the reduction within each block
    // Each block needs 'block_size' floats for the shared memory reduction array.
    size_t smem_size = block_size * sizeof(float);

    // Launch the CUDA kernel
    fused_pool_ops_kernel<<<num_blocks, block_size, smem_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        divisor_val,
        out.data_ptr<float>(),
        B, C, D_mp, H_mp, W_mp
    );

    return out;
}
"""

