# --- Custom CUDA Kernel 1: Fused Subtract and Global Mean ---
# This kernel performs: x = x - self.subtract; x = torch.mean(x, dim=1, keepdim=True)
subtract_global_mean_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel to perform (x - subtract_param) and then global mean along dim=1
__global__ void subtract_global_mean_kernel(const float* x, const float* subtract_param, float* out, int B, int O) {
    int b_idx = blockIdx.x; // Each block handles one batch item (row)

    if (b_idx < B) {
        float row_sum = 0.0f;

        // Dynamically allocated shared memory for reduction within the block
        extern __shared__ float s_sum[]; 

        int tid = threadIdx.x;
        int stride = blockDim.x;

        // Sum elements for the current row
        for (int o_idx = tid; o_idx < O; o_idx += stride) {
            row_sum += (x[b_idx * O + o_idx] - subtract_param[o_idx]);
        }

        s_sum[tid] = row_sum;
        __syncthreads();

        // Parallel reduction in shared memory
        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (tid < s) {
                s_sum[tid] += s_sum[tid + s];
            }
            __syncthreads();
        }

        if (tid == 0) {
            out[b_idx] = s_sum[0] / O;
        }
    }
}

torch::Tensor subtract_global_mean_cuda(torch::Tensor x, torch::Tensor subtract_param) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(subtract_param.is_cuda(), "subtract_param must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(subtract_param.dim() == 1, "subtract_param must be 1D");
    TORCH_CHECK(x.size(1) == subtract_param.size(0), "x.size(1) must match subtract_param.size(0)");

    int B = x.size(0);
    int O = x.size(1);

    auto out = torch::empty({B, 1}, x.options());

    const int block_size = 256; // A common block size for reductions
    const int num_blocks = B;   // One block per batch item

    // Calculate shared memory size for the s_sum array
    size_t smem_size = block_size * sizeof(float);

    subtract_global_mean_kernel<<<num_blocks, block_size, smem_size>>>(
        x.data_ptr<float>(),
        subtract_param.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        O
    );
    // CUDA_CHECK(cudaGetLastError()); // Uncomment for explicit error checking

    return out;
}
"""

