# --- Custom CUDA Kernel 2: Fused GELU and Residual Add ---
# This kernel performs: x = torch.nn.functional.gelu(x); x = x + original_x
# Note: The original model's torch.logsumexp(x, dim=1, keepdim=True) on a (B,1) tensor is a no-op.
gelu_residual_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For __erff

// GELU approximation using __erff (PyTorch's standard GELU uses erf)
__device__ __forceinline__ float gelu_approx(float x) {
    // 0.5 * x * (1.0 + erf(x / sqrt(2.0)))
    return 0.5f * x * (1.0f + __erff(x * 0.70710678118f)); // 1/sqrt(2) approx 0.70710678118
}

__global__ void gelu_residual_add_kernel(const float* mean_output, const float* original_x, float* final_output, int B, int I) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < B * I) {
        int b_idx = idx / I; // Batch index for mean_output (which is (B, 1))

        float gelu_val = gelu_approx(mean_output[b_idx]); // mean_output is (B, 1), so index by b_idx
        final_output[idx] = gelu_val + original_x[idx];
    }
}

torch::Tensor gelu_residual_add_cuda(torch::Tensor mean_output, torch::Tensor original_x) {
    TORCH_CHECK(mean_output.is_cuda(), "mean_output must be a CUDA tensor");
    TORCH_CHECK(original_x.is_cuda(), "original_x must be a CUDA tensor");
    TORCH_CHECK(mean_output.dim() == 2 && mean_output.size(1) == 1, "mean_output must be 2D with size(1)=1");
    TORCH_CHECK(original_x.dim() == 2, "original_x must be 2D");
    TORCH_CHECK(mean_output.size(0) == original_x.size(0), "Batch sizes must match");

    int B = original_x.size(0);
    int I = original_x.size(1);

    auto final_output = torch::empty_like(original_x);

    const int block_size = 256;
    const int num_elements = B * I;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    gelu_residual_add_kernel<<<num_blocks, block_size>>>(
        mean_output.data_ptr<float>(),
        original_x.data_ptr<float>(),
        final_output.data_ptr<float>(),
        B,
        I
    );
    // CUDA_CHECK(cudaGetLastError()); // Uncomment for explicit error checking

    return final_output;
}
"""

gelu_residual_add_cpp_source = (
    "torch::Tensor gelu_residual_add_cuda(torch::Tensor mean_output, torch::Tensor original_x);"
)

gelu_residual_add_module = load_inline(
