    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    """
    Optimized Model that replaces Subtract, GlobalAvgPool, LogSumExp, GELU, and ResidualAdd
    with custom CUDA kernels for potential speedups through operator fusion.
    """
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=bias)
        self.subtract = nn.Parameter(torch.randn(out_features))

        # Load custom CUDA modules
        self.subtract_global_mean_op = subtract_global_mean_module.subtract_global_mean_cuda
        self.gelu_residual_add_op = gelu_residual_add_module.gelu_residual_add_cuda

    def forward(self, x):
        # Store original_x for the residual connection.
        # Detach to prevent gradients from flowing back through this path if not needed.
        original_x = x.clone().detach() 

        # Gemm (nn.Linear) is typically highly optimized by PyTorch (cuBLAS/cuDNN),
        # so it's left as is.
        x = self.gemm(x) # Shape: (batch_size, out_features)

        # Fused Kernel 1:
        # Combines:
        # 1. x = x - self.subtract
        # 2. x = torch.mean(x, dim=1, keepdim=True)
        # Output shape: (batch_size, 1)
        x_mean = self.subtract_global_mean_op(x, self.subtract) 

        # Fused Kernel 2:
        # Combines:
        # 1. x = torch.logsumexp(x_mean, dim=1, keepdim=True)
        #    (Note: For a (B,1) tensor, logsumexp along dim=1 is a no-op, returning the input itself)
        # 2. x = torch.nn.functional.gelu(x)
        # 3. x = x + original_x (with broadcasting from (B,1) to (B, in_features))
        # Output shape: (batch_size, in_features)
        x_final = self.gelu_residual_add_op(x_mean, original_x) 

        return x_final

