import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused ReLU and Group Normalization
group_norm_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For fmaxf, fmax

// Kernel 1: Computes mean and reciprocal standard deviation for each group.
// Each thread block is responsible for one (batch_idx, group_idx) pair.
__global__ void group_norm_relu_mean_var_kernel(
    const float* x,
    int N, int C, int D, int H, int W,
    int num_groups,
    float* mean_out,
    float* rstd_out,
    float epsilon) {

    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int channels_per_group = C / num_groups;
    long long spatial_size = (long long)D * H * W;
    long long group_elements = (long long)channels_per_group * spatial_size;

    // Calculate the starting pointer for the current group's data within the batch item
    const float* group_start_ptr = x + (long long)batch_idx * C * spatial_size + (long long)group_idx * channels_per_group * spatial_size;

    // Use shared memory for efficient reduction within the block.
    // s_data[0...blockDim.x-1] stores sums, s_data[blockDim.x...2*blockDim.x-1] stores sum of squares.
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Grid-stride loop: Each thread processes multiple elements to cover the entire group's data.
    for (long long i = threadIdx.x; i < group_elements; i += blockDim.x) {
        float val = group_start_ptr[i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    s_sum[threadIdx.x] = thread_sum;
    s_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    // Parallel reduction within the block using shared memory.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final mean and rstd to global memory.
    if (threadIdx.x == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];

        float mean_val = total_sum / group_elements;
        float var_val = total_sum_sq / group_elements - mean_val * mean_val;
        // Ensure variance is non-negative due to potential floating point inaccuracies.
        var_val = fmaxf(0.0f, var_val);
        float rstd_val = rsqrtf(var_val + epsilon); // Reciprocal standard deviation

        mean_out[batch_idx * num_groups + group_idx] = mean_val;
        rstd_out[batch_idx * num_groups + group_idx] = rstd_val;
    }
}

// Kernel 2: Applies Group Normalization, ReLU activation, and then scales and shifts the result.
// Each thread processes one element of the output tensor.
__global__ void group_norm_relu_apply_kernel(
    const float* x,
    const float* gamma,
    const float* beta,
    const float* mean,
    const float* rstd,
    int N, int C, int D, int H, int W,
    int num_groups,
    float* out) {

    long long total_elements = (long long)N * C * D * H * W;
    int channels_per_group = C / num_groups;
    long long spatial_size = (long long)D * H * W;

    // Grid-stride loop: Each thread processes elements in a strided fashion to cover the entire tensor.
    for (long long idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total_elements; idx += blockDim.x * gridDim.x) {
        // Deconstruct the flattened index 'idx' back into N, C, D, H, W coordinates
        // Assumes a C-contiguous (NCDHW) memory layout.
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int d_idx = (idx / ((long long)W * H)) % D;
        int c_idx = (idx / ((long long)W * H * D)) % C;
        int n_idx = idx / ((long long)W * H * D * C);

        int group_idx = c_idx / channels_per_group;

        // Retrieve pre-computed mean and rstd for the current batch item and group.
        float mean_val = mean[n_idx * num_groups + group_idx];
        float rstd_val = rstd[n_idx * num_groups + group_idx];
        // Retrieve learnable gamma (weight) and beta (bias) for the current channel.
        float gamma_val = gamma[c_idx];
        float beta_val = beta[c_idx];

        float val = x[idx];

        // Step 1: Group Normalization
        // Equivalent to (val - mean) / sqrt(var + epsilon)
        float normalized_val = (val - mean_val) * rstd_val;

        // Step 2: ReLU activation
        float relu_val = fmaxf(0.0f, normalized_val);

        // Step 3: Scale and Shift (affine transformation)
        out[idx] = gamma_val * relu_val + beta_val;
    }
}

// C++ wrapper function that orchestrates the two CUDA kernel launches.
torch::Tensor group_norm_relu_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float epsilon) {

    // Input tensor x: (N, C, D, H, W)
    // gamma, beta: (C) - learnable parameters for GroupNorm

    // Input validation checks
    TORCH_CHECK(x.is_cuda(), "Input tensor x must be a CUDA tensor.");
    TORCH_CHECK(gamma.is_cuda(), "Gamma tensor must be a CUDA tensor.");
    TORCH_CHECK(beta.is_cuda(), "Beta tensor must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 5, "Input tensor x must be a 5D tensor (NCDHW format).");
    TORCH_CHECK(x.is_contiguous(), "Input tensor x must be contiguous for efficient memory access in the kernel.");

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    TORCH_CHECK(C % num_groups == 0, "Number of channels (C) must be divisible by num_groups.");
    TORCH_CHECK(gamma.numel() == C, "Gamma tensor must have C elements, matching the number of channels.");
    TORCH_CHECK(beta.numel() == C, "Beta tensor must have C elements, matching the number of channels.");

    // Allocate output tensors for mean and rstd (reciprocal standard deviation).
    // These tensors will store statistics per (batch_item, group). Shape: (N, num_groups).
    auto mean_out = torch::empty({N, num_groups}, x.options());
    auto rstd_out = torch::empty({N, num_groups}, x.options());

    // --- Launch Kernel 1: Compute mean and rstd ---
    const int block_size_mean_var = 256;
    // Each block processes one (batch_idx, group_idx) pair.
    const int num_blocks_mean_var = N * num_groups;
    // Shared memory size required for sum and sum_sq arrays (2 * block_size_mean_var floats).
    const int shared_mem_size_mean_var = 2 * block_size_mean_var * sizeof(float);

    group_norm_relu_mean_var_kernel<<<num_blocks_mean_var, block_size_mean_var, shared_mem_size_mean_var>>>(
        x.data_ptr<float>(),
        N, C, D, H, W,
        num_groups,
        mean_out.data_ptr<float>(),
        rstd_out.data_ptr<float>(),
        epsilon);

    // Allocate the final output tensor, which will have the same shape as the input 'x'.
    auto out = torch::empty_like(x);

    // --- Launch Kernel 2: Apply GroupNorm, ReLU, Scale, and Shift ---
    const int block_size_apply = 256;
    long long total_elements = (long long)N * C * D * H * W;
    // Calculate the number of blocks needed to cover all elements using ceil division.
    const int num_blocks_apply = (total_elements + block_size_apply - 1) / block_size_apply;

    group_norm_relu_apply_kernel<<<num_blocks_apply, block_size_apply>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        mean_out.data_ptr<float>(),
        rstd_out.data_ptr<float>(),
        N, C, D, H, W,
        num_groups,
        out.data_ptr<float>());

