import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused BatchNorm2d and Tanh
# This kernel performs the operations of BatchNorm2d (in inference mode)
# followed by Tanh activation, all within a single CUDA kernel.
# This fusion avoids writing an intermediate tensor to global memory,
# potentially improving memory bandwidth utilization and overall speed.
batchnorm_tanh_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanh and sqrt

// CUDA kernel for fused BatchNorm2d and Tanh
// This kernel processes each element (N, C, H, W) independently.
// It applies BatchNorm's normalization, scaling, and shifting using
// the pre-computed running_mean and running_var (inference mode behavior).
// Subsequently, it applies the Tanh activation function.
__global__ void batchnorm_tanh_kernel(
    const float* input,
    const float* weight_bn,
    const float* bias_bn,
    const float* running_mean_bn,
    const float* running_var_bn,
    float eps_bn,
    float* output,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H * W) {
        // Calculate the channel index 'c' for the current element 'idx'.
        // The input tensor is assumed to be in NCHW format.
        // idx = n * C * H * W + c * H * W + h * W + w
        // So, c = (idx / (H * W)) % C
        int c = (idx / (H * W)) % C;

        float val = input[idx];

        // Retrieve BatchNorm parameters for the current channel
        float mean = running_mean_bn[c];
        float var = running_var_bn[c];
        float bn_weight = weight_bn[c];
        float bn_bias = bias_bn[c];

        // Apply BatchNorm formula (inference mode: uses running statistics)
        // y = (x - running_mean) / sqrt(running_var + eps) * weight + bias
        float normalized_val = (val - mean) / sqrtf(var + eps_bn);
        float bn_output = normalized_val * bn_weight + bn_bias;

        // Apply Tanh activation
        output[idx] = tanhf(bn_output);
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch.
// It handles tensor checks, dimension extraction, and kernel launch configuration.
torch::Tensor batchnorm_tanh_cuda(
    torch::Tensor input,
    torch::Tensor weight_bn,
    torch::Tensor bias_bn,
    torch::Tensor running_mean_bn,
    torch::Tensor running_var_bn,
    double eps_bn) {

    // Validate input tensors: ensure they are on CUDA, contiguous, and float32.
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight_bn.is_cuda(), "weight_bn must be a CUDA tensor");
    TORCH_CHECK(bias_bn.is_cuda(), "bias_bn must be a CUDA tensor");
    TORCH_CHECK(running_mean_bn.is_cuda(), "running_mean_bn must be a CUDA tensor");
    TORCH_CHECK(running_var_bn.is_cuda(), "running_var_bn must be a CUDA tensor");

    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight_bn.is_contiguous(), "weight_bn must be contiguous");
    TORCH_CHECK(bias_bn.is_contiguous(), "bias_bn must be contiguous");
    TORCH_CHECK(running_mean_bn.is_contiguous(), "running_mean_bn must be contiguous");
    TORCH_CHECK(running_var_bn.is_contiguous(), "running_var_bn must be contiguous");

    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight_bn.dtype() == torch::kFloat32, "weight_bn must be float32");
    TORCH_CHECK(bias_bn.dtype() == torch::kFloat32, "bias_bn must be float32");
    TORCH_CHECK(running_mean_bn.dtype() == torch::kFloat32, "running_mean_bn must be float32");
    TORCH_CHECK(running_var_bn.dtype() == torch::kFloat32, "running_var_bn must be float32");

    // Extract dimensions from the input tensor
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int total_elements = N * C * H * W;

    // Create an empty output tensor with the same shape and type as the input
    auto output = torch::empty_like(input);

    // Configure and launch the CUDA kernel
    const int block_size = 256; // A common block size for general-purpose kernels
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    batchnorm_tanh_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight_bn.data_ptr<float>(),
        bias_bn.data_ptr<float>(),
        running_mean_bn.data_ptr<float>(),
        running_var_bn.data_ptr<float>(),
        (float)eps_bn, // Cast epsilon to float for the kernel
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}
"""

# C++ header for the custom CUDA function
batchnorm_tanh_cpp_source = (
    "torch::Tensor batchnorm_tanh_cuda(torch::Tensor input, torch::Tensor weight_bn, torch::Tensor bias_bn, torch::Tensor running_mean_bn, torch::Tensor running_var_bn, double eps_bn);"
)

