    """
    Optimized Model that replaces the sequential BatchNorm2d and Tanh operators
    with a single fused custom CUDA kernel for potential speedups.
    The custom BatchNorm+Tanh kernel operates in inference mode (uses running_mean/var).
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, num_groups):
        super(ModelNew, self).__init__()
        # Keep ConvTranspose2d as a standard PyTorch operator
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, groups=groups)

        # We instantiate BatchNorm2d to manage its learnable parameters (weight, bias)
        # and its buffers (running_mean, running_var, num_batches_tracked, eps).
        # However, its forward method will not be called directly;
        # instead, its parameters will be passed to our custom kernel.
        self.batch_norm = nn.BatchNorm2d(out_channels)

        # Tanh is now fused into the custom kernel, so no separate module is needed.

        # Keep MaxPool2d as a standard PyTorch operator
        self.max_pool = nn.MaxPool2d(kernel_size=2, stride=2)

        # Keep GroupNorm as a standard PyTorch operator
        self.group_norm = nn.GroupNorm(num_groups=num_groups, num_channels=out_channels)

        # Store the custom kernel function for easy access in forward pass
        self.batchnorm_tanh_op = batchnorm_tanh_module.batchnorm_tanh_cuda

    def forward(self, x):
        # Step 1: Transposed Convolution
        x = self.conv_transpose(x)

        # Step 2 & 3: Fused BatchNorm2d and Tanh using the custom CUDA kernel.
        # This custom kernel uses the running_mean and running_var from the BatchNorm2d module,
        # effectively mimicking BatchNorm's behavior in evaluation mode.
        # For training, a more complex kernel would be needed to compute batch statistics
        # and update running statistics.
        x = self.batchnorm_tanh_op(
            x,
            self.batch_norm.weight,
            self.batch_norm.bias,
            self.batch_norm.running_mean,
            self.batch_norm.running_var,
            self.batch_norm.eps
        )

        # Step 4: Max Pooling
        x = self.max_pool(x)

        # Step 5: Group Normalization
        x = self.group_norm(x)

        return x

