fused_avg_pool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min

// Helper function to get 5D index from a flattened 1D index
// This is used to map a thread's linear index to a specific (N, C, D, H, W) output element.
__device__ void get_5d_indices(int flat_idx, int N, int C, int D, int H, int W,
                               int& n, int& c, int& d, int& h, int& w) {
    w = flat_idx % W;
    flat_idx /= W;
    h = flat_idx % H;
    flat_idx /= H;
    d = flat_idx % D;
    flat_idx /= D;
    c = flat_idx % C;
    flat_idx /= C;
    n = flat_idx;
}

// Helper function to get a flattened 1D index from 5D indices
// This is used to access elements in the input tensor `x`.
__device__ int get_flat_index(int n, int c, int d, int h, int w,
                              int C, int D, int H, int W) {
    return n * (C * D * H * W) + c * (D * H * W) + d * (H * W) + h * W + w;
}


__global__ void fused_avg_pool3d_kernel(
    const float* __restrict__ x, // Input tensor (output of BatchNorm3d)
    float* __restrict__ out,     // Output tensor
    int N, int C, int D_in, int H_in, int W_in, // Input tensor dimensions
    int D_out_pool1, int H_out_pool1, int W_out_pool1, // Intermediate pooling output dimensions
    int D_out_pool2, int H_out_pool2, int W_out_pool2, // Final pooling output dimensions
    int total_output_elements) {

    // Each thread computes one element of the final output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Unflatten the 1D thread index to 5D output indices (n_o, c_o, d_o, h_o, w_o)
        int n_o, c_o, d_o, h_o, w_o;
        get_5d_indices(idx, N, C, D_out_pool2, H_out_pool2, W_out_pool2, n_o, c_o, d_o, h_o, w_o);

        float sum_val = 0.0f;

        // Simulate the first AvgPool3d(kernel_size=2, stride=2)
        // This loop iterates over the 2x2x2 window in the *intermediate* pooling output.
        // For each element in this window, we calculate its value by performing the first pooling step.
        int d1_start = d_o * 2;
        int h1_start = h_o * 2;
        int w1_start = w_o * 2;

        for (int kd1 = 0; kd1 < 2; ++kd1) {
            for (int kh1 = 0; kh1 < 2; ++kh1) {
                for (int kw1 = 0; kw1 < 2; ++kw1) {
                    int d1 = d1_start + kd1;
                    int h1 = h1_start + kh1;
                    int w1 = w1_start + kw1;

                    // Check if this intermediate pooling output element would have been valid
                    // (i.e., its source window in the original input `x` would be within bounds
                    // and thus contribute to the first pooling output).
                    // This replicates PyTorch's default AvgPool3d behavior where output is truncated.
                    if (d1 < D_out_pool1 && h1 < H_out_pool1 && w1 < W_out_pool1) {
                        // This (d1, h1, w1) represents an element in the *first* pooling output.
                        // Now, find its source 2x2x2 window in the original input `x`.
                        int d2_start = d1 * 2;
                        int h2_start = h1 * 2;
                        int w2_start = w1 * 2;

                        float sub_sum = 0.0f;
                        // The divisor for AvgPool3d with count_include_pad=True (default) is always kernel_size^3 (8 for 2x2x2).
                        // Elements outside input bounds are effectively treated as zero.

                        for (int kd2 = 0; kd2 < 2; ++kd2) {
                            for (int kh2 = 0; kh2 < 2; ++kh2) {
                                for (int kw2 = 0; kw2 < 2; ++kw2) {
                                    int d2 = d2_start + kd2;
                                    int h2 = h2_start + kh2;
                                    int w2 = w2_start + kw2;

                                    // Check if this input element is within the original input bounds
                                    if (d2 < D_in && h2 < H_in && w2 < W_in) {
