import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
custom_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, rsqrtf

// Kernel 1: calculate_group_mean_var_kernel
// This kernel computes the mean and variance (then reciprocal standard deviation)
// for each group across all batch items. Each CUDA block processes one group.
__global__ void calculate_group_mean_var_kernel(
    const float* x,
    float* mean_out,
    float* rstd_out,
    int batch_size,
    int hidden_size,
    int num_groups,
    int channels_per_group,
    float eps
) {
    // Map blockIdx.x to a unique group across all batch items
    int group_flat_idx = blockIdx.x; // Ranges from 0 to (batch_size * num_groups - 1)
    int batch_idx = group_flat_idx / num_groups;
    int group_idx = group_flat_idx % num_groups;

    // Calculate the starting offset for this group's data in the input tensor 'x'
    int group_start_offset = batch_idx * hidden_size + group_idx * channels_per_group;

    // Shared memory for parallel reduction within the block.
    // The size must be at least blockDim.x.
    // For channels_per_group = 16 and blockDim.x = 256, only the first 16 elements
    // of shared memory will be actively used by threads 0-15.
    __shared__ float s_sum_data[256];
    __shared__ float s_sum_sq_data[256];

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Each thread processes multiple elements if channels_per_group > blockDim.x,
    // or a single element if channels_per_group <= blockDim.x.
    // This loop ensures all elements within the group are summed by the block.
    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        float val = x[group_start_offset + i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    // Store thread-local sums into shared memory
    s_sum_data[threadIdx.x] = thread_sum;
    s_sum_sq_data[threadIdx.x] = thread_sum_sq;
    __syncthreads(); // Synchronize to ensure all writes to shared memory are visible

    // Perform parallel tree reduction within the block to get total sum and sum of squares
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum_data[threadIdx.x] += s_sum_data[threadIdx.x + s];
            s_sum_sq_data[threadIdx.x] += s_sum_sq_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Only the first thread (threadIdx.x == 0) writes the final mean and rstd for the group
    if (threadIdx.x == 0) {
        float total_sum = s_sum_data[0];
        float total_sum_sq = s_sum_sq_data[0];

        float mean = total_sum / channels_per_group;
        float var = total_sum_sq / channels_per_group - mean * mean;
        // Ensure variance is non-negative to avoid issues with sqrt of negative numbers
        if (var < 0) var = 0;
        float rstd = rsqrtf(var + eps); // Calculate 1 / sqrt(var + eps) using fast intrinsic

        // Store the calculated mean and rstd to global memory
        mean_out[group_flat_idx] = mean;
        rstd_out[group_flat_idx] = rstd;
    }
}

// Kernel 2: fused_gn_leakyrelu_add_kernel
// This kernel performs the Group Normalization (normalization part), LeakyReLU activation,
// and element-wise addition (x+x) in a single fused operation.
// Each thread processes one element in the output tensor.
__global__ void fused_gn_leakyrelu_add_kernel(
    const float* x,
    const float* mean,
    const float* rstd,
    const float* gamma, // GroupNorm learnable scale parameter (per channel)
    const float* beta,  // GroupNorm learnable bias parameter (per channel)
    float* out,
    int batch_size,
    int hidden_size,
    int num_groups,
    int channels_per_group,
    float negative_slope // LeakyReLU parameter
) {
    // Map global thread index to an element in the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Process only valid elements within the tensor bounds
    if (idx < batch_size * hidden_size) {
        int batch_idx = idx / hidden_size;
        int channel_idx = idx % hidden_size;
        // Determine which group this channel belongs to
        int group_idx = channel_idx / channels_per_group;

        // Get group-specific mean and rstd from the pre-calculated tensors
        int group_flat_idx = batch_idx * num_groups + group_idx;
        float current_mean = mean[group_flat_idx];
        float current_rstd = rstd[group_flat_idx];

        // Get channel-specific gamma and beta
        float current_gamma = gamma[channel_idx];
        float current_beta = beta[channel_idx];

        float val = x[idx];

        // 1. Group Normalization: (x - mean) / sqrt(var + eps) * gamma + beta
        val = (val - current_mean) * current_rstd * current_gamma + current_beta;

        // 2. LeakyReLU activation: val = max(0, val) + negative_slope * min(0, val)
        val = (val > 0) ? val : val * negative_slope;

        // 3. Element-wise addition (x + x), which is equivalent to val * 2.0f
        val = val * 2.0f;

        // Store the final result to the output tensor
        out[idx] = val;
    }
}

// C++ wrapper for calculate_group_mean_var_kernel
// This function is called from Python and launches the CUDA kernel.
// It returns a vector of two tensors: mean and rstd.
std::vector<torch::Tensor> calculate_group_mean_var_cuda(
    torch::Tensor x,
    int num_groups,
    int channels_per_group,
    float eps
) {
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 2, "Input tensor 'x' must be 2D (batch_size, hidden_size).");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous."); // Ensure contiguous for direct pointer access

    int batch_size = x.size(0);
    int hidden_size = x.size(1);

    // Output tensors for mean and rstd, allocated on the same device as x
    auto mean_out = torch::empty({batch_size, num_groups}, x.options());
    auto rstd_out = torch::empty({batch_size, num_groups}, x.options());

    const int block_size = 256; // Common block size for reduction kernels
    const int num_blocks = batch_size * num_groups; // One block per group per batch item

    calculate_group_mean_var_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean_out.data_ptr<float>(),
        rstd_out.data_ptr<float>(),
        batch_size,
        hidden_size,
        num_groups,
        channels_per_group,
        eps
    );
    C10_CUDA_KERNEL_CHECK(); // Check for CUDA errors after kernel launch

    return {mean_out, rstd_out}; // Return a vector of tensors
