class ModelNew(nn.Module):
    """
    A model that performs a matrix multiplication, custom fused group normalization,
    leaky ReLU activation, and element-wise sum.
    This version replaces the PyTorch nn.GroupNorm, nn.LeakyReLU, and the element-wise
    addition (x+x) with two custom CUDA kernels for potential speedups.
    """
    def __init__(self, input_size, hidden_size, num_groups, eps=1e-5, negative_slope=0.01):
        super(ModelNew, self).__init__()
        # The linear layer remains a standard PyTorch operation, as it's typically
        # highly optimized (e.g., using cuBLAS) and complex to replace efficiently.
        self.fc = nn.Linear(input_size, hidden_size)

        # GroupNorm parameters are now managed directly by ModelNew.
        # These are learnable parameters, initialized similar to nn.GroupNorm (weight=1, bias=0).
        self.gn_gamma = nn.Parameter(torch.ones(hidden_size))
        self.gn_beta = nn.Parameter(torch.zeros(hidden_size))
        self.gn_eps = eps
        self.num_groups = num_groups

        # Ensure hidden_size is divisible by num_groups as required by GroupNorm.
        if hidden_size % num_groups != 0:
            raise ValueError(f"hidden_size ({hidden_size}) must be divisible by num_groups ({num_groups})")
        self.channels_per_group = hidden_size // num_groups

        # LeakyReLU parameter.
        self.negative_slope = negative_slope

        # Store the compiled custom CUDA operations module.
        self.custom_ops = custom_ops

    def forward(self, x):
        """
        Performs the forward pass of the model using custom CUDA kernels.

        Args:
            x: Input tensor of shape (batch_size, input_size).

        Returns:
            Output tensor of shape (batch_size, hidden_size).
        """
        # Step 1: Matrix multiplication (PyTorch's nn.Linear)
        x = self.fc(x)

        # Step 2: Custom fused GroupNorm - Mean and Variance Calculation
        # This kernel computes the mean and reciprocal standard deviation for each group.
        # It returns a tuple (mean_tensor, rstd_tensor).
        mean, rstd = self.custom_ops.calculate_group_mean_var_cuda(
            x, self.num_groups, self.channels_per_group, self.gn_eps
        )

        # Step 3: Custom fused GroupNorm (Normalization) + LeakyReLU + Element-wise (x+x)
        # This kernel takes the input 'x', the pre-calculated 'mean' and 'rstd',
        # GroupNorm's 'gamma' and 'beta', LeakyReLU's 'negative_slope',
        # and performs all three operations in a single pass, writing to the output.
        x = self.custom_ops.fused_gn_leakyrelu_add_cuda(
            x, mean, rstd, self.gn_gamma, self.gn_beta,
            self.num_groups, self.channels_per_group, self.negative_slope
        )
        return x

