# Compile the inline CUDA code
fused_linear_gelu_softmax = load_inline(
    name="fused_linear_gelu_softmax",
    cpp_sources=fused_linear_gelu_softmax_cpp_source,
    cuda_sources=fused_linear_gelu_softmax_source,
    functions=["linear_gelu_softmax_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Add optimization and fast math flags for CUDA compiler
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a fused Linear + GELU + Softmax operation using a custom CUDA kernel.
    """
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
