// CUDA kernel for fused min(x, constant) + bias * scaling_factor
__global__ void fused_min_add_mul_kernel(
    const float* x,
    float constant_value,
    const float* bias,
    float scaling_factor,
    float* out,
    int total_elements,
    int C, // Number of channels (out_channels)
    int HW // Height * Width of the feature map
