        // idx is flattened as (batch, channel, height, width)
        // channel_idx = (idx / (H*W)) % C
        int channel_idx = (idx / HW) % C;

        float val_bias = bias[channel_idx];

        float temp = fminf(val_x, constant_value); // Element-wise min
        temp += val_bias;                          // Add bias
        out[idx] = temp * scaling_factor;          // Multiply by scaling factor
    }
