from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernel for Softmax (along dim=1) ---
# This kernel computes softmax across the channel dimension (dim=1) for each spatial slice.
# It uses a block-level reduction for finding the maximum value and sum of exponentials
# for numerical stability and correct probability distribution.
custom_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void custom_softmax_kernel(const float* input, float* output,
                                      int N, int C, int D, int H, int W) {
    // Each block processes one (N, D, H, W) spatial slice
    int slice_idx = blockIdx.x; // Corresponds to (n, d, h, w)
    int total_spatial_slices = N * D * H * W;

    if (slice_idx >= total_spatial_slices) {
        return;
    }

    // Decompose slice_idx back to (n, d, h, w)
    int w_idx = slice_idx % W;
    int h_idx = (slice_idx / W) % H;
    int d_idx = (slice_idx / (W * H)) % D;
    int n_idx = slice_idx / (W * H * D);

    // Find max value for numerical stability
    float max_val = -FLT_MAX;
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int input_offset = n_idx * C * D * H * W +
                           c_idx * D * H * W +
                           d_idx * H * W +
                           h_idx * W +
                           w_idx;
        max_val = fmaxf(max_val, input[input_offset]);
    }

    // Reduce max_val across threads in the block using shared memory
    __shared__ float s_max_val[256]; // Max block size
    s_max_val[threadIdx.x] = max_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_max_val[threadIdx.x] = fmaxf(s_max_val[threadIdx.x], s_max_val[threadIdx.x + s]);
        }
        __syncthreads();
    }
    max_val = s_max_val[0]; // The max value for this slice is now in s_max_val[0]

    // Compute sum of exponentials
    float exp_sum = 0.0f;
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int input_offset = n_idx * C * D * H * W +
                           c_idx * D * H * W +
                           d_idx * H * W +
                           h_idx * W +
                           w_idx;
        exp_sum += expf(input[input_offset] - max_val);
    }

    // Reduce exp_sum across threads in the block using shared memory
    __shared__ float s_exp_sum[256];
    s_exp_sum[threadIdx.x] = exp_sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_exp_sum[threadIdx.x] += s_exp_sum[threadIdx.x + s];
        }
        __syncthreads();
    }
    exp_sum = s_exp_sum[0]; // The sum for this slice is now in s_exp_sum[0]

    // Compute softmax output
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int input_offset = n_idx * C * D * H * W +
                           c_idx * D * H * W +
                           d_idx * H * W +
                           h_idx * W +
                           w_idx;
        output[input_offset] = expf(input[input_offset] - max_val) / exp_sum;
    }
}

torch::Tensor custom_softmax_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N, C, D, H, W)");

    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::zeros_like(input);

    int total_spatial_slices = N * D * H * W;
    const int block_size = 256; // Max threads per block
    const int num_blocks = (total_spatial_slices + block_size - 1) / block_size;

    custom_softmax_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        N, C, D, H, W
    );
    cudaGetLastError(); // Check for kernel launch errors

    return output;
}
