# --- Custom CUDA Kernel for Fused MaxPool3d ---
# This kernel replaces two consecutive MaxPool3d(K) operations with a single
# MaxPool3d(K*K) operation, effectively fusing them.
custom_fused_maxpool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void custom_fused_maxpool3d_kernel(const float* input, float* output,
                                              int N, int C, int D_in, int H_in, int W_in,
                                              int D_out, int H_out, int W_out,
                                              int effective_kernel_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int total_output_elements = N * C * D_out * H_out * W_out;

    if (idx >= total_output_elements) {
        return;
    }

    // Decompose idx back to (n, c, d_out, h_out, w_out)
    int w_out_idx = idx % W_out;
    int h_out_idx = (idx / W_out) % H_out;
    int d_out_idx = (idx / (W_out * H_out)) % D_out;
    int c_idx = (idx / (W_out * H_out * D_out)) % C;
    int n_idx = idx / (W_out * H_out * D_out * C);

    float max_val = -FLT_MAX;

    // Calculate input window start coordinates
    int d_start = d_out_idx * effective_kernel_size;
    int h_start = h_out_idx * effective_kernel_size;
    int w_start = w_out_idx * effective_kernel_size;

    // Iterate over the pooling window
    for (int d = 0; d < effective_kernel_size; ++d) {
        for (int h = 0; h < effective_kernel_size; ++h) {
            for (int w = 0; w < effective_kernel_size; ++w) {
                int current_d = d_start + d;
                int current_h = h_start + h;
                int current_w = w_start + w;

                // Check bounds for input (handles cases where input dimensions are not perfectly divisible)
                if (current_d < D_in && current_h < H_in && current_w < W_in) {
                    int input_offset = n_idx * C * D_in * H_in * W_in +
                                       c_idx * D_in * H_in * W_in +
                                       current_d * H_in * W_in +
                                       current_h * W_in +
                                       current_w;
                    max_val = fmaxf(max_val, input[input_offset]);
                }
            }
        }
    }

    // Write the max value to the output
    int output_offset = n_idx * C * D_out * H_out * W_out +
                        c_idx * D_out * H_out * W_out +
                        d_out_idx * H_out * W_out +
                        h_out_idx * W_out +
                        w_out_idx;
    output[output_offset] = max_val;
}

torch::Tensor custom_fused_maxpool3d_cuda(torch::Tensor input, int effective_kernel_size) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N, C, D, H, W)");

    int N = input.size(0);
    int C = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // Output dimensions are calculated using integer division, replicating PyTorch's default MaxPool behavior
    int D_out = D_in / effective_kernel_size;
    int H_out = H_in / effective_kernel_size;
    int W_out = W_in / effective_kernel_size;

    auto output = torch::zeros({N, C, D_out, H_out, W_out}, input.options());

    int total_output_elements = N * C * D_out * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    custom_fused_maxpool3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        N, C, D_in, H_in, W_in,
        D_out, H_out, W_out,
        effective_kernel_size
    );
    cudaGetLastError(); // Check for kernel launch errors

    return output;
}
"""

custom_fused_maxpool3d_cpp_source = (
    "torch::Tensor custom_fused_maxpool3d_cuda(torch::Tensor input, int effective_kernel_size);"
)

# Compile the inline CUDA code for custom softmax
custom_softmax_module = load_inline(
