import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused activation: x * tanh(softplus(x))
fused_activation_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For __logf, __expf, __tanhf

// Numerically stable softplus function for float
__device__ float softplus_f(float x) {
    // softplus(x) = log(1 + exp(x))
    // For numerical stability:
    // if x > 0, softplus(x) = x + log(1 + exp(-x))
    // if x <= 0, softplus(x) = log(1 + exp(x))
    return (x > 0) ? (x + __logf(1.0f + __expf(-x))) : __logf(1.0f + __expf(x));
}

// CUDA kernel to compute x * tanh(softplus(x)) element-wise
__global__ void fused_activation_kernel(const float* x_ptr, float* out_ptr, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        float val_x = x_ptr[idx];
        float sp_val = softplus_f(val_x);
        float tanh_sp_val = __tanhf(sp_val); // Use CUDA's intrinsic tanh function for performance
        out_ptr[idx] = val_x * tanh_sp_val;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor fused_activation_cuda(torch::Tensor x) {
    // Input tensor must be on CUDA, contiguous, and float32
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");

    auto N = x.numel(); // Total number of elements
    auto out = torch::empty_like(x); // Allocate output tensor with the same properties as x

    // Define block and grid dimensions
    const int block_size = 256; // Standard block size
    const int num_blocks = (N + block_size - 1) / block_size; // Calculate number of blocks needed

    // Launch the CUDA kernel
    fused_activation_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), // Pointer to input data
        out.data_ptr<float>(), // Pointer to output data
        N // Total size
    );

    // No explicit cudaDeviceSynchronize() needed here, PyTorch handles stream synchronization
    // for subsequent operations on the same stream.
    // For robust error checking in production, cudaGetLastError() after launch and
    // cudaDeviceSynchronize() before returning could be added.

    return out;
}
"""

# C++ header for the function signature
fused_activation_cpp_source = (
    "torch::Tensor fused_activation_cuda(torch::Tensor x);"
)

# Compile the inline CUDA code
# verbose=False to avoid printing compilation details unless debugging
# extra_cuda_cflags for performance optimizations
fused_activation_module = load_inline(
    name="fused_activation_module",
    cpp_sources=fused_activation_cpp_source,
    cuda_sources=fused_activation_source,
    functions=["fused_activation_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a convolution, applies a fused activation,
    and then applies Batch Normalization.
    The activation block `x * tanh(softplus(x))` is replaced by a custom CUDA kernel
    for improved performance through operator fusion.
    """
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        # Convolution layer remains as PyTorch's highly optimized nn.Conv2d
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        # Batch Normalization layer remains as PyTorch's nn.BatchNorm2d
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)
        # Custom fused activation operator
        self.fused_activation_op = fused_activation_module.fused_activation_cuda

    def forward(self, x):
        x = self.conv(x)
        # Apply the custom fused activation kernel, replacing:
        # x = torch.multiply(torch.tanh(torch.nn.functional.softplus(x)), x)
        x = self.fused_activation_op(x)
        x = self.bn(x)
        return x

