import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for fused Batch Normalization, Scaling, and Softmax
fused_bn_scale_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, expf, fmaxf
#include <float.h> // For FLT_MAX

// Macro for checking CUDA errors
#define CUDA_CHECK(call)                                                               \
  do {                                                                                 \
    cudaError_t err = call;                                                            \
    if (err != cudaSuccess) {                                                          \
      fprintf(stderr, "CUDA error in %s:%d: %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \
      exit(EXIT_FAILURE);                                                              \
    }                                                                                  \
  } while (0)

// Define BLOCK_SIZE for shared memory reductions.
// A common choice is 256 or 512, limited by hardware.
#define BLOCK_SIZE 256

// Kernel 1: Apply Batch Normalization and Scaling, then find the maximum value per row.
// Stores the intermediate BN+Scaled result to global memory for subsequent kernels.
__global__ void fused_bn_scale_max_kernel(
    const float* x_in,
    const float* bn_weight,
    const float* bn_bias,
    const float* running_mean,
    const float* running_var,
    const float* scale,
    float* temp_bn_scaled_val, // Output: intermediate result (BN + Scale)
    float* row_max_buffer,     // Output: max value per row
    int batch_size,
    int out_features,
    float bn_eps) {

    int batch_idx = blockIdx.x; // Each block processes one row (batch item)
    int tid = threadIdx.x;      // Thread ID within the block
    int block_size = blockDim.x;

    if (batch_idx >= batch_size) return; // Guard against excess blocks

    int row_offset = batch_idx * out_features;

    float thread_max = -FLT_MAX; // Initialize thread-local max to smallest float value

    // Loop through elements assigned to this thread for the current row
    for (int j = tid; j < out_features; j += block_size) {
        int global_idx = row_offset + j;
        float val = x_in[global_idx];

        // Apply Batch Normalization (inference mode)
        float norm_val = (val - running_mean[j]) / sqrtf(running_var[j] + bn_eps);
        float bn_scaled_val = bn_weight[j] * norm_val + bn_bias[j];

        // Apply element-wise scaling (scale is a scalar, so scale[0])
        float final_val = scale[0] * bn_scaled_val; 

        temp_bn_scaled_val[global_idx] = final_val; // Store intermediate result
        thread_max = fmaxf(thread_max, final_val);  // Update thread-local max
    }

    // Shared memory for parallel reduction to find the maximum value in the row
    __shared__ float s_max[BLOCK_SIZE];
    s_max[tid] = thread_max;
    __syncthreads();

    // Parallel reduction (tree reduction)
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_max[tid] = fmaxf(s_max[tid], s_max[tid + s]);
        }
        __syncthreads();
    }

    // The first thread in the block writes the row's maximum value to global memory
    if (tid == 0) {
        row_max_buffer[batch_idx] = s_max[0];
    }
}

// Kernel 2: Compute exp(val - row_max) and find the sum of these exponentiated values per row.
// Stores the intermediate exp(val - row_max) result to global memory.
__global__ void fused_exp_sum_kernel(
    const float* temp_bn_scaled_val, // Input: intermediate result from K1
    const float* row_max_buffer,     // Input: max value per row from K1
    float* temp_exp_val,             // Output: exp(val - row_max)
    float* row_sum_exp_buffer,       // Output: sum of exp per row
    int batch_size,
    int out_features) {

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    if (batch_idx >= batch_size) return;

    int row_offset = batch_idx * out_features;
    float row_max = row_max_buffer[batch_idx]; // Load the pre-computed row max
    float thread_sum_exp = 0.0f;

    // Loop through elements assigned to this thread for the current row
    for (int j = tid; j < out_features; j += block_size) {
        int global_idx = row_offset + j;
        float final_val = temp_bn_scaled_val[global_idx]; // Load intermediate BN+Scaled value
        float exp_val = expf(final_val - row_max);       // Compute exp for softmax stability

        temp_exp_val[global_idx] = exp_val;              // Store intermediate exp value
        thread_sum_exp += exp_val;                       // Accumulate thread-local sum
    }

    // Shared memory for parallel reduction to find the sum of exponentiated values in the row
    __shared__ float s_sum_exp[BLOCK_SIZE];
    s_sum_exp[tid] = thread_sum_exp;
    __syncthreads();

    // Parallel reduction (tree reduction)
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_sum_exp[tid] += s_sum_exp[tid + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the row's sum of exp to global memory
    if (tid == 0) {
        row_sum_exp_buffer[batch_idx] = s_sum_exp[0];
    }
}

// Kernel 3: Perform the final division to get the softmax output.
__global__ void fused_div_kernel(
    const float* temp_exp_val,       // Input: exp(val - row_max) from K2
    const float* row_sum_exp_buffer, // Input: sum of exp per row from K2
    float* x_out,                    // Output: final softmax result
    int batch_size,
    int out_features) {

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    if (batch_idx >= batch_size) return;

    int row_offset = batch_idx * out_features;
    float row_sum_exp = row_sum_exp_buffer[batch_idx]; // Load the pre-computed row sum of exp

    // Loop through elements assigned to this thread for the current row
    for (int j = tid; j < out_features; j += block_size) {
        int global_idx = row_offset + j;
        float exp_val = temp_exp_val[global_idx]; // Load intermediate exp value
        x_out[global_idx] = exp_val / row_sum_exp; // Final softmax division
    }
}

