# Define the custom CUDA kernels for fused operations
fused_kernels_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cub/cub.cuh> // For block-wide reductions
#include <float.h>     // For FLT_MAX

// Helper macro for CUDA error checking
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error in %s:%d: %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(EXIT_FAILURE); \\
        } \\
    } while (0)

// Kernel 1: Fused Global Average Pooling and Bias Addition
// This kernel processes (B, C, H, W) input and (C) bias to produce (B, C) output.
// Each thread block is responsible for one (batch_idx, channel_idx) pair.
// Threads within the block collaborate to sum H*W elements for GAP.
__global__ void fused_gap_bias_add_kernel(
    const float* x_ptr,
    const float* bias_ptr,
    float* out_ptr,
    int B, int C, int H, int W) {

    int b = blockIdx.x; // Batch index
    int c = blockIdx.y; // Channel index

    // Calculate the starting index for the current (b, c) slice in x
    // x is assumed to be (B, C, H, W)
    long long x_slice_start_idx = (long long)b * C * H * W + (long long)c * H * W;

    // Each thread sums a portion of the H*W elements for its assigned (b, c) slice
    float thread_sum = 0.0f;
    long long num_elements_in_slice = (long long)H * W;
    for (long long i = threadIdx.x; i < num_elements_in_slice; i += blockDim.x) {
        thread_sum += x_ptr[x_slice_start_idx + i];
    }

    // Use CUB for block-wide sum reduction
    // The block size for CUB's BlockReduce must match blockDim.x.
    // We assume a block size of 256 for this kernel.
    typedef cub::BlockReduce<float, 256> BlockReduce;
    __shared__ typename BlockReduce::TempStorage temp_storage;

    float block_sum = BlockReduce(temp_storage).Sum(thread_sum);

    // Only the first thread in the block writes the result
    if (threadIdx.x == 0) {
        float mean_val = block_sum / num_elements_in_slice;
        // bias is assumed to be (C), so index by c
        float bias_val = bias_ptr[c];
        // out is (B, C)
        out_ptr[(long long)b * C + c] = mean_val + bias_val;
    }
}

// Kernel 2: Fused LogSumExp, Sum, and Multiplication by 10.0
// This kernel processes (B, C) intermediate input to produce (B, 1) output.
// Each thread block is responsible for one batch_idx.
// Threads within the block collaborate to compute logsumexp over C channels.
__global__ void fused_logsumexp_mul_kernel(
    const float* intermediate_ptr,
    float* out_ptr,
    int B, int C) {

    int b = blockIdx.x; // Batch index

    // Calculate the starting index for the current batch item 'b' in intermediate
    // intermediate is assumed to be (B, C)
    long long intermediate_slice_start_idx = (long long)b * C;

    // --- Step 1: Find max_val for numerical stability of logsumexp ---
    float thread_max = -FLT_MAX;
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        thread_max = fmaxf(thread_max, intermediate_ptr[intermediate_slice_start_idx + c_idx]);
    }

    // Use CUB for block-wide max reduction
    typedef cub::BlockReduce<float, 256> BlockReduce;
    __shared__ typename BlockReduce::TempStorage temp_storage_max;
    float block_max = BlockReduce(temp_storage_max).Reduce(thread_max, cub::Max());

    // Ensure all threads have the block_max value by broadcasting it via shared memory
    __shared__ float s_block_max;
    if (threadIdx.x == 0) {
        s_block_max = block_max;
    }
    __syncthreads(); // Ensure s_block_max is visible to all threads

    // --- Step 2: Compute sum(exp(val - max_val)) ---
    float thread_sum_exp = 0.0f;
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        thread_sum_exp += expf(intermediate_ptr[intermediate_slice_start_idx + c_idx] - s_block_max);
    }

    // Use CUB for block-wide sum reduction
    __shared__ typename BlockReduce::TempStorage temp_storage_sum_exp;
    float block_sum_exp = BlockReduce(temp_storage_sum_exp).Sum(thread_sum_exp);

    // Only the first thread in the block writes the final result
    if (threadIdx.x == 0) {
        float logsumexp_val = logf(block_sum_exp) + s_block_max;
        // The original model's `sum(dim=(2,3))` on a (B,1,1,1) tensor effectively flattens to (B,1).
        // Our output is directly (B,1).
        out_ptr[b] = logsumexp_val * 10.0f;
    }
}

