    TORCH_CHECK(x.is_contiguous() && bias.is_contiguous(), "Inputs must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32 && bias.dtype() == torch::kFloat32, "Inputs must be float32.");

    auto out = torch::empty({B, C}, x.options());

