    TORCH_CHECK(intermediate.is_contiguous(), "Input must be contiguous.");
    TORCH_CHECK(intermediate.dtype() == torch::kFloat32, "Input must be float32.");

    auto out = torch::empty({B, 1}, intermediate.options());

    const int block_size = 256; // Max threads per block for each kernel
    dim3 grid_dim_lse(B); // Grid for B batch items for LSE kernel

    fused_logsumexp_mul_kernel<<<grid_dim_lse, block_size>>>(
        intermediate.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C
    );
    CUDA_CHECK(cudaGetLastError()); // Check for errors

    return out;
