"""

# C++ declarations for the Python bindings
fused_kernels_cpp_source = """
torch::Tensor fused_gap_bias_add_cuda(torch::Tensor x, torch::Tensor bias, int B, int C, int H, int W);
torch::Tensor fused_logsumexp_mul_cuda(torch::Tensor intermediate, int B, int C);
