#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

// CUDA kernel for fused bias add, scale multiply, and sigmoid
__global__ void conv_post_ops_kernel(
    const float* input,
    const float* bias,
    const float* scale,
    float* output,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Calculate channel index 'c'
        // The input tensor is NCHW.
        // The bias and scale tensors are (C, 1, 1), effectively indexed by channel.
        int c = (idx / (H * W)) % C;

        float val = input[idx];
        val += bias[c]; // Bias is applied per channel
        val *= scale[c]; // Scale is applied per channel

        // Sigmoid activation: 1.0 / (1.0 + exp(-val))
        output[idx] = 1.0f / (1.0f + expf(-val));
    }
}

