fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat> // For FLT_MAX

// CUDA kernel to fuse Softmax (dim=1), Subtract, Swish, and Max (dim=1)
// This kernel processes one (batch, depth, height, width) spatial location per thread.
__global__ void fused_softmax_sub_swish_max_kernel(
    const float* input,
    const float* subtract_param,
    float* output,
    int B, int C, int D, int H, int W) {

    // Calculate global index for the current (b, d, h, w) spatial location
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure we don't go out of bounds of the total spatial elements
    if (idx < B * D * H * W) {
        // Decompose the linear index 'idx' back into (batch, depth, height, width) coordinates
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int d_idx = (idx / (W * H)) % D;
        int b_idx = idx / (W * H * D);

        // --- Softmax (numerically stable version) ---
        // Step 1: Find the maximum value across channels (C) for the current spatial location.
        // This is crucial for numerical stability of the exponential function in softmax.
        float max_val_for_softmax = -FLT_MAX; // Initialize with the smallest possible float value
        for (int c = 0; c < C; ++c) {
            // Calculate the linear index for input_tensor[b_idx, c, d_idx, h_idx, w_idx]
            int input_offset = b_idx * (C * D * H * W) +
                               c * (D * H * W) +
                               d_idx * (H * W) +
                               h_idx * W +
                               w_idx;
            max_val_for_softmax = fmaxf(max_val_for_softmax, input[input_offset]);
        }

        // Step 2: Compute exp(x - max_x) for each channel and sum them up.
        float sum_exp = 0.0f;
        // Use a stack-allocated array to store the exponentiated values for each channel.
        // This is efficient for small 'C' (out_channels), like 16 in the given example.
        // A size of 1024 is a common safe upper bound for stack arrays in CUDA kernels.
        float channel_exp_values[1024]; // Assuming C <= 1024. Adjust if C can be larger.
        for (int c = 0; c < C; ++c) {
            int input_offset = b_idx * (C * D * H * W) +
                               c * (D * H * W) +
                               d_idx * (H * W) +
                               h_idx * W +
                               w_idx;
            channel_exp_values[c] = expf(input[input_offset] - max_val_for_softmax);
            sum_exp += channel_exp_values[c];
        }

        // --- Fused operations: Softmax, Subtract, Swish, and Max reduction ---
        // Initialize the variable to find the maximum value after all operations.
        float final_max_val = -FLT_MAX;

        for (int c = 0; c < C; ++c) {
            // 1. Softmax: Divide the exponentiated value by the sum of exponentials.
            float softmax_val = channel_exp_values[c] / sum_exp;

            // 2. Subtract: Subtract the channel-specific parameter.
            float sub_val = softmax_val - subtract_param[c];

            // 3. Swish activation: x * sigmoid(x) = x / (1 + exp(-x))
            float swish_val = sub_val / (1.0f + expf(-sub_val));

            // 4. Max reduction: Keep track of the maximum value encountered so far.
            final_max_val = fmaxf(final_max_val, swish_val);
        }

        // Store the final maximum value for this spatial location into the output tensor.
        // The output tensor has shape (B, D, H, W) as the channel dimension has been reduced.
        int output_offset = b_idx * (D * H * W) +
                            d_idx * (H * W) +
                            h_idx * W +
                            w_idx;
        output[output_offset] = final_max_val;
    }
}

