fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanh, sqrt

// GELU approximation constants
#define M_SQRT2_PI 0.7978845608028654f // sqrt(2/pi)
#define GELU_CONST 0.044715f

// Approximation of GELU function
__device__ float gelu_approx(float x) {
    return 0.5f * x * (1.0f + tanhf(M_SQRT2_PI * (x + GELU_CONST * x * x * x)));
}

__global__ void fused_conv_post_kernel(
    const float* x_ptr,
    const float* multiplier_ptr,
    float* out_ptr,
    int N, int C, int H, int W,
    float negative_slope) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Calculate channel index for multiplier.
        // x has shape (N, C, H, W).
        // multiplier has shape (C, 1, 1), effectively (C,) for broadcasting.
        // The multiplier value depends only on the channel dimension.
        // Linear index `idx` maps to (n, c, h, w).
        // c = (idx / (H * W)) % C
        int c_idx = (idx / (H * W)) % C;

        float val = x_ptr[idx];
        float mult_val = multiplier_ptr[c_idx]; // Access multiplier based on channel

        // 1. Element-wise multiplication by multiplier
        val *= mult_val;

        // 2. LeakyReLU activation
        val = (val > 0) ? val : val * negative_slope;

        // 3. GELU activation (approximation)
        val = gelu_approx(val);

        out_ptr[idx] = val;
    }
}

