import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- CUDA Kernel Sources ---

# Common headers for all kernels
cuda_common_headers = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf, expf, logf, fmaxf, fminf, rsqrtf
#include <limits> // For std::numeric_limits
"""

# Kernel 1: GroupNorm Mean/Variance Calculation
# This kernel computes the mean and reciprocal standard deviation (rstd) for each group
# within each batch item. These are then used in the fused kernel.
group_norm_mean_var_source = cuda_common_headers + """
__global__ void group_norm_mean_var_kernel(
    const float* x,
    float* mean_out,
    float* rstd_out,
    int N, int C, int H, int W, int G, float eps) {

    int batch_group_idx = blockIdx.x; // Linear index for (batch_idx, group_idx)
    int n = batch_group_idx / G;
    int g = batch_group_idx % G;

    int C_per_group = C / G;
    int group_elements = C_per_group * H * W;

    // Shared memory for reduction: sdata[blockDim.x] for sum, sdata[blockDim.x*2] for sum_sq
    extern __shared__ float sdata[]; 

    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Each thread processes multiple elements in a strided loop
    for (int i = threadIdx.x; i < group_elements; i += blockDim.x) {
        int c_in_group = i / (H * W);
        int hw_idx = i % (H * W);
        int h = hw_idx / W;
        int w = hw_idx % W;

        int c = g * C_per_group + c_in_group; // Global channel index

        // Index into x: N, C, H, W
        int x_idx = n * (C * H * W) + c * (H * W) + h * W + w;
        float val = x[x_idx];
        sum_val += val;
        sum_sq_val += val * val;
    }

    // Reduce sums within the block using shared memory
    sdata[threadIdx.x] = sum_val;
    sdata[threadIdx.x + blockDim.x] = sum_sq_val;
    __syncthreads();

    // Tree reduction
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
            sdata[threadIdx.x + blockDim.x] += sdata[threadIdx.x + s + blockDim.x];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float total_sum = sdata[0];
        float total_sum_sq = sdata[blockDim.x];

        float mean = total_sum / group_elements;
        float var = total_sum_sq / group_elements - mean * mean;
        // Ensure variance is non-negative due to potential floating point inaccuracies
        var = fmaxf(0.0f, var);
        float rstd = rsqrtf(var + eps); // Reciprocal standard deviation

        mean_out[batch_group_idx] = mean;
        rstd_out[batch_group_idx] = rstd;
    }
}

// C++ wrapper for group_norm_mean_var_kernel
torch::Tensor group_norm_mean_var_cuda(torch::Tensor x, int N, int C, int H, int W, int G, float eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto mean_out = torch::empty({N, G}, x.options());
    auto rstd_out = torch::empty({N, G}, x.options());

    int num_blocks = N * G;
    int block_size = 256; 
    int C_per_group = C / G;
    int group_elements = C_per_group * H * W;

    if (group_elements == 0) { // Handle empty groups
        return torch::stack({mean_out, rstd_out});
    }

    // Adjust block_size if group_elements is very small to avoid idle threads
    if (group_elements < block_size) {
        block_size = group_elements;
    }
    // Shared memory for reduction: 2 * block_size * sizeof(float) for sum and sum_sq
    group_norm_mean_var_kernel<<<num_blocks, block_size, 2 * block_size * sizeof(float)>>>(
        x.data_ptr<float>(),
        mean_out.data_ptr<float>(),
        rstd_out.data_ptr<float>(),
        N, C, H, W, G, eps
    );
    return torch::stack({mean_out, rstd_out}); // Return as a stacked tensor (2, N, G)
}
"""

# Kernel 2: Fused GroupNorm Apply + Tanh + Hardswish + Residual Add
# This kernel applies the GroupNorm transformation using pre-computed mean/rstd,
# then Tanh, Hardswish, and finally the residual addition, all in a single pass.
fused_gn_activations_res_source = cuda_common_headers + """
// Device helper function for Hardswish activation
__device__ float hardswish_fwd(float x) {
    float val = x + 3.0f;
    val = fmaxf(0.0f, val); // clamp lower bound
    val = fminf(6.0f, val); // clamp upper bound
    return x * (val / 6.0f);
}

__global__ void fused_gn_activations_res_kernel(
    const float* x_conv,
    const float* mean,
    const float* rstd,
    const float* gn_weight,
    const float* gn_bias,
    float* out,
    int N, int C, int H, int W, int G) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / (H * W)) % C;
        int n = idx / (C * H * W);

        int C_per_group = C / G;
        int g = c / C_per_group; // Group index for current channel

        // Get mean and rstd for this batch item and group
        float current_mean = mean[n * G + g];
        float current_rstd = rstd[n * G + g];

        float x_conv_val = x_conv[idx];

        // 1. Group Normalization
        float x_norm_val = (x_conv_val - current_mean) * current_rstd;
        float gn_weight_val = (gn_weight == nullptr) ? 1.0f : gn_weight[c];
        float gn_bias_val = (gn_bias == nullptr) ? 0.0f : gn_bias[c];
        float x_gn_out = x_norm_val * gn_weight_val + gn_bias_val;

        // 2. Tanh activation
        float x_tanh_val = tanhf(x_gn_out);

        // 3. HardSwish activation
        float x_hard_swish_val = hardswish_fwd(x_tanh_val);

        // 4. Residual Addition
        out[idx] = x_conv_val + x_hard_swish_val;
    }
}

// C++ wrapper for fused_gn_activations_res_kernel
torch::Tensor fused_gn_activations_res_cuda(
    torch::Tensor x_conv,
    torch::Tensor mean,
    torch::Tensor rstd,
    torch::Tensor gn_weight,
    torch::Tensor gn_bias,
    int N, int C, int H, int W, int G) {

    TORCH_CHECK(x_conv.is_cuda(), "x_conv must be a CUDA tensor");
    TORCH_CHECK(mean.is_cuda(), "mean must be a CUDA tensor");
    TORCH_CHECK(rstd.is_cuda(), "rstd must be a CUDA tensor");
    TORCH_CHECK(x_conv.is_contiguous(), "x_conv must be contiguous");
    TORCH_CHECK(mean.is_contiguous(), "mean must be contiguous");
    TORCH_CHECK(rstd.is_contiguous(), "rstd must be contiguous");
    if (gn_weight.defined()) TORCH_CHECK(gn_weight.is_cuda() && gn_weight.is_contiguous(), "gn_weight must be a contiguous CUDA tensor");
    if (gn_bias.defined()) TORCH_CHECK(gn_bias.is_cuda() && gn_bias.is_contiguous(), "gn_bias must be a contiguous CUDA tensor");

    auto out = torch::empty_like(x_conv);

    int total_elements = N * C * H * W;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* gn_weight_ptr = gn_weight.defined() ? gn_weight.data_ptr<float>() : nullptr;
    const float* gn_bias_ptr = gn_bias.defined() ? gn_bias.data_ptr<float>() : nullptr;

    fused_gn_activations_res_kernel<<<num_blocks, block_size>>>(
        x_conv.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        gn_weight_ptr,
        gn_bias_ptr,
        out.data_ptr<float>(),
        N, C, H, W, G
    );
    return out;
}
"""

# Kernel 3: LogSumExp
# This kernel computes LogSumExp along the channel dimension (dim=1) for numerical stability.
logsumexp_source = cuda_common_headers + """
__global__ void logsumexp_kernel(
    const float* x,
    float* out,
    int N, int C, int H, int W) {

    int batch_hw_idx = blockIdx.x; // Linear index for (batch_idx, h_idx, w_idx)
    int n = batch_hw_idx / (H * W);
    int hw_idx = batch_hw_idx % (H * W);
    int h = hw_idx / W;
    int w = hw_idx % W;

    // Shared memory for reduction
    extern __shared__ float sdata[]; 

    // First pass: find max value for numerical stability
    // Initialize with negative infinity to correctly find the maximum
    float max_val = -std::numeric_limits<float>::infinity(); 
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int x_idx = n * (C * H * W) + c_idx * (H * W) + h * W + w;
        max_val = fmaxf(max_val, x[x_idx]);
    }

    sdata[threadIdx.x] = max_val;
    __syncthreads();

    // Reduce max within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] = fmaxf(sdata[threadIdx.x], sdata[threadIdx.x + s]);
        }
        __syncthreads();
    }

    float block_max = sdata[0]; // Max value for this (n, h, w) slice

    // Second pass: compute sum of exponentials (shifted by block_max for stability)
    float sum_exp_val = 0.0f;
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        int x_idx = n * (C * H * W) + c_idx * (H * W) + h * W + w;
        sum_exp_val += expf(x[x_idx] - block_max);
    }

    sdata[threadIdx.x] = sum_exp_val;
    __syncthreads();

    // Reduce sum_exp within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float total_sum_exp = sdata[0];
        out[n * (1 * H * W) + h * W + w] = block_max + logf(total_sum_exp);
    }
}

// C++ wrapper for logsumexp_kernel
torch::Tensor logsumexp_cuda(torch::Tensor x_res, int N, int C, int H, int W) {
    TORCH_CHECK(x_res.is_cuda(), "x_res must be a CUDA tensor");
    TORCH_CHECK(x_res.is_contiguous(), "x_res must be contiguous");

    // Output shape: (N, 1, H, W) as dim=1 and keepdim=True
    auto out = torch::empty({N, 1, H, W}, x_res.options());

    int num_blocks = N * H * W;
    int block_size = 256; 

    if (C == 0) { // Handle empty channel dimension
        return out;
    }

    // Adjust block_size if C is very small to avoid idle threads
    if (C < block_size) {
        block_size = C;
    }
    // Shared memory for reduction: block_size * sizeof(float)
    logsumexp_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        x_res.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W
    );
    return out;
}
"""

# Combine all CUDA sources
all_cuda_sources = (
    group_norm_mean_var_source +
    fused_gn_activations_res_source +
    logsumexp_source
)

# C++ declarations for all functions to be exposed to Python
all_cpp_sources = """
torch::Tensor group_norm_mean_var_cuda(torch::Tensor x, int N, int C, int H, int W, int G, float eps);
torch::Tensor fused_gn_activations_res_cuda(torch::Tensor x_conv, torch::Tensor mean, torch::Tensor rstd, torch::Tensor gn_weight, torch::Tensor gn_bias, int N, int C, int H, int W, int G);
torch::Tensor logsumexp_cuda(torch::Tensor x_res, int N, int C, int H, int W);
"""

# Compile all inline CUDA code into a single module
custom_ops = load_inline(
    name="custom_model_ops",
    cpp_sources=all_cpp_sources,
    cuda_sources=all_cuda_sources,
    functions=[
        "group_norm_mean_var_cuda",
        "fused_gn_activations_res_cuda",
        "logsumexp_cuda",
    ],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Add optimization flags for CUDA compiler, including fast math
)


class ModelNew(nn.Module):
    """
    Optimized Model that performs a convolution, applies Group Normalization, Tanh, HardSwish, 
    Residual Addition, and LogSumExp using custom CUDA kernels for fusion and specific ops.
    """
    def __init__(self, in_channels, out_channels, kernel_size, groups, eps=1e-5):
        super(ModelNew, self).__init__()
        # Convolution layer (kept as PyTorch's highly optimized implementation)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size).cuda() 
        # GroupNorm layer (parameters are used, but computation is custom)
        self.group_norm = nn.GroupNorm(groups, out_channels, eps=eps).cuda() 

        # Store parameters needed for custom kernels
        self.eps = eps
        self.groups = groups
        self.out_channels = out_channels

        # Store references to the compiled custom CUDA functions
        self.group_norm_mean_var_cuda = custom_ops.group_norm_mean_var_cuda
        self.fused_gn_activations_res_cuda = custom_ops.fused_gn_activations_res_cuda
        self.logsumexp_cuda = custom_ops.logsumexp_cuda

    def forward(self, x):
        # Ensure input is on CUDA device
        x = x.cuda()

        # 1. Convolution (PyTorch operator)
        x_conv = self.conv(x) # Shape: (N, C, H, W)

        N, C, H, W = x_conv.shape
        G = self.groups

        # 2. Custom GroupNorm Mean/Variance calculation
        # This kernel computes mean and rstd per group, per batch item.
        # Returns a stacked tensor (2, N, G) where [0] is mean and [1] is rstd.
        mean_rstd_stacked = self.group_norm_mean_var_cuda(
            x_conv, N, C, H, W, G, self.eps
        )
        mean = mean_rstd_stacked[0] # Shape: (N, G)
        rstd = mean_rstd_stacked[1] # Shape: (N, G)

        # 3. Custom Fused GroupNorm Apply + Tanh + Hardswish + Residual Addition
        # This kernel takes x_conv, the pre-computed mean/rstd, and GroupNorm's
        # learnable weights/biases, and performs all subsequent element-wise operations
        # (GroupNorm application, Tanh, Hardswish, Residual Add) in a single kernel.
        x_res = self.fused_gn_activations_res_cuda(
            x_conv, mean, rstd, 
            self.group_norm.weight, self.group_norm.bias, # Pass GroupNorm's learnable parameters
            N, C, H, W, G
        )

        # 4. Custom LogSumExp
        # This kernel computes logsumexp along the channel dimension (dim=1)
        # for numerical stability and efficiency.
        x_logsumexp = self.logsumexp_cuda(x_res, N, C, H, W)

        return x_logsumexp

