#include <torch/extension.h>
#include <cuda_runtime.h>

// HardSwish activation function
// hardswish(x) = x * relu6(x + 3) / 6
__device__ inline float hardswish(float x) {
    float y = x + 3.0f;
    y = fmaxf(0.0f, y);
    y = fminf(6.0f, y);
    return x * y / 6.0f;
}

// Kernel 1: Computes mean and variance of hardswish(x) per group
// Input: x (B, C, D, H, W)
// Output: mean (B, num_groups), var (B, num_groups)
__global__ void hardswish_groupnorm_mean_var_kernel(
    const float* x_ptr,
    float* mean_out_ptr,
    float* var_out_ptr,
    int B, int C, int D, int H, int W,
    int num_groups, float eps) {

    // Grid dimensions: (num_groups, B)
    int g_idx = blockIdx.x; // Group index
    int b_idx = blockIdx.y; // Batch index

    if (b_idx >= B || g_idx >= num_groups) return;

    int C_per_group = C / num_groups;
    int spatial_size = D * H * W;
    long long group_elements = (long long)C_per_group * spatial_size;

    // Shared memory for reduction (sum and sum_sq)
    extern __shared__ float s_data[]; // s_data[blockDim.x * 2]

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Each thread processes a portion of the group's elements
    for (long long i = threadIdx.x; i < group_elements; i += blockDim.x) {
        int c_offset_in_group = i / spatial_size;
        int spatial_offset = i % spatial_size;

        int c_idx = g_idx * C_per_group + c_offset_in_group;
        int d_idx = spatial_offset / (H * W);
        int h_idx = (spatial_offset % (H * W)) / W;
        int w_idx = spatial_offset % W;

        // Calculate linear index for x
        long long x_idx = (long long)b_idx * (C * D * H * W) +
                          (long long)c_idx * (D * H * W) +
                          (long long)d_idx * (H * W) +
                          (long long)h_idx * W +
                          (long long)w_idx;

        float val = x_ptr[x_idx];
        float h_val = hardswish(val);

        thread_sum += h_val;
        thread_sum_sq += h_val * h_val;
    }

    // Reduce sums within the block using shared memory
    s_data[threadIdx.x] = thread_sum;
    s_data[threadIdx.x + blockDim.x] = thread_sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
            s_data[threadIdx.x + blockDim.x + threadIdx.x] += s_data[threadIdx.x + blockDim.x + threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float group_sum = s_data[0];
        float group_sum_sq = s_data[blockDim.x];

        float mean = group_sum / group_elements;
        float variance = group_sum_sq / group_elements - mean * mean;

        mean_out_ptr[b_idx * num_groups + g_idx] = mean;
        var_out_ptr[b_idx * num_groups + g_idx] = fmaxf(0.0f, variance); // Ensure non-negative variance
    }
}

// Kernel 2: Applies hardswish, normalization, affine transform, and then mean pooling
// Input: x (B, C, D, H, W), mean (B, num_groups), var (B, num_groups), gamma (C), beta (C)
// Output: out (B, C)
__global__ void hardswish_groupnorm_affine_mean_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* var_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int B, int C, int D, int H, int W,
    int num_groups, float eps) {

    // Grid dimensions: (C, B)
    int c_idx = blockIdx.x; // Channel index
    int b_idx = blockIdx.y; // Batch index

    if (b_idx >= B || c_idx >= C) return;

    int C_per_group = C / num_groups;
    int g_idx = c_idx / C_per_group; // Group index for this channel

    float current_mean = mean_ptr[b_idx * num_groups + g_idx];
    float current_var = var_ptr[b_idx * num_groups + g_idx];
    float current_gamma = gamma_ptr[c_idx];
    float current_beta = beta_ptr[c_idx];

    float inv_std = rsqrtf(current_var + eps); // 1 / sqrt(var + eps)

    // Shared memory for reduction (sum)
    extern __shared__ float s_data[]; // s_data[blockDim.x]

    float thread_sum = 0.0f;
    int spatial_size = D * H * W;

    // Each thread processes a portion of the channel's spatial elements
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        int d_idx = i / (H * W);
        int h_idx = (i % (H * W)) / W;
        int w_idx = i % W;

        // Calculate linear index for x
        long long x_idx = (long long)b_idx * (C * D * H * W) +
                          (long long)c_idx * (D * H * W) +
                          (long long)d_idx * (H * W) +
                          (long long)h_idx * W +
                          (long long)w_idx;

        float val = x_ptr[x_idx];
        float h_val = hardswish(val);

        // Apply GroupNorm affine transform
        float norm_val = current_gamma * (h_val - current_mean) * inv_std + current_beta;

        thread_sum += norm_val;
    }

    // Reduce sums within the block using shared memory
    s_data[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
