// CUDA kernel for scalar multiplication and global average pooling
// Input x: (N, C, H, W)
// Output out: (N, C, 1, 1)
__global__ void scalar_mul_and_gap_kernel(const float* x_ptr, float multiplier, float* out_ptr,
                                          int N, int C, int H, int W) {
    // Each block processes one (N, C) slice (i.e., one feature map)
    int nc_idx = blockIdx.x; // Index for N*C dimension

    if (nc_idx < N * C) {
        // Calculate the starting index for this feature map in the input tensor
        // x_ptr is (N, C, H, W)
        // The stride for C is H*W
        // The stride for N is C*H*W
        int feature_map_offset = nc_idx * H * W;

        // Shared memory for reduction within the block
        // Declared as extern to allow dynamic sizing based on block_size
        extern __shared__ float s_sum[]; 

        float thread_sum = 0.0f;
        int total_elements_in_map = H * W;

        // Each thread processes multiple elements in the feature map
        for (int idx = threadIdx.x; idx < total_elements_in_map; idx += blockDim.x) {
            thread_sum += x_ptr[feature_map_offset + idx];
        }

        // Reduce within the block using shared memory
        s_sum[threadIdx.x] = thread_sum;
        __syncthreads();

        // Perform reduction in shared memory
        // This assumes blockDim.x is a power of 2 for efficient reduction
        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            }
            __syncthreads();
        }

        // The first thread writes the final result for this feature map
        if (threadIdx.x == 0) {
            out_ptr[nc_idx] = (s_sum[0] * multiplier) / (static_cast<float>(H) * W);
        }
    }
}

