#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, fmaxf, fminf

// Kernel 1: Compute mean and variance for each (N, C) slice
// Each block processes one (N, C) slice. Threads within the block perform a parallel reduction.
__global__ void compute_mean_var_kernel(const float* x, float* means, float* vars,
                                        int N, int C, int D, int H, int W, float eps) {
    int nc_idx = blockIdx.x; // Maps to n * C + c
    if (nc_idx >= N * C) return;

    int n = nc_idx / C;
    int c = nc_idx % C;

    int spatial_size = D * H * W;
    // Calculate starting index for this (n,c) slice in the input tensor
    int base_idx = n * C * D * H * W + c * D * H * W;

    // Use dynamically allocated shared memory for reduction within the block
    // The size of s_data is passed during kernel launch
    extern __shared__ float s_data[];
    float* s_sum = s_data;          // First half for sum
    float* s_sum_sq = s_data + blockDim.x; // Second half for sum of squares

    s_sum[threadIdx.x] = 0.0f;
    s_sum_sq[threadIdx.x] = 0.0f;

    // Each thread processes multiple elements using a grid-stride loop within its assigned (n,c) slice
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = x[base_idx + i];
        s_sum[threadIdx.x] += val;
        s_sum_sq[threadIdx.x] += val * val;
    }
    __syncthreads();

    // Parallel reduction within the block to get total sum and sum of squares
    // This loop assumes blockDim.x is a power of 2 for optimal performance
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Only the first thread in the block writes the final mean and variance
    if (threadIdx.x == 0) {
        float mean = s_sum[0] / spatial_size;
        float var = (s_sum_sq[0] / spatial_size) - (mean * mean);
        // Ensure variance is non-negative due to potential floating point inaccuracies
        var = fmaxf(0.0f, var); // Clamp variance to be at least 0

        means[nc_idx] = mean;
        vars[nc_idx] = var;
    }
}

// Kernel 2: Apply fused operations using pre-computed means and variances
// Each thread processes one element in the output tensor. A grid-stride loop ensures all elements are covered.
__global__ void fused_ops_kernel(const float* x, const float* multiplier,
                                 const float* means, const float* vars,
                                 float clamp_min, float clamp_max, float eps,
                                 float* out,
                                 int N, int C, int D, int H, int W) {
    int total_elements = N * C * D * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Grid-stride loop to ensure all elements are processed if total_elements > num_blocks * block_size
    while (idx < total_elements) {
        // Deconstruct global index to N, C, D, H, W indices
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int d_idx = (idx / (W * H)) % D;
        int c_idx = (idx / (W * H * D)) % C;
        int n_idx = idx / (W * H * D * C);

        // Get values from input tensors
        float x_val = x[idx];
        float mult_val = multiplier[c_idx]; // multiplier is (C, 1, 1, 1), so index by C
        float mean_val = means[n_idx * C + c_idx]; // means/vars are (N, C)
        float var_val = vars[n_idx * C + c_idx];

        // Apply the sequence of fused operations:
        // 1. x = x * self.multiplier
        float val_after_mult1 = x_val * mult_val;
        // 2. x = self.instance_norm(x)
        float normalized_val = (val_after_mult1 - mean_val) / sqrtf(var_val + eps);
        // 3. x = torch.clamp(x, self.clamp_min, self.clamp_max)
        float clamped_val = fmaxf(clamp_min, fminf(clamp_max, normalized_val));
        // 4. x = x * self.multiplier
        float final_val = clamped_val * mult_val;

        // Store the result in the output tensor
        out[idx] = final_val;

        // Move to the next element in grid-stride
        idx += gridDim.x * blockDim.x;
    }
