    TORCH_CHECK(x.dim() == 5, "Input tensor 'x' must be 5-dimensional (N, C, D, H, W).");
    TORCH_CHECK(multiplier.dim() == 4, "Multiplier tensor must be 4-dimensional (C, 1, 1, 1).");
