import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Instance Normalization and division
fused_instance_norm_divide_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

// Define epsilon for InstanceNorm, matching PyTorch's default
const float INSTANCE_NORM_EPS = 1e-5;

// Helper macro for checking CUDA errors (for debugging purposes)
#define CUDA_CHECK(call)                                                               \
  do {                                                                                 \
    cudaError_t err = call;                                                            \
    if (err != cudaSuccess) {                                                          \
      fprintf(stderr, "CUDA error in %s:%d: %s\\n", __FILE__, __LINE__,                \
              cudaGetErrorString(err));                                                \
      exit(EXIT_FAILURE);                                                              \
    }                                                                                  \
  } while (0)

// Kernel to compute mean and variance for each (N, C) slice.
// Each thread block is responsible for one (N, C) slice.
// It performs a parallel reduction within the block using shared memory.
__global__ void instance_norm_mean_var_kernel(
    const float* x,
    float* mean_out,
    float* var_out,
    int N, int C, int H, int W
) {
    // Each block handles one (n, c) slice.
    // blockIdx.x maps directly to the linear index of the (n, c) slice.
    int nc_idx = blockIdx.x; 
    int n = nc_idx / C;
    int c = nc_idx % C;

    // Calculate the starting offset for the current (n, c) slice in the flattened tensor.
    // Use long long for slice_offset to prevent overflow for large tensors.
    long long slice_offset = (long long)(n * C + c) * H * W;
    int slice_size = H * W; // Number of elements in this (H, W) slice

    // Shared memory for parallel reduction within the block.
    // Max block size is 1024, but 256 is a common safe choice for shared memory usage.
    __shared__ float s_sum[256]; 
    __shared__ float s_sum_sq[256];

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Grid-stride loop for each thread to accumulate its partial sum and sum of squares
    // across the elements in its assigned (n, c) slice.
    for (int i = threadIdx.x; i < slice_size; i += blockDim.x) {
        float val = x[slice_offset + i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    // Store partial sums in shared memory and synchronize.
    s_sum[threadIdx.x] = thread_sum;
    s_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    // Perform parallel reduction in shared memory.
    // Assumes blockDim.x is a power of 2.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final mean and variance for this slice.
    if (threadIdx.x == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];

        float mean = total_sum / slice_size;
        // Calculate variance: E[X^2] - (E[X])^2
        float var = (total_sum_sq / slice_size) - (mean * mean);
        // Ensure variance is non-negative due to potential floating point inaccuracies
        if (var < 0.0f) var = 0.0f;

        mean_out[nc_idx] = mean;
        var_out[nc_idx] = var;
    }
}

// Kernel to perform normalization and division.
// Each thread processes one element of the output tensor.
__global__ void instance_norm_divide_kernel(
    const float* x,
    const float* mean,
    const float* var,
    float* out,
    float divide_by,
    int N, int C, int H, int W
) {
    // Calculate global linear index for the current element.
    // Use long long for idx to handle very large tensors.
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total_elements = (long long)N * C * H * W;

    if (idx < total_elements) {
        // Calculate n, c, h, w from the linear index.
        // Use long long for intermediate products to prevent overflow before division.
        long long elements_per_hw_slice = (long long)H * W;
        long long elements_per_c_slice = (long long)C * H * W;

        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / elements_per_hw_slice) % C;
        int n = idx / elements_per_c_slice; 

        // Linear index for (n, c) to fetch the pre-computed mean and variance.
        int nc_idx = n * C + c; 

        float current_mean = mean[nc_idx];
        float current_var = var[nc_idx];

        float val = x[idx];
        // Perform instance normalization: (value - mean) / sqrt(variance + epsilon)
        float normalized_val = (val - current_mean) / sqrtf(current_var + INSTANCE_NORM_EPS);
        // Perform the final division by the constant.
        out[idx] = normalized_val / divide_by;
    }
}

// C++ wrapper function to launch the CUDA kernels.
torch::Tensor fused_instance_norm_divide_cuda(torch::Tensor x, float divide_by) {
    // Input validation
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous."); // For simpler indexing
    TORCH_CHECK(x.dim() == 4, "Input tensor 'x' must be a 4D tensor (N, C, H, W).");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor 'x' must be of float32 type.");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    long long total_elements = (long long)N * C * H * W;
    int num_nc_slices = N * C; // Number of (N, C) slices for which mean/var are computed

    // Allocate output tensor on the GPU.
    auto out = torch::empty_like(x);

    // Allocate temporary buffers for mean and variance (N, C) on the GPU.
    auto mean_buffer = torch::empty({N, C}, x.options());
    auto var_buffer = torch::empty({N, C}, x.options());

    // --- Launch kernel to compute mean and variance ---
    // Each block processes one (N, C) slice.
    // The block size should be a power of 2 and <= 1024. 256 is a good general choice.
    const int mean_var_block_size = 256; 
    const int mean_var_num_blocks = num_nc_slices; 

    instance_norm_mean_var_kernel<<<mean_var_num_blocks, mean_var_block_size>>>(
        x.data_ptr<float>(),
        mean_buffer.data_ptr<float>(),
        var_buffer.data_ptr<float>(),
        N, C, H, W
    );
    CUDA_CHECK(cudaGetLastError()); // Check for errors after kernel launch

    // --- Launch kernel to perform normalization and division ---
    // Each thread processes one element of the output tensor.
    const int norm_divide_block_size = 256;
    // Calculate number of blocks needed to cover all elements.
    const int norm_divide_num_blocks = (total_elements + norm_divide_block_size - 1) / norm_divide_block_size;

    instance_norm_divide_kernel<<<norm_divide_num_blocks, norm_divide_block_size>>>(
        x.data_ptr<float>(),
        mean_buffer.data_ptr<float>(),
        var_buffer.data_ptr<float>(),
        out.data_ptr<float>(),
        divide_by,
        N, C, H, W
    );
    CUDA_CHECK(cudaGetLastError()); // Check for errors after kernel launch

    return out;
}
"""

# C++ header for the custom CUDA function
fused_instance_norm_divide_cpp_source = (
    "torch::Tensor fused_instance_norm_divide_cuda(torch::Tensor x, float divide_by);"
