#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For erff, sqrtf

// GELU approximation using erf, consistent with PyTorch's default GELU
__device__ float gelu_approx(float x) {
    const float M_SQRT1_2 = 0.70710678118f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

// LeakyReLU function
__device__ float leaky_relu_func(float x, float negative_slope) {
    return (x > 0) ? x : (x * negative_slope);
