        val = leaky_relu_func(val, negative_slope);

        // Apply LeakyReLU (second instance)
        val = leaky_relu_func(val, negative_slope);

        // Apply GELU (first instance)
        val = gelu_approx(val);

        // Apply GELU (second instance)
        val = gelu_approx(val);

        out[idx] = val;
    }
}

