import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused HardSwish and ReLU
fused_hardswish_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // Not strictly needed for this specific logic, but good practice for math ops

// CUDA kernel for fused HardSwish and ReLU
// This kernel implements ReLU(HardSwish(x))
// HardSwish(x) = x * min(max(x + 3, 0), 6) / 6
// ReLU(y) = max(0, y)
//
// Combined logic:
// If x < 0: HardSwish(x) is <= 0. ReLU(HardSwish(x)) = 0.
// If 0 <= x <= 3: HardSwish(x) = x * (x + 3) / 6. This is >= 0. ReLU(HardSwish(x)) = x * (x + 3) / 6.
// If x > 3: HardSwish(x) = x. This is > 0. ReLU(HardSwish(x)) = x.
__global__ void fused_hardswish_relu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        float result;
        if (val < 0.0f) {
            result = 0.0f;
        } else if (val <= 3.0f) { // This covers 0 <= val <= 3
            result = val * (val + 3.0f) / 6.0f;
        } else { // val > 3.0f
            result = val;
        }
        out[idx] = result;
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor fused_hardswish_relu_cuda(torch::Tensor input) {
    // Ensure input is on CUDA and contiguous
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be of float32 type.");

    // Create an output tensor of the same shape and type as the input
