#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For __erff and M_SQRT1_2F

// Define M_SQRT1_2F if not already defined by the compiler/headers
#ifndef M_SQRT1_2F
#define M_SQRT1_2F 0.707106781186547524400844362104849039f // 1/sqrt(2)
#endif

__global__ void gelu_adaptive_avg_pool2d_kernel(const float* input, float* output,
                                                int N, int C, int H, int W) {
    // Each block processes one (batch, channel) pair.
    // blockIdx.x ranges from 0 to N*C - 1.
    int b_c_idx = blockIdx.x;
    int batch_idx = b_c_idx / C;
    int channel_idx = b_c_idx % C;

    // Calculate the starting index for the current (batch, channel) slice
    // Input tensor layout: (N, C, H, W)
    const int slice_offset = batch_idx * C * H * W + channel_idx * H * W;
    const int num_elements_per_channel = H * W;

    // Shared memory for reduction within the block
    extern __shared__ float sdata[]; // sdata size = blockDim.x * sizeof(float)

    float thread_sum = 0.0f;
    // Each thread processes a subset of H*W elements for its (batch, channel) slice
    for (int i = threadIdx.x; i < num_elements_per_channel; i += blockDim.x) {
        float val = input[slice_offset + i];
        // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
        // __erff is the float version of erf from CUDA math library
        float gelu_val = 0.5f * val * (1.0f + __erff(val * M_SQRT1_2F));
        thread_sum += gelu_val;
    }

    sdata[threadIdx.x] = thread_sum;
    __syncthreads();

    // Perform reduction in shared memory
    // This is a standard parallel reduction pattern
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final result for this (batch, channel) pair
    if (threadIdx.x == 0) {
        output[b_c_idx] = sdata[0] / num_elements_per_channel;
    }
}

