# Define the custom CUDA kernel for fused post-matmul operations
fused_post_matmul_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel to perform: (input / 2) -> sum along dim 1 -> multiply by scaling_factor
__global__ void fused_post_matmul_ops_kernel(
    const float* in_ptr,
    float* out_ptr,
    int N, // batch_size
    int M, // hidden_size
    float scaling_factor) {

    // Each block processes one row (batch_size dimension)
    int row_idx = blockIdx.x;

    if (row_idx < N) {
        // Shared memory for reduction within the block.
        // We use a fixed block_size of 256, so shared memory size is fixed.
        __shared__ float s_sum[256]; 

        float thread_partial_sum = 0.0f;
        // Each thread processes multiple elements in the row
        for (int col_idx = threadIdx.x; col_idx < M; col_idx += blockDim.x) {
            thread_partial_sum += in_ptr[row_idx * M + col_idx] / 2.0f;
        }

        // Store thread's partial sum in shared memory
        s_sum[threadIdx.x] = thread_partial_sum;
        __syncthreads();

        // Parallel reduction in shared memory
        // This loop assumes blockDim.x is a power of 2
        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            }
            __syncthreads();
        }

        // The first thread writes the final sum for the row, scaled
        if (threadIdx.x == 0) {
            out_ptr[row_idx] = s_sum[0] * scaling_factor;
        }
    }
}

