    int M = matmul_output.size(1); // hidden_size

    // Create output tensor of shape (N, 1) with the same options (device, dtype) as input
    auto out = torch::empty({N, 1}, matmul_output.options());

    const int block_size = 256; // A common block size for reduction
    const int num_blocks = N;   // One block per row

    fused_post_matmul_ops_kernel<<<num_blocks, block_size>>>(
