import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GELU and GroupNorm
gelu_group_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For erff, fmaxf, rsqrtf

// Define M_SQRT1_2F if not already defined (e.g., in math.h or cmath)
#ifndef M_SQRT1_2F
#define M_SQRT1_2F 0.7071067811865475f
#endif

// Kernel 1: Compute mean and inverse standard deviation for GELU-activated values per group
// Each block handles one (batch_idx, group_idx) pair.
__global__ void gelu_group_norm_mean_var_kernel(
    const float* x_ptr,
    float* mean_out_ptr,
    float* rstd_out_ptr,
    int N, int C, int H, int W,
    int num_groups, float epsilon) {

    int batch_group_idx = blockIdx.x; // Global index for (batch_idx, group_idx)
    int n = batch_group_idx / num_groups; // Batch index
    int g = batch_group_idx % num_groups; // Group index

    int channels_per_group = C / num_groups;
    // Number of elements in one group for one batch item (channels_per_group * H * W)
    int group_elements_per_batch = channels_per_group * H * W;

    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Each thread processes multiple elements within its assigned group
    for (int i = threadIdx.x; i < group_elements_per_batch; i += blockDim.x) {
        int c_in_group = i / (H * W); // Channel index within the group
        int hw_idx = i % (H * W);     // H*W index
        int h = hw_idx / W;
        int w = hw_idx % W;

        int c = g * channels_per_group + c_in_group; // Global channel index

        // Calculate linear index for x_ptr
        int x_idx = n * C * H * W + c * H * W + h * W + w;

        float val = x_ptr[x_idx];
        // Apply GELU to the value before accumulating for mean/variance
        // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
        val = 0.5f * val * (1.0f + erff(val * M_SQRT1_2F));

        sum_val += val;
        sum_sq_val += val * val;
    }

    // Shared memory for block-wise reduction
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    s_sum[threadIdx.x] = sum_val;
    s_sum_sq[threadIdx.x] = sum_sq_val;
    __syncthreads();

    // Perform reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mean = s_sum[0] / group_elements_per_batch;
        float var = s_sum_sq[0] / group_elements_per_batch - mean * mean;
        var = fmaxf(0.0f, var); // Ensure variance is non-negative
        float rstd = rsqrtf(var + epsilon); // Reciprocal standard deviation

        mean_out_ptr[batch_group_idx] = mean;
        rstd_out_ptr[batch_group_idx] = rstd;
    }
}

// Kernel 2: Apply GELU and GroupNorm using pre-computed mean and rstd
// Each thread processes one output element.
__global__ void gelu_group_norm_apply_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* rstd_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int N, int C, int H, int W,
    int num_groups) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        int n = idx / (C * H * W);
        int c_hw_idx = idx % (C * H * W);
        int c = c_hw_idx / (H * W);
        // int hw_idx = c_hw_idx % (H * W); // Not needed for this kernel

        int channels_per_group = C / num_groups;
        int g = c / channels_per_group; // Group index

        int batch_group_idx = n * num_groups + g;

        float current_mean = mean_ptr[batch_group_idx];
        float current_rstd = rstd_ptr[batch_group_idx];
        float current_gamma = gamma_ptr[c]; // Gamma is per channel
        float current_beta = beta_ptr[c];   // Beta is per channel

        float val = x_ptr[idx];
        // Apply GELU to the value (this is the second part of the fusion)
        val = 0.5f * val * (1.0f + erff(val * M_SQRT1_2F));

        float normalized_val = (val - current_mean) * current_rstd;
        out_ptr[idx] = current_gamma * normalized_val + current_beta;
    }
}

// C++ wrapper function to launch the CUDA kernels
torch::Tensor gelu_group_norm_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
