#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Helper function to get linear index for a 5D tensor
// Assumes row-major order (PyTorch default for contiguous tensors)
__device__ size_t get_input_idx(int n, int c, int d, int h, int w,
                                int N_stride, int C_stride, int D_stride, int H_stride, int W_stride) {
    return (size_t)n * N_stride + (size_t)c * C_stride +
           (size_t)d * D_stride + (size_t)h * H_stride +
           (size_t)w * W_stride;
}

// Helper function to get linear index for a 4D tensor (output of min_and_softmax)
// Assumes row-major order (PyTorch default for contiguous tensors)
__device__ size_t get_output_idx(int n, int c, int s1, int s2,
                                 int N_stride, int C_stride, int S1_stride, int S2_stride) {
    return (size_t)n * N_stride + (size_t)c * C_stride +
           (size_t)s1 * S1_stride + (size_t)s2 * S2_stride;
}


__global__ void min_and_softmax_kernel(
    const float* input,
    float* output,
    int N, int C, int D, int H, int W, // Input dimensions (from conv output)
    int min_dim_idx, // The dimension index (2, 3, or 4) to apply min reduction along
    int out_s1_size, int out_s2_size, // Sizes of the two spatial dims remaining after min
    int N_in_stride, int C_in_stride, int D_in_stride, int H_in_stride, int W_in_stride, // Input strides
    int N_out_stride, int C_out_stride, int S1_out_stride, int S2_out_stride // Output strides
) {
    // Each block processes one (n, s1, s2) slice.
    // (n, s1, s2) represents a unique combination of batch, and the two spatial dimensions
    // that are *not* reduced by the min operation.
    int block_flat_idx = blockIdx.x;

    int n_idx = block_flat_idx / (out_s1_size * out_s2_size);
    int s_flat_idx = block_flat_idx % (out_s1_size * out_s2_size);
    int s1_idx = s_flat_idx / out_s2_size;
    int s2_idx = s_flat_idx % out_s2_size;

    // Shared memory for intermediate min_values for the current (n, s1, s2) slice
    // and for max_val and sum_exp needed for softmax.
    // s_data[0...C-1] stores min_vals for each channel 'c'.
    // s_data[C] stores the maximum value across channels for the current slice (for softmax stability).
    // s_data[C+1] stores the sum of exponentials across channels for the current slice.
    extern __shared__ float s_data[];

    // Phase 1: Compute min_values for each channel 'c' for the current (n, s1, s2) slice.
    // Each thread computes the min for its assigned channel(s).
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        float current_min = FLT_MAX; // Initialize with max float value

        // Determine which original spatial dimensions s1_idx and s2_idx correspond to,
        // and which one is min_dim_idx.
        // d_val_fixed, h_val_fixed, w_val_fixed hold the values for the spatial dimensions
        // that are *not* being reduced by the min operation.
        int d_val_fixed = 0, h_val_fixed = 0, w_val_fixed = 0;

        if (min_dim_idx == 2) { // Original D dimension is reduced, H and W are fixed
            h_val_fixed = s1_idx;
            w_val_fixed = s2_idx;
        } else if (min_dim_idx == 3) { // Original H dimension is reduced, D and W are fixed
            d_val_fixed = s1_idx;
            w_val_fixed = s2_idx;
        } else { // Original W dimension is reduced, D and H are fixed
            d_val_fixed = s1_idx;
            h_val_fixed = s2_idx;
        }

        // Iterate over the dimension specified by min_dim_idx to find the minimum value.
        int min_dim_size = (min_dim_idx == 2) ? D : ((min_dim_idx == 3) ? H : W);
        for (int k = 0; k < min_dim_size; ++k) {
            int current_d = d_val_fixed;
            int current_h = h_val_fixed;
            int current_w = w_val_fixed;

            if (min_dim_idx == 2) current_d = k;
            else if (min_dim_idx == 3) current_h = k;
            else if (min_dim_idx == 4) current_w = k;

            size_t input_offset = get_input_idx(n_idx, c_idx, current_d, current_h, current_w,
                                                N_in_stride, C_in_stride, D_in_stride, H_in_stride, W_in_stride);
            current_min = fminf(current_min, input[input_offset]);
        }
        s_data[c_idx] = current_min; // Store the computed min value in shared memory
    }
    __syncthreads(); // All threads must finish computing their min_vals before proceeding.

    // Phase 2: Compute max_val and sum_exp for softmax across channels 'C'.
    // This is a reduction within the block. For simplicity and small C, thread 0 performs this.
    float max_val = -FLT_MAX;
    if (threadIdx.x == 0) {
        for (int c_idx = 0; c_idx < C; ++c_idx) {
            max_val = fmaxf(max_val, s_data[c_idx]);
        }
        s_data[C] = max_val; // Store max_val in shared memory for other threads
    }
    __syncthreads();
    max_val = s_data[C]; // All threads get the computed max_val

    float sum_exp = 0.0f;
    if (threadIdx.x == 0) {
        for (int c_idx = 0; c_idx < C; ++c_idx) {
            sum_exp += expf(s_data[c_idx] - max_val);
        }
        s_data[C+1] = sum_exp; // Store sum_exp in shared memory
    }
    __syncthreads();
    sum_exp = s_data[C+1]; // All threads get the computed sum_exp

    // Phase 3: Final softmax calculation and write results to global memory.
    for (int c_idx = threadIdx.x; c_idx < C; c_idx += blockDim.x) {
        float val = s_data[c_idx];
        float softmax_val = expf(val - max_val) / sum_exp;

        size_t output_offset = get_output_idx(n_idx, c_idx, s1_idx, s2_idx,
                                              N_out_stride, C_out_stride, S1_out_stride, S2_out_stride);
        output[output_offset] = softmax_val;
    }
