# This kernel combines `x * self.scale` and `self.bn(x)` into a single GPU kernel launch.
scale_and_batchnorm1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For rsqrtf

// CUDA kernel to perform fused element-wise scaling and BatchNorm1d
__global__ void scale_and_batchnorm1d_kernel(
    const float* input,         // Input tensor from the linear layer (N, C)
    const float* scale,         // Scale parameter (C,)
    const float* bn_weight,     // BatchNorm weight (gamma) (C,)
    const float* bn_bias,       // BatchNorm bias (beta) (C,)
    const float* running_mean,  // BatchNorm running mean (C,)
    const float* running_var,   // BatchNorm running variance (C,)
    float eps,                  // BatchNorm epsilon
    float* output,              // Output tensor (N, C)
    int N,                      // Batch size
    int C                       // Number of features (out_features)
) {
    // Calculate global index for the current thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure index is within bounds of the total number of elements
    if (idx < N * C) {
        // Decompose global index into batch (n) and feature (c) indices
        int n = idx / C; // Batch index
        int c = idx % C; // Feature index

        // Load values for the current element and its corresponding feature parameters
        float val = input[idx];
        float scale_val = scale[c];
        float bn_weight_val = bn_weight[c];
        float bn_bias_val = bn_bias[c];
        float mean_val = running_mean[c];
        float var_val = running_var[c];

        // Step 1: Fused element-wise multiplication with `self.scale`
        float scaled_input = val * scale_val;

        // Step 2: Batch Normalization (inference mode)
        // Calculate inverse standard deviation: 1 / sqrt(variance + epsilon)
        float inv_std = rsqrtf(var_val + eps); 

        // Normalize the scaled input
        float normalized_val = (scaled_input - mean_val) * inv_std;

        // Apply BatchNorm weight (gamma) and bias (beta)
        output[idx] = bn_weight_val * normalized_val + bn_bias_val;
    }
}

