        # The linear layer (GEMM) is kept as a standard PyTorch operator,
        # as it's highly optimized by cuBLAS/cuDNN.
        self.gemm = nn.Linear(in_features, out_features)

        # The scale parameter is still a learnable parameter
        self.scale = nn.Parameter(torch.randn(scale_shape))

