            x = self.bn(x)
        else:
            x = self.fused_scale_bn_op(
                x,
                self.scale,
                self.bn.weight,
                self.bn.bias,
                self.bn.running_mean,
                self.bn.running_var,
                self.bn.eps
            )
        return x

