import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h> // For block-level reductions
#include <float.h> // For FLT_MAX

namespace cg = cooperative_groups;

// Helper for block-wide reduction (max) using cooperative_groups
// This function finds the maximum value among all threads in a block
// and broadcasts it to all threads in that block.
__device__ float blockReduceMax(cg::thread_block block, float val) {
    for (int offset = block.size() / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, block.shfl_down(val, offset));
    }
    return block.shfl(val, 0); // Broadcast the final max value to all threads in the block
}

// Helper for block-wide reduction (sum) using cooperative_groups
// This function sums values from all threads in a block
// and broadcasts the total sum to all threads in that block.
__device__ float blockReduceSum(cg::thread_block block, float val) {
    for (int offset = block.size() / 2; offset > 0; offset /= 2) {
        val += block.shfl_down(val, offset);
    }
    return block.shfl(val, 0); // Broadcast the final sum to all threads in the block
}

__global__ void fused_softmax_bias_scale_sigmoid_kernel(
    const float* x_ptr,
    const float* bias_ptr,
    float scaling_factor,
    float* out_ptr,
    int N, int C, int H, int W) {

    // Get the current thread block handle for cooperative groups operations
    cg::thread_block block = cg::this_thread_block();

    // Each block processes one (n, h, w) slice of the input tensor.
    // The total number of such slices is N * H * W.
    int nhw_idx = blockIdx.x;

    // Calculate the batch (n), height (h), and width (w) indices for this slice
    int n = nhw_idx / (H * W);
    int hw = nhw_idx % (H * W);
    int h = hw / W;
    int w = hw % W;

    // Step 1: Find max_val for numerical stability across channels for this (n, h, w) slice.
    // Each thread iterates over a subset of channels (C) to find its local maximum.
    float thread_max_val = -FLT_MAX; // Initialize with smallest possible float value
    for (int c = threadIdx.x; c < C; c += block.size()) {
        thread_max_val = fmaxf(thread_max_val, x_ptr[n * C * H * W + c * H * W + h * W + w]);
    }
    // Reduce the thread-local max values to get the block-wide max_val
    float max_val = blockReduceMax(block, thread_max_val);
    // No explicit __syncthreads() needed here as blockReduceMax ensures synchronization
    // and broadcasts the result to all threads in the block.

    // Step 2: Calculate exp_sum for this (n, h, w) slice.
    // Each thread iterates over a subset of channels to sum its exponential values.
    float thread_exp_sum = 0.0f;
    for (int c = threadIdx.x; c < C; c += block.size()) {
        thread_exp_sum += expf(x_ptr[n * C * H * W + c * H * W + h * W + w] - max_val);
    }
    // Reduce the thread-local exp_sum values to get the block-wide exp_sum
    float exp_sum = blockReduceSum(block, thread_exp_sum);
    // No explicit __syncthreads() needed here as blockReduceSum ensures synchronization
    // and broadcasts the result to all threads in the block.

    // Step 3: Compute the final output for each channel in this (n, h, w) slice.
    // Each thread iterates over a subset of channels to compute its final output value.
    for (int c = threadIdx.x; c < C; c += block.size()) {
        // Get the input value for the current (n, c, h, w)
        float val = x_ptr[n * C * H * W + c * H * W + h * W + w];

        // Softmax calculation
        float softmax_val = expf(val - max_val) / exp_sum;

        // Add bias (bias_ptr[c] correctly accesses the channel-specific bias as bias is (C,1,1))
        float biased_val = softmax_val + bias_ptr[c];

        // Scale the result
        float scaled_val = biased_val * scaling_factor;

        // Apply sigmoid: 1 / (1 + exp(-x))
        out_ptr[n * C * H * W + c * H * W + h * W + w] = 1.0f / (1.0f + expf(-scaled_val));
    }
}

// PyTorch C++ wrapper for the CUDA kernel
torch::Tensor fused_softmax_bias_scale_sigmoid_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float scaling_factor) {

    // Input validation to ensure tensors are on CUDA, have correct dimensions, and are contiguous
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(bias.is_cuda(), "Bias tensor 'bias' must be a CUDA tensor.");
    TORCH_CHECK(x.dim() == 4, "Input tensor 'x' must be a 4D tensor (N, C, H, W).");
    TORCH_CHECK(bias.dim() == 3, "Bias tensor 'bias' must be a 3D tensor (C, 1, 1).");
    TORCH_CHECK(bias.size(1) == 1 && bias.size(2) == 1, "Bias tensor 'bias' must have dimensions (C, 1, 1).");
    TORCH_CHECK(x.size(1) == bias.size(0), "Channel dimension of 'x' and 'bias' must match.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(bias.is_contiguous(), "Bias tensor 'bias' must be contiguous.");

    // Extract dimensions
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Create an output tensor with the same shape and type as x
    auto out = torch::empty_like(x);

    // Define kernel launch parameters
    const int block_size = 256; // A common block size, typically a multiple of warp size (32)
    // Each block processes one (N, H, W) slice, iterating over C channels.
    // So, the number of blocks is N * H * W.
    const int num_blocks = N * H * W;

    // Launch the CUDA kernel
    fused_softmax_bias_scale_sigmoid_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),          // Pointer to input tensor x data
        bias.data_ptr<float>(),       // Pointer to bias tensor data
        scaling_factor,               // Scaling factor
        out.data_ptr<float>(),        // Pointer to output tensor data
        N, C, H, W                    // Dimensions
    );

    // Check for any CUDA errors that might have occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
