import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source for fused element-wise addition, Layer Normalization, and GELU activation.
# This kernel processes a 5D tensor (N, C, D, H, W) where LayerNorm is applied over the last (W) dimension.
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, tanhf, M_PI_F

// GELU approximation function for device code
__device__ float gelu_approx(float x) {
    // Using the standard approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    // M_PI_F is typically defined in <cmath> or <math.h> for device code.
    return 0.5f * x * (1.0f + tanhf(sqrtf(2.0f / M_PI_F) * (x + 0.044715f * x * x * x)));
}

__global__ void add_scalar_layernorm_gelu_kernel(
    const float* x_ptr,
    float sum_weight_val,
    const float* ln_weight_ptr,
    const float* ln_bias_ptr,
    float eps,
    float* out_ptr,
    int N, int C, int D, int H, int W
) {
    // Each block processes one (n, c, d, h) group, normalizing along the W dimension.
    // The grid size is N * C * D * H, and block size is W.
    int group_idx = blockIdx.x;

    // Calculate the N, C, D, H indices for the current group
    int n = group_idx / (C * D * H);
    int rem = group_idx % (C * D * H);
    int c = rem / (D * H);
    rem = rem % (D * H);
    int d = rem / H;
    int h = rem % H;

    // Calculate the starting offset for the current W-dimension slice
    long long x_offset = (long long)n * C * D * H * W + (long long)c * D * H * W + (long long)d * H * W + (long long)h * W;

    // Shared memory for reduction (size W, which is blockDim.x)
    extern __shared__ float s_data[];

    // Step 1: Add sum_weight and load data into shared memory
    float val_plus_sum_weight = x_ptr[x_offset + threadIdx.x] + sum_weight_val;
    s_data[threadIdx.x] = val_plus_sum_weight;
    __syncthreads(); // Ensure all data is loaded into shared memory before reduction

    // Step 2: Parallel reduction to find the sum for mean calculation
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Thread 0 calculates the mean and broadcasts it
    float mean;
    if (threadIdx.x == 0) {
        mean = s_data[0] / W;
    }
    __syncthreads(); // Ensure mean is visible to all threads in the block

    // Step 3: Calculate squared difference from mean and store in shared memory
    s_data[threadIdx.x] = (val_plus_sum_weight - mean) * (val_plus_sum_weight - mean);
    __syncthreads(); // Ensure all squared differences are computed before reduction

    // Step 4: Parallel reduction to find the sum of squared differences for variance calculation
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // Thread 0 calculates the variance and broadcasts it
    float var;
    if (threadIdx.x == 0) {
        var = s_data[0] / W;
    }
    __syncthreads(); // Ensure var is visible to all threads in the block

    // Step 5: Final calculation: normalize, apply affine parameters, and apply GELU
    // rsqrtf is typically faster than 1.0f / sqrtf for inverse square root
    float std_dev = rsqrtf(var + eps); 
    float norm_val = (val_plus_sum_weight - mean) * std_dev;

    // Apply LayerNorm affine parameters (weight and bias)
    // ln_weight_ptr and ln_bias_ptr are 1D tensors of size W (out_channels).
    // threadIdx.x directly maps to the index along the W dimension.
    float weighted_norm_val = norm_val * ln_weight_ptr[threadIdx.x] + ln_bias_ptr[threadIdx.x];

    // Apply GELU activation and store the result
    out_ptr[x_offset + threadIdx.x] = gelu_approx(weighted_norm_val);
}

