    TORCH_CHECK(x.is_contiguous(), "Input tensor x must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor x must be float32.");
    TORCH_CHECK(x.dim() == 5, "Input tensor x must be 5-dimensional (N, C, D, H, W).");

    // sum_weight validation
    TORCH_CHECK(sum_weight_tensor.numel() == 1, "sum_weight must be a scalar tensor.");
    TORCH_CHECK(sum_weight_tensor.is_cuda(), "sum_weight must be a CUDA tensor."); 
    TORCH_CHECK(sum_weight_tensor.dtype() == torch::kFloat32, "sum_weight must be float32.");

    // LayerNorm parameters validation
    TORCH_CHECK(ln_weight.is_cuda() && ln_weight.is_contiguous() && ln_weight.dtype() == torch::kFloat32, "ln_weight must be a contiguous float32 CUDA tensor.");
    TORCH_CHECK(ln_bias.is_cuda() && ln_bias.is_contiguous() && ln_bias.dtype() == torch::kFloat32, "ln_bias must be a contiguous float32 CUDA tensor.");

    // Extract dimensions from the input tensor
    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4); // This is the dimension over which LayerNorm is applied

    // Validate LayerNorm parameter sizes against the W dimension
    TORCH_CHECK(ln_weight.numel() == W, "ln_weight size must match the W dimension of x.");
    TORCH_CHECK(ln_bias.numel() == W, "ln_bias size must match the W dimension of x.");

    // Create an empty output tensor with the same properties as x
    auto out = torch::empty_like(x);

    // Extract the scalar value from sum_weight_tensor
    float sum_weight_val = sum_weight_tensor.item<float>();

    // Kernel launch configuration
    int num_groups = N * C * D * H; // Each group corresponds to one (N, C, D, H) slice
    int block_size = W;             // Each block processes the W dimension of a group

    // Ensure block_size is within CUDA limits (typically 1 to 1024 threads per block)
    TORCH_CHECK(block_size > 0 && block_size <= 1024, "Block size (W dimension) must be between 1 and 1024.");

    // Calculate shared memory size required for reduction (W floats)
    size_t smem_size = block_size * sizeof(float);

    // Launch the CUDA kernel
    add_scalar_layernorm_gelu_kernel<<<num_groups, block_size, smem_size>>>(
        x.data_ptr<float>(),
        sum_weight_val,
        ln_weight.data_ptr<float>(),
        ln_bias.data_ptr<float>(),
        (float)eps, // Cast epsilon to float for device computation
        out.data_ptr<float>(),
        N, C, D, H, W
    );
    // Check for CUDA errors after kernel launch
    torch::cuda::check_error(cudaGetLastError());

    return out;
}
"""

# C++ header for the inline CUDA function
fused_kernel_cpp_source = (
    "torch::Tensor add_scalar_layernorm_gelu_cuda("
    "torch::Tensor x, torch::Tensor sum_weight_tensor, torch::Tensor ln_weight, torch::Tensor ln_bias, double eps);"
)

# Compile the inline CUDA code using torch.utils.cpp_extension.load_inline
