    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization and fast math flags for CUDA compiler
)


class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution, followed by a fused
    element-wise sum, layer normalization, and GELU activation, then average pooling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, sum_weight, norm_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)

        # sum_weight is a scalar parameter. Ensure it's on the CUDA device.
        self.sum_weight = nn.Parameter(torch.tensor(sum_weight, dtype=torch.float32).cuda())

        # LayerNorm's weight and bias are now managed by the custom kernel.
        # We define them as parameters here so they are trainable and part of the model's state_dict.
        # The original LayerNorm had normalized_shape=(out_channels,).
        # So its weight and bias would be 1D tensors of size 'out_channels'.
        # norm_shape[0] corresponds to 'out_channels' in this context.
        self.ln_weight = nn.Parameter(torch.ones(norm_shape[0], dtype=torch.float32).cuda()) 
        self.ln_bias = nn.Parameter(torch.zeros(norm_shape[0], dtype=torch.float32).cuda())
        self.ln_eps = 1e-5 # Default epsilon for LayerNorm, matching PyTorch's default.

        self.avg_pool = nn.AvgPool3d(kernel_size=pool_kernel_size)
        self.fused_ops = fused_ops # Reference to the compiled custom CUDA operations

        # Initialize LayerNorm parameters similar to PyTorch's nn.LayerNorm defaults.
        # PyTorch's LayerNorm initializes weight to 1 and bias to 0.
        nn.init.ones_(self.ln_weight)
        nn.init.zeros_(self.ln_bias)


    def forward(self, x):
        # Step 1: 3D Transposed Convolution
        x = self.conv_transpose(x)

        # Step 2: Fused operation: (x + self.sum_weight) -> LayerNorm -> GELU
        # This replaces the separate addition, LayerNorm, and GELU calls with a single custom kernel.
        x = self.fused_ops.add_scalar_layernorm_gelu_cuda(
            x, self.sum_weight, self.ln_weight, self.ln_bias, self.ln_eps
        )

        # Step 3: 3D Average Pooling
        x = self.avg_pool(x)
        return x

