#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf, fminf

// CUDA kernel for fused ReLU and HardSwish
// Computes: output = max(0, input) * clamp((max(0, input) + 3) / 6, 0, 1)
__global__ void relu_hardswish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];

        // Step 1: Apply ReLU (max(0, x))
        float x_relu = fmaxf(0.0f, x);

        // Step 2: Apply HardSwish formula to x_relu
        // HardSwish is x * clamp((x + 3) / 6, 0, 1)
        // Here, x is x_relu
        float val = (x_relu + 3.0f) / 6.0f;
        float clamped_val = fmaxf(0.0f, fminf(1.0f, val)); // clamp(val, 0, 1)

        output[idx] = x_relu * clamped_val;
    }
}

