import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused LayerNorm, GELU, and Scaling
fused_layernorm_gelu_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrt, tanh

// GELU approximation (standard PyTorch GELU)
// 0.5 * x * (1 + tanh(sqrt(2 / pi) * (x + 0.044715 * x^3)))
__device__ float gelu_activation(float x) {
    const float M_SQRT2_PI = 0.7978845608028654f; // sqrt(2 / pi)
    const float CUBIC_TERM_COEFF = 0.044715f;
    float x_cubed = x * x * x;
    float tanh_arg = M_SQRT2_PI * (x + CUBIC_TERM_COEFF * x_cubed);
    return 0.5f * x * (1.0f + tanhf(tanh_arg));
}

// Kernel 1: Compute Mean and Variance for LayerNorm
// Each block processes one (B, C, D, H) slice.
// Threads within the block compute partial sums and then reduce them using shared memory.
__global__ void fused_layernorm_gelu_scale_mean_var_kernel(
    const float* x_ptr,
    float* mean_ptr,
    float* rstd_ptr,
    int B, int C, int D, int H, int W,
    float eps) {

    // blockIdx.x maps to the slice index (b, c, d, h)
    int slice_idx = blockIdx.x;

    // Calculate b, c, d, h from slice_idx
    int b = slice_idx / (C * D * H);
    int c = (slice_idx / (D * H)) % C;
    int d = (slice_idx / H) % D;
    int h = slice_idx % H;

    // Accumulators for sum and sum of squares for the current thread
    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Grid-stride loop within the block to process all W elements
    // Each thread processes multiple elements if W > blockDim.x
    for (int w = threadIdx.x; w < W; w += blockDim.x) {
        int x_idx = b * (C * D * H * W) + c * (D * H * W) + d * (H * W) + h * W + w;
        float val = x_ptr[x_idx];
        sum_val += val;
        sum_sq_val += val * val;
    }

    // Shared memory for block-wise reduction
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    // Store partial sums in shared memory
    s_sum[threadIdx.x] = sum_val;
    s_sum_sq[threadIdx.x] = sum_sq_val;
    __syncthreads();

    // Perform parallel reduction within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Only the first thread in the block writes the final mean and rstd
    if (threadIdx.x == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];

        float mean = total_sum / W;
        float var = total_sum_sq / W - mean * mean;
        if (var < 0) var = 0; // Handle potential floating point inaccuracies

        mean_ptr[slice_idx] = mean;
        rstd_ptr[slice_idx] = rsqrtf(var + eps); // Reciprocal standard deviation
    }
}

// Kernel 2: Apply normalization, GELU activation, and scaling
// Each thread processes one element of the output tensor.
__global__ void fused_layernorm_gelu_scale_apply_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* rstd_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int B, int C, int D, int H, int W,
    float scaling_factor) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * C * D * H * W;

    if (idx < total_elements) {
        // Calculate b, c, d, h, w from global index
        int b = idx / (C * D * H * W);
        int c = (idx / (D * H * W)) % C;
        int d = (idx / (H * W)) % D;
        int h = (idx / W) % H;
        int w = idx % W;

        // Index for mean and rstd (per slice)
        int slice_idx = b * (C * D * H) + c * (D * H) + d * H + h;

        float val = x_ptr[idx];
        float mean = mean_ptr[slice_idx];
        float rstd = rstd_ptr[slice_idx];

        // Gamma and beta are applied element-wise along the normalized dimension (W)
        float gamma = gamma_ptr[w]; 
        float beta = beta_ptr[w];

        // 1. Layer Normalization
        float normalized_val = (val - mean) * rstd;
        float scaled_shifted_val = normalized_val * gamma + beta;

        // 2. GELU Activation
        float gelu_val = gelu_activation(scaled_shifted_val);

        // 3. Scaling
        out_ptr[idx] = gelu_val * scaling_factor;
    }
}

// C++ wrapper function to launch CUDA kernels
torch::Tensor fused_layernorm_gelu_scale_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    float scaling_factor) {

    // Input validation
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
    TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(gamma.dtype() == torch::kFloat32, "gamma must be float32");
    TORCH_CHECK(beta.dtype() == torch::kFloat32, "beta must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be a 5D tensor (B, C, D, H, W)");
    TORCH_CHECK(gamma.dim() == 1 && gamma.size(0) == x.size(4), "gamma must be 1D and match x's last dimension (W)");
    TORCH_CHECK(beta.dim() == 1 && beta.size(0) == x.size(4), "beta must be 1D and match x's last dimension (W)");


    // Get dimensions
    int B = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4); // Dimension to normalize over

    // Output tensor
    auto out = torch::empty_like(x);

    // Intermediate tensors for mean and reciprocal standard deviation (rstd)
    // These are per-slice (B, C, D, H)
    auto mean = torch::empty({B, C, D, H}, x.options());
    auto rstd = torch::empty({B, C, D, H}, x.options());

    // Kernel 1: Compute Mean and Variance
    int num_slices = B * C * D * H;
    const int mean_var_block_size = 256; // A common block size for reduction
    int mean_var_num_blocks = num_slices; // One block per slice
    // Shared memory size for mean_var_kernel: 2 * blockDim.x * sizeof(float) for sum and sum_sq
    size_t mean_var_shmem_size = 2 * mean_var_block_size * sizeof(float);

    fused_layernorm_gelu_scale_mean_var_kernel<<<mean_var_num_blocks, mean_var_block_size, mean_var_shmem_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        B, C, D, H, W,
        eps
    );

    // Kernel 2: Apply normalization, GELU, and scaling
    int total_elements = B * C * D * H * W;
    const int apply_block_size = 256; // A common block size for element-wise operations
    int apply_num_blocks = (total_elements + apply_block_size - 1) / apply_block_size;

    fused_layernorm_gelu_scale_apply_kernel<<<apply_num_blocks, apply_block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W,
        scaling_factor
    );

    return out;
}
"""

fused_layernorm_gelu_scale_cpp_source = (
    "torch::Tensor fused_layernorm_gelu_scale_cuda("
    "torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps, float scaling_factor);"
)

# Compile the inline CUDA code
fused_layernorm_gelu_scale = load_inline(
    name="fused_layernorm_gelu_scale",
    cpp_sources=fused_layernorm_gelu_scale_cpp_source,
