from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused clamp (min) and division
clamp_and_divide_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf

// CUDA kernel for fused clamp (min) and division
__global__ void clamp_and_divide_kernel(const float* input, float* output, float min_value, float divisor, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        val = fmaxf(val, min_value); // Apply clamp(min=min_value)
        output[idx] = val / divisor; // Apply division
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor clamp_and_divide_cuda(torch::Tensor input, float min_value, float divisor) {
    // Ensure input is a float tensor and on CUDA
