    int nc_idx = blockIdx.x;
    int n = nc_idx / C;
    int c = nc_idx % C;

    long spatial_size = (long)D * H * W;

    // Calculate sum for the current (n, c) slice
    float local_sum = 0.0f;
    long base_offset_x = n * x_stride_n + c * x_stride_c;

