// CUDA kernel for row-wise sum
__global__ void row_sum_kernel(const float* input, float* output, int rows, int cols) {
    // Each block processes one row
    int row_idx = blockIdx.x;

    if (row_idx < rows) {
        // Pointer to the start of the current row
        const float* row_ptr = input + row_idx * cols;

        // Shared memory for reduction
        // Dynamically allocated shared memory, size specified at kernel launch
        extern __shared__ float s_data[]; 

        // Each thread loads and sums a portion of the row
        float thread_sum = 0.0f;
        for (int col_idx = threadIdx.x; col_idx < cols; col_idx += blockDim.x) {
            thread_sum += row_ptr[col_idx];
        }
        s_data[threadIdx.x] = thread_sum;
        __syncthreads();

        // Perform reduction in shared memory
        // This assumes blockDim.x is a power of 2 for efficient reduction
        for (int s = blockDim.x / 2; s > 0; s /= 2) {
            if (threadIdx.x < s) {
                s_data[threadIdx.x] += s_data[threadIdx.x + s];
            }
            __syncthreads();
        }

        // The first thread writes the final sum for this row to global memory
        if (threadIdx.x == 0) {
            output[row_idx] = s_data[0];
        }
    }
}

