# Define the custom CUDA kernel for fused Dropout and Softmax
dropout_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <curand_kernel.h> // For random number generation
#include <float.h>         // For FLT_MAX

#define NEG_INF -FLT_MAX

// CUDA kernel to perform fused Dropout and Softmax
// Each block processes one row (batch item).
// Threads within a block cooperate to compute max, sum, and normalize.
__global__ void dropout_softmax_kernel_impl(
    const float* input_ptr,
    float* temp_dropout_output_ptr, // Intermediate buffer for dropout output
    float* output_ptr,
    int batch_size,
    int out_features,
    float dropout_p,
    bool training,
    unsigned long long seed,
    unsigned long long offset)
{
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Ensure block processes a valid batch item
    if (batch_idx >= batch_size) {
        return;
    }

    // Dynamically allocated shared memory for reduction operations (max and sum)
    extern __shared__ float s_data[]; 
    curandState_t rand_state;

    // Initialize curand state for each thread if in training mode
    if (training) {
        // A unique seed for each thread is generated based on a global seed,
        // the current batch index, thread index, and an additional offset.
        curand_init(seed, batch_idx * block_size + tid + offset, 0, &rand_state);
    }

    // --- Pass 1: Apply dropout and find the maximum value in the row ---
    // Each thread processes multiple elements if out_features > block_size
    float thread_max_val = NEG_INF;
    for (int j = tid; j < out_features; j += block_size) {
        float val = input_ptr[batch_idx * out_features + j];
        if (training) {
            float rand_val = curand_uniform(&rand_state);
            if (rand_val < dropout_p) {
                val = NEG_INF; // Masked out by setting to a very small number
            } else {
                val /= (1.0f - dropout_p); // Scale up
            }
        }
        // Store the dropout-applied value in a temporary global memory buffer
        temp_dropout_output_ptr[batch_idx * out_features + j] = val;
        thread_max_val = fmaxf(thread_max_val, val); // Update thread's local max
    }

    // Store thread's local max in shared memory for block-wide reduction
    s_data[tid] = thread_max_val;
    __syncthreads();

    // Parallel reduction (max) within the block
    // This loop finds the maximum value across all threads in the block
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] = fmaxf(s_data[tid], s_data[tid + s]);
        }
        __syncthreads();
    }
    float row_max_val = s_data[0]; // The maximum value for the current row

    // --- Pass 2: Compute the sum of exponentials for the row ---
    // (using the numerically stable `exp(val - max_val)` form)
    float thread_exp_sum = 0.0f;
    for (int j = tid; j < out_features; j += block_size) {
        float val = temp_dropout_output_ptr[batch_idx * out_features + j];
        thread_exp_sum += expf(val - row_max_val); // Sum of exponentials
    }

    // Store thread's local sum in shared memory for block-wide reduction
    s_data[tid] = thread_exp_sum;
    __syncthreads();

    // Parallel reduction (sum) within the block
    // This loop finds the sum of exponentials across all threads in the block
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float row_exp_sum = s_data[0]; // The sum of exponentials for the current row

    // --- Pass 3: Normalize the values to get the final softmax probabilities ---
    for (int j = tid; j < out_features; j += block_size) {
        float val = temp_dropout_output_ptr[batch_idx * out_features + j];
        output_ptr[batch_idx * out_features + j] = expf(val - row_max_val) / row_exp_sum;
    }
}

// Python-callable wrapper for the CUDA kernel
torch::Tensor dropout_softmax_cuda(
    torch::Tensor input,
    float dropout_p,
    bool training)
{
    // Input tensor must be on CUDA and be a floating point type
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(input.is_floating_point(), "Input tensor must be a floating point type.");

