    int out_features = input.size(1);

    // Allocate output tensor on the same device as input
    auto output = torch::empty_like(input);

    // Allocate a temporary buffer for storing dropout-applied values
    // This avoids recomputing dropout and allows for multi-pass softmax within one kernel launch
    auto temp_dropout_output = torch::empty_like(input);

    // Kernel launch parameters
    const int BLOCK_SIZE = 256; // Number of threads per block
    const int NUM_BLOCKS = batch_size; // One block per row (batch item)

    // Calculate shared memory size required for reduction (BLOCK_SIZE floats)
    size_t shared_mem_size = BLOCK_SIZE * sizeof(float);

    // Generate a random seed and offset for CURAND.
    // These are used to initialize the per-thread random states.
    // For reproducibility, these could be fixed or derived from a global seed.
    unsigned long long seed = torch::randint(0, 1000000, {1}).item<long long>();
    unsigned long long offset = torch::randint(0, 1000000, {1}).item<long long>();

