        # Changed scale parameter shape to (out_channels,) for easier access in the custom CUDA kernel.
        # PyTorch's broadcasting will handle the multiplication correctly if it were (1, C, 1, 1, 1) or (C,).
        self.scale = nn.Parameter(torch.ones(out_channels)) 
