import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations: LeakyReLU, Add, Clamp, and GELU
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For erff, fmaxf, fminf

// GELU approximation using erf
__device__ float gelu_approx(float x) {
    // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
    return 0.5f * x * (1.0f + erff(x / sqrtf(2.0f)));
}

__global__ void fused_leaky_add_clamp_gelu_kernel(
    const float* input,
    const float* sum_tensor_ptr, // Flattened sum_tensor (C elements)
    float* output,
    int total_elements,
    int C, // Number of channels
    long channel_stride, // Stride for the channel dimension (D*H*W for NCDHW)
    float negative_slope,
    float min_val,
    float max_val) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        float val = input[idx];

        // 1. LeakyReLU
        val = (val > 0.0f) ? val : val * negative_slope;

        // 2. Add sum_tensor (broadcasting handled by indexing)
        // For an NCDHW tensor, the channel index 'c' for a linear index 'idx' is:
        // c = (idx / channel_stride) % C
        int c_idx = (idx / channel_stride) % C;
        val += sum_tensor_ptr[c_idx];

        // 3. Clamp
        val = fmaxf(min_val, fminf(max_val, val));

        // 4. GELU
        val = gelu_approx(val);

        output[idx] = val;
    }
}

torch::Tensor fused_leaky_add_clamp_gelu_cuda(
    torch::Tensor input,
    torch::Tensor sum_tensor,
    float negative_slope,
    float min_val,
    float max_val) {

    // Ensure input is contiguous for simpler linear indexing in the kernel.
    // This might involve a memory copy if the tensor is not already contiguous.
    input = input.contiguous();

    // sum_tensor is expected to be (C, 1, 1, 1). Squeeze it to (C,) for direct access.
    sum_tensor = sum_tensor.squeeze().contiguous();

    TORCH_CHECK(input.is_cuda(), "Input tensor must be a CUDA tensor.");
    TORCH_CHECK(sum_tensor.is_cuda(), "Sum tensor must be a CUDA tensor.");
    TORCH_CHECK(input.dim() == 5, "Input tensor must be 5D (NCDHW format).");
    TORCH_CHECK(sum_tensor.dim() == 1, "Sum tensor must be 1D after squeezing (shape C,).");
    TORCH_CHECK(input.size(1) == sum_tensor.size(0), "Channel dimension mismatch between input and sum_tensor.");

    auto output = torch::empty_like(input);

    int total_elements = input.numel();
    int C = input.size(1); // Number of channels

    // Calculate the stride for the channel dimension.
    // For a contiguous NCDHW tensor, input.stride(1) gives D*H*W.
    long channel_stride = input.stride(1);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_leaky_add_clamp_gelu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        sum_tensor.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elements,
        C,
        channel_stride,
        negative_slope,
        min_val,
        max_val);

    return output;
}
