import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Fused Subtract + HardSwish Kernel ---
# This kernel fuses the element-wise subtraction and the HardSwish activation function.
# HardSwish(x) = x * ReLU6(x + 3) / 6
# Fusing these two operations reduces memory bandwidth and kernel launch overhead.
subtract_hardswish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For logf, expf, tanhf, fminf, fmaxf

__global__ void subtract_hardswish_kernel(const float* input, float subtract_val, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] - subtract_val;
        // HardSwish: x * relu6(x + 3) / 6
        // relu6(y) = clamp(y, 0, 6)
        float clamped = fminf(fmaxf(val + 3.0f, 0.0f), 6.0f);
        output[idx] = val * clamped / 6.0f;
    }
}

torch::Tensor subtract_hardswish_cuda(torch::Tensor input, float subtract_val) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");

    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    subtract_hardswish_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        subtract_val,
        output.data_ptr<float>(),
        size
    );
    return output;
}
"""

subtract_hardswish_cpp_source = (
    "torch::Tensor subtract_hardswish_cuda(torch::Tensor input, float subtract_val);"
)

fused_subtract_hardswish = load_inline(
    name="fused_subtract_hardswish",
    cpp_sources=subtract_hardswish_cpp_source,
    cuda_sources=subtract_hardswish_source,
    functions=["subtract_hardswish_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

# --- Mish Activation Kernel ---
# This kernel implements the Mish activation function.
# Mish(x) = x * tanh(softplus(x))
# softplus(x) = log(1 + exp(x))
# Implementing it as a custom kernel avoids multiple PyTorch function calls and potential intermediate tensor allocations.
mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For logf, expf, tanhf

__global__ void mish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // softplus(x) = log(1 + exp(x))
        float softplus_x = logf(1.0f + expf(x));
        // tanh(x) = (exp(x) - exp(-x)) / (exp(x) + exp(-x))
        float tanh_softplus_x = tanhf(softplus_x);
        // Mish(x) = x * tanh(softplus(x))
        output[idx] = x * tanh_softplus_x;
    }
}

torch::Tensor mish_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");

    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    mish_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );
    return output;
}
