#include <algorithm> // For fmaxf/fminf

// CUDA kernel for fused operations:
// x = x + bias
// x = torch.clamp(x, min=0.0, max=1.0)
// x = x * scaling_factor
// x = torch.clamp(x, min=0.0, max=1.0)
// x = x / scaling_factor
__global__ void fused_post_conv_kernel(
    const float* x_ptr,
    const float* bias_ptr,
    float scaling_factor_val,
    float* out_ptr,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Decompose idx to N, C, H, W indices
        // W is the fastest changing dimension, then H, then C, then N
        // int w_idx = idx % W; // Not explicitly needed for bias access
        // int h_idx = (idx / W) % H; // Not explicitly needed for bias access
        int c_idx = (idx / (W * H)) % C; // Channel index for bias lookup
        // int n_idx = idx / (W * H * C); // Not explicitly needed for bias access

        float val = x_ptr[idx];
        // Bias is (C, 1, 1), so it's broadcasted across H, W, and N dimensions.
        // We only need the channel index to access the correct bias value.
        float bias_val = bias_ptr[c_idx];

        // Operation 1: Add bias
        val = val + bias_val;

        // Operation 2: Clamp [0.0, 1.0]
        val = fmaxf(0.0f, fminf(val, 1.0f));

        // Operation 3: Multiply by scaling_factor
        val = val * scaling_factor_val;

