        int n = idx / (H * W);
        int hw_idx = idx % (H * W);
        int h = hw_idx / W;
        int w = hw_idx % W;

        // Initialize min_val with the first channel's value for the current (n, h, w)
        // Input tensor is (N, C, H, W) and is assumed to be contiguous.
        // The linear index for input[n, c, h, w] is n * (C*H*W) + c * (H*W) + h * W + w
        float min_val = input[n * C * H * W + 0 * H * W + h * W + w];

