    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sum_sq[tid] += s_sum_sq[tid + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }
}

__global__ void fused_norm_add_mul_kernel(
    const float* x_ptr,
    const float* y_ptr,
    const float* gamma_ptr, // Corresponds to instance_norm.weight
    const float* beta_ptr,  // Corresponds to instance_norm.bias
    float* out_ptr,
    int batch_size,
    int out_features,
    float eps) {

    int batch_idx = blockIdx.x;

    // Guard against out-of-bounds batch indices
    if (batch_idx >= batch_size) {
        return;
    }

    // Pointers to the start of the current row for x, y, and output
    const float* x_row_start = x_ptr + batch_idx * out_features;
    const float* y_row_start = y_ptr + batch_idx * out_features;
    float* out_row_start = out_ptr + batch_idx * out_features;

    // Shared memory for reduction: first half for sum, second half for sum_sq
    extern __shared__ float s_data[];
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x; // Offset by blockDim.x to store sum_sq

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Each thread processes multiple elements if out_features > blockDim.x
    // This ensures all elements of the row are covered for mean/variance calculation
    for (int i = threadIdx.x; i < out_features; i += blockDim.x) {
        float val = x_row_start[i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    // Store thread-local sums into shared memory
    s_sum[threadIdx.x] = thread_sum;
    s_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads(); // Synchronize to ensure all thread-local sums are written to shared memory

    // Perform parallel reduction to get the total sum and sum of squares for the row
    reduce_sum_and_sum_sq(s_sum, s_sum_sq, threadIdx.x);

    // Only the first thread (threadIdx.x == 0) will have the final reduced values
    float row_sum = s_sum[0];
    float row_sum_sq = s_sum_sq[0];

    // Calculate mean and variance for the current row
    float mean = row_sum / out_features;
    // Variance calculation: E[X^2] - (E[X])^2
    float variance = (row_sum_sq / out_features) - (mean * mean);
    // Guard against negative variance due to floating point inaccuracies
    if (variance < 0.0f) variance = 0.0f;

    // Calculate inverse standard deviation
    float inv_std = rsqrtf(variance + eps); // 1 / sqrt(variance + eps)

    __syncthreads(); // Synchronize to ensure mean/variance/inv_std are computed before element-wise ops

    // Perform the final element-wise normalization, addition, and multiplication
    for (int i = threadIdx.x; i < out_features; i += blockDim.x) {
        float val_x = x_row_start[i];
        float val_y = y_row_start[i];
        float val_gamma = gamma_ptr[i]; // Gamma parameter for scaling
        float val_beta = beta_ptr[i];   // Beta parameter for shifting

        // LayerNorm-like normalization
        float x_norm = (val_x - mean) * inv_std;
        float x_scaled = val_gamma * x_norm + val_beta;

        // Addition and multiplication
        out_row_start[i] = (x_scaled + val_y) * val_y;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor fused_norm_add_mul_cuda(
    torch::Tensor x,
    torch::Tensor y,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps) {

    // Input tensor checks
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(y.is_cuda(), "y must be a CUDA tensor");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
    TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(y.is_contiguous(), "y must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(beta.is_contiguous(), "beta must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(y.dtype() == torch::kFloat32, "y must be float32");
    TORCH_CHECK(gamma.dtype() == torch::kFloat32, "gamma must be float32");
    TORCH_CHECK(beta.dtype() == torch::kFloat32, "beta must be float32");

    int batch_size = x.size(0);
    int out_features = x.size(1);

    TORCH_CHECK(y.size(0) == batch_size && y.size(1) == out_features, "y must have same shape as x");
    TORCH_CHECK(gamma.numel() == out_features, "gamma must have numel == out_features");
    TORCH_CHECK(beta.numel() == out_features, "beta must have numel == out_features");

    // Allocate output tensor
    auto out = torch::empty_like(x);

    // Kernel launch parameters
    const int block_size = 256; // A common block size for parallel reduction and element-wise ops
    const int num_blocks = batch_size; // One block per batch element (row)

    // Calculate shared memory size needed for sum and sum_sq arrays
    // Each array needs block_size * sizeof(float)
    size_t smem_size = 2 * block_size * sizeof(float);

    // Launch the CUDA kernel
    fused_norm_add_mul_kernel<<<num_blocks, block_size, smem_size>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        out_features,
        eps
    );

    // Check for CUDA errors
    CUDA_CHECK(cudaGetLastError());

    return out;
}
"""

fused_kernel_cpp_source = (
    "torch::Tensor fused_norm_add_mul_cuda("
    "torch::Tensor x, torch::Tensor y, torch::Tensor x_gamma, torch::Tensor x_beta, float eps);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_norm_add_mul",
    cpp_sources=fused_kernel_cpp_source,
    cuda_sources=fused_kernel_source,
    functions=["fused_norm_add_mul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Use fast math for CUDA operations
)


class ModelNew(nn.Module):
    """
    Optimized Model that performs a batch matrix multiplication,
    followed by a fused LayerNorm-like operation, summation, and multiplication.
    """
    def __init__(self, in_features, out_features, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.bmm = nn.Linear(in_features, out_features)

        # The original InstanceNorm2d(out_features, ...) with input (B,1,1,out_features)
        # would cause a RuntimeError. We interpret the intent as a LayerNorm-like operation
        # across the 'out_features' dimension for each batch element.
        # We use nn.LayerNorm to correctly obtain learnable affine parameters (weight/bias)
        # of shape (out_features,) which are then passed to our custom kernel as gamma and beta.
        self.norm_params = nn.LayerNorm(out_features, eps=eps)
        self.eps = eps # Store eps for the custom kernel
        self.fused_ops = fused_ops

    def forward(self, x, y):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_features).
            y (torch.Tensor): Input tensor of shape (batch_size, out_features).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_features).
        """
        # Step 1: Batch Matrix Multiplication (Linear layer)
        x = self.bmm(x)

        # Steps 2, 3, 4: Fused LayerNorm-like operation, addition, and multiplication
        # Replaces:
        # x = self.instance_norm(x.unsqueeze(1).unsqueeze(1)).squeeze(1).squeeze(1)
        # x = x + y
        # x = x * y
        x = self.fused_ops.fused_norm_add_mul_cuda(
            x, y, self.norm_params.weight, self.norm_params.bias, self.eps
        )
        return x

