# Define the custom CUDA kernel for fused element-wise operations
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf and expf

__global__ void fused_kernel(const float* conv_out, const float* scaling_factor, const float* bias, float* out,
                             int N, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * D * H * W;

    if (idx < total_elements) {
        // De-flatten index to get N, C, D, H, W indices
        // We only need 'c' (channel index) for broadcasting scaling_factor and bias
        int c = (idx / (W * H * D)) % C;

        // Access scaling_factor and bias using channel index 'c'
        // scaling_factor and bias are (C, 1, 1, 1), so we just need the 'c' index
        float s_factor = scaling_factor[c];
        float b_val = bias[c];

        float val = conv_out[idx];
        val = val * s_factor; // Equivalent to x * self.scaling_factor
        val = tanhf(val);     // Equivalent to torch.tanh(x)
        val = val * b_val;    // Equivalent to x * self.bias
        val = 1.0f / (1.0f + expf(-val)); // Equivalent to torch.sigmoid(x)

        out[idx] = val;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor conv_out, torch::Tensor scaling_factor, torch::Tensor bias) {
