    // If not contiguous, a contiguous copy is made.
    conv_out = conv_out.contiguous();
    scaling_factor = scaling_factor.contiguous();
    bias = bias.contiguous();

    // Get dimensions of conv_out (N, C, D, H, W)
    int N = conv_out.size(0);
    int C = conv_out.size(1);
    int D = conv_out.size(2);
    int H = conv_out.size(3);
    int W = conv_out.size(4);

    // Create output tensor with the same shape and type as conv_out
    auto out = torch::empty_like(conv_out);

    // Calculate grid and block dimensions for kernel launch
    int total_elements = N * C * D * H * W;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the fused CUDA kernel
    fused_kernel<<<num_blocks, block_size>>>(
        conv_out.data_ptr<float>(),
        scaling_factor.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W
    );

    // Check for any CUDA errors that might have occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
}
