import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations:
# 1. Simplification of `torch.min(x, min_value)` followed by `torch.clamp(x, min=min_value, max=max_value)`
#    As analyzed, if `min_value <= max_value`, this sequence effectively sets all elements of the tensor to `min_value`.
#    For the given `min_value=0.0` and `max_value=1.0`, this means all elements become `0.0`.
# 2. Application of `nn.Dropout` on the resulting tensor.
fused_min_clamp_dropout_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <curand_kernel.h> // For GPU random number generation

// Kernel for fused operation:
// - First, it implicitly sets all elements to 'min_val' (based on the simplification of min/clamp).
// - Then, it applies dropout to these 'min_val' elements.
__global__ void fused_min_clamp_dropout_kernel(float* out, int size, float min_val, float dropout_p, float scale, unsigned long long seed) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Initialize CURAND state for each thread
        curandState_t state;
        // Use a combination of seed, blockIdx.x, and threadIdx.x for better randomness across threads
        curand_init(seed, idx, 0, &state); 

        float rand_val = curand_uniform(&state); // Generate uniform float in [0, 1)

        if (rand_val < dropout_p) {
            out[idx] = 0.0f; // Drop out the value
        } else {
            out[idx] = min_val * scale; // Keep the value and apply dropout scaling
        }
    }
}

torch::Tensor fused_min_clamp_dropout_cuda(torch::Tensor input_template, float min_val, float dropout_p, unsigned long long seed) {
    // Ensure input_template is on CUDA and is a float tensor
    TORCH_CHECK(input_template.is_cuda(), "input_template must be a CUDA tensor");
    TORCH_CHECK(input_template.dtype() == torch::kFloat, "input_template must be of float type");
    TORCH_CHECK(input_template.is_contiguous(), "input_template must be contiguous for this kernel");

    auto out = torch::empty_like(input_template);
    auto size = input_template.numel();

    // Calculate scale factor for dropout: value / (1 - p)
    float scale = 1.0f;
    if (dropout_p == 1.0f) { 
        scale = 0.0f; // If dropout_p is 1.0, all elements are dropped (set to 0)
    } else if (dropout_p > 0.0f) { // Only apply scaling if dropout_p is between 0 and 1 (exclusive)
        scale = 1.0f / (1.0f - dropout_p);
    }
    // If dropout_p is 0.0, scale remains 1.0, which is correct (no dropout, no scaling)

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_min_clamp_dropout_kernel<<<num_blocks, block_size>>>(
        out.data_ptr<float>(), size, min_val, dropout_p, scale, seed
    );

    return out;
}
"""

fused_min_clamp_dropout_cpp_source = (
    "torch::Tensor fused_min_clamp_dropout_cuda(torch::Tensor input_template, float min_val, float dropout_p, unsigned long long seed);"
)

# Compile the inline CUDA code
fused_min_clamp_dropout = load_inline(
    name="fused_min_clamp_dropout",
