#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for fused element-wise addition and HardSwish activation
// The operation performed is: out = (conv_out + add_input) * hardswish(conv_out + add_input)
// where hardswish(x) = x * ReLU6(x + 3) / 6
__global__ void fused_add_hardswish_kernel(const float* conv_out, const float* add_input, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Step 1: Element-wise addition
        float val = conv_out[idx] + add_input[idx];

        // Step 2: Calculate ReLU6(val + 3)
        float relu6_arg = val + 3.0f;
        float relu6_val = fminf(fmaxf(0.0f, relu6_arg), 6.0f); // ReLU6(z) = min(max(0, z), 6)

        // Step 3: Calculate hardswish(val) = val * ReLU6(val + 3) / 6
        float hardswish_result = val * relu6_val / 6.0f;

        // Step 4: Final output: val * hardswish(val)
        out[idx] = val * hardswish_result;
    }
}

