import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations:
# torch.min(x, dim=1, keepdim=True)[0]
# torch.sum(x, dim=2, keepdim=True)
# torch.nn.functional.gelu(x)
# x + self.bias
#
# The kernel takes the output of conv_transpose (NCHW) and the bias (scalar)
# and produces the final output (N, 1, 1, W_out).
fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>   // For erff, sqrtf
#include <float.h>  // For FLT_MAX

// GELU activation function for CUDA, using the exact erf formulation
__device__ float gelu_cuda(float x) {
    const float M_SQRT1_2 = 0.70710678118f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

// CUDA kernel to perform fused min, sum, GELU, and bias addition
__global__ void fused_min_sum_gelu_add_kernel(
    const float* input,
    const float* bias_ptr,
    float* output,
    int N, int C_out, int H_out, int W_out) {

    // Each thread computes one element of the final output tensor,
    // which has shape (N, 1, 1, W_out).
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * W_out) {
        int n = idx / W_out;    // Batch index
        int w_out = idx % W_out; // Output width index

        float sum_of_mins_across_height = 0.0f;

        // Step 1: Iterate along H_out dimension
        // For each (n, w_out), we sum up the minimums found across channels for each h_out.
        for (int h_out = 0; h_out < H_out; ++h_out) {
            float min_val_across_channels = FLT_MAX; // Initialize with a very large float value

            // Step 2: Iterate along C_out dimension to find the minimum for current (n, h_out, w_out)
            for (int c = 0; c < C_out; ++c) {
                // Calculate linear index for input_tensor[n, c, h_out, w_out]
                // Assuming input is contiguous and in NCHW format
                int input_idx = n * (C_out * H_out * W_out) +
                                c * (H_out * W_out) +
                                h_out * W_out +
                                w_out;
                float current_val = input[input_idx];
                if (current_val < min_val_across_channels) {
                    min_val_across_channels = current_val;
                }
            }
            // Accumulate the minimum value found for this (n, h_out, w_out)
            sum_of_mins_across_height += min_val_across_channels;
        }

        // Step 3: Apply GELU activation to the accumulated sum
        float gelu_val = gelu_cuda(sum_of_mins_across_height);

        // Step 4: Add the bias (bias is (1,1,1), effectively a scalar)
        float final_val = gelu_val + bias_ptr[0];

        // Store the final result in the output tensor
        // Output is (N, 1, 1, W_out), so its linear index is n * W_out + w_out
        output[n * W_out + w_out] = final_val;
    }
}

// C++ wrapper function that launches the CUDA kernel
torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor bias) {
    // Input validation
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input tensor must be of float32 type.");
    TORCH_CHECK(input.dim() == 4, "Input tensor must be 4-dimensional (NCHW).");

    TORCH_CHECK(bias.is_cuda(), "Bias tensor must be on CUDA device.");
    TORCH_CHECK(bias.is_contiguous(), "Bias tensor must be contiguous.");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "Bias tensor must be of float32 type.");
    TORCH_CHECK(bias.numel() == 1, "Bias tensor must contain exactly one element (scalar).");

    int N = input.size(0);
    int C_out = input.size(1);
    int H_out = input.size(2);
    int W_out = input.size(3);

    // Allocate output tensor with shape (N, 1, 1, W_out) on the same device and dtype as input
    auto output = torch::zeros({N, 1, 1, W_out}, input.options());

    const int total_output_elements = N * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    fused_min_sum_gelu_add_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_out, H_out, W_out
    );

    // Check for any CUDA errors after kernel launch
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
"""

# C++ header for the wrapper function declaration
fused_ops_cpp_header = "torch::Tensor fused_ops_cuda(torch::Tensor input, torch::Tensor bias);"

# Compile the inline CUDA code
fused_ops_module = load_inline(
    name="fused_min_sum_gelu_add",
    cpp_sources=fused_ops_cpp_header,
    cuda_sources=fused_ops_cuda_source,
    functions=["fused_ops_cuda"],
    verbose=True,
    extra_cflags=["-O3"],  # Enable compiler optimizations for C++ host code
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Enable compiler optimizations and fast math for CUDA device code
)


