relu_add_bias_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for fused ReLU and element-wise bias addition
// This kernel takes the output of a convolution (N, C, H, W),
// applies ReLU, and then adds a channel-wise bias (C, 1, 1)
// by broadcasting it across N, H, and W dimensions.
__global__ void relu_add_bias_kernel(const float* conv_output, const float* bias, float* out,
                                     int N, int C, int H, int W) {
    // Calculate a unique linear index for each thread
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of elements in the output tensor
    long long total_elements = (long long)N * C * H * W;

    if (idx < total_elements) {
        // Calculate the channel index 'c' from the linear index 'idx'.
        // The bias is applied per channel, so we need to know which channel this element belongs to.
        // conv_output is (N, C, H, W)
        // idx = n * (C*H*W) + c * (H*W) + h * W + w
        // To get c: (idx / (H*W)) % C
        int c = (idx / ((long long)H * W)) % C; 

        float val = conv_output[idx];
        // The bias tensor is (C, 1, 1). When flattened, it's a 1D array of C elements.
        // Accessing bias[c] correctly retrieves the bias value for the current channel.
        float bias_val = bias[c]; 

        // Apply ReLU: if val > 0, keep val, else 0.
        // Then add the bias.
        if (val > 0) {
            out[idx] = val + bias_val;
        } else {
            out[idx] = bias_val; // If val <= 0, ReLU makes it 0, so result is just bias_val
        }
    }
}

