#include <cuda_runtime.h>
#include <cmath> // For erff

// GELU approximation used by PyTorch: 0.5 * x * (1 + erf(x / sqrt(2)))
__device__ float gelu_cuda(float x) {
    // M_SQRT1_2F is 1/sqrt(2) from cmath
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2F));
