        // 2. Minimum with 0.0
        val = fminf(val, 0.0f); // fminf for float

        // 3. GELU activation
        val = gelu_cuda(val);

        // 4. Multiply by mul_val
        val = val * mul_val;

        output[idx] = val;
    }
}

