import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused LogSumExp, custom activation, subtraction, and clamp
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max
#include <cmath>     // For log, exp, sigmoid
#include <float.h>   // For FLT_MAX

// Helper for sigmoid
__device__ float sigmoid_device(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_logsumexp_activation_sub_clamp_kernel(
    const float* input,
    float* output,
    float bias_val,
    int B, int C, int D, int H, int W,
    long stride_b, long stride_c, long stride_d, long stride_h, long stride_w
) {
    // Each thread computes one output element (b, 0, d, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements (B * 1 * D * H * W)
    int total_output_elements = B * D * H * W;

    if (idx < total_output_elements) {
        // Map idx back to (b, d, h, w) for the output tensor
        int w_out = idx % W;
        int h_out = (idx / W) % H;
        int d_out = (idx / (W * H)) % D;
        int b_out = idx / (W * H * D);

        // Calculate max_val for logsumexp
        float max_val = -FLT_MAX; // Initialize with smallest possible float
        for (int c = 0; c < C; ++c) {
            // Calculate input offset using strides
            size_t input_offset = b_out * stride_b + c * stride_c + d_out * stride_d + h_out * stride_h + w_out * stride_w;
            max_val = fmaxf(max_val, input[input_offset]);
        }

        // Calculate sum_exp for logsumexp
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            // Calculate input offset using strides
            size_t input_offset = b_out * stride_b + c * stride_c + d_out * stride_d + h_out * stride_h + w_out * stride_w;
            sum_exp += expf(input[input_offset] - max_val);
        }

        // LogSumExp result: log(sum(exp(x - max_val))) + max_val
        float logsumexp_val = logf(sum_exp) + max_val;

        // Apply custom activation: x * sigmoid(x + 3) / 6
        float activated_val = logsumexp_val * sigmoid_device(logsumexp_val + 3.0f) / 6.0f;

        // Subtract bias
        float subtracted_val = activated_val - bias_val;

        // Clamp result: clamp(x, min=-1, max=1)
        float clamped_val = fmaxf(-1.0f, fminf(1.0f, subtracted_val));

        // Store to output
        // Output shape: (B, 1, D, H, W)
        // Output is assumed to be contiguous.
        size_t output_offset = b_out * (D * H * W) + d_out * (H * W) + h_out * W + w_out;
        output[output_offset] = clamped_val;
    }
}

