import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused AvgPool2d + Sigmoid + Sum
# This kernel replaces the sequence: x = self.avg_pool(x); x = torch.sigmoid(x); x = torch.sum(x, dim=[1,2,3])
avg_sigmoid_sum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

// Helper function for sigmoid
__device__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void avg_sigmoid_sum_kernel(
    const float* conv_output,
    float* final_sums,
    int N, int C, int H_conv, int W_conv,
    int K, // pool_kernel_size
    int H_pool, int W_pool
) {
    // Each block processes one batch item 'n'.
    int n = blockIdx.x;

    if (n >= N) return;

    // Shared memory for block-wise reduction.
    // The size is determined at kernel launch time (smem_size).
    extern __shared__ float s_sum[];

    float thread_sum = 0.0f;

    // Iterate over all (c, h_pool, w_pool) elements for the current batch item 'n'.
    // Each thread processes a subset of these elements using a strided loop.
    int total_pool_elements_per_batch = C * H_pool * W_pool;

    for (int idx_in_batch = threadIdx.x; idx_in_batch < total_pool_elements_per_batch; idx_in_batch += blockDim.x) {
        // Decompose the flattened index back into (c, h_pool, w_pool)
        int c = idx_in_batch / (H_pool * W_pool);
        int rem_idx = idx_in_batch % (H_pool * W_W_pool);
        int h_pool = rem_idx / W_pool;
        int w_pool = rem_idx % W_pool;

        // Calculate the starting coordinates of the pooling window in conv_output
        int h_start = h_pool * K;
        int w_start = w_pool * K;

        float window_sum = 0.0f;
        // Loop over the KxK window to sum its elements
        for (int kh = 0; kh < K; ++kh) {
            for (int kw = 0; kw < K; ++kw) {
                int current_h = h_start + kh;
                int current_w = w_start + kw;

                // Calculate index in conv_output (NCHW format)
                // conv_output is (N, C, H_conv, W_conv)
                int conv_idx = n * (C * H_conv * W_conv) +
                               c * (H_conv * W_conv) +
                               current_h * W_conv +
                               current_w;
                window_sum += conv_output[conv_idx];
            }
        }

        // Calculate average, apply sigmoid, and add to thread's partial sum
        float avg_val = window_sum / (K * K);
        float sigmoid_val = sigmoid_f(avg_val);
        thread_sum += sigmoid_val;
    }

    // Store thread's partial sum to shared memory
    s_sum[threadIdx.x] = thread_sum;
    __syncthreads();

    // Perform reduction within the block using shared memory (tree reduction)
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final sum for this batch item
    if (threadIdx.x == 0) {
        final_sums[n] = s_sum[0];
    }
}

torch::Tensor avg_sigmoid_sum_cuda(torch::Tensor conv_output, int K) {
    // Input validation
    TORCH_CHECK(conv_output.is_cuda(), "conv_output must be a CUDA tensor");
    TORCH_CHECK(conv_output.dtype() == torch::kFloat, "conv_output must be of float type");
    TORCH_CHECK(conv_output.dim() == 4, "conv_output must be a 4D tensor (N, C, H, W)");

    int N = conv_output.size(0);
    int C = conv_output.size(1);
    int H_conv = conv_output.size(2);
    int W_conv = conv_output.size(3);

    // Calculate H_pool, W_pool based on PyTorch's AvgPool2d behavior
    // For AvgPool2d with kernel_size=K, stride=K, padding=0:
    // output_size = floor((input_size - kernel_size) / stride) + 1
    // This matches the behavior for the given example (382, 382) with K=4 -> (95, 95)
    int H_pool = (H_conv - K) / K + 1;
    int W_pool = (W_conv - K) / K + 1;

    // Create output tensor of shape (N,)
    auto final_sums = torch::zeros({N}, conv_output.options());

    const int block_size = 256; // Standard block size for CUDA kernels
    const int num_blocks = N;   // One block per batch item for efficient reduction

    // Calculate shared memory size for reduction. Each thread needs a float.
    size_t smem_size = block_size * sizeof(float);

    // Launch the kernel
    avg_sigmoid_sum_kernel<<<num_blocks, block_size, smem_size>>>(
        conv_output.data_ptr<float>(),
        final_sums.data_ptr<float>(),
        N, C, H_conv, W_conv, K, H_pool, W_pool
    );

    // Check for CUDA errors after kernel launch
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in avg_sigmoid_sum_kernel: ", cudaGetErrorString(err));
    }

    return final_sums;
}
