                        size_t input_idx = (size_t)n * C * D * H * W +
                                           (size_t)c * D * H * W +
                                           (size_t)input_d * H * W +
                                           (size_t)input_h * W +
                                           (size_t)input_w;

                        // Update the maximum value for the current channel's pooling window
                        max_val_for_channel = fmaxf(max_val_for_channel, input[input_idx]);
                    }
                }
            }
            // Add the maximum value found for this channel to the running sum
            current_sum += max_val_for_channel;
        }
        // Store the final sum in the output tensor
        output[idx] = current_sum;
    }
}

