import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Min Reduction and Bias Addition
# This kernel fuses the torch.min(x, dim=1, keepdim=True)[0] and x + self.bias operations.
# It performs a parallel reduction to find the minimum value for each row (batch element)
# and then adds this minimum value (broadcasted) to the bias tensor.
min_reduce_and_add_bias_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Helper for error checking (optional, but good practice)
#define CUDA_CHECK(call)                                                       \\
  do {                                                                         \\
    cudaError_t err = call;                                                    \\
    if (err != cudaSuccess) {                                                  \\
      fprintf(stderr, "CUDA error at %s:%d - %s\\n", __FILE__, __LINE__,        \\
              cudaGetErrorString(err));                                        \\
      exit(1);                                                                 \\
    }                                                                          \\
  } while (0)

__global__ void min_reduce_and_add_bias_kernel(
    const float* input_ptr,
    const float* bias_ptr,
    float* output_ptr,
    int batch_size,
    int out_features) {

    // Each block processes one row (batch_idx)
    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) {
        return;
    }

    // Shared memory for reduction. Size is blockDim.x * sizeof(float)
    // This will store partial minimums from threads within the block.
    extern __shared__ float s_min[];

    // Initialize thread_min_val with a very large value (FLT_MAX)
    float thread_min_val = FLT_MAX;

    // Each thread processes multiple elements if out_features > blockDim.x
    // This loop finds the minimum value for the elements assigned to the current thread.
    for (int i = threadIdx.x; i < out_features; i += blockDim.x) {
        thread_min_val = fminf(thread_min_val, input_ptr[batch_idx * out_features + i]);
    }
    s_min[threadIdx.x] = thread_min_val;
    __syncthreads(); // Synchronize threads to ensure all partial minimums are in shared memory

    // Perform parallel reduction in shared memory to find the overall minimum for the row.
    // This loop assumes blockDim.x is a power of 2 for efficient reduction.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_min[threadIdx.x] = fminf(s_min[threadIdx.x], s_min[threadIdx.x + s]);
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The minimum value for this row is now in s_min[0] (only thread 0 needs to read it,
    // but it's available to all threads after the final __syncthreads()).
    float row_min_val = s_min[0];

    // Now, perform the element-wise addition with bias.
    // Each thread computes multiple output elements if out_features > blockDim.x.
    // The output tensor has shape (batch_size, out_features, 1, 1).
    // The bias tensor has shape (1, out_features, 1, 1).
    // Linear indexing for output: batch_idx * out_features + c
    // Linear indexing for bias: c (since it's broadcast across batch and last two dims)
    for (int c = threadIdx.x; c < out_features; c += blockDim.x) {
        output_ptr[batch_idx * out_features + c] = row_min_val + bias_ptr[c];
    }
}

torch::Tensor min_reduce_and_add_bias_cuda(
    torch::Tensor input_tensor,
    torch::Tensor bias_tensor) {

    // Ensure inputs are on CUDA and are float32
    TORCH_CHECK(input_tensor.is_cuda(), "input_tensor must be a CUDA tensor");
    TORCH_CHECK(bias_tensor.is_cuda(), "bias_tensor must be a CUDA tensor");
    TORCH_CHECK(input_tensor.is_contiguous(), "input_tensor must be contiguous");
    TORCH_CHECK(bias_tensor.is_contiguous(), "bias_tensor must be contiguous");
    TORCH_CHECK(input_tensor.dtype() == torch::kFloat32, "input_tensor must be float32");
    TORCH_CHECK(bias_tensor.dtype() == torch::kFloat32, "bias_tensor must be float32");

    int batch_size = input_tensor.size(0);
    int out_features = input_tensor.size(1);

    // The output tensor will have shape (batch_size, out_features, 1, 1)
    auto output_tensor = torch::empty({batch_size, out_features, 1, 1}, input_tensor.options());

    // Configure kernel launch parameters
    const int block_size = 256; // Number of threads per block (should be a power of 2)
    const int num_blocks = batch_size; // One block per batch element (row)

    // Calculate shared memory size required for the reduction
    // Each thread needs space for its partial minimum.
    size_t smem_size = block_size * sizeof(float);

    // Launch the CUDA kernel
    min_reduce_and_add_bias_kernel<<<num_blocks, block_size, smem_size>>>(
        input_tensor.data_ptr<float>(),
        bias_tensor.data_ptr<float>(),
        output_tensor.data_ptr<float>(),
        batch_size,
        out_features);

    CUDA_CHECK(cudaGetLastError()); // Check for any errors during kernel launch

    return output_tensor;
}
"""

min_reduce_and_add_bias_cpp_source = (
    "torch::Tensor min_reduce_and_add_bias_cuda(torch::Tensor input_tensor, torch::Tensor bias_tensor);"
)

