# Define the custom CUDA kernel for fused BatchNorm2d and element-wise scaling
fused_bn_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For rsqrtf

// CUDA kernel for fused BatchNorm2d and element-wise scaling
// This kernel computes: output = ((input - running_mean) / sqrt(running_var + eps) * gamma + beta) * scaling_factor
__global__ void fused_bn_scale_kernel(
    const float* input,
    const float* gamma,
    const float* beta,
    const float* running_mean,
    const float* running_var,
    double eps,
    double scaling_factor,
    float* output,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Map flattened index back to (n, c, h, w) for NCHW format
        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / (W * H)) % C;
        // int n = idx / (C * H * W); // 'n' is not needed for parameter access as BN is per-channel

        float val = input[idx];

        // Get channel-specific parameters (gamma, beta, running_mean, running_var are 1D tensors of size C)
        float mean_c = running_mean[c];
        float var_c = running_var[c];
        float gamma_c = gamma[c];
        float beta_c = beta[c];

        // Compute inverse standard deviation using rsqrtf for performance
        float inv_std = rsqrtf(var_c + (float)eps);

        // Apply BatchNorm formula: (x - mean) / sqrt(var + eps) * gamma + beta
        float normalized_x = (val - mean_c) * inv_std;
        float bn_output = normalized_x * gamma_c + beta_c;

        // Apply the final scaling factor
        output[idx] = bn_output * (float)scaling_factor;
    }
}

