import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Hardtanh + Mean + Tanh fusion
hardtanh_mean_tanh_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf

// CUDA kernel for Hardtanh, Mean, and Tanh fusion
// Each block processes one (N, C) slice, performing reduction over H*W dimensions.
__global__ void hardtanh_mean_tanh_kernel(const float* input, float* output,
                                          int N, int C, int H, int W,
                                          float min_val, float max_val) {
    // Calculate the index for the current (N, C) slice
    // blockIdx.x ranges from 0 to N*C - 1
    int nc_idx = blockIdx.x;
    int n = nc_idx / C;
    int c = nc_idx % C;

    // Pointer to the start of the current (n, c) slice in the input tensor
    // Using long long for pointer arithmetic to prevent potential overflow with large dimensions
    const float* slice_start_ptr = input + (long long)n * C * H * W + (long long)c * H * W;

    // Shared memory for reduction within the block
    // Declared as extern to use dynamic shared memory, size passed at kernel launch
    extern __shared__ float s_sum[];

    float thread_sum = 0.0f;
    int total_elements_in_slice = H * W;

    // Each thread processes multiple elements in the slice
    for (int i = threadIdx.x; i < total_elements_in_slice; i += blockDim.x) {
        float val = slice_start_ptr[i];
        // Apply Hardtanh: max(min(val, max_val), min_val)
        val = fmaxf(fminf(val, max_val), min_val);
        thread_sum += val;
    }

    // Store thread's partial sum in shared memory
    s_sum[threadIdx.x] = thread_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    // Sum up partial sums from all threads in the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final result
    if (threadIdx.x == 0) {
        float mean_val = s_sum[0] / total_elements_in_slice;
        // Apply Tanh
        output[nc_idx] = tanhf(mean_val);
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor hardtanh_mean_tanh_cuda(torch::Tensor input, float min_val, float max_val) {
    // Ensure input is on CUDA, is float, and is contiguous
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input tensor must be of float32 type.");
    TORCH_CHECK(input.dim() == 4, "Input tensor must be 4-dimensional (N, C, H, W).");

    // Get dimensions
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    // Output tensor will have shape (N, C, 1, 1)
    // Use input.options() to ensure output tensor has same device and dtype
    auto output = torch::empty({N, C, 1, 1}, input.options());

    // Kernel launch parameters
    const int block_size = 256; // A common block size for reduction
    const int num_blocks = N * C; // One block per (N, C) slice

    // Calculate dynamic shared memory size required for the block_size threads
    size_t smem_size = block_size * sizeof(float);

    // Launch the kernel
    hardtanh_mean_tanh_kernel<<<num_blocks, block_size, smem_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        N, C, H, W, min_val, max_val
    );

    // Check for CUDA errors after kernel launch
    AT_CUDA_CHECK(cudaGetLastError());

    return output;
}
"""

hardtanh_mean_tanh_cpp_source = (
    "torch::Tensor hardtanh_mean_tanh_cuda(torch::Tensor input, float min_val, float max_val);"
