import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GroupNorm, element-wise scaling, and clamping
group_norm_fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

// Helper for grid-stride loop
#define CUDA_KERNEL_LOOP(i, n) \
  for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < (n); i += blockDim.x * gridDim.x)

// Kernel 1: Compute Mean and Variance for GroupNorm
// Each block computes mean and variance for one (batch, group)
__global__ void group_norm_mean_var_kernel(
    const float* x_ptr,
    float* mean_ptr,
    float* var_ptr,
    int N, int C, int H, int W,
    int num_groups) {

    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int C_per_group = C / num_groups;
    int group_elements = C_per_group * H * W;

    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Offset to the start of the current group's data
    size_t group_start_offset = (size_t)batch_idx * C * H * W + (size_t)group_idx * C_per_group * H * W;

    // Each thread processes a subset of elements within its assigned group
    for (int i = threadIdx.x; i < group_elements; i += blockDim.x) {
        float val = x_ptr[group_start_offset + i];
        sum_val += val;
        sum_sq_val += val * val;
    }

    // Shared memory for reduction
    extern __shared__ float sdata[]; // Size: 2 * blockDim.x * sizeof(float)
    sdata[threadIdx.x] = sum_val;
    sdata[threadIdx.x + blockDim.x] = sum_sq_val;
    __syncthreads();

    // Parallel reduction in shared memory
    // This assumes blockDim.x is a power of 2 for optimal performance
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
            sdata[threadIdx.x + blockDim.x] += sdata[threadIdx.x + blockDim.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float final_sum = sdata[0];
        float final_sum_sq = sdata[blockDim.x];

        float current_mean = final_sum / group_elements;
        float current_var = final_sum_sq / group_elements - current_mean * current_mean;

        mean_ptr[blockIdx.x] = current_mean;
        var_ptr[blockIdx.x] = current_var;
    }
}

// Kernel 2: Apply GroupNorm normalization, GroupNorm affine parameters, additional scaling, and clamping
__global__ void group_norm_scale_clamp_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* var_ptr,
    const float* weight_ptr,       // GroupNorm weight (C,)
    const float* bias_ptr,         // GroupNorm bias (C,)
    const float* scale_factor_ptr, // self.scale (C, 1, 1)
    float* out_ptr,
    int N, int C, int H, int W,
    int num_groups,
    float eps,
    float clamp_min,
    float clamp_max) {

    int C_per_group = C / num_groups;
    int total_elements = N * C * H * W;

    CUDA_KERNEL_LOOP(idx, total_elements) {
        // De-linearize index to (n, c, h, w)
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int c_idx = (idx / (W * H)) % C;
        int n_idx = idx / (C * H * W);

        // Get group index
        int group_idx = c_idx / C_per_group;
        int batch_group_idx = n_idx * num_groups + group_idx;

        float current_mean = mean_ptr[batch_group_idx];
        float current_var = var_ptr[batch_group_idx];

        float val = x_ptr[idx];

        // GroupNorm normalization: (x - mean) / sqrt(variance + eps)
        val = (val - current_mean) / sqrtf(current_var + eps);

        // Apply GroupNorm weight and bias: val * weight + bias
        val = val * weight_ptr[c_idx] + bias_ptr[c_idx];

        // Apply additional scale factor: val * self.scale
        // self.scale is (C, 1, 1), so it broadcasts across H and W.
        // We access it using c_idx.
        val = val * scale_factor_ptr[c_idx];

        // Apply clamp: max(clamp_min, min(clamp_max, val))
        val = fmaxf(clamp_min, fminf(clamp_max, val));

        out_ptr[idx] = val;
    }
}
"""

# C++ wrapper for the CUDA kernels
group_norm_fused_cpp_source = """
torch::Tensor group_norm_scale_clamp_cuda(
    torch::Tensor x,
    torch::Tensor weight,
