    auto out = torch::empty_like(x);

    // Allocate mean and variance tensors on CUDA
    // Shape: (N, num_groups)
    auto mean = torch::empty({N, num_groups}, x.options());
    auto var = torch::empty({N, num_groups}, x.options());

    // Kernel 1: Compute Mean and Variance
    const int THREADS_PER_BLOCK_MEAN_VAR = 256; // Standard block size
    const int NUM_BLOCKS_MEAN_VAR = N * num_groups;
    // Shared memory size for mean/var kernel: 2 * THREADS_PER_BLOCK_MEAN_VAR * sizeof(float)
    size_t shmem_size_mean_var = 2 * THREADS_PER_BLOCK_MEAN_VAR * sizeof(float);

    group_norm_mean_var_kernel<<<NUM_BLOCKS_MEAN_VAR, THREADS_PER_BLOCK_MEAN_VAR, shmem_size_mean_var>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, H, W,
        num_groups);

    // Kernel 2: Apply GroupNorm, Scale, Clamp
    const int THREADS_PER_BLOCK_FUSED = 256; // Standard block size
    const int NUM_BLOCKS_FUSED = (N * C * H * W + THREADS_PER_BLOCK_FUSED - 1) / THREADS_PER_BLOCK_FUSED;

    group_norm_scale_clamp_kernel<<<NUM_BLOCKS_FUSED, THREADS_PER_BLOCK_FUSED>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale_factor.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W,
        num_groups,
        eps,
        clamp_min,
        clamp_max);

    return out;
}
"""

# Compile the inline CUDA code
group_norm_fused = load_inline(
    name="group_norm_fused",
    cpp_sources=group_norm_fused_cpp_source,
