import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel source for fused operations
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for error checking
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error in %s (%s:%d): %s\\n", #call, __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(EXIT_FAILURE); \\
        } \\
    } while (0)

// Fused Forward Kernel
// Computes: out = (((y + bias) + y) * y) + y
// Where the 'y' terms in the additions and multiplication (after the first y+bias)
// are treated as if they were detached (i.e., original_x in the PyTorch code).
__global__ void fused_forward_kernel(const float* y_ptr, const float* bias_ptr, float* out_ptr,
                                    int N, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C * D * H * W) {
        // Calculate channel index for bias lookup
        // y is (N, C, D, H, W)
        // bias is (C, 1, 1, 1) -> effectively a 1D array of C elements
        int c_idx = (idx / (D * H * W)) % C;

        float y_val = y_ptr[idx];
        float bias_val = bias_ptr[c_idx]; // Bias is effectively 1D array indexed by channel

        float temp1 = y_val + bias_val; // x + self.bias
        float temp2 = temp1 + y_val;    // (x + self.bias) + original_x
        float temp3 = temp2 * y_val;    // ((x + self.bias) + original_x) * original_x
        out_ptr[idx] = temp3 + y_val;   // (((x + self.bias) + original_x) * original_x) + original_x
    }
}

// Fused Backward Kernel
// Computes gradients for y and bias based on the forward pass and the detach() semantics.
// The original PyTorch code used `original_x = x.clone().detach()`.
// This means that for the operations `x = x + original_x`, `x = x * original_x`, `x = x + original_x`,
// `original_x` acts as a constant during backpropagation.
// Let `y` be the output of `conv_transpose` and `b` be `self.bias`.
// The forward pass is `f(y, b) = (((y + b) + y_detached) * y_detached) + y_detached`.
// The gradient of `f` with respect to `y` and `b` is derived as follows:
// Let `z1 = y + b`
// Let `z2 = z1 + y_detached`
// Let `z3 = z2 * y_detached`
// Let `z4 = z3 + y_detached` (final output)
//
// dL/dz4 = grad_output
// dL/dz3 = dL/dz4 * (d(z4)/dz3) = grad_output * 1
// dL/dz2 = dL/dz3 * (d(z3)/dz2) = (grad_output * 1) * y_detached
// dL/dz1 = dL/dz2 * (d(z2)/dz1) = (grad_output * y_detached) * 1
//
// dL/dy = dL/dz1 * (d(z1)/dy) = (grad_output * y_detached) * 1 = grad_output * y_detached
// dL/db = dL/dz1 * (d(z1)/db) = (grad_output * y_detached) * 1 = grad_output * y_detached
//
// So, `grad_y = grad_output * y_val` and `grad_bias = grad_output * y_val`.
__global__ void fused_backward_kernel(const float* grad_output_ptr, const float* y_ptr,
                                        float* grad_y_ptr, float* grad_bias_ptr,
                                        int N, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C * D * H * W) {
        int c_idx = (idx / (D * H * W)) % C;

        float grad_out_val = grad_output_ptr[idx];
        float y_val = y_ptr[idx]; // Value of y from forward pass, used for chain rule

        // dL/dy = grad_output * y_val
        grad_y_ptr[idx] = grad_out_val * y_val;

        // dL/dbias = grad_output * y_val (needs atomic add as multiple threads write to the same bias element)
        // grad_bias is initialized to zeros before launching this kernel
        atomicAdd(&grad_bias_ptr[c_idx], grad_out_val * y_val);
    }
}

// C++ wrapper for forward
torch::Tensor fused_forward_cuda(torch::Tensor y, torch::Tensor bias) {
    TORCH_CHECK(y.is_cuda(), "y must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(y.dim() == 5, "y must be 5D (N, C, D, H, W)");
    TORCH_CHECK(bias.dim() == 4, "bias must be 4D (C, 1, 1, 1)");

    int N = y.size(0);
    int C = y.size(1);
    int D = y.size(2);
    int H = y.size(3);
    int W = y.size(4);

    auto out = torch::zeros_like(y);

    const int block_size = 256;
    const int num_elements = N * C * D * H * W;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_forward_kernel<<<num_blocks, block_size>>>(
        y.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(),
        N, C, D, H, W
    );
    CUDA_CHECK(cudaGetLastError());
    return out;
}

// C++ wrapper for backward
std::vector<torch::Tensor> fused_backward_cuda(torch::Tensor grad_output, torch::Tensor y, torch::Tensor bias) {
    TORCH_CHECK(grad_output.is_cuda(), "grad_output must be a CUDA tensor");
    TORCH_CHECK(y.is_cuda(), "y must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    int N = y.size(0);
    int C = y.size(1);
    int D = y.size(2);
    int H = y.size(3);
    int W = y.size(4);

    auto grad_y = torch::zeros_like(y);
    // grad_bias needs to be initialized to zeros before atomic adds
    auto grad_bias = torch::zeros_like(bias);

    const int block_size = 256;
    const int num_elements = N * C * D * H * W;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_backward_kernel<<<num_blocks, block_size>>>(
        grad_output.data_ptr<float>(), y.data_ptr<float>(),
        grad_y.data_ptr<float>(), grad_bias.data_ptr<float>(),
        N, C, D, H, W
    );
    CUDA_CHECK(cudaGetLastError());
    return {grad_y, grad_bias};
}
"""

fused_cpp_source = """
torch::Tensor fused_forward_cuda(torch::Tensor y, torch::Tensor bias);
std::vector<torch::Tensor> fused_backward_cuda(torch::Tensor grad_output, torch::Tensor y, torch::Tensor bias);
"""

# Compile the inline CUDA code for fused operations
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_kernel_source,
    functions=["fused_forward_cuda", "fused_backward_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


# Define a custom autograd.Function to integrate the fused CUDA kernels
class FusedResidualAddMul(torch.autograd.Function):
    @staticmethod
    def forward(ctx, y, bias):
        # Save y and bias for the backward pass
        ctx.save_for_backward(y, bias)
        output = fused_ops.fused_forward_cuda(y, bias)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        y, bias = ctx.saved_tensors
        # Ensure grad_output is contiguous for kernel access
        grad_y, grad_bias = fused_ops.fused_backward_cuda(grad_output.contiguous(), y, bias)
        return grad_y, grad_bias


class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution, followed by a fused
