import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, expf
#include <algorithm> // For fmaxf

// Helper for sigmoid
__device__ __forceinline__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// Kernel 1: Compute Mean and Variance for GroupNorm
// Each block handles one (N, G) pair.
// Threads within a block perform a parallel reduction over C_per_group channels.
__global__ void compute_mean_var_kernel(
    const float* x,
    float* mean_out,
    float* var_out,
    int N, int C, int num_groups, int C_per_group, float eps) {

    // Each block handles one (N, G) pair
    int n = blockIdx.y; // Batch index
    int g = blockIdx.x; // Group index

    if (n >= N || g >= num_groups) return;

    float sum_val = 0.0f;
    float sum_sq_val = 0.0f;

    // Each thread processes a subset of C_per_group channels
    for (int c_local = threadIdx.x; c_local < C_per_group; c_local += blockDim.x) {
        int c_global = g * C_per_group + c_local;
        // Assuming C is perfectly divisible by num_groups here.
        float val = x[n * C + c_global];
        sum_val += val;
        sum_sq_val += val * val;
    }

    // Use shared memory for reduction
    extern __shared__ float sdata[]; // sdata will be used for both sum and sum_sq
                                     // We need 2*blockDim.x floats for sum and sum_sq
    float* sdata_sum = sdata;
    float* sdata_sum_sq = sdata + blockDim.x;

    sdata_sum[threadIdx.x] = sum_val;
    sdata_sum_sq[threadIdx.x] = sum_sq_val;
    __syncthreads();

    // Parallel reduction within the block
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            sdata_sum[threadIdx.x] += sdata_sum[threadIdx.x + s];
            sdata_sum_sq[threadIdx.x] += sdata_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float total_sum = sdata_sum[0];
        float total_sum_sq = sdata_sum_sq[0];

        float mean_val = total_sum / C_per_group;
        float var_val = (total_sum_sq / C_per_group) - (mean_val * mean_val);
        var_val = fmaxf(0.0f, var_val); // Ensure non-negative variance

        mean_out[n * num_groups + g] = mean_val;
        var_out[n * num_groups + g] = var_val;
    }
}


// Kernel 2: Fused GroupNorm + Swish + Multiply + Swish
// Each thread processes one (N, C) element.
__global__ void fused_ops_kernel(
    const float* x,
    const float* mean,
    const float* var,
    const float* gamma,
    const float* beta,
    const float* multiply_weight,
    float* out,
    int N, int C, int num_groups, int C_per_group, float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C) {
        int n = idx / C; // Batch index
        int c = idx % C; // Channel index
        int g = c / C_per_group; // Group index

        float val_x = x[idx];
        float mean_val = mean[n * num_groups + g];
        float var_val = var[n * num_groups + g];
        float gamma_val = gamma[c];
        float beta_val = beta[c];
        float multiply_weight_val = multiply_weight[c];

        // GroupNorm
        float x_norm = (val_x - mean_val) / sqrtf(var_val + eps);
        float x_gn = gamma_val * x_norm + beta_val;

        // First Swish
        float swish1 = x_gn * sigmoid(x_gn);

        // Element-wise multiply
        float mult = swish1 * multiply_weight_val;

        // Second Swish
        float swish2 = mult * sigmoid(mult);

        out[idx] = swish2;
    }
}

torch::Tensor fused_groupnorm_swish_multiply_swish_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor multiply_weight,
    int num_groups,
    float eps) {

    // Ensure inputs are on CUDA and are float
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be a CUDA tensor");
    TORCH_CHECK(beta.is_cuda(), "beta must be a CUDA tensor");
    TORCH_CHECK(multiply_weight.is_cuda(), "multiply_weight must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(gamma.dtype() == torch::kFloat32, "gamma must be float32");
    TORCH_CHECK(beta.dtype() == torch::kFloat32, "beta must be float32");
    TORCH_CHECK(multiply_weight.dtype() == torch::kFloat32, "multiply_weight must be float32");


    // Input x is (N, C)
    int N = x.size(0);
    int C = x.size(1);
    TORCH_CHECK(C % num_groups == 0, "Number of channels must be divisible by num_groups");
    int C_per_group = C / num_groups;

    // Allocate tensors for mean and variance
    auto mean = torch::empty({N, num_groups}, x.options());
    auto var = torch::empty({N, num_groups}, x.options());

    // Kernel 1: Compute Mean and Variance
    dim3 blocks_mean_var(num_groups, N); // Grid: (num_groups, N)
    dim3 threads_mean_var(32); // Threads per block for reduction. C_per_group = 32.
                               // Shared memory size: 2 * blockDim.x * sizeof(float)
    size_t smem_size_mean_var = 2 * threads_mean_var.x * sizeof(float);

    compute_mean_var_kernel<<<blocks_mean_var, threads_mean_var, smem_size_mean_var>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, num_groups, C_per_group, eps);

    // Allocate output tensor
    auto out = torch::empty_like(x);

    // Kernel 2: Fused operations
    const int block_size = 256;
    const int num_elements = N * C;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        multiply_weight.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, num_groups, C_per_group, eps);

    return out;
}
"""

fused_ops_cpp_source = (
    "torch::Tensor fused_groupnorm_swish_multiply_swish_cuda("
    "torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, "
    "torch::Tensor multiply_weight, int num_groups, float eps);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_groupnorm_swish_multiply_swish",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_groupnorm_swish_multiply_swish_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    """
    Optimized Model that replaces GroupNorm, Swish, Multiply, and Swish
    operations with a single fused CUDA kernel.
    """
    def __init__(self, in_features, out_features, num_groups, multiply_weight_shape):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)

        # GroupNorm's learnable parameters (gamma and beta) are now explicitly
        # defined as nn.Parameters to be discoverable by optimizers.
        # Default initialization for GroupNorm affine parameters: gamma=1, beta=0.
        self.group_norm_weight = nn.Parameter(torch.ones(out_features)) # gamma
        self.group_norm_bias = nn.Parameter(torch.zeros(out_features))  # beta

        self.multiply_weight = nn.Parameter(torch.randn(multiply_weight_shape))
