        self.eps = 1e-5 # Default epsilon for GroupNorm
        self.fused_ops = fused_ops

    def forward(self, x):
        # (batch_size, in_features) -> (batch_size, out_features)
        x = self.gemm(x)

        # Fused GroupNorm, Swish, Multiply, Swish operations
        x = self.fused_ops.fused_groupnorm_swish_multiply_swish_cuda(
            x,
            self.group_norm_weight,
            self.group_norm_bias,
