#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX
#include <math.h>  // For expf, logf, fmaxf

__global__ void logsumexp_relu_kernel(const float* input, float* output,
                                      int B, int C, int D, int H, int W) {
    // Calculate the global index for the output element
    // Each thread processes one (b, d, h, w) slice
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements (B * D * H * W)
    int total_output_elements = B * D * H * W;

    if (idx < total_output_elements) {
        // Deconstruct idx to (b, d, h, w) coordinates
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int d_idx = (idx / (W * H)) % D;
        int b_idx = idx / (W * H * D);

        // Find max_val for numerical stability of logsumexp
        float max_val = -FLT_MAX; // Initialize with a very small number
        for (int c = 0; c < C; ++c) {
            // Calculate input offset for current (b, c, d, h, w)
            // Input tensor is (B, C, D, H, W)
            long long input_offset = (long long)b_idx * C * D * H * W +
                                     (long long)c * D * H * W +
                                     (long long)d_idx * H * W +
                                     (long long)h_idx * W +
                                     (long long)w_idx;
            max_val = fmaxf(max_val, input[input_offset]);
        }

        // Compute sum_exp
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            // Calculate input offset for current (b, c, d, h, w)
            long long input_offset = (long long)b_idx * C * D * H * W +
                                     (long long)c * D * H * W +
                                     (long long)d_idx * H * W +
                                     (long long)h_idx * W +
                                     (long long)w_idx;
            sum_exp += expf(input[input_offset] - max_val);
        }

        // Compute logsumexp
        float logsumexp_val = max_val + logf(sum_exp);

        // Apply ReLU activation
        float relu_val = fmaxf(0.0f, logsumexp_val);

        // Store result in output
        // Output tensor is (B, 1, D, H, W) due to keepdim=True
        long long output_offset = (long long)b_idx * 1 * D * H * W + // Channel dim is 1, so c_idx is always 0
                                  (long long)d_idx * H * W +
                                  (long long)h_idx * W +
                                  (long long)w_idx;
        output[output_offset] = relu_val;
    }
}

torch::Tensor logsumexp_relu_cuda(torch::Tensor input) {
