    auto output = torch::zeros({B, 1, D, H, W}, input.options());

    // Calculate total number of output elements to determine grid size
    int total_output_elements = B * D * H * W;

    // Define block and grid dimensions
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    logsumexp_relu_kernel<<<num_blocks, block_size>>>(
