#ifndef M_SQRT1_2F
#define M_SQRT1_2F 0.707106781186547572937f // 1/sqrt(2)
#endif

__global__ void fused_activation_kernel(
    const float* input,
    float* output,
    int size,
    float scaling_factor,
    float hardtanh_min,
    float hardtanh_max) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < size) {
        float val = input[idx];

        // 1. Scaling: x = x * scaling_factor
        val = val * scaling_factor;

        // 2. Hardtanh: x = max(hardtanh_min, min(x, hardtanh_max))
        val = fmaxf(hardtanh_min, fminf(val, hardtanh_max));

        // 3. GELU (standard definition): 0.5 * x * (1 + erf(x / sqrt(2)))
        val = 0.5f * val * (1.0f + erff(val * M_SQRT1_2F));

        output[idx] = val;
    }
