import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused activations and bias addition
fused_activations_bias_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, tanh, sqrtf, erf, M_PI

// Define M_PI if not already defined (common in CUDA)
#ifndef M_PI
#define M_PI 3.14159265358979323846f
#endif

// GELU activation (using erf approximation)
__device__ float gelu_activation(float x) {
    return 0.5f * x * (1.0f + erff(x / sqrtf(2.0f)));
}

// Sigmoid activation
__device__ float sigmoid_activation(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_activations_bias_kernel(
    const float* input,
    const float* bias,
    float* output,
    int N, int C, int D, int H, int W,
    float negative_slope) {

    int total_elements = N * C * D * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate channel index for bias broadcasting
        // input shape: (N, C, D, H, W)
        // bias shape: (C, 1, 1, 1)
        // The bias value for a given element at (n, c, d, h, w) is bias[c].
        int c = (idx / (D * H * W)) % C;

        float val = input[idx];

        // 1. ReLU: max(0, x)
        val = fmaxf(0.0f, val);

        // 2. LeakyReLU: x if x > 0 else x * negative_slope
        val = (val > 0.0f) ? val : val * negative_slope;

        // 3. GELU
        val = gelu_activation(val);

        // 4. Sigmoid
        val = sigmoid_activation(val);

        // 5. Add bias
        val += bias[c];

        output[idx] = val;
    }
}

