# Define the custom CUDA kernel for fused AvgPool1d, GELU, Scale, and Max
avgpool_gelu_scale_max_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <device_launch_parameters.h> // For __global__
#include <float.h> // For FLT_MAX
#include <math.h>  // For erff, fmaxf

// Define M_SQRT1_2F if not already defined (it usually is in math.h or cmath)
#ifndef M_SQRT1_2F
#define M_SQRT1_2F 0.707106781186547572440084600000000000f /* 1/sqrt(2) */
#endif

__global__ void avgpool_gelu_scale_max_kernel(const float* input, float* output,
                                              int batch_size, int out_features,
                                              int pool_kernel_size, float scale_factor,
                                              int L_out) {
    // Each block processes one batch item
    int b_idx = blockIdx.x;

    if (b_idx < batch_size) {
        const float* batch_input_ptr = input + b_idx * out_features;

        // Shared memory for reduction within the block.
        // Size determined at launch: block_dim * sizeof(float)
        extern __shared__ float s_max[]; 

        int tid = threadIdx.x;
        int block_dim = blockDim.x;

        // Each thread computes its local max over its assigned segments
        float thread_local_max = -FLT_MAX;

        // Loop through the L_out segments. Each thread processes multiple if L_out > block_dim.
        for (int i = tid; i < L_out; i += block_dim) {
            float sum_val = 0.0f;
            // Calculate average for the current window.
            // This implementation assumes out_features is a multiple of pool_kernel_size.
            for (int k = 0; k < pool_kernel_size; ++k) {
                sum_val += batch_input_ptr[i * pool_kernel_size + k];
            }
            float avg_val = sum_val / pool_kernel_size;

            // Apply GELU (using approximation with erf)
            // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
            float gelu_val = 0.5f * avg_val * (1.0f + erff(avg_val * M_SQRT1_2F));

            // Apply scaling
            float scaled_val = gelu_val * scale_factor;

            thread_local_max = fmaxf(thread_local_max, scaled_val);
        }

        // Store thread's local max in shared memory
        s_max[tid] = thread_local_max;
        __syncthreads();

        // Perform reduction in shared memory to find the maximum across all threads in the block.
        // This is a standard parallel reduction pattern.
        for (int s = block_dim / 2; s > 0; s /= 2) {
            if (tid < s) {
                s_max[tid] = fmaxf(s_max[tid], s_max[tid + s]);
            }
            __syncthreads();
        }

        // The final max for this batch item is in s_max[0]
        if (tid == 0) {
            output[b_idx] = s_max[0];
        }
    }
}

