# Define the custom CUDA kernel for fused GroupNorm and Hardtanh
group_norm_hardtanh_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, fmaxf, fminf

// Macro for CUDA error checking
#define CUDA_CHECK(call)                                                               \
  do {                                                                                 \
    cudaError_t err = call;                                                            \
    if (err != cudaSuccess) {                                                          \
      fprintf(stderr, "CUDA error in %s:%d - %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \
      exit(EXIT_FAILURE);                                                              \
    }                                                                                  \
  } while (0)

// Define constants
const float GN_EPS = 1e-5; // Default epsilon for GroupNorm

// Kernel 1: Calculate mean and variance for each group
// Each block handles one group.
__global__ void group_norm_mean_var_kernel(
    const float* __restrict__ x,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int B, // batch_size
    int C, // out_features
    int G, // num_groups
    int C_per_group // channels_per_group
) {
    // Each block processes one group
    int group_idx = blockIdx.x;

    // Calculate the starting channel index for this group
    int group_start_c = group_idx * C_per_group;

    // Total elements in this group across all batches
    int group_elements = B * C_per_group;

    // Shared memory for reduction
    // We need to sum x and x*x
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sum_sq = sdata + blockDim.x;

    s_sum[threadIdx.x] = 0.0f;
    s_sum_sq[threadIdx.x] = 0.0f;
    __syncthreads();

    // Each thread processes multiple elements
    for (int i = threadIdx.x; i < group_elements; i += blockDim.x) {
        int b = i / C_per_group; // batch index
        int c_in_group = i % C_per_group; // channel index within the group
        int c = group_start_c + c_in_group; // global channel index

        float val = x[b * C + c];
        s_sum[threadIdx.x] += val;
        s_sum_sq[threadIdx.x] += val * val;
    }
    __syncthreads();

    // Perform reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Store the final mean and variance for this group
    if (threadIdx.x == 0) {
        float sum = s_sum[0];
        float sum_sq = s_sum_sq[0];

        float mean = sum / group_elements;
        float var = (sum_sq / group_elements) - (mean * mean);
        // Ensure variance is non-negative due to potential floating point inaccuracies
        var = fmaxf(0.0f, var);

        mean_out[group_idx] = mean;
        var_out[group_idx] = var;
    }
}

// Kernel 2: Apply normalization, scale, shift, and Hardtanh
// Each thread processes one element of the output tensor.
__global__ void group_norm_hardtanh_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    float min_val,
    float max_val,
    int B, // batch_size
    int C, // out_features
    int G, // num_groups
    int C_per_group // channels_per_group
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < B * C) {
        int b = idx / C; // batch index
        int c = idx % C; // global channel index

        int group_idx = c / C_per_group;

        float current_mean = mean[group_idx];
        float current_var = var[group_idx];

        float val = x[idx];
        float gamma_val = gamma[c];
        float beta_val = beta[c];

        // Group Normalization
        float normalized_val = (val - current_mean) / sqrtf(current_var + GN_EPS);
        float scaled_shifted_val = gamma_val * normalized_val + beta_val;

        // Hardtanh
        out[idx] = fmaxf(min_val, fminf(max_val, scaled_shifted_val));
    }
}

