# This kernel combines:
# 1. Addition with self.add_value (broadcasted)
# 2. Swish activation (sigmoid(x) * x)
# 3. Tanh activation
# 4. GELU activation (using the standard approximation: 0.5 * x * (1.0 + erf(x / sqrt(2.0))))
# 5. Hardtanh activation (clamp(x, min_val, max_val))
fused_activations_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For erf, tanh, sigmoid

// Define constant for GELU approximation: 1 / sqrt(2)
#define M_SQRT1_2F 0.70710678118f

// Custom device-side sigmoid function
__device__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__global__ void fused_activations_kernel(
    const float* input,
    const float* add_value,
    float* output,
    int batch_size,
    int out_features,
    float hardtanh_min,
    float hardtanh_max) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < batch_size * out_features) {
        // Calculate the feature index for broadcasting add_value
        int feature_idx = idx % out_features;

        // 1. Add self.add_value (broadcasted across batch dimension)
        float val = input[idx] + add_value[feature_idx];

        // 2. Swish activation: x = sigmoid(x) * x
        val = sigmoid_f(val) * val;

        // 3. Tanh activation: x = tanh(x)
        val = tanhf(val);

        // 4. GELU activation: x = 0.5 * x * (1.0 + erf(x / sqrt(2.0)))
        // Using the standard approximation for GELU, consistent with torch.nn.functional.gelu
        val = 0.5f * val * (1.0f + erff(val * M_SQRT1_2F));

        // 5. Hardtanh activation: x = max(min_val, min(max_val, x))
        val = fmaxf(hardtanh_min, fminf(hardtanh_max, val));

        output[idx] = val;
    }
}

