import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Global Average Pooling, Scaling, and Clamping
fused_gap_scale_clamp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max and std::min

// CUDA kernel for fused Global Average Pooling, Scaling, and Clamping
// Input: (N, C, D_in, H_in, W_in)
// Output: (N, C, 1, 1, 1)
__global__ void fused_gap_scale_clamp_kernel(
    const float* input,
    float* output,
    int N, int C, int D_in, int H_in, int W_in,
    float scale, float clamp_min, float clamp_max)
{
    // Each block handles one (n, c) slice
    // blockIdx.x for channel, blockIdx.y for batch
    int c = blockIdx.x; // Channel index
    int n = blockIdx.y; // Batch index

    if (n < N && c < C) {
        long long total_spatial_elements = (long long)D_in * H_in * W_in;
        // Calculate the starting index for this (n, c) slice in the input tensor
        // Input is N C D H W, so offset = n * (C*D*H*W) + c * (D*H*W)
        long long slice_offset = (long long)n * C * D_in * H_in * W_in + (long long)c * D_in * H_in * W_in;

        float thread_sum = 0.0f;

        // Grid-stride loop for summing elements within the (n, c) slice
        // Each thread sums a portion of the spatial elements.
        for (long long idx = threadIdx.x; idx < total_spatial_elements; idx += blockDim.x) {
            thread_sum += input[slice_offset + idx];
        }

        // Perform a block-wide reduction using shared memory
        // This assumes blockDim.x is <= 1024 (max block size)
        __shared__ float s_sum[1024]; 
        s_sum[threadIdx.x] = thread_sum;
        __syncthreads();

        // Reduce in shared memory
        for (int offset = blockDim.x / 2; offset > 0; offset /= 2) {
            if (threadIdx.x < offset) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + offset];
            }
            __syncthreads(); // Synchronize after each reduction step
        }

        // Only the first thread in the block writes the final result
        if (threadIdx.x == 0) {
            float avg = s_sum[0] / total_spatial_elements;
            float scaled_avg = avg * scale;
            float clamped_output = fmaxf(clamp_min, fminf(clamp_max, scaled_avg));
            // Output is N C 1 1 1, so its linear index is n * C + c
            output[n * C + c] = clamped_output;
        }
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor fused_gap_scale_clamp_cuda(
    torch::Tensor input,
    float scale,
    float clamp_min,
    float clamp_max)
