    auto output = torch::empty({N, C, 1, 1, 1}, input.options());

    // Configure grid and block dimensions for the kernel launch
    // Each block processes one (N, C) slice.
    // Grid dimensions: (C, N)
    dim3 blocks(C, N);
    // Block dimensions: threads for spatial reduction within each (N, C) slice.
    // A common block size, the grid-stride loop handles larger spatial dimensions.
    int block_size = 256; 

    // Launch the CUDA kernel
    fused_gap_scale_clamp_kernel<<<blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D_in, H_in, W_in,
