# CUDA kernel source for fused double Mish activation
double_mish_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf, expf, logf

// Helper function for stable softplus: log(1 + exp(x))
__device__ float softplus_cuda(float x) {
    // Stable implementation to prevent overflow/underflow for large/small x
    if (x > 0.0f) {
        return x + logf(1.0f + expf(-x));
    } else {
        return logf(1.0f + expf(x));
    }
}

// Helper function for Mish activation: x * tanh(softplus(x))
__device__ float mish_cuda(float x) {
    return x * tanhf(softplus_cuda(x));
}

// CUDA kernel to apply Mish activation twice (fused)
__global__ void double_mish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        // Apply first Mish
        val = mish_cuda(val);
        // Apply second Mish
        output[idx] = mish_cuda(val);
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor double_mish_cuda(torch::Tensor input) {
    // Ensure input is on CUDA and is float32
