    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");

    auto output = torch::empty_like(input); // Allocate output tensor on CUDA
    int size = input.numel(); // Total number of elements

    // Define block and grid dimensions
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Launch the CUDA kernel
    double_mish_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),  // Pointer to input data
        output.data_ptr<float>(), // Pointer to output data
