# Define the custom CUDA kernel for fused operations:
# (x * scale1) -> AvgPool3d(kernel_size=2, stride=2) -> (x + bias) -> (x * scale2)
mul_scale1_avg_pool3d_add_bias_mul_scale2_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::min/max if needed, though not strictly for this simple pooling

__global__ void mul_scale1_avg_pool3d_add_bias_mul_scale2_kernel(
    const float* x,
    float scale1_val,
    const float* bias,
    float scale2_val,
    float* out,
    int N, int C,
    int D_in, int H_in, int W_in, // Input spatial dimensions to this kernel (output of conv_transpose)
    int D_out, int H_out, int W_out) { // Output spatial dimensions of this kernel (final output)

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * D_out * H_out * W_out) {
        // Map flat index to 5D output coordinates (n, c, d_out, h_out, w_out)
        int w_out = idx % W_out;
        idx /= W_out;
        int h_out = idx % H_out;
        idx /= H_out;
        int d_out = idx % D_out;
        idx /= D_out;
        int c = idx % C;
        idx /= C;
        int n = idx;

        // Calculate corresponding input window start coordinates for AvgPool3d
        // AvgPool3d kernel_size=2, stride=2
        int d_in_start = d_out * 2;
        int h_in_start = h_out * 2;
        int w_in_start = w_out * 2;

        float sum_scaled = 0.0f;
        const int kernel_size = 2;
        const float inv_kernel_volume = 1.0f / (kernel_size * kernel_size * kernel_size); // 1/8.0f

        // Iterate over the 2x2x2 window in the input tensor
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int current_d_in = d_in_start + kd;
                    int current_h_in = h_in_start + kh;
                    int current_w_in = w_in_start + kw;

                    // Calculate linear index for input x
                    // Assuming NCDHW memory layout (PyTorch default for 3D tensors)
                    size_t x_idx = (size_t)n * C * D_in * H_in * W_in +
                                   (size_t)c * D_in * H_in * W_in +
                                   (size_t)current_d_in * H_in * W_in +
                                   (size_t)current_h_in * W_in +
                                   (size_t)current_w_in;

                    // Apply scale1 here before summing for pooling
                    sum_scaled += x[x_idx] * scale1_val;
                }
            }
        }

        float avg_scaled = sum_scaled * inv_kernel_volume;

        // Add bias (bias is (C, 1, 1, 1), so only depends on channel c)
        // Assuming bias is contiguous and its elements are bias[0,0,0,0], bias[1,0,0,0], etc.
        float bias_val = bias[c]; 

        float avg_plus_bias = avg_scaled + bias_val;

        // Multiply by scale2
        float result = avg_plus_bias * scale2_val;

        // Store result in output tensor
        out[idx] = result;
    }
}

