import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fusing bias addition and element-wise scaling
# This kernel takes the output of a matrix multiplication, adds a bias vector
# (if provided), and then multiplies by a scale vector, all in a single pass.
bias_add_and_scale_mul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h> // Required for c10::optional

// Kernel for (matmul_output + bias) * scale
// matmul_output: (N, M) - result of matrix multiplication
// bias: (M,) or nullptr - bias vector to add per feature
// scale: (M,) - scale vector to multiply per feature
// out: (N, M) - final output tensor
__global__ void bias_add_and_scale_mul_kernel(
    const float* matmul_output,
    const float* bias, // Can be nullptr if no bias is present
    const float* scale,
    float* out,
    int N, // batch_size (number of rows in matmul_output)
    int M  // out_features (number of columns in matmul_output)
) {
    // Each thread processes one element in the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * M) {
        // Calculate the column index (feature index)
        // The bias and scale are applied per feature (column)
        int m = idx % M; 

        float val = matmul_output[idx];

        // Add bias if it exists
        if (bias != nullptr) {
            val += bias[m];
        }

        // Multiply by scale
        val *= scale[m];

        out[idx] = val;
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor bias_add_and_scale_mul_cuda(
    torch::Tensor matmul_output,
    c10::optional<torch::Tensor> bias_opt, // Use c10::optional for an optional bias tensor
    torch::Tensor scale
) {
