    TORCH_CHECK(matmul_output.is_cuda(), "matmul_output must be a CUDA tensor");
    TORCH_CHECK(matmul_output.is_contiguous(), "matmul_output must be contiguous");
    TORCH_CHECK(matmul_output.scalar_type() == torch::kFloat, "matmul_output must be float32");

    TORCH_CHECK(scale.is_cuda(), "scale must be a CUDA tensor");
    TORCH_CHECK(scale.is_contiguous(), "scale must be contiguous");
    TORCH_CHECK(scale.scalar_type() == torch::kFloat, "scale must be float32");

    const float* bias_ptr = nullptr;
    if (bias_opt.has_value()) {
        torch::Tensor bias = bias_opt.value();
        TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias.scalar_type() == torch::kFloat, "bias must be float32");
        TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
        TORCH_CHECK(bias.size(0) == matmul_output.size(1), "bias size mismatch with matmul_output columns");
        bias_ptr = bias.data_ptr<float>();
    }

    TORCH_CHECK(matmul_output.dim() == 2, "matmul_output must be 2D (batch_size, out_features)");
    TORCH_CHECK(scale.dim() == 1, "scale must be 1D");
    TORCH_CHECK(scale.size(0) == matmul_output.size(1), "scale size mismatch with matmul_output columns");

    int N = matmul_output.size(0); // batch_size
    int M = matmul_output.size(1); // out_features

    // Create an output tensor of the same shape and type as matmul_output
    auto out = torch::empty_like(matmul_output);

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    const int num_elements = N * M;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    bias_add_and_scale_mul_kernel<<<num_blocks, block_size>>>(
        matmul_output.data_ptr<float>(),
        bias_ptr, // Pass nullptr if bias_opt is empty
        scale.data_ptr<float>(),
        out.data_ptr<float>(),
        N, M
    );

    return out;
}
"""

# C++ header for the custom function
bias_add_and_scale_mul_cpp_source = (
    "torch::Tensor bias_add_and_scale_mul_cuda(torch::Tensor matmul_output, c10::optional<torch::Tensor> bias_opt, torch::Tensor scale);"
)

# Compile the inline CUDA code
# This creates a Python module 'bias_add_and_scale_mul' with the 'bias_add_and_scale_mul_cuda' function
