    name="bias_add_and_scale_mul",
    cpp_sources=bias_add_and_scale_mul_cpp_source,
    cuda_sources=bias_add_and_scale_mul_source,
    functions=["bias_add_and_scale_mul_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that replaces the separate bias addition and element-wise scaling
    operations with a single fused custom CUDA kernel.

    Original operations:
    1. x = self.gemm(x)  # Equivalent to (x @ self.gemm.weight.T) + self.gemm.bias
    2. x = x * self.scale # Element-wise multiplication

    Optimized operations:
    1. matmul_output = F.linear(x, self.gemm.weight, None) # Only the matrix multiplication part
    2. x = custom_kernel(matmul_output, self.gemm.bias, self.scale) # Fused bias add and scale mul
    3. x = self.bn(x) # BatchNorm remains unchanged
    """
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)

        # Store the compiled custom CUDA operator
        self.bias_add_and_scale_mul_op = bias_add_and_scale_mul

    def forward(self, x):
        # Step 1: Perform only the matrix multiplication part of nn.Linear.
        # F.linear(input, weight, bias=None) computes input @ weight.T
        matmul_output = F.linear(x, self.gemm.weight, None)

