class ModelNew(nn.Module):
    """
    Optimized model that performs a matrix multiplication, scaling, and residual addition.
    The bias addition from the linear layer and the subsequent scalar multiplication
    (which results from the original scaling and residual addition) are fused into a
    single custom CUDA kernel.
    """
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        # Replace nn.Linear with its components: weight and bias parameters
        # This allows us to perform the GEMM part separately and then fuse bias+scale.
        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        self.bias = nn.Parameter(torch.empty(out_features))

        # Initialize weights and bias similar to nn.Linear for consistency
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        fan_in, _ = nn.init._calculate_fan_in_and_out(self.weight)
        bound = 1 / (fan_in**0.5)
        nn.init.uniform_(self.bias, -bound, bound)

