        # x = self.matmul(x)  -> result_linear = x @ W.T + B
        # original_x = x.clone().detach() -> original_x = result_linear
        # x = x * self.scaling_factor -> x = result_linear * scaling_factor
        # x = x + original_x -> x = (result_linear * scaling_factor) + result_linear
        # x = result_linear * (scaling_factor + 1)
        # So, we need to apply (scaling_factor + 1) to the output of the linear layer.
        self.effective_scaling_factor = scaling_factor + 1.0

