        # F.linear handles the transpose of weight internally.
        # The result is `x @ self.weight.T`.
        gemm_output = F.linear(x, self.weight, None)

        # Apply the fused bias addition and scalar multiplication using the custom CUDA kernel.
        # This computes `(gemm_output + self.bias) * self.effective_scaling_factor`.
        x = self.fused_bias_scale_op.fused_bias_scale_cuda(
            gemm_output, self.bias, self.effective_scaling_factor
        )
        return x

