#define M_SQRT2_PI_F 0.7978845608028654f // sqrt(2.0 / PI)
#define GELU_COEFF_F 0.044715f

// Custom GELU function for float, using __nv_tanhf for CUDA performance
__device__ __forceinline__ float gelu_f(float x) {
