# Define the custom CUDA kernel for fused operations
fused_mean_bias_softmax_tanh_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// Helper for 5D indexing (B, C, D, H, W)
// Assumes contiguous memory layout
__device__ __forceinline__ int get_conv_out_idx(int b, int c, int d, int h, int w, int C_out, int D, int H, int W) {
    return b * (C_out * D * H * W) + c * (D * H * W) + d * (H * W) + h * W + w;
}

// Helper for 5D indexing (B, C, 1, H, W)
// Assumes contiguous memory layout
__device__ __forceinline__ int get_final_out_idx(int b, int c, int h, int w, int C_out, int H, int W) {
    return b * (C_out * H * W) + c * (H * W) + h * W + w;
}

__global__ void fused_mean_bias_softmax_tanh_scale_kernel(
    const float* conv_out_ptr,
    const float* bias_ptr,
    float scaling_factor,
    float* final_out_ptr,
    int B, int C_out, int D, int H, int W) {

    // Each block processes one (b, h, w) slice across all C_out channels.
    // This means a block is responsible for computing the output for a specific
    // batch item, height, and width, across all channels.
    int block_idx = blockIdx.x;
    int b = block_idx / (H * W);
    int hw_idx = block_idx % (H * W);
    int h = hw_idx / W;
    int w = hw_idx % W;

    // Dynamic shared memory is used for intermediate values and reduction buffers.
    // s_data layout:
    // [0 ... C_out-1] : s_intermediate_vals (stores mean + bias for each channel)
    // [C_out ... C_out + blockDim.x - 1] : s_max_reduction_buffer
    // [C_out + blockDim.x ... C_out + 2*blockDim.x - 1] : s_sum_reduction_buffer
    extern __shared__ float s_data[]; 

    float* s_intermediate_vals = s_data;
    float* s_max_reduction_buffer = s_data + C_out;
    float* s_sum_reduction_buffer = s_data + C_out + blockDim.x;

    // Step 1: Compute mean pooling over depth and add bias for each channel 'c'.
    // Each thread iterates over channels if C_out > blockDim.x.
    for (int c = threadIdx.x; c < C_out; c += blockDim.x) {
        float sum_val = 0.0f;
        for (int d = 0; d < D; ++d) {
            sum_val += conv_out_ptr[get_conv_out_idx(b, c, d, h, w, C_out, D, H, W)];
        }
        float mean_val = sum_val / D;
        s_intermediate_vals[c] = mean_val + bias_ptr[c];
    }
    __syncthreads(); // Ensure all threads have written their intermediate values

    // Step 2: Find the maximum value across channels for numerical stability in softmax.
    float thread_max_val = -FLT_MAX;
    for (int c = threadIdx.x; c < C_out; c += blockDim.x) {
        thread_max_val = fmaxf(thread_max_val, s_intermediate_vals[c]);
    }
    // Reduce thread_max_val across the block using shared memory.
    s_max_reduction_buffer[threadIdx.x] = thread_max_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_max_reduction_buffer[threadIdx.x] = fmaxf(s_max_reduction_buffer[threadIdx.x], s_max_reduction_buffer[threadIdx.x + s]);
        }
        __syncthreads();
    }
    float max_val = s_max_reduction_buffer[0]; // The maximum value for this (b, h, w) slice

    // Step 3: Compute the sum of exponentials for the softmax denominator.
    float thread_sum_exp = 0.0f;
    for (int c = threadIdx.x; c < C_out; c += blockDim.x) {
        thread_sum_exp += expf(s_intermediate_vals[c] - max_val);
    }
    // Reduce thread_sum_exp across the block using shared memory.
    s_sum_reduction_buffer[threadIdx.x] = thread_sum_exp;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum_reduction_buffer[threadIdx.x] += s_sum_reduction_buffer[threadIdx.x + s];
        }
        __syncthreads();
    }
    float sum_exp = s_sum_reduction_buffer[0]; // The sum of exponentials for this (b, h, w) slice

    // Step 4: Compute final softmax, tanh, and scaling.
    for (int c = threadIdx.x; c < C_out; c += blockDim.x) {
        float softmax_val = expf(s_intermediate_vals[c] - max_val) / sum_exp;
        float tanh_val = tanhf(softmax_val);
        final_out_ptr[get_final_out_idx(b, c, h, w, C_out, H, W)] = tanh_val * scaling_factor;
    }
}

torch::Tensor fused_mean_bias_softmax_tanh_scale_cuda(
    torch::Tensor conv_out,
    torch::Tensor bias,
    float scaling_factor) {

    // Input validation
    TORCH_CHECK(conv_out.is_cuda(), "conv_out must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(conv_out.is_contiguous(), "conv_out must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(conv_out.dtype() == torch::kFloat32, "conv_out must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");

    // Extract dimensions from conv_out (B, C_out, D, H, W)
    int B = conv_out.size(0);
    int C_out = conv_out.size(1);
    int D = conv_out.size(2);
    int H = conv_out.size(3);
    int W = conv_out.size(4);

    // The output tensor will have shape (B, C_out, 1, H, W)
    auto final_out = torch::empty({B, C_out, 1, H, W}, conv_out.options());

    // Each block processes one (b, h, w) slice.
    const int num_blocks = B * H * W;
    // A common block size. Should be chosen considering C_out for optimal performance.
    // For C_out=64, 256 is a good choice as it's a multiple of 32 (warp size) and >= C_out.
    const int block_size = 256; 

    // Calculate dynamic shared memory size required by the kernel:
    // C_out * sizeof(float) for s_intermediate_vals
    // block_size * sizeof(float) for s_max_reduction_buffer
    // block_size * sizeof(float) for s_sum_reduction_buffer
    size_t smem_size = C_out * sizeof(float) + 2 * block_size * sizeof(float);

    // Launch the CUDA kernel
    fused_mean_bias_softmax_tanh_scale_kernel<<<num_blocks, block_size, smem_size>>>(
        conv_out.data_ptr<float>(),
        bias.data_ptr<float>(),
        scaling_factor,
        final_out.data_ptr<float>(),
