import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for fused Swish, GroupNorm, and HardSwish
# This involves two kernels:
# 1. group_norm_mean_var_kernel: Calculates mean and variance per group for GroupNorm.
# 2. fused_swish_gn_hardswish_kernel: Applies Swish, then GroupNorm (using pre-calculated mean/var), then HardSwish.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, sqrtf, fmaxf, fminf

// Kernel 1: Calculates mean and variance for each group within each batch item.
// Input: x (N, C, D, H, W)
// Output: mean (N, num_groups), var (N, num_groups)
__global__ void group_norm_mean_var_kernel(
    const float* x_ptr,
    float* mean_ptr,
    float* var_ptr,
    int N, int C, int D, int H, int W,
    int num_groups)
{
    // Each block computes mean/var for one (batch_idx, group_idx) pair.
    // The grid is N * num_groups blocks.
    int batch_idx = blockIdx.x / num_groups;
    int group_idx = blockIdx.x % num_groups;

    int channels_per_group = C / num_groups;
    int group_start_channel = group_idx * channels_per_group;

    // Number of elements in one group slice (channels_per_group * D * H * W)
    long long elements_per_group_slice = (long long)channels_per_group * D * H * W;

    // Offset to the start of this batch item's data in the flattened tensor
    long long batch_offset = (long long)batch_idx * C * D * H * W;

    // Shared memory for reduction within the block.
    // We need space for sum and sum_sq for all threads in the block.
    extern __shared__ float s_data[]; // s_data[0...blockDim.x-1] for sum, s_data[blockDim.x...2*blockDim.x-1] for sum_sq
    float* s_sum = s_data;
    float* s_sum_sq = s_data + blockDim.x;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // Each thread processes a stride of elements within its assigned group slice.
    for (long long i = threadIdx.x; i < elements_per_group_slice; i += blockDim.x) {
        // Deconstruct 'i' to relative c_offset_in_group, d, h, w within the group slice.
        long long w_offset = i % W;
        long long h_offset = (i / W) % H;
        long long d_offset = (i / (W * H)) % D;
        long long c_offset_in_group = i / (D * H * W);

        int current_c = group_start_channel + c_offset_in_group;

        // Calculate the global index in the input tensor 'x'.
        long long global_idx = batch_offset +
                               (long long)current_c * D * H * W +
                               (long long)d_offset * H * W +
                               (long long)h_offset * W +
                               (long long)w_offset;

        float val = x_ptr[global_idx];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    // Store thread-local sums in shared memory.
    s_sum[threadIdx.x] = thread_sum;
    s_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    // Perform parallel reduction in shared memory to get the total sum and sum of squares for the group.
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    // The first thread in the block writes the final mean and variance to global memory.
    if (threadIdx.x == 0) {
        float final_sum = s_sum[0];
        float final_sum_sq = s_sum_sq[0];

        float current_mean = final_sum / elements_per_group_slice;
        float current_var = (final_sum_sq / elements_per_group_slice) - (current_mean * current_mean);
        // Ensure variance is non-negative due to potential floating point inaccuracies.
        current_var = fmaxf(0.0f, current_var);

        mean_ptr[batch_idx * num_groups + group_idx] = current_mean;
        var_ptr[batch_idx * num_groups + group_idx] = current_var;
    }
}

// Kernel 2: Fuses Swish activation, Group Normalization, and HardSwish activation.
// Input: x (N, C, D, H, W), pre-calculated mean (N, num_groups), var (N, num_groups),
//        GroupNorm's gamma (C,), beta (C,), num_groups, and eps.
// Output: out (N, C, D, H, W)
__global__ void fused_swish_gn_hardswish_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* var_ptr,
    const float* gamma_ptr, // GroupNorm weight (C,)
    const float* beta_ptr,  // GroupNorm bias (C,)
    float* out_ptr,
    int N, int C, int D, int H, int W,
    int num_groups,
    float eps)
{
    long long total_elements = (long long)N * C * D * H * W;
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Deconstruct global index to N, C, D, H, W coordinates.
        long long w_idx = idx % W;
        long long h_idx = (idx / W) % H;
        long long d_idx = (idx / (W * H)) % D;
        long long c_idx = (idx / (W * H * D)) % C;
        long long n_idx = idx / ((long long)C * D * H * W);

        // Determine the group index for the current channel.
        int channels_per_group = C / num_groups;
        int group_idx = c_idx / channels_per_group;

        float val = x_ptr[idx];

        // 1. Swish activation: x * sigmoid(x)
        float swish_val = val * (1.0f / (1.0f + expf(-val)));

        // 2. Group Normalization
        float current_mean = mean_ptr[n_idx * num_groups + group_idx];
        float current_var = var_ptr[n_idx * num_groups + group_idx];

        // Normalize the value
        float normalized_val = (swish_val - current_mean) / sqrtf(current_var + eps);

        // Apply affine transformation (gamma and beta from GroupNorm).
        // gamma and beta are per-channel.
        float gamma = gamma_ptr[c_idx];
        float beta = beta_ptr[c_idx];

        float gn_val = normalized_val * gamma + beta;

        // 3. HardSwish activation: x * ReLU6(x + 3) / 6
        // ReLU6(x) = min(max(x, 0), 6)
        float relu6_arg = gn_val + 3.0f;
        float relu6_val = fminf(fmaxf(relu6_arg, 0.0f), 6.0f);
        float hardswish_val = gn_val * relu6_val / 6.0f;

        out_ptr[idx] = hardswish_val;
    }
}

// PyTorch C++ API wrapper for group_norm_mean_var_kernel
std::vector<torch::Tensor> group_norm_mean_var_cuda(torch::Tensor x, int num_groups) {
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(x.dim() == 5, "Input tensor 'x' must be 5D (N, C, D, H, W).");

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    TORCH_CHECK(C % num_groups == 0, "Number of channels (C) must be divisible by num_groups.");

    // Allocate output tensors for mean and variance.
    auto mean = torch::empty({N, num_groups}, x.options());
    auto var = torch::empty({N, num_groups}, x.options());

    const int block_size = 256;
    const int num_blocks = N * num_groups; // One block per (batch_idx, group_idx) pair.
    // Shared memory size for sum and sum_sq (2 * block_size floats).
    const int shared_mem_size = 2 * block_size * sizeof(float);

    group_norm_mean_var_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, D, H, W,
        num_groups);

    return {mean, var};
}

// PyTorch C++ API wrapper for fused_swish_gn_hardswish_kernel
torch::Tensor fused_swish_gn_hardswish_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps) {
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(x.dim() == 5, "Input tensor 'x' must be 5D (N, C, D, H, W).");
    TORCH_CHECK(mean.is_cuda() && var.is_cuda(), "Mean and variance tensors must be CUDA tensors.");
    TORCH_CHECK(gamma.is_cuda() && beta.is_cuda(), "Gamma and beta tensors must be CUDA tensors.");
    TORCH_CHECK(gamma.is_contiguous() && beta.is_contiguous(), "Gamma and beta tensors must be contiguous.");


    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    TORCH_CHECK(C % num_groups == 0, "Number of channels (C) must be divisible by num_groups.");

    auto out = torch::empty_like(x);

    const int block_size = 256;
    long long total_elements = (long long)N * C * D * H * W;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_swish_gn_hardswish_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        num_groups,
        eps);

    return out;
}
"""

# C++ function declarations for load_inline
cpp_sources = """
std::vector<torch::Tensor> group_norm_mean_var_cuda(torch::Tensor x, int num_groups);
torch::Tensor fused_swish_gn_hardswish_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float eps);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name="fused_swish_gn_hardswish_ops",
    cpp_sources=cpp_sources,
    cuda_sources=cuda_source,
    functions=["group_norm_mean_var_cuda", "fused_swish_gn_hardswish_cuda"],
    verbose=True,
