        # 1. Perform 3D Transposed Convolution (PyTorch operator)
        x = self.conv_transpose(x)

        # Ensure x is contiguous before passing to custom kernels
        x = x.contiguous()

        # 2. Calculate GroupNorm mean and variance using custom CUDA kernel
