import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels and C++ Wrappers ---
# This block defines the CUDA kernels and their C++ wrappers.
# It includes:
# 1. A custom CUDA kernel for element-wise ReLU.
# 2. A custom CUDA kernel for element-wise Add + ReLU.
# 3. A C++ wrapper `fused_conv_bn_relu_cuda` that performs Conv2d, BatchNorm2d (using PyTorch's optimized ATen functions),
#    and then applies the custom ReLU kernel.
# 4. A C++ wrapper `fused_conv_bn_cuda` that performs Conv2d and BatchNorm2d (using PyTorch's optimized ATen functions).
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h> // Required for AT_DISPATCH_FLOATING_TYPES_AND_HALF

// Custom CUDA kernel for element-wise ReLU
// Takes an input tensor and writes the ReLU result to an output tensor.
template <typename scalar_t>
__global__ void relu_kernel(const scalar_t* in, scalar_t* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = fmaxf(0.0f, in[idx]);
    }
}

// Custom CUDA kernel for element-wise Add + ReLU
// Takes two input tensors, adds them element-wise, and then applies ReLU,
// writing the result to an output tensor.
template <typename scalar_t>
__global__ void add_relu_kernel(const scalar_t* a, const scalar_t* b, scalar_t* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = fmaxf(0.0f, a[idx] + b[idx]);
    }
}

// C++ wrapper for fused_conv_bn_relu: Performs Conv2d, BatchNorm2d, then a custom ReLU kernel.
// This function leverages PyTorch's highly optimized `torch::convolution` and `torch::batch_norm`
// for the computationally intensive parts, and then dispatches a custom CUDA kernel for ReLU
// to reduce Python overhead and potentially improve locality.
torch::Tensor fused_conv_bn_relu_cuda(
    torch::Tensor x,
    torch::Tensor conv_weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    int64_t stride_h, int64_t stride_w,
    int64_t padding_h, int64_t padding_w,
    int64_t dilation_h, int64_t dilation_w,
    int64_t groups) {

    // 1. Convolution (using torch's optimized implementation, likely cuDNN)
    // Note: Original convs in ResNet BasicBlock have bias=False, so an empty tensor is passed for bias.
    torch::Tensor conv_out = torch::convolution(
        x, conv_weight, {}, // No bias
        {stride_h, stride_w}, {padding_h, padding_w}, {dilation_h, dilation_w},
        false, {0,0}, groups
    );

    // 2. BatchNorm (using torch's optimized implementation, likely cuDNN)
    // For inference, training=false, momentum=0.0 (not used), cudnn_enabled=false (or true, but false is safer for custom kernels)
    torch::Tensor bn_out = torch::batch_norm(
        conv_out, bn_weight, bn_bias, running_mean, running_var,
        false, 0.0, eps, false // Inference mode
    );

    // 3. ReLU (custom CUDA kernel for element-wise operation)
    torch::Tensor relu_out = torch::empty_like(bn_out);
    int size = bn_out.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Dispatch the ReLU kernel based on the tensor's scalar type (e.g., float, half)
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(bn_out.scalar_type(), "relu_kernel", ([&] {
        relu_kernel<scalar_t><<<num_blocks, block_size>>>(
            bn_out.data_ptr<scalar_t>(), // Input pointer
            relu_out.data_ptr<scalar_t>(), // Output pointer
            size
        );
    }));

    return relu_out;
}

// C++ wrapper for fused_conv_bn: Performs Conv2d and BatchNorm2d.
// Similar to `fused_conv_bn_relu_cuda` but without the final ReLU.
torch::Tensor fused_conv_bn_cuda(
    torch::Tensor x,
    torch::Tensor conv_weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    int64_t stride_h, int64_t stride_w,
    int64_t padding_h, int64_t padding_w,
    int64_t dilation_h, int64_t dilation_w,
    int64_t groups) {

    // 1. Convolution
    torch::Tensor conv_out = torch::convolution(
        x, conv_weight, {},
        {stride_h, stride_w}, {padding_h, padding_w}, {dilation_h, dilation_w},
        false, {0,0}, groups
    );

    // 2. BatchNorm
    torch::Tensor bn_out = torch::batch_norm(
        conv_out, bn_weight, bn_bias, running_mean, running_var,
        false, 0.0, eps, false // Inference mode
    );

    return bn_out;
}

// C++ wrapper for fused_add_relu: Performs element-wise Add, then a custom ReLU kernel.
// This is a true kernel fusion, combining two element-wise operations into a single CUDA kernel launch.
torch::Tensor fused_add_relu_cuda(torch::Tensor a, torch::Tensor b) {
    torch::Tensor out = torch::empty_like(a);
    int size = a.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Dispatch the Add+ReLU kernel based on the tensor's scalar type
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(a.scalar_type(), "add_relu_kernel", ([&] {
        add_relu_kernel<scalar_t><<<num_blocks, block_size>>>(
            a.data_ptr<scalar_t>(),
            b.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            size
        );
    }));

    return out;
}
"""

# C++ declarations for the functions defined in the CUDA source
cpp_source = """
torch::Tensor fused_conv_bn_relu_cuda(
    torch::Tensor x,
    torch::Tensor conv_weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
