    int64_t padding_h, int64_t padding_w,
    int64_t dilation_h, int64_t dilation_w,
    int64_t groups);

torch::Tensor fused_conv_bn_cuda(
    torch::Tensor x,
    torch::Tensor conv_weight,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    int64_t stride_h, int64_t stride_w,
    int64_t padding_h, int64_t padding_w,
    int64_t dilation_h, int64_t dilation_w,
    int64_t groups);

torch::Tensor fused_add_relu_cuda(torch::Tensor a, torch::Tensor b);
"""

# Compile the inline CUDA code.
# The compiled functions will be available via the 'fused_ops' object.
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=[
        "fused_conv_bn_relu_cuda",
        "fused_conv_bn_cuda",
        "fused_add_relu_cuda",
    ],
    verbose=False, # Set to True for debugging compilation issues
    extra_cflags=["-O3"], # Optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization flags for CUDA compiler
)


class BasicBlockNew(nn.Module):
    expansion = 1

    def __init__(self, in_channels, out_channels, stride=1, downsample=None, fused_ops_module=None):
        """
        :param in_channels: Number of input channels
        :param out_channels: Number of output channels
        :param stride: Stride for the first convolutional layer
        :param downsample: Downsample layer for the shortcut connection
        :param fused_ops_module: The compiled fused_ops module from load_inline.
                                 This is passed to allow BasicBlockNew to use the custom kernels.
        """
        super(BasicBlockNew, self).__init__()
        if fused_ops_module is None:
            raise ValueError("fused_ops_module must be provided to BasicBlockNew")
        self.fused_ops = fused_ops_module

        # Original Conv2d and BatchNorm2d modules are kept to manage weights and running stats.
        # Their forward calls are replaced by calls to the fused kernels.
        self.conv1 = nn.Conv2d(in_channels, out_channels, kernel_size=3, stride=stride, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(out_channels)
        # self.relu is now fused into the custom kernel

        self.conv2 = nn.Conv2d(out_channels, out_channels, kernel_size=3, stride=1, padding=1, bias=False)
        self.bn2 = nn.BatchNorm2d(out_channels)
        # The final relu after addition is fused into the custom kernel

        self.downsample = downsample
        self.stride = stride

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, in_channels, height, width)
        :return: Output tensor, shape (batch_size, out_channels, height, width)
        """
        identity = x

        # Replace conv1 + bn1 + relu with fused_conv_bn_relu_cuda
        out = self.fused_ops.fused_conv_bn_relu_cuda(
            x,
            self.conv1.weight,
            self.bn1.weight,
            self.bn1.bias,
            self.bn1.running_mean,
            self.bn1.running_var,
            self.bn1.eps,
            self.conv1.stride[0], self.conv1.stride[1],
            self.conv1.padding[0], self.conv1.padding[1],
            self.conv1.dilation[0], self.conv1.dilation[1],
            self.conv1.groups
        )

        # Replace conv2 + bn2 with fused_conv_bn_cuda
        out = self.fused_ops.fused_conv_bn_cuda(
            out,
            self.conv2.weight,
            self.bn2.weight,
            self.bn2.bias,
            self.bn2.running_mean,
            self.bn2.running_var,
            self.bn2.eps,
            self.conv2.stride[0], self.conv2.stride[1],
