# Define the custom CUDA kernel for Conv2d + ReLU fusion
# This kernel performs a convolution using ATen's highly optimized `at::conv2d`
# (which leverages cuDNN for performance) and then applies an element-wise ReLU
# in a custom CUDA kernel. This fuses the two operations, reducing kernel launch
# overhead and memory bandwidth compared to separate Conv2d and ReLU operations.
conv2d_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h> // For at::conv2d

// CUDA kernel for element-wise ReLU activation
// It applies ReLU (max(0, x)) to each element in the input data.
__global__ void relu_kernel(float* data, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        data[idx] = fmaxf(0.0f, data[idx]);
    }
}

// C++ wrapper function that orchestrates the Conv2d + ReLU fusion.
// It takes the necessary parameters for a 2D convolution, performs the convolution
// using ATen's backend, and then launches the custom ReLU kernel on the result.
torch::Tensor conv2d_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias, // bias can be an undefined tensor if not used (bias=False in Conv2d)
    torch::IntArrayRef stride,
    torch::IntArrayRef padding,
    torch::IntArrayRef dilation,
    int64_t groups) {

    // Input validation: Ensure all tensors are on the CUDA device.
    TORCH_CHECK(input.is_cuda(), "Input tensor must be a CUDA tensor.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be a CUDA tensor.");
    if (bias.defined()) { // Check if bias tensor is provided (i.e., bias=True in Conv2d)
        TORCH_CHECK(bias.is_cuda(), "Bias tensor must be a CUDA tensor if defined.");
    }

    // Step 1: Perform convolution using ATen's highly optimized `at::conv2d`.
    // This function is equivalent to `F.conv2d` in Python and uses cuDNN when available.
    torch::Tensor conv_output = at::conv2d(input, weight, bias, stride, padding, dilation, groups);

    // Step 2: Apply ReLU using the custom CUDA kernel.
    // The ReLU operation is performed in-place on the `conv_output` tensor,
    // saving memory allocation and transfer for an intermediate tensor.
    auto size = conv_output.numel(); // Total number of elements in the output tensor.
    const int block_size = 256; // Standard block size for CUDA kernels.
    const int num_blocks = (size + block_size - 1) / block_size; // Calculate required number of blocks.

    // Input validation: Ensure the output tensor is float32, as the `relu_kernel` is specialized for floats.
    TORCH_CHECK(conv_output.scalar_type() == torch::kFloat, "Convolution output must be float32 for relu_kernel.");

    // Launch the CUDA kernel to apply ReLU.
    relu_kernel<<<num_blocks, block_size>>>(conv_output.data_ptr<float>(), size);

    return conv_output;
}
"""

# C++ header for the custom CUDA function, required by load_inline.
conv2d_relu_cpp_source = (
