        x_expand1x1 = self.conv2d_relu_op.conv2d_relu_cuda(
            x_squeezed,
            self.expand1x1_conv.weight,
            self.expand1x1_conv.bias,
            self.expand1x1_conv.stride,
            self.expand1x1_conv.padding,
            self.expand1x1_conv.dilation,
            self.expand1x1_conv.groups
        )

        # Replace `self.expand3x3_activation(self.expand3x3(x))` with the fused kernel call.
        x_expand3x3 = self.conv2d_relu_op.conv2d_relu_cuda(
            x_squeezed,
            self.expand3x3_conv.weight,
            self.expand3x3_conv.bias,
            self.expand3x3_conv.stride,
            self.expand3x3_conv.padding,
            self.expand3x3_conv.dilation,
            self.expand3x3_conv.groups
        )

        # The concatenation operation remains unchanged as it's efficient and not part of the fusion target.
        return torch.cat([x_expand1x1, x_expand3x3], 1)

