import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernel 1: Fused segsum and exp for L ---
# This kernel computes L[b,h,c,i,j] = exp(A_blocks_cumsum[b,h,c,i] - A_blocks_cumsum[b,h,c,j]) if j <= i, else 0.
# It takes the pre-computed cumsum of A_blocks as input.
segsum_exp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

__global__ void segsum_exp_kernel(
    const float* A_blocks_cumsum_ptr, 
    float* L_ptr, 
    int B, int H, int C, int L_block) {

    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long total_elements = (long long)B * H * C * L_block * L_block;

    if (idx < total_elements) {
        long long b = idx / ((long long)H * C * L_block * L_block);
        long long rem = idx % ((long long)H * C * L_block * L_block);
        long long h = rem / ((long long)C * L_block * L_block);
        rem = rem % ((long long)C * L_block * L_block);
        long long c = rem / ((long long)L_block * L_block);
        rem = rem % ((long long)L_block * L_block);
        long long i = rem / L_block;
        long long j = rem % L_block;

        if (j <= i) {
            // A_blocks_cumsum_ptr is (B, H, C, L_block)
            // Access A_blocks_cumsum[b, h, c, i] and A_blocks_cumsum[b, h, c, j]
            long long offset_i = b * H * C * L_block + h * C * L_block + c * L_block + i;
            long long offset_j = b * H * C * L_block + h * C * L_block + c * L_block + j;

            float val_i = A_blocks_cumsum_ptr[offset_i];
            float val_j = A_blocks_cumsum_ptr[offset_j];
            L_ptr[idx] = expf(val_i - val_j);
        } else {
            L_ptr[idx] = 0.0f;
        }
    }
}

torch::Tensor segsum_exp_cuda(torch::Tensor A_blocks_cumsum) {
    TORCH_CHECK(A_blocks_cumsum.is_cuda(), "A_blocks_cumsum must be a CUDA tensor");
    TORCH_CHECK(A_blocks_cumsum.is_contiguous(), "A_blocks_cumsum must be contiguous");
    TORCH_CHECK(A_blocks_cumsum.dim() == 4, "A_blocks_cumsum must be 4D");

    int B = A_blocks_cumsum.size(0);
    int H = A_blocks_cumsum.size(1);
    int C = A_blocks_cumsum.size(2);
    int L_block = A_blocks_cumsum.size(3);

    auto L = torch::zeros({B, H, C, L_block, L_block}, A_blocks_cumsum.options());

    const int block_size = 256;
    long long total_elements = (long long)B * H * C * L_block * L_block;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    segsum_exp_kernel<<<num_blocks, block_size>>>(
        A_blocks_cumsum.data_ptr<float>(), 
        L.data_ptr<float>(), 
        B, H, C, L_block);

    return L;
}
"""

segsum_exp_cpp_source = "torch::Tensor segsum_exp_cuda(torch::Tensor A_blocks_cumsum);"

segsum_exp_module = load_inline(
    name="segsum_exp_module",
    cpp_sources=segsum_exp_cpp_source,
    cuda_sources=segsum_exp_source,
    functions=["segsum_exp_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# --- Custom CUDA Kernel 2: Fused decay_states calculation ---
# This kernel computes decay_states[b,h,c,l] = exp(A_cumsum[b,h,c,L_block-1] - A_cumsum[b,h,c,l]).
# It takes the pre-computed A_cumsum as input.
decay_states_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

__global__ void decay_states_kernel(
    const float* A_cumsum_ptr, 
    float* decay_states_ptr, 
    int B, int H, int C, int L_block) {

    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long total_elements = (long long)B * H * C * L_block;

    if (idx < total_elements) {
        long long b = idx / ((long long)H * C * L_block);
        long long rem = idx % ((long long)H * C * L_block);
        long long h = rem / ((long long)C * L_block);
        rem = rem % ((long long)C * L_block);
        long long c = rem / L_block;
        long long l = rem % L_block;

        // A_cumsum_ptr is (B, H, C, L_block)
        // Access A_cumsum[b, h, c, L_block-1]
        long long offset_last = b * H * C * L_block + h * C * L_block + c * L_block + (L_block - 1);

        float A_cumsum_last_val = A_cumsum_ptr[offset_last];
        float A_cumsum_current_val = A_cumsum_ptr[idx]; // idx directly corresponds to [b,h,c,l]

        decay_states_ptr[idx] = expf(A_cumsum_last_val - A_cumsum_current_val);
    }
}

torch::Tensor decay_states_cuda(torch::Tensor A_cumsum) {
    TORCH_CHECK(A_cumsum.is_cuda(), "A_cumsum must be a CUDA tensor");
    TORCH_CHECK(A_cumsum.is_contiguous(), "A_cumsum must be contiguous");
    TORCH_CHECK(A_cumsum.dim() == 4, "A_cumsum must be 4D");

    int B = A_cumsum.size(0);
    int H = A_cumsum.size(1);
    int C = A_cumsum.size(2);
    int L_block = A_cumsum.size(3);

    auto decay_states = torch::zeros_like(A_cumsum);

    const int block_size = 256;
    long long total_elements = (long long)B * H * C * L_block;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    decay_states_kernel<<<num_blocks, block_size>>>(
        A_cumsum.data_ptr<float>(), 
        decay_states.data_ptr<float>(), 
        B, H, C, L_block);

    return decay_states;
}
"""

decay_states_cpp_source = "torch::Tensor decay_states_cuda(torch::Tensor A_cumsum);"

decay_states_module = load_inline(
    name="decay_states_module",
    cpp_sources=decay_states_cpp_source,
    cuda_sources=decay_states_source,
    functions=["decay_states_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# --- Custom CUDA Kernel 3: Fused segsum and exp for decay_chunk ---
# This kernel computes decay_chunk[b,h,i,j] = exp(val_i - val_j) if j <= i, else 0,
# where val_k = (k == 0) ? 0.0f : A_last_cumsum[b,h,k-1].
# It takes the pre-computed cumsum of A_cumsum[:, :, :, -1] as input.
segsum_exp_chunk_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

__global__ void segsum_exp_chunk_kernel(
    const float* A_last_cumsum_ptr, 
    float* decay_chunk_ptr, 
    int B, int H, int C_chunks) {

    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long total_elements = (long long)B * H * (C_chunks + 1) * (C_chunks + 1);

    if (idx < total_elements) {
        long long b = idx / ((long long)H * (C_chunks + 1) * (C_chunks + 1));
        long long rem = idx % ((long long)H * (C_chunks + 1) * (C_chunks + 1));
        long long h = rem / ((long long)(C_chunks + 1) * (C_chunks + 1));
        rem = rem % ((long long)(C_chunks + 1) * (C_chunks + 1));
        long long i = rem / (C_chunks + 1);
        long long j = rem % (C_chunks + 1);

        // A_last_cumsum_ptr is (B, H, C_chunks)
        // val_k = (k == 0) ? 0.0f : A_last_cumsum[b,h,k-1]
        float val_i = (i == 0) ? 0.0f : A_last_cumsum_ptr[b * H * C_chunks + h * C_chunks + (i - 1)];
        float val_j = (j == 0) ? 0.0f : A_last_cumsum_ptr[b * H * C_chunks + h * C_chunks + (j - 1)];

        if (j <= i) {
            decay_chunk_ptr[idx] = expf(val_i - val_j);
