    int H = A_last_cumsum.size(1);
    int C_chunks = A_last_cumsum.size(2);

    auto decay_chunk = torch::zeros({B, H, C_chunks + 1, C_chunks + 1}, A_last_cumsum.options());

    const int block_size = 256;
    long long total_elements = (long long)B * H * (C_chunks + 1) * (C_chunks + 1);
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    segsum_exp_chunk_kernel<<<num_blocks, block_size>>>(
        A_last_cumsum.data_ptr<float>(), 
        decay_chunk.data_ptr<float>(), 
        B, H, C_chunks);

    return decay_chunk;
}
"""

segsum_exp_chunk_cpp_source = "torch::Tensor segsum_exp_chunk_cuda(torch::Tensor A_last_cumsum);"

segsum_exp_chunk_module = load_inline(
    name="segsum_exp_chunk_module",
