import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused BatchNorm2d and ReLU
# This kernel performs the BatchNorm normalization and then applies the ReLU activation
# in a single pass, reducing memory bandwidth and kernel launch overhead.
fused_batchnorm_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf and fmaxf

// CUDA kernel for fused BatchNorm2d and ReLU
// Input: x (N, C, H, W), mean (C), var (C), gamma (C), beta (C), eps (scalar)
// Output: out (N, C, H, W)
__global__ void fused_batchnorm_relu_kernel(
    const float* x_ptr,
    const float* mean_ptr,
    const float* var_ptr,
    const float* gamma_ptr,
    const float* beta_ptr,
    float* out_ptr,
    int N, int C, int H, int W,
    float eps) {

    // Calculate a global index for the current thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    // Ensure the thread operates within the bounds of the tensor
    if (idx < total_elements) {
        // For a (N, C, H, W) tensor in row-major order, the channel index (C)
        // can be derived as follows:
        // idx = n * (C*H*W) + c * (H*W) + h * W + w
        // So, c_idx = (idx / (H * W)) % C;
        int c_idx = (idx / (H * W)) % C;

        // Access the input value for the current element
        float val_x = x_ptr[idx];

        // Access BatchNorm parameters (mean, variance, weight, bias)
        // which are channel-wise (C,)
        float val_mean = mean_ptr[c_idx];
        float val_var = var_ptr[c_idx];
        float val_gamma = gamma_ptr[c_idx];
        float val_beta = beta_ptr[c_idx];

        // Perform BatchNorm normalization: (x - mean) / sqrt(var + eps)
        float norm_val = (val_x - val_mean) / sqrtf(val_var + eps);

        // Apply affine transformation: norm_val * gamma + beta
        float scaled_shifted_val = norm_val * val_gamma + val_beta;

        // Apply ReLU activation: max(0, value)
        out_ptr[idx] = fmaxf(0.0f, scaled_shifted_val);
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor fused_batchnorm_relu_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps) {

    // Input validation: ensure tensors are on CUDA, are float, and are contiguous
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(mean.is_cuda(), "Input tensor 'mean' must be a CUDA tensor.");
    TORCH_CHECK(var.is_cuda(), "Input tensor 'var' must be a CUDA tensor.");
    TORCH_CHECK(gamma.is_cuda(), "Input tensor 'gamma' must be a CUDA tensor.");
    TORCH_CHECK(beta.is_cuda(), "Input tensor 'beta' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(mean.is_contiguous(), "Input tensor 'mean' must be contiguous.");
    TORCH_CHECK(var.is_contiguous(), "Input tensor 'var' must be contiguous.");
    TORCH_CHECK(gamma.is_contiguous(), "Input tensor 'gamma' must be contiguous.");
    TORCH_CHECK(beta.is_contiguous(), "Input tensor 'beta' must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor 'x' must be of float32 type.");
    TORCH_CHECK(mean.dtype() == torch::kFloat32, "Input tensor 'mean' must be of float32 type.");
    TORCH_CHECK(var.dtype() == torch::kFloat32, "Input tensor 'var' must be of float32 type.");
    TORCH_CHECK(gamma.dtype() == torch::kFloat32, "Input tensor 'gamma' must be of float32 type.");
    TORCH_CHECK(beta.dtype() == torch::kFloat32, "Input tensor 'beta' must be of float32 type.");


    // Get dimensions of the input tensor
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int total_elements = N * C * H * W;

    // Create an output tensor with the same shape and type as the input
    auto out = torch::empty_like(x);

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size; // Calculate number of blocks needed

    // Launch the CUDA kernel
    fused_batchnorm_relu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W,
        eps);

    // Check for any CUDA errors that occurred during kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
}
"""

# C++ header for the inline compilation, declaring the C++ wrapper function
fused_batchnorm_relu_cpp_source = (
    "torch::Tensor fused_batchnorm_relu_cuda("
    "torch::Tensor x, torch::Tensor mean, torch::Tensor var, "
    "torch::Tensor gamma, torch::Tensor beta, float eps);"
)

# Compile the inline CUDA code for fused BatchNorm2d and ReLU
# This compilation happens once when the script is loaded.
fused_batchnorm_relu_op = load_inline(
    name="fused_batchnorm_relu",
    cpp_sources=fused_batchnorm_relu_cpp_source,
    cuda_sources=fused_batchnorm_relu_source,
    functions=["fused_batchnorm_relu_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[""],
)

# Custom PyTorch Module to wrap the fused CUDA kernel
class FusedBatchNormReLU(nn.Module):
    def __init__(self, num_features, eps=1e-5, momentum=0.1, affine=True, track_running_stats=True):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum # Not directly used by the custom kernel in inference, but kept for compatibility
        self.affine = affine
        self.track_running_stats = track_running_stats

        # Initialize learnable parameters (weight and bias) if affine is True
        if self.affine:
            self.weight = nn.Parameter(torch.ones(num_features))
            self.bias = nn.Parameter(torch.zeros(num_features))
        else:
            self.register_parameter('weight', None)
            self.register_parameter('bias', None)

        # Initialize buffers for running mean and variance if tracking stats
        if self.track_running_stats:
            self.register_buffer('running_mean', torch.zeros(num_features))
            self.register_buffer('running_var', torch.ones(num_features))
        else:
            self.register_buffer('running_mean', None)
            self.register_buffer('running_var', None)

        # Store a reference to the compiled CUDA function
        self.fused_op = fused_batchnorm_relu_op.fused_batchnorm_relu_cuda

    def forward(self, x):
        # This custom kernel is specifically designed for inference mode (model.eval()).
        # In inference, BatchNorm uses its stored running_mean and running_var.
        # Implementing the full BatchNorm training logic (batch statistics computation,
        # running stats update, and backward pass) in a custom CUDA kernel is significantly
        # more complex and typically not the primary target for "speedup" requests,
        # which usually focus on optimizing inference performance.
        if self.training:
            # If the model is in training mode, we raise an error to indicate that
            # this custom kernel does not support training-time BatchNorm behavior.
            # A more complete solution for training would involve a much more complex
            # custom kernel or a fallback to PyTorch's native BatchNorm.
            raise NotImplementedError(
                "FusedBatchNormReLU custom kernel is designed for inference mode (model.eval()). "
                "Training mode with custom batchnorm logic (batch statistics computation and running stats update) "
                "is not implemented in this fused kernel. Please set model.eval() for inference."
            )

        # In evaluation mode, use the stored running_mean and running_var
        mean = self.running_mean
        var = self.running_var

        # Handle cases where affine=False (weight and bias are effectively 1 and 0)
        weight = self.weight if self.affine and self.weight is not None else torch.ones_like(mean)
        bias = self.bias if self.affine and self.bias is not None else torch.zeros_like(mean)

        # Call the fused CUDA kernel
        return self.fused_op(x, mean, var, weight, bias, self.eps)


class ModelNew(nn.Module):
    def __init__(self, input_channels, stages, block_widths, output_classes):
        """
        :param input_channels: int, Number of input channels for the first layer
        :param stages: int, Number of stages in the RegNet architecture
        :param block_widths: List[int], Width (number of channels) for each block in the stages
        :param output_classes: int, Number of output classes for classification
        """
        super(ModelNew, self).__init__()

        self.stages = stages
        self.block_widths = block_widths

        layers = []
        current_channels = input_channels

        # Construct the stages with their respective blocks
        for i in range(stages):
            layers.append(self._make_stage(current_channels, block_widths[i]))
            current_channels = block_widths[i]

        self.feature_extractor = nn.Sequential(*layers)

        # Final fully connected layer for classification
        self.fc = nn.Linear(block_widths[-1], output_classes)

    def _make_stage(self, in_channels, out_channels):
        """
        Creates a simple block for each stage, replacing BatchNorm2d and ReLU
        with the custom FusedBatchNormReLU module.
        :param in_channels: int, number of input channels
        :param out_channels: int, number of output channels
        :return: nn.Sequential block with convolutional layers
        """
        return nn.Sequential(
            nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
            FusedBatchNormReLU(out_channels), # Replaced nn.BatchNorm2d(out_channels) and nn.ReLU()
            nn.Conv2d(out_channels, out_channels, kernel_size=3, padding=1),
            FusedBatchNormReLU(out_channels), # Replaced nn.BatchNorm2d(out_channels) and nn.ReLU()
            nn.MaxPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x):
        """
        Forward pass through the RegNet model.
        :param x: torch.Tensor of shape (batch_size, input_channels, height, width)
        :return: torch.Tensor of shape (batch_size, output_classes)
        """
        x = self.feature_extractor(x)
        x = torch.mean(x, dim=[2, 3])  # Global Average Pooling
        x = self.fc(x)
        return x

