import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernel for NewGELU Activation ---
new_gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h> // For sqrtf, powf, tanhf, M_PI

__global__ void new_gelu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = in[idx];
        // Original formula: 0.5 * x * (1.0 + torch.tanh(math.sqrt(2.0 / math.pi) * (x + 0.044715 * torch.pow(x, 3.0))))
        out[idx] = 0.5f * x * (1.0f + tanhf(sqrtf(2.0f / M_PI) * (x + 0.044715f * powf(x, 3.0f))));
    }
}

torch::Tensor new_gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input tensor must be float32.");

    auto out = torch::empty_like(x);
    int size = x.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    new_gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

new_gelu_cpp_source = "torch::Tensor new_gelu_cuda(torch::Tensor x);"

# Compile the inline CUDA code for NewGELU
new_gelu_module = load_inline(
    name="new_gelu_module",
    cpp_sources=new_gelu_cpp_source,
    cuda_sources=new_gelu_source,
    functions=["new_gelu_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# --- Custom CUDA Kernel for Fused Attention Score Calculation (Scale + Mask + Softmax) ---
fused_attention_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For -FLT_MAX

// Helper for warp-level reduction (sum)
// From https://github.com/NVIDIA/apex/blob/master/csrc/fused_softmax/fused_softmax_cuda.cu
__device__ inline float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

// Helper for warp-level reduction (max)
__device__ inline float warpReduceMax(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    }
    return val;
}

__global__ void fused_attention_softmax_kernel(
    const float* attn_scores_raw,  // (B, nh, T, T)
    const unsigned char* bias_mask, // (1, 1, max_seqlen, max_seqlen) - bool tensor stored as uint8
    float* attn_weights,           // (B, nh, T, T) output
    float scale_factor,
    int B, int nh, int T,          // Batch size, num heads, current sequence length
    int max_seqlen                 // Max sequence length for bias_mask indexing
) {
    // Each block processes one row of the attention matrix (T elements)
    // The grid is (B * nh * T) blocks
    int row_idx_global = blockIdx.x; // This is the index for (b, h, t_row)

    int b = row_idx_global / (nh * T);
    int h = (row_idx_global / T) % nh;
    int t_row = row_idx_global % T; // Current query position

    // Pointers for the current row
    const float* input_row_ptr = attn_scores_raw + (b * nh * T * T + h * T * T + t_row * T);
    float* output_row_ptr = attn_weights + (b * nh * T * T + h * T * T + t_row * T);

    // Shared memory for block-wise max and sum reduction
    __shared__ float s_row_max;
    __shared__ float s_row_sum_exp;

    float thread_max_val = -FLT_MAX;

    // First pass: calculate scaled, masked values and find max for numerical stability
    for (int t_col = threadIdx.x; t_col < T; t_col += blockDim.x) {
        float val = input_row_ptr[t_col] * scale_factor;

        // Apply causal mask: if bias_mask[0, 0, t_row, t_col] == 0, set to -FLT_MAX
        // bias_mask is (1, 1, max_seqlen, max_seqlen). Indexing: bias_mask[0][0][t_row][t_col]
        // which is equivalent to bias_mask[t_row * max_seqlen + t_col] in flattened memory.
        if (bias_mask[t_row * max_seqlen + t_col] == 0) { // 0 means mask, 1 means keep
            val = -FLT_MAX; // Use -FLT_MAX for masked values
        }
        if (val > thread_max_val) {
            thread_max_val = val;
        }
    }

    // Reduce max across the block
    thread_max_val = warpReduceMax(thread_max_val);
    if (threadIdx.x == 0) {
        s_row_max = thread_max_val;
    }
    __syncthreads(); // Ensure s_row_max is visible to all threads

    float thread_sum_exp_val = 0.0f;

    // Second pass: calculate exp(val - max) and sum
    for (int t_col = threadIdx.x; t_col < T; t_col += blockDim.x) {
        float val = input_row_ptr[t_col] * scale_factor;
        if (bias_mask[t_row * max_seqlen + t_col] == 0) {
            val = -FLT_MAX;
        }

        // Apply max for numerical stability and then exp
        val = expf(val - s_row_max);
        thread_sum_exp_val += val;
    }

    // Reduce sum_exp across the block
    thread_sum_exp_val = warpReduceSum(thread_sum_exp_val);
    if (threadIdx.x == 0) {
        s_row_sum_exp = thread_sum_exp_val;
    }
    __syncthreads(); // Ensure s_row_sum_exp is visible to all threads

    // Final pass: calculate softmax and write to output
    for (int t_col = threadIdx.x; t_col < T; t_col += blockDim.x) {
        float val = input_row_ptr[t_col] * scale_factor;
        if (bias_mask[t_row * max_seqlen + t_col] == 0) {
            val = -FLT_MAX;
        }

        val = expf(val - s_row_max);
        output_row_ptr[t_col] = val / s_row_sum_exp;
    }
}
"""

fused_attention_softmax_cpp_source = (
    "torch::Tensor fused_attention_softmax_cuda(torch::Tensor attn_scores_raw, torch::Tensor bias_mask, float scale_factor, int max_seqlen_param);"
)

# Compile the inline CUDA code for fused attention softmax
fused_attention_module = load_inline(
    name="fused_attention_module",
    cpp_sources=fused_attention_softmax_cpp_source,
    cuda_sources=fused_attention_softmax_source,
    functions=["fused_attention_softmax_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


# --- Optimized Model Architecture ---

class NewGELUNew(nn.Module):
    """
    Optimized NewGELU activation function using a custom CUDA kernel.
    """
    def __init__(self, custom_gelu_op):
        super(NewGELUNew, self).__init__()
        self.custom_gelu_op = custom_gelu_op

    def forward(self, x):
        return self.custom_gelu_op.new_gelu_cuda(x)

class CausalSelfAttentionNew(nn.Module):
    """
    A vanilla multi-head masked self-attention layer with a projection at the end.
    Uses a custom CUDA kernel for fused attention score calculation (scale + mask + softmax).
    """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen, fused_attention_op):
        super().__init__()
        assert n_embd % n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        # causal mask to ensure that attention is only applied to the left in the input sequence
        # Store as bool tensor for direct use with unsigned char* in CUDA kernel
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen, dtype=torch.bool))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd
        self.max_seqlen = max_seqlen # Store max_seqlen for kernel to correctly index bias
        self.fused_attention_op = fused_attention_op

    def forward(self, x):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, k ,v  = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        attn_scores_raw = q @ k.transpose(-2, -1)
        scale_factor = (1.0 / math.sqrt(k.size(-1)))

        # Use custom fused kernel for scaling, masking, and softmax
        # Pass the full bias buffer and max_seqlen for correct indexing within the kernel
        att = self.fused_attention_op.fused_attention_softmax_cuda(
            attn_scores_raw,
            self.bias, # Full bias tensor (1, 1, max_seqlen, max_seqlen)
            scale_factor,
            self.max_seqlen # Original max_seqlen for kernel indexing
        )

        att = self.attn_dropout(att)
        y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y

class ModelNew(nn.Module):
    """ An optimized Transformer block using custom CUDA kernels. """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        # Load custom kernel modules
        self.new_gelu_op = new_gelu_module
        self.fused_attention_op = fused_attention_module

        self.ln_1 = nn.LayerNorm(n_embd)
        # Use the optimized CausalSelfAttention
        self.attn = CausalSelfAttentionNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen, self.fused_attention_op)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELUNew(self.new_gelu_op), # Use the optimized NewGELU
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x)))) # MLP forward

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x

