# Define the custom CUDA kernel for fused linear layer on the last timestep
fused_linear_last_timestep_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Fused kernel for extracting the last timestep's output,
// performing a linear transformation (matrix multiplication + bias addition).
// Each thread computes one element of the output matrix (batch_size x output_size).
__global__ void fused_linear_last_timestep_kernel(
    const float* lstm_output_ptr, // Input: (batch_size, seq_length, hidden_size)
    const float* fc_weight_ptr,   // Input: (output_size, hidden_size)
    const float* fc_bias_ptr,     // Input: (output_size,)
    float* fc_output_ptr,         // Output: (batch_size, output_size)
