    int output_size
) {
    // Calculate global thread ID in X and Y dimensions
    int b = blockIdx.y * blockDim.y + threadIdx.y; // Batch index
    int o = blockIdx.x * blockDim.x + threadIdx.x; // Output feature index

    // Check bounds to ensure threads don't access out-of-range memory
    if (b < batch_size && o < output_size) {
        float sum = 0.0f;

        // Calculate the starting address of the last timestep's hidden state for the current batch 'b'.
        // The LSTM output is stored as (batch, sequence, hidden).
        // We need the element at index [b, seq_length - 1, h].
        // Stride for batch: seq_length * hidden_size
        // Stride for sequence: hidden_size
        // Using long for pointer arithmetic to prevent potential overflow with very large tensor dimensions.
        const float* current_batch_last_h_ptr = lstm_output_ptr + (long)b * seq_length * hidden_size + (long)(seq_length - 1) * hidden_size;

        // Calculate the starting address of the weight row for the current output feature 'o'.
        // The FC weight is stored as (output_size, hidden_size).
        const float* current_output_weight_ptr = fc_weight_ptr + (long)o * hidden_size;

        // Perform the dot product between the last timestep's hidden state and the weight row.
        // This is the matrix multiplication part.
        for (int h = 0; h < hidden_size; ++h) {
            sum += current_batch_last_h_ptr[h] * current_output_weight_ptr[h];
        }

        // Add the bias term for the current output feature 'o'.
        sum += fc_bias_ptr[o];

        // Store the final computed value in the output tensor.
        fc_output_ptr[b * output_size + o] = sum;
    }
