import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math # Required for parameter initialization

# Define the custom CUDA kernel for GRU cell element-wise operations
# This kernel fuses the sigmoid, tanh, and final hidden state update operations
# for a single GRU cell, reducing memory bandwidth and kernel launch overhead.
gru_cell_fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanh and sigmoid functions

// Device function for sigmoid activation
__device__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// Device function for tanh activation
__device__ float tanh_approx(float x) {
    // Using standard tanhf from cmath for GPU
    return tanhf(x);
}

// CUDA kernel to perform the fused GRU cell computations
// It takes the pre-computed input-to-hidden (gi) and hidden-to-hidden (gh)
// gate sums, the previous hidden state (h_prev), and computes the new hidden state (h_new).
__global__ void gru_cell_fused_kernel(
    const float* gi_ptr, const float* gh_ptr, const float* h_prev_ptr,
    float* h_new_ptr, int batch_size, int hidden_size) {

    // Calculate a unique global index for each thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure thread operates within valid data bounds
    if (idx < batch_size * hidden_size) {
        int b = idx / hidden_size; // Batch index
        int h = idx % hidden_size; // Hidden dimension index

        // Pointers for current batch and hidden dimension
        // gi and gh are shaped (batch_size, 3 * hidden_size)
        // h_prev and h_new are shaped (batch_size, hidden_size)

        // Calculate r_t (reset gate)
        // The first 'hidden_size' elements of the 3*hidden_size block correspond to the reset gate
        float gi_r = gi_ptr[b * (3 * hidden_size) + h];
        float gh_r = gh_ptr[b * (3 * hidden_size) + h];
        float r_t = sigmoid(gi_r + gh_r);

        // Calculate z_t (update gate)
        // The second 'hidden_size' elements correspond to the update gate
        float gi_z = gi_ptr[b * (3 * hidden_size) + hidden_size + h];
        float gh_z = gh_ptr[b * (3 * hidden_size) + hidden_size + h];
        float z_t = sigmoid(gi_z + gh_z);

        // Calculate n_t (new candidate hidden state)
        // The third 'hidden_size' elements correspond to the new candidate hidden state
        float gi_n = gi_ptr[b * (3 * hidden_size) + 2 * hidden_size + h];
        float gh_n = gh_ptr[b * (3 * hidden_size) + 2 * hidden_size + h];
        float n_t = tanh_approx(gi_n + r_t * gh_n); // Note: r_t is applied here as per GRU equations

        // Calculate h_t (new hidden state)
        float h_prev_val = h_prev_ptr[b * hidden_size + h];
        float h_new_val = (1.0f - z_t) * n_t + z_t * h_prev_val;

        // Store the computed new hidden state
        h_new_ptr[b * hidden_size + h] = h_new_val;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor gru_cell_fused_cuda(
    torch::Tensor gi, torch::Tensor gh, torch::Tensor h_prev,
    int batch_size, int hidden_size) {

    // Ensure input tensors are contiguous in memory and on CUDA device
    // This is crucial for correct pointer arithmetic within the kernel.
    gi = gi.contiguous();
    gh = gh.contiguous();
    h_prev = h_prev.contiguous();

    // Allocate the output tensor on the same device and with the same data type as inputs
    auto h_new = torch::empty({batch_size, hidden_size}, gi.options());

    // Determine grid and block dimensions for kernel launch
    const int num_elements = batch_size * hidden_size;
    const int block_size = 256; // A common block size for CUDA kernels
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    gru_cell_fused_kernel<<<num_blocks, block_size>>>(
        gi.data_ptr<float>(), gh.data_ptr<float>(), h_prev.data_ptr<float>(),
        h_new.data_ptr<float>(), batch_size, hidden_size);

    return h_new;
}
"""

# C++ header for the CUDA function
gru_cell_fused_cpp_source = (
    "torch::Tensor gru_cell_fused_cuda("
    "torch::Tensor gi, torch::Tensor gh, torch::Tensor h_prev, "
    "int batch_size, int hidden_size);"
)

# Compile the inline CUDA code using torch.utils.cpp_extension.load_inline
gru_cell_fused = load_inline(
    name="gru_cell_fused",
    cpp_sources=gru_cell_fused_cpp_source,
    cuda_sources=gru_cell_fused_source,
    functions=["gru_cell_fused_cuda"],
    verbose=False, # Set to True for debugging compilation issues
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization flags for NVCC compiler
)


class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        """
        Custom GRU implementation replacing the element-wise operations of a GRU cell
        with a fused CUDA kernel.

        :param input_size: The number of expected features in the input x
        :param hidden_size: The number of features in the hidden state h
        :param num_layers: Number of recurrent layers (default: 3)
        :param bias: If False, then the layer does not use bias weights b_ih and b_hh (default: True)
        :param batch_first: If True, then the input and output tensors are provided as (batch, seq, feature) (default: False)
                            Note: Internal processing assumes batch_first=False and transposes if needed.
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.bias = bias
        self.batch_first = batch_first

        # Store the custom kernel function from the compiled module
        self.gru_cell_fused_op = gru_cell_fused.gru_cell_fused_cuda

        # Manually create parameters for each layer, similar to nn.GRU
        self.weight_ih_l = nn.ParameterList() # Input-to-hidden weights
        self.weight_hh_l = nn.ParameterList() # Hidden-to-hidden weights
        self.bias_ih_l = nn.ParameterList()   # Input-to-hidden biases
        self.bias_hh_l = nn.ParameterList()   # Hidden-to-hidden biases

        for layer in range(num_layers):
            # Input size for the current layer (input_size for first layer, hidden_size for subsequent)
            layer_input_size = input_size if layer == 0 else hidden_size

            # weight_ih: (3 * hidden_size, layer_input_size)
            self.weight_ih_l.append(nn.Parameter(torch.empty(3 * hidden_size, layer_input_size)))
            # weight_hh: (3 * hidden_size, hidden_size)
            self.weight_hh_l.append(nn.Parameter(torch.empty(3 * hidden_size, hidden_size)))

            if bias:
                # bias_ih: (3 * hidden_size)
                self.bias_ih_l.append(nn.Parameter(torch.empty(3 * hidden_size)))
                # bias_hh: (3 * hidden_size)
                self.bias_hh_l.append(nn.Parameter(torch.empty(3 * hidden_size)))
            else:
                # Append None if bias is False to maintain consistent list indexing
                self.bias_ih_l.append(None)
                self.bias_hh_l.append(None)

        self.reset_parameters()

    def reset_parameters(self):
        # Initialize parameters using a common strategy (uniform distribution)
        # This mimics PyTorch's default GRU initialization
        stdv = 1.0 / math.sqrt(self.hidden_size)
        for layer in range(self.num_layers):
            nn.init.uniform_(self.weight_ih_l[layer], -stdv, stdv)
            nn.init.uniform_(self.weight_hh_l[layer], -stdv, stdv)
            if self.bias:
                nn.init.uniform_(self.bias_ih_l[layer], -stdv, stdv)
                nn.init.uniform_(self.bias_hh_l[layer], -stdv, stdv)

    def forward(self, x, h0=None):
        """
        :param x: The input tensor, shape (seq_len, batch_size, input_size) if batch_first=False,
                  otherwise (batch_size, seq_len, input_size)
        :param h0: The initial hidden state for the input sequence, shape (num_layers, batch_size, hidden_size)
                   (default: None, initializes to zeros)
        :return: output: The output features (h_t) from the last layer of the GRU, for each t.
                         Shape (seq_len, batch_size, hidden_size) if batch_first=False,
                         otherwise (batch_size, seq_len, hidden_size)
        """
        # If batch_first is True, transpose input to (seq_len, batch_size, input_size) for internal processing
        if self.batch_first:
            x = x.transpose(0, 1).contiguous()

        seq_len, batch_size, _ = x.shape

        # Initialize hidden state if not provided
        if h0 is None:
            # Create a zero-initialized hidden state on the same device and dtype as input x
            h_n = torch.zeros(self.num_layers, batch_size, self.hidden_size, device=x.device, dtype=x.dtype)
        else:
            # Use provided h0, ensure it's on the correct device and clone to avoid modifying original
            h_n = h0.clone().to(x.device).to(x.dtype) 

        output_sequence = [] # List to store the output of the last layer for each time step

        # Loop through each time step in the sequence
        for t in range(seq_len):
            input_t = x[t] # (batch_size, input_size) for the current time step

            # List to store hidden states for the current time step across all layers
            # h_current_timestep_layers[k] will hold h_k_t (output of layer k at time t)
            h_current_timestep_layers = [] 

            # Loop through each layer
            for layer in range(self.num_layers):
                # Determine the input for the current layer
                # For the first layer (layer 0), input comes from the sequence `x`
                # For subsequent layers, input is the output of the previous layer at the current time step
                if layer == 0:
                    layer_input = input_t
                else:
                    layer_input = h_current_timestep_layers[-1] # Output of the previous layer

                # Get the previous hidden state for the current layer (from the previous time step)
                h_prev_layer = h_n[layer] # (batch_size, hidden_size)

                # Compute input-to-hidden gates (W_ih @ x_t + b_ih)
                # F.linear performs matrix multiplication and bias addition efficiently
                gi = F.linear(layer_input, self.weight_ih_l[layer], self.bias_ih_l[layer]) # (batch_size, 3*hidden_size)

                # Compute hidden-to-hidden gates (W_hh @ h_{t-1} + b_hh)
                gh = F.linear(h_prev_layer, self.weight_hh_l[layer], self.bias_hh_l[layer]) # (batch_size, 3*hidden_size)

                # Call the custom fused GRU cell kernel for element-wise operations
                # This replaces multiple PyTorch operations (chunk, sigmoid, tanh, element-wise arithmetic)
                h_new_layer = self.gru_cell_fused_op(
                    gi, gh, h_prev_layer, batch_size, self.hidden_size
                ) # (batch_size, hidden_size)

                h_current_timestep_layers.append(h_new_layer) # Store for next layer's input
                h_n[layer] = h_new_layer # Update h_n for the next time step's initial hidden state

            # The output of the GRU at time `t` is the output of the last layer at time `t`
            output_sequence.append(h_current_timestep_layers[-1]) 

        # Stack the outputs from all time steps to form the final output sequence
        output = torch.stack(output_sequence, dim=0) # (seq_len, batch_size, hidden_size)

        # If batch_first was True, transpose output back to (batch_size, seq_len, hidden_size)
        if self.batch_first:
            output = output.transpose(0, 1).contiguous()

        # The original model returns only the output sequence
        return output

