import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused RNN i2h + Tanh
# This kernel replaces the torch.cat, nn.Linear (i2h), and nn.Tanh operations
# within a single recurrent step.
rnn_fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf

// Fused kernel for computing: h_curr = tanh( (x_t || h_prev) @ W_i2h.T + b_i2h )
// where '||' denotes concatenation.
__global__ void rnn_i2h_tanh_kernel(
    const float* x_t,          // Input tensor for current time step (batch_size, input_size)
    const float* h_prev,       // Previous hidden state (batch_size, hidden_size)
    const float* W_i2h,        // Weight matrix for input-to-hidden (hidden_size, input_size + hidden_size)
    const float* b_i2h,        // Bias vector for input-to-hidden (hidden_size)
    float* h_curr,             // Output: Current hidden state (batch_size, hidden_size)
    int batch_size,
    int input_size,
    int hidden_size
) {
    // Each thread computes one element of the h_curr (current hidden state) tensor.
    // We use a 2D grid to parallelize across batch_size and hidden_size dimensions.
    int b = blockIdx.y * blockDim.y + threadIdx.y; // Batch index
    int h = blockIdx.x * blockDim.x + threadIdx.x; // Hidden state feature index

    if (b < batch_size && h < hidden_size) {
        float sum = 0.0f;

        // Perform the dot product for the linear transformation (combined input @ W_i2h.T).
        // This implicitly handles the concatenation of x_t and h_prev.
        // The effective combined input vector for a given batch item 'b' has size (input_size + hidden_size).
        // W_i2h is (hidden_size, input_size + hidden_size).
        // We are computing h_curr[b, h] = sum_k( combined[b, k] * W_i2h[h, k] )

        // Part 1: Contribution from the current input x_t
        for (int k = 0; k < input_size; ++k) {
            // Access x_t[b][k] and W_i2h[h][k]
            sum += x_t[b * input_size + k] * W_i2h[h * (input_size + hidden_size) + k];
        }

        // Part 2: Contribution from the previous hidden state h_prev
        for (int k = 0; k < hidden_size; ++k) {
            // Access h_prev[b][k] and W_i2h[h][input_size + k]
            sum += h_prev[b * hidden_size + k] * W_i2h[h * (input_size + hidden_size) + input_size + k];
        }

        // Add the bias term
        sum += b_i2h[h];

        // Apply the Tanh activation function
        h_curr[b * hidden_size + h] = tanhf(sum);
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor rnn_i2h_tanh_cuda(
    torch::Tensor x_t,
    torch::Tensor h_prev,
    torch::Tensor W_i2h,
    torch::Tensor b_i2h
) {
    // Input validation: Ensure tensors are on CUDA, contiguous, and of float type.
    TORCH_CHECK(x_t.is_cuda() && h_prev.is_cuda() && W_i2h.is_cuda() && b_i2h.is_cuda(), "All tensors must be CUDA tensors");
    TORCH_CHECK(x_t.is_contiguous() && h_prev.is_contiguous() && W_i2h.is_contiguous() && b_i2h.is_contiguous(), "All tensors must be contiguous");
    TORCH_CHECK(x_t.dtype() == torch::kFloat && h_prev.dtype() == torch::kFloat && W_i2h.dtype() == torch::kFloat && b_i2h.dtype() == torch::kFloat, "All tensors must be float");

    int batch_size = x_t.size(0);
    int input_size = x_t.size(1);
    int hidden_size = h_prev.size(1);

    // Allocate output tensor for the current hidden state
    auto h_curr = torch::empty({batch_size, hidden_size}, x_t.options());

    // Define grid and block dimensions for kernel launch.
    // A block size of 32x8 (256 threads) is a common choice for NVIDIA GPUs.
    const int block_size_x = 32; // Threads per block along the hidden_size dimension
    const int block_size_y = 8;  // Threads per block along the batch_size dimension
    dim3 block_dim(block_size_x, block_size_y);

    // Calculate the number of blocks needed to cover the entire output tensor.
    dim3 grid_dim(
        (hidden_size + block_size_x - 1) / block_size_x, // Blocks for hidden_size
        (batch_size + block_size_y - 1) / block_size_y    // Blocks for batch_size
    );

    // Launch the CUDA kernel
    rnn_i2h_tanh_kernel<<<grid_dim, block_dim>>>(
        x_t.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        W_i2h.data_ptr<float>(),
        b_i2h.data_ptr<float>(),
        h_curr.data_ptr<float>(),
        batch_size,
        input_size,
        hidden_size
    );

    return h_curr;
}
"""

