        self.i2h_bias = nn.Parameter(torch.empty(hidden_size))

        # Initialize weights and biases similar to nn.Linear's default initialization.
        # Kaiming uniform for weights, uniform for biases.
        nn.init.kaiming_uniform_(self.i2h_weight, a=5**0.5)
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.i2h_weight)
        bound = 1 / (fan_in**0.5)
        nn.init.uniform_(self.i2h_bias, -bound, bound)

        # The h2o layer remains a standard nn.Linear, as it's a separate operation
        # and fusing it would involve a second GEMM, making the custom kernel more complex.
        self.h2o = nn.Linear(hidden_size, output_size)

        # Store the loaded custom kernel module for use in the forward pass.
        self.rnn_fused_op = rnn_fused_ops

    def forward(self, x: torch.Tensor, h0: torch.Tensor) -> torch.Tensor:
        """
        Forward pass of the Vanilla RNN using custom CUDA kernels.

        :param x: Input tensor of shape (seq_len, batch_size, input_size)
        :param h0: Initial hidden state tensor of shape (batch_size, hidden_size)
        :return: Output tensor of shape (seq_len, batch_size, output_size)
        """
        seq_len, batch_size, _ = x.size()
        hidden = h0.to(x.device) # Ensure initial hidden state is on the correct device
        outputs = []

        for t in range(seq_len):
            # Use the custom fused kernel for the i2h transformation and Tanh activation.
            # This single call replaces:
            # 1. torch.cat((x[t], hidden), dim=1)
            # 2. self.i2h(combined) (which is a linear layer: matrix multiplication + bias)
            # 3. self.tanh(...) (the activation function)
            hidden = self.rnn_fused_op.rnn_i2h_tanh_cuda(
                x[t], hidden, self.i2h_weight, self.i2h_bias
            )

            # Compute output using the standard nn.Linear layer.
            output = self.h2o(hidden)
            outputs.append(output)

        # Stack all individual time step outputs to form the final output tensor.
        return torch.stack(outputs, dim=0)

