import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for fused operations
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, expf, fmaxf

// Fused BatchNorm + ReLU kernel
// This kernel applies BatchNorm using provided running statistics (suitable for inference)
// followed by a ReLU activation.
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* running_mean,
    const float* running_var,
    float epsilon,
    float* output,
    int total_elements,
    int C, int H, int W) { // C, H, W are for channel indexing in NCHW format

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Calculate channel index for the current element (assuming NCHW layout)
        // idx = n*C*H*W + c*H*W + h*W + w
        // c = (idx / (H*W)) % C
        int c = (idx / (H * W)) % C;

        float val = input[idx];
        float mean = running_mean[c];
        float var = running_var[c];
        float gamma = weight[c];
        float beta = bias[c];

        // BatchNorm calculation: y = (x - mean) / sqrt(var + eps) * gamma + beta
        float bn_val = (val - mean) / sqrtf(var + epsilon) * gamma + beta;

        // ReLU activation: max(0, y)
        output[idx] = fmaxf(0.0f, bn_val);
    }
}

// Fused ReLU kernel
// This kernel applies a ReLU activation element-wise.
__global__ void fused_relu_kernel(const float* input, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        output[idx] = fmaxf(0.0f, input[idx]);
    }
}

// Fused Sigmoid kernel
// This kernel applies a Sigmoid activation element-wise.
__global__ void fused_sigmoid_kernel(const float* input, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        output[idx] = 1.0f / (1.0f + expf(-input[idx]));
    }
}

// C++ wrapper for Fused BatchNorm + ReLU
torch::Tensor fused_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double epsilon) {

    // Input validation
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(running_mean.is_cuda(), "running_mean must be a CUDA tensor");
    TORCH_CHECK(running_var.is_cuda(), "running_var must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(running_mean.is_contiguous(), "running_mean must be contiguous");
    TORCH_CHECK(running_var.is_contiguous(), "running_var must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(running_mean.dtype() == torch::kFloat32, "running_mean must be float32");
    TORCH_CHECK(running_var.dtype() == torch::kFloat32, "running_var must be float32");

    // Get tensor dimensions
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int total_elements = N * C * H * W;

    // Create output tensor
    auto output = torch::empty_like(input);

    // Configure kernel launch parameters
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the kernel
    fused_bn_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
