}

// C++ wrapper for Fused ReLU
torch::Tensor fused_relu_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");

    int total_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elements
    );
    return output;
}

// C++ wrapper for Fused Sigmoid
torch::Tensor fused_sigmoid_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");

    int total_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_sigmoid_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elements
    );
    return output;
}
"""

# C++ header for the inline compilation
cpp_source = """
torch::Tensor fused_bn_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor running_mean, torch::Tensor running_var, double epsilon);
torch::Tensor fused_relu_cuda(torch::Tensor input);
torch::Tensor fused_sigmoid_cuda(torch::Tensor input);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_bn_relu_cuda", "fused_relu_cuda", "fused_sigmoid_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Use fast math for CUDA for potential speedup
)


# Wrapper Modules for Fused Operations
# These modules encapsulate the custom CUDA calls and manage the parameters
class FusedBnReLUModule(nn.Module):
    def __init__(self, bn_layer, fused_ops_handle):
        super().__init__()
        self.bn = bn_layer
        # Store the custom CUDA function
        self.fused_op = fused_ops_handle.fused_bn_relu_cuda

    def forward(self, x):
        # Pass the input and BatchNorm parameters to the custom kernel
        # Note: This implementation uses the running_mean and running_var from the BatchNorm layer.
        # This is suitable for inference. For training, a more complex kernel would be needed
        # to compute batch statistics and update running statistics.
        return self.fused_op(
            x,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.eps
        )

class FusedReLUModule(nn.Module):
    def __init__(self, fused_ops_handle):
        super().__init__()
        self.fused_op = fused_ops_handle.fused_relu_cuda

    def forward(self, x):
        return self.fused_op(x)

class FusedSigmoidModule(nn.Module):
    def __init__(self, fused_ops_handle):
        super().__init__()
        self.fused_op = fused_ops_handle.fused_sigmoid_cuda

    def forward(self, x):
        return self.fused_op(x)


# Custom MBConvBlock to integrate fused operations
class MBConvBlockNew(nn.Module):
    def __init__(self, in_channels, out_channels, stride, expand_ratio, fused_ops_handle):
        super().__init__()
        self.fused_ops = fused_ops_handle

        expanded_channels = in_channels * expand_ratio

        # Expansion phase: Conv2d -> BatchNorm2d -> ReLU (fused)
        self.expand_conv = None
        self.expand_bn_relu = None
        if expand_ratio != 1:
            self.expand_conv = nn.Conv2d(in_channels, expanded_channels, kernel_size=1, stride=1, padding=0, bias=False)
            self.expand_bn = nn.BatchNorm2d(expanded_channels)
            self.expand_bn_relu = FusedBnReLUModule(self.expand_bn, self.fused_ops)

        # Depthwise convolution phase: Conv2d -> BatchNorm2d -> ReLU (fused)
        self.depthwise_conv = nn.Conv2d(expanded_channels, expanded_channels, kernel_size=3, stride=stride, padding=1, groups=expanded_channels, bias=False)
        self.depthwise_bn = nn.BatchNorm2d(expanded_channels)
        self.depthwise_bn_relu = FusedBnReLUModule(self.depthwise_bn, self.fused_ops)

        # Squeeze and Excitation (SE) block
        # AdaptiveAvgPool2d (PyTorch) -> Conv2d -> ReLU (fused) -> Conv2d -> Sigmoid (fused)
        self.se_avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.se_reduce_conv = nn.Conv2d(expanded_channels, expanded_channels // 4, kernel_size=1, stride=1, padding=0, bias=False)
        self.se_relu = FusedReLUModule(self.fused_ops) # Fused ReLU after reduction convolution
        self.se_expand_conv = nn.Conv2d(expanded_channels // 4, expanded_channels, kernel_size=1, stride=1, padding=0, bias=False)
        self.se_sigmoid = FusedSigmoidModule(self.fused_ops) # Fused Sigmoid after expansion convolution

        # Output phase: Conv2d -> BatchNorm2d (no ReLU here in the original block definition)
        self.project_conv = nn.Conv2d(expanded_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=False)
        self.project_bn = nn.BatchNorm2d(out_channels)

    def forward(self, x):
        # Expansion phase
        if self.expand_conv is not None:
            x = self.expand_conv(x)
            x = self.expand_bn_relu(x)

        # Depthwise convolution
        x = self.depthwise_conv(x)
        x = self.depthwise_bn_relu(x)

        # Squeeze and Excitation
        se_tensor = self.se_avgpool(x)
        se_tensor = self.se_reduce_conv(se_tensor)
        se_tensor = self.se_relu(se_tensor) # Custom fused ReLU
        se_tensor = self.se_expand_conv(se_tensor)
        se_tensor = self.se_sigmoid(se_tensor) # Custom fused Sigmoid
        x = x * se_tensor # Element-wise multiplication (PyTorch operator)

        # Output phase
        x = self.project_conv(x)
        x = self.project_bn(x)

        return x


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        EfficientNetB2 architecture implementation with custom CUDA kernels.

        :param num_classes: The number of output classes (default is 1000 for ImageNet).
        """
        super(ModelNew, self).__init__()

        # Store the loaded fused operations
        self.fused_ops = fused_ops

        # Define the EfficientNetB2 architecture components
        # Initial block: Conv2d -> BatchNorm2d -> ReLU (fused)
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)
        self.fused_bn1_relu = FusedBnReLUModule(self.bn1, self.fused_ops) # Custom fused module

        # Define the MBConv blocks using the new custom block
        self.mbconv1 = self._make_mbconv_block(32, 96, 1, 3)
        self.mbconv2 = self._make_mbconv_block(96, 144, 2, 6)
        self.mbconv3 = self._make_mbconv_block(144, 192, 2, 6)
        self.mbconv4 = self._make_mbconv_block(192, 288, 2, 6)
        self.mbconv5 = self._make_mbconv_block(288, 384, 1, 6)

        # Final layers: Conv2d -> BatchNorm2d -> ReLU (fused) -> AvgPool -> Flatten -> Linear
        self.conv_final = nn.Conv2d(384, 1408, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn_final = nn.BatchNorm2d(1408)
        self.fused_bn_final_relu = FusedBnReLUModule(self.bn_final, self.fused_ops) # Custom fused module
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = nn.Linear(1408, num_classes)

    def _make_mbconv_block(self, in_channels, out_channels, stride, expand_ratio):
        """
        Helper function to create a MBConv block using the custom MBConvBlockNew.
        """
        return MBConvBlockNew(in_channels, out_channels, stride, expand_ratio, self.fused_ops)

    def forward(self, x):
        """
        Forward pass of the EfficientNetB2 model with custom CUDA kernels.

        :param x: The input tensor, shape (batch_size, 3, 224, 224)
        :return: The output tensor, shape (batch_size, num_classes)
        """
        # Initial block
        x = self.conv1(x)
        x = self.fused_bn1_relu(x) # Replaced self.relu(self.bn1(self.conv1(x)))

        # MBConv blocks
        x = self.mbconv1(x)
        x = self.mbconv2(x)
        x = self.mbconv3(x)
        x = self.mbconv4(x)
        x = self.mbconv5(x)

        # Final layers
        x = self.conv_final(x)
        x = self.fused_bn_final_relu(x) # Replaced self.relu(self.bn_final(self.conv_final(x)))
        x = self.avgpool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

