import math
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels ---

# 1. Softmax and Slice Kernel
# Fuses F.softmax and the subsequent slicing operation `assignment[:, :self.cluster_size]`.
# This kernel processes each row (BN x (K+G)) independently, performing a numerically stable
# softmax and then only writing out the first `cluster_size` columns.
softmax_and_slice_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void softmax_and_slice_kernel(const float* input, float* output, int rows, int cols_in, int cols_out) {
    int row_idx = blockIdx.x; // Each block handles one row
    if (row_idx >= rows) return;

    // Shared memory for reduction (size: cols_in * sizeof(float))
    extern __shared__ float s_data[]; 

    const float* row_input = input + row_idx * cols_in;
    float* row_output = output + row_idx * cols_out;

    // 1. Find max value for numerical stability (reduction within block)
    float max_val = -FLT_MAX;
    for (int i = threadIdx.x; i < cols_in; i += blockDim.x) {
        s_data[i] = row_input[i];
    }
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] = fmaxf(s_data[threadIdx.x], s_data[threadIdx.x + s]);
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        max_val = s_data[0];
    }
    __syncthreads(); // Ensure max_val is visible to all threads

    // 2. Compute exponentials (exp(val - max_val)) and sum (reduction within block)
    float sum_exp = 0.0f;
    for (int i = threadIdx.x; i < cols_in; i += blockDim.x) {
        s_data[i] = expf(row_input[i] - max_val);
    }
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        sum_exp = s_data[0];
    }
    __syncthreads(); // Ensure sum_exp is visible to all threads

    // 3. Compute softmax and slice (only write out cols_out elements)
    for (int i = threadIdx.x; i < cols_out; i += blockDim.x) {
        row_output[i] = s_data[i] / sum_exp;
    }
}

torch::Tensor softmax_and_slice_cuda(torch::Tensor input, int cluster_size) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 2, "input must be 2D (BN x (K+G))");

    int rows = input.size(0);
    int cols_in = input.size(1);
    int cols_out = cluster_size;

    TORCH_CHECK(cols_out <= cols_in, "cluster_size must be less than or equal to input columns");

    auto output = torch::empty({rows, cols_out}, input.options());

    // block_size is chosen to be 32, which is the typical value for K+G (32+0)
    // This allows each thread to process one element in the row for reduction.
    const int block_size = 32; 
    const int num_blocks = rows; // One block per row

    softmax_and_slice_kernel<<<num_blocks, block_size, cols_in * sizeof(float)>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols_in, cols_out);

    return output;
}
"""

softmax_and_slice_cpp_source = (
    "torch::Tensor softmax_and_slice_cuda(torch::Tensor input, int cluster_size);"
)

softmax_and_slice = load_inline(
    name="softmax_and_slice",
    cpp_sources=softmax_and_slice_cpp_source,
    cuda_sources=softmax_and_slice_source,
    functions=["softmax_and_slice_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

# 2. Transpose and Subtract Kernel
# Fuses `vlad.transpose(1, 2)` and `vlad - a`.
# This is an element-wise kernel that computes the transposed subtraction directly.
transpose_sub_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transpose_sub_kernel(const float* input_vlad_intermediate, const float* input_a, float* output_vlad, int B, int K, int D) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * D * K) return;

    // Calculate batch, feature, and cluster indices for the output tensor (B x D x K)
    int b_idx = idx / (D * K);
    int d_idx = (idx % (D * K)) / K;
    int k_idx = idx % K;

    // input_vlad_intermediate is B x K x D.
    // To get the element corresponding to output[b_idx, d_idx, k_idx] after transpose,
    // we need input_vlad_intermediate[b_idx, k_idx, d_idx].
    float val_vlad_transposed = input_vlad_intermediate[b_idx * K * D + k_idx * D + d_idx];

    // input_a is B x D x K.
    float val_a = input_a[b_idx * D * K + d_idx * K + k_idx];

    output_vlad[idx] = val_vlad_transposed - val_a;
}

torch::Tensor transpose_sub_cuda(torch::Tensor vlad_intermediate, torch::Tensor a) {
    TORCH_CHECK(vlad_intermediate.is_cuda() && a.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(vlad_intermediate.dim() == 3 && a.dim() == 3, "Inputs must be 3D tensors");

    int B = vlad_intermediate.size(0);
    int K = vlad_intermediate.size(1); // K for vlad_intermediate (B x K x D)
    int D = vlad_intermediate.size(2);

    // 'a' is B x D x K. Verify its shape matches expectations.
    TORCH_CHECK(a.size(0) == B && a.size(1) == D && a.size(2) == K, "Shape mismatch for 'a' tensor");

    auto output_vlad = torch::empty({B, D, K}, vlad_intermediate.options());

    const int total_elements = B * D * K;
    const int block_size = 256; // Standard block size for element-wise operations
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    transpose_sub_kernel<<<num_blocks, block_size>>>(
        vlad_intermediate.data_ptr<float>(), a.data_ptr<float>(), output_vlad.data_ptr<float>(), B, K, D);

    return output_vlad;
}
"""

transpose_sub_cpp_source = (
    "torch::Tensor transpose_sub_cuda(torch::Tensor vlad_intermediate, torch::Tensor a);"
)

transpose_sub = load_inline(
    name="transpose_sub",
    cpp_sources=transpose_sub_cpp_source,
    cuda_sources=transpose_sub_source,
    functions=["transpose_sub_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

# 3. L2 Normalize 3D (dim=1) Kernel
# Implements F.normalize for a 3D tensor (B x D x K) along dimension D (dim=1).
# Each block normalizes one D-dimensional vector (for a given B and K).
l2_normalize_3d_dim1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void l2_normalize_3d_dim1_kernel(const float* input, float* output, int B, int D, int K) {
    int vector_idx = blockIdx.x; // Maps to (b, k) pair
    if (vector_idx >= B * K) return;

    int b_idx = vector_idx / K;
    int k_idx = vector_idx % K;

    // Calculate base pointer for the current vector input[b_idx, :, k_idx]
    // Elements are stored as input[b_idx * D * K + d * K + k_idx]
    const float* current_input_vec_base = input + b_idx * D * K + k_idx;
    float* current_output_vec_base = output + b_idx * D * K + k_idx;

    // Shared memory for reduction (size: D * sizeof(float))
    extern __shared__ float s_data[]; 

    // 1. Compute sum of squares (reduction within block)
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = current_input_vec_base[i * K]; // Access elements with stride K
        s_data[i] = val * val;
    }
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_data[threadIdx.x] += s_data[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        sum_sq = s_data[0];
    }
    __syncthreads();

    float norm = sqrtf(sum_sq + 1e-12f); // Add epsilon for numerical stability

    // 2. Divide by norm
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        current_output_vec_base[i * K] = current_input_vec_base[i * K] / norm;
    }
}

