class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        self.clusters = nn.Parameter(init_sc * th.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        self.clusters2 = nn.Parameter(init_sc * th.randn(1, feature_size, cluster_size))
        self.out_dim = self.cluster_size * feature_size

        # Register custom CUDA kernels
        self.softmax_and_slice_op = softmax_and_slice
        self.transpose_sub_op = transpose_sub
        self.l2_normalize_3d_dim1_op = l2_normalize_3d_dim1

    def forward(self, x, mask=None):
        max_sample = x.size()[1]
        x_original_view = x # Keep original view (B x N x D) for later matmul
        x = x.view(-1, self.feature_size)  # B x N x D -> BN x D

        if x.device != self.clusters.device:
            msg = f"x.device {x.device} != cluster.device {self.clusters.device}"
            raise ValueError(msg)

        assignment = th.matmul(x, self.clusters)  # (BN x D) x (D x (K+G)) -> BN x (K+G)
        assignment = self.batch_norm(assignment)

        # OPTIMIZATION 1: Fused Softmax + Slicing
        # Replaces:
        # assignment = F.softmax(assignment, dim=1)
        # assignment = assignment[:, :self.cluster_size]
        assignment = self.softmax_and_slice_op.softmax_and_slice_cuda(assignment, self.cluster_size)

        assignment = assignment.view(-1, max_sample, self.cluster_size)  # -> B x N x K

        a_sum = th.sum(assignment, dim=1, keepdim=True)  # B x N x K -> B x 1 x K
        # a will be B x D x K due to broadcasting with self.clusters2 (1 x D x K)
        a = a_sum * self.clusters2 

        assignment = assignment.transpose(1, 2)  # B x N x K -> B x K x N

        # OPTIMIZATION 2: Fused Matmul (PyTorch) + Transpose + Subtract
        # The matmul itself is handled by PyTorch (cuBLAS), then the custom kernel
        # performs the transpose and subtraction in a single pass.
        # Replaces:
        # vlad = th.matmul(assignment, x_original_view)
        # vlad = vlad.transpose(1, 2)
        # vlad = vlad - a
        vlad_intermediate = th.matmul(assignment, x_original_view) # Result is B x K x D
        vlad = self.transpose_sub_op.transpose_sub_cuda(vlad_intermediate, a) # Result is B x D x K

        # OPTIMIZATION 3: Custom L2 Intra-Normalization (for 3D tensor along dim=1)
        # Replaces:
        # vlad = F.normalize(vlad)
        vlad = self.l2_normalize_3d_dim1_op.l2_normalize_3d_dim1_cuda(vlad)

        # Flattening + L2 norm (this second normalization is left as PyTorch's F.normalize)
        # The vector length (DK = 16384) for this normalization is very large,
        # making a simple single-block CUDA kernel inefficient due to shared memory limits
        # and requiring more complex multi-pass or multi-block reduction strategies.
        vlad = vlad.reshape(-1, self.cluster_size * self.feature_size)  # -> B x DK
        vlad = F.normalize(vlad) 

        return vlad

