import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels ---

# Fused ReLU Kernel
# This kernel performs an element-wise ReLU operation.
# It's used to fuse with Conv2d operations, avoiding an intermediate tensor allocation
# and a separate kernel launch for ReLU.
fused_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf

__global__ void relu_kernel(const float* input, float* output, long long size) {
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = fmaxf(0.0f, input[idx]);
    }
}

torch::Tensor fused_relu_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA device.");
    TORCH_CHECK(input.is_floating_point(), "Input tensor must be of floating point type.");

    auto output = torch::empty_like(input); // Allocate output tensor

    long long size = input.numel();

    const int block_size = 256; // Standard block size
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in fused_relu_cuda: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
