# Fused Concatenation Kernel for 4 inputs (specific to InceptionModule)
# This kernel concatenates four input tensors along the channel dimension (dim=1)
# into a single output tensor. This avoids multiple memory copies and allocations
# that would occur with `torch.cat` for each Inception module.
fused_cat_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_cat_kernel_4_inputs(
    const float* in0, const float* in1, const float* in2, const float* in3,
    float* out,
    long long N, long long C0, long long C1, long long C2, long long C3, long long H, long long W,
    long long total_C
) {
    long long total_elements = N * total_C * H * W;
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Deconstruct global index to (n, c_out, h, w) for NCHW layout
        long long hw_size = H * W;
        long long c_hw_size = total_C * hw_size;

        long long n = idx / c_hw_size;          // Batch index
        long long remaining = idx % c_hw_size;
        long long c_out = remaining / hw_size;  // Output channel index
        long long hw_idx = remaining % hw_size; // Spatial index (h*W + w)

        // Determine which input tensor this output channel belongs to and copy the value
        if (c_out < C0) {
            // Belongs to in0
            out[idx] = in0[n * C0 * hw_size + c_out * hw_size + hw_idx];
        } else if (c_out < C0 + C1) {
            // Belongs to in1
            long long c_in1 = c_out - C0; // Relative channel index for in1
            out[idx] = in1[n * C1 * hw_size + c_in1 * hw_size + hw_idx];
        } else if (c_out < C0 + C1 + C2) {
            // Belongs to in2
            long long c_in2 = c_out - (C0 + C1); // Relative channel index for in2
            out[idx] = in2[n * C2 * hw_size + c_in2 * hw_size + hw_idx];
        } else { // c_out < C0 + C1 + C2 + C3
            // Belongs to in3
            long long c_in3 = c_out - (C0 + C1 + C2); // Relative channel index for in3
            out[idx] = in3[n * C3 * hw_size + c_in3 * hw_size + hw_idx];
        }
    }
}

torch::Tensor fused_cat_cuda(
    torch::Tensor in0, torch::Tensor in1, torch::Tensor in2, torch::Tensor in3,
    long long C0, long long C1, long long C2, long long C3
) {
    // Input validation
    TORCH_CHECK(in0.is_cuda() && in1.is_cuda() && in2.is_cuda() && in3.is_cuda(), "All inputs must be CUDA tensors.");
    TORCH_CHECK(in0.is_floating_point() && in1.is_floating_point() && in2.is_floating_point() && in3.is_floating_point(), "All inputs must be floating point tensors.");

    TORCH_CHECK(in0.dim() == 4 && in1.dim() == 4 && in2.dim() == 4 && in3.dim() == 4, "All inputs must be 4D tensors (NCHW).");
    TORCH_CHECK(in0.size(0) == in1.size(0) && in0.size(0) == in2.size(0) && in0.size(0) == in3.size(0), "Batch sizes must match.");
    TORCH_CHECK(in0.size(2) == in1.size(2) && in0.size(2) == in2.size(2) && in0.size(2) == in3.size(2), "Heights must match.");
    TORCH_CHECK(in0.size(3) == in1.size(3) && in0.size(3) == in2.size(3) && in0.size(3) == in3.size(3), "Widths must match.");

    long long N = in0.size(0);
    long long H = in0.size(2);
    long long W = in0.size(3);
    long long total_C = C0 + C1 + C2 + C3;

    // Allocate output tensor with combined channels
    auto output_options = torch::TensorOptions().dtype(in0.dtype()).device(in0.device());
    auto out = torch::empty({N, total_C, H, W}, output_options);

    long long total_elements = N * total_C * H * W;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_cat_kernel_4_inputs<<<num_blocks, block_size>>>(
        in0.data_ptr<float>(), in1.data_ptr<float>(), in2.data_ptr<float>(), in3.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C0, C1, C2, C3, H, W, total_C
    );

    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in fused_cat_cuda: %s\\n", cudaGetErrorString(err));
    }

    return out;
}
"""

