import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused BatchNorm (inference) + ReLU
# This kernel combines the normalization, scaling, and shifting of BatchNorm
# with the element-wise ReLU activation into a single GPU kernel launch.
# This reduces memory traffic and kernel launch overhead, leading to speedups
# during inference. For training, it falls back to PyTorch's native operators
# due to the complexity of implementing batch statistics computation and
# running statistics updates in a custom kernel.
fused_bn_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf and fmaxf

// Fused BatchNorm (inference) + ReLU kernel
// This kernel operates on 4D tensors (N, C, H, W).
// Each thread processes one element of the output tensor.
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* running_mean,
    const float* running_var,
    float eps,
    float* output,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Calculate indices for N, C, H, W assuming row-major order
        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / W / H) % C;
        // int n = (idx / W / H / C); // 'n' index is not directly needed for channel-wise parameters

        // Get channel-specific parameters for BatchNorm
        float mean_c = running_mean[c];
        float var_c = running_var[c];
        float gamma_c = weight[c];
        float beta_c = bias[c];

        // Perform BatchNorm (inference mode)
        float val = input[idx];
        // Use rsqrtf for faster inverse square root calculation
        float inv_std = rsqrtf(var_c + eps); 
        float normalized_val = (val - mean_c) * inv_std;
        float scaled_shifted_val = normalized_val * gamma_c + beta_c;

        // Perform ReLU activation
        output[idx] = fmaxf(0.0f, scaled_shifted_val);
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor fused_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps) {

    // Input validation checks
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(running_mean.is_cuda(), "running_mean must be a CUDA tensor");
    TORCH_CHECK(running_var.is_cuda(), "running_var must be a CUDA tensor");
    TORCH_CHECK(input.is_floating_point(), "input must be a floating point tensor");
    TORCH_CHECK(input.dim() == 4, "input must be a 4D tensor (N, C, H, W)");
    TORCH_CHECK(weight.dim() == 1 && weight.size(0) == input.size(1), "weight must be 1D with size C");
    TORCH_CHECK(bias.dim() == 1 && bias.size(0) == input.size(1), "bias must be 1D with size C");
    TORCH_CHECK(running_mean.dim() == 1 && running_mean.size(0) == input.size(1), "running_mean must be 1D with size C");
    TORCH_CHECK(running_var.dim() == 1 && running_var.size(0) == input.size(1), "running_var must be 1D with size C");

    // Get dimensions from the input tensor
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int total_elements = N * C * H * W;

    // Create an empty output tensor with the same shape and type as input
    auto output = torch::empty_like(input);

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the fused kernel
    fused_bn_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        (float)eps, // Cast double eps to float for CUDA kernel
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}
"""

fused_bn_relu_cpp_source = (
    "torch::Tensor fused_bn_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor running_mean, torch::Tensor running_var, double eps);"
