class FusedBNReLU(nn.Module):
    """
    A custom PyTorch module that replaces nn.BatchNorm2d and nn.ReLU.
    It uses a custom CUDA kernel for fused BatchNorm (inference) + ReLU.
    For training, it falls back to PyTorch's native F.batch_norm and F.relu
    to correctly handle batch statistics computation and running statistics updates.
    """
    def __init__(self, num_features, eps=1e-5, momentum=0.1, affine=True, track_running_stats=True):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum
        self.affine = affine
        self.track_running_stats = track_running_stats

        if self.affine:
            self.weight = nn.Parameter(torch.ones(num_features))
            self.bias = nn.Parameter(torch.zeros(num_features))
        else:
            self.register_parameter('weight', None)
            self.register_parameter('bias', None)

        if self.track_running_stats:
            self.register_buffer('running_mean', torch.zeros(num_features))
            self.register_buffer('running_var', torch.ones(num_features))
            self.register_buffer('num_batches_tracked', torch.tensor(0, dtype=torch.long))
        else:
            self.register_buffer('running_mean', None)
            self.register_buffer('running_var', None)
            self.register_buffer('num_batches_tracked', None)

    def forward(self, input):
        if self.training:
            # Fallback to PyTorch's native F.batch_norm for training.
            # This ensures correct behavior for batch statistics computation
            # and running statistics updates, which are complex to implement
            # efficiently in a custom CUDA kernel.
            output = F.batch_norm(
                input, self.running_mean, self.running_var, self.weight, self.bias,
                self.training, self.momentum, self.eps, self.track_running_stats
            )
            return F.relu(output, inplace=True)
        else:
            # Use the custom fused CUDA kernel for inference.
            # Prepare parameters, handling cases where affine or track_running_stats are False.
            weight = self.weight if self.affine else torch.ones(self.num_features, device=input.device)
            bias = self.bias if self.affine else torch.zeros(self.num_features, device=input.device)
            running_mean = self.running_mean if self.track_running_stats else torch.zeros(self.num_features, device=input.device)
            running_var = self.running_var if self.track_running_stats else torch.ones(self.num_features, device=input.device)

            return fused_bn_relu_module.fused_bn_relu_cuda(
                input, weight, bias, running_mean, running_var, self.eps
            )

    def extra_repr(self):
        return f'{self.num_features}, eps={self.eps}, momentum={self.momentum}, affine={self.affine}, track_running_stats={self.track_running_stats}'


class ModelNew(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        """
        Optimized DenseNet-like block architecture.
        Replaces nn.BatchNorm2d + nn.ReLU with a fused custom CUDA kernel for inference.
        Removes nn.Dropout(0.0) as it's a no-op.

        :param num_layers: The number of layers in the dense block
        :param num_input_features: The number of input feature maps
        :param growth_rate: The growth rate for the dense block (new features added per layer)
        """
        super(ModelNew, self).__init__()
        layers = []
        for i in range(num_layers):
            # The number of input features to each layer increases with each iteration
            # due to concatenation of previous feature maps.
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

    def _make_layer(self, in_features: int, growth_rate: int):
        """
        Creates a single layer with FusedBNReLU and Conv2D.
        The original nn.Dropout(0.0) is removed as it has no effect.
        """
        return nn.Sequential(
            FusedBNReLU(in_features), # Custom fused BatchNorm (inference) + ReLU
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False),
            # nn.Dropout(0.0) is removed as it is a no-op.
        )

    def forward(self, x):
        """
        :param x: Input tensor of shape (batch_size, num_input_features, height, width)
        :return: Concatenated output tensor with shape (batch_size, num_output_features, height, width)
        """
        features = [x]
        for layer in self.layers:
            new_feature = layer(x)
            features.append(new_feature)
            # This torch.cat operation is a significant part of DenseNet's memory traffic.
            # While a custom kernel for general concatenation is complex and might not
            # outperform PyTorch's highly optimized implementation, fusing the preceding
            # BatchNorm+ReLU is a more direct and common optimization.
            x = torch.cat(features, 1)  # Concatenate along channel axis
        return x

