fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_kernels_cpp_source,
    cuda_sources=fused_kernels_source,
    functions=["conv_relu_cuda", "linear_relu_cuda"],
    verbose=True,
    extra_cflags=["-O3"],  # General C++ optimization flags
    extra_cuda_cflags=["-O3", "--use_fast_math"],  # CUDA specific optimization flags
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        Initialize the VGG19 model with custom fused Conv2d+ReLU and Linear+ReLU kernels.

        :param num_classes: The number of output classes (default is 1000 for ImageNet)
        """
        super(ModelNew, self).__init__()

        # Custom module to encapsulate the fused Conv2d + ReLU operation.
        # This allows us to use it within nn.Sequential and manage parameters correctly.
        class FusedConvReLU(nn.Module):
            def __init__(self, in_channels, out_channels, kernel_size, stride=1, padding=0, dilation=1, groups=1, bias=True):
                super().__init__()
                # The underlying nn.Conv2d layer holds the learnable parameters (weight, bias).
                self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, dilation, groups, bias)
                # Reference to the compiled custom CUDA function.
                self.fused_op_func = fused_ops.conv_relu_cuda

            def forward(self, x):
                # Call the custom fused CUDA function, passing the parameters from the nn.Conv2d layer.
                return self.fused_op_func(
                    x, self.conv.weight, self.conv.bias,
                    self.conv.stride, self.conv.padding, self.conv.dilation, self.conv.groups
                )

