                return self.fused_op_func(
                    x, self.linear.weight, self.linear.bias
                )

        # Rebuild the VGG19 features block using the FusedConvReLU modules.
        self.features = nn.Sequential(
            # Block 1
            FusedConvReLU(3, 64, kernel_size=3, padding=1),
            FusedConvReLU(64, 64, kernel_size=3, padding=1),
            nn.MaxPool2d(kernel_size=2, stride=2),

            # Block 2
            FusedConvReLU(64, 128, kernel_size=3, padding=1),
            FusedConvReLU(128, 128, kernel_size=3, padding=1),
            nn.MaxPool2d(kernel_size=2, stride=2),

            # Block 3
            FusedConvReLU(128, 256, kernel_size=3, padding=1),
            FusedConvReLU(256, 256, kernel_size=3, padding=1),
            FusedConvReLU(256, 256, kernel_size=3, padding=1),
            FusedConvReLU(256, 256, kernel_size=3, padding=1),
            nn.MaxPool2d(kernel_size=2, stride=2),

            # Block 4
            FusedConvReLU(256, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            nn.MaxPool2d(kernel_size=2, stride=2),

            # Block 5
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            FusedConvReLU(512, 512, kernel_size=3, padding=1),
            nn.MaxPool2d(kernel_size=2, stride=2)
        )

        # Rebuild the VGG19 classifier block using the FusedLinearReLU modules.
        self.classifier = nn.Sequential(
            FusedLinearReLU(512 * 7 * 7, 4096),
            nn.Dropout(p=0.0),  # Dropout with p=0.0 is a no-op, kept for structural similarity.
            FusedLinearReLU(4096, 4096),
            nn.Dropout(p=0.0),  # Dropout with p=0.0 is a no-op, kept for structural similarity.
            nn.Linear(4096, num_classes) # The final linear layer typically does not have a ReLU after it.
        )

    def forward(self, x):
        """
        Forward pass of the optimized VGG19 model.

        :param x: The input tensor, shape (batch_size, 3, 224, 224)
        :return: The output tensor, shape (batch_size, num_classes)
        """
        x = self.features(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)
        return x

