import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Original Model (provided in the problem description)
class Model(nn.Module):
    def __init__(self, input_size, layer_sizes, output_size):
        """
        :param input_size: The number of input features
        :param layer_sizes: A list of ints containing the sizes of each hidden layer
        :param output_size: The number of output features
        """
        super(Model, self).__init__()

        layers = []
        current_input_size = input_size

        for layer_size in layer_sizes:
            layers.append(nn.Linear(current_input_size, layer_size))
            layers.append(nn.ReLU())
            current_input_size = layer_size

        layers.append(nn.Linear(current_input_size, output_size))

        self.network = nn.Sequential(*layers)

    def forward(self, x):
        """
        :param x: The input tensor, shape (batch_size, input_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        return self.network(x)

# Helper functions for input generation (provided in the problem description)
# These are included as ModelNew's initialization strategy depends on the structure
# of the original Model, which is defined in terms of these parameters.
def get_inputs():
    batch_size = 128
    input_size = 16384
    return [torch.rand(batch_size, input_size)]

def get_init_inputs():
    input_size = 16384
    layer_sizes = [16384, 16384]
    output_size = 8192
    return [input_size, layer_sizes, output_size]

# --- Custom CUDA Kernel and C++ Wrapper Definitions ---

# CUDA source for bias_add_relu_kernel
bias_add_relu_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max

// Kernel for fusing bias addition and ReLU activation
// Each thread processes one element. Bias is applied per column.
__global__ void bias_add_relu_kernel(const float* input, const float* bias, float* output, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * cols) {
        int col = idx % cols; // Bias is a 1D vector, applied per column
        output[idx] = fmaxf(0.0f, input[idx] + bias[col]);
    }
}
"""

# C++ source for the wrappers that expose CUDA kernels to Python
fused_linear_cpp_source = """
#include <torch/extension.h>
#include <vector>

// Declare the CUDA kernel wrapper (defined in .cu file)
// This function will launch the __global__ bias_add_relu_kernel.
torch::Tensor bias_add_relu_cuda(torch::Tensor input, torch::Tensor bias);

// C++ wrapper for the bias_add_relu_kernel
torch::Tensor bias_add_relu_cuda(torch::Tensor input, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(bias.is_cuda(), "Bias tensor must be on CUDA.");
    TORCH_CHECK(input.dim() == 2, "Input tensor must be 2D (batch_size, features).");
    TORCH_CHECK(bias.dim() == 1, "Bias tensor must be 1D (features).");
    TORCH_CHECK(input.size(1) == bias.size(0), "Input columns must match bias size.");

    auto output = torch::zeros_like(input);

    int rows = input.size(0);
    int cols = input.size(1);
    int size = rows * cols;

    const int block_size = 256; // Standard block size
    const int num_blocks = (size + block_size - 1) / block_size;

    bias_add_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols
    );
    // No explicit CUDA error checking here; PyTorch's runtime will typically catch errors.

    return output;
}

// C++ function to perform Linear + ReLU fusion
// This function combines torch::mm (matrix multiplication) with the custom bias_add_relu_cuda kernel.
torch::Tensor linear_relu_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "Input tensor must be on CUDA.");
    TORCH_CHECK(weight.is_cuda(), "Weight tensor must be on CUDA.");
    TORCH_CHECK(bias.is_cuda(), "Bias tensor must be on CUDA.");

    // Perform matrix multiplication: input @ weight.T
    // nn.Linear internally uses weight.T for the actual multiplication.
    torch::Tensor mm_output = torch::mm(input, weight.transpose(0, 1));

    // Fuse bias addition and ReLU using the custom CUDA kernel
    return bias_add_relu_cuda(mm_output, bias);
}
"""

# Compile the inline CUDA code
# This creates a Python module 'fused_linear_ops' that contains the C++ functions.
fused_linear_ops = load_inline(
    name="fused_linear_ops",
    cpp_sources=fused_linear_cpp_source,
    cuda_sources=bias_add_relu_cuda_source,
    functions=["bias_add_relu_cuda", "linear_relu_forward_cuda"], # Functions to expose to Python
    verbose=True, # Print compilation output
    extra_cflags=["-O3"], # Optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization flags for CUDA compiler
)

# --- Optimized Model Definition ---

class ModelNew(nn.Module):
    def __init__(self, input_size, layer_sizes, output_size):
        super(ModelNew, self).__init__()

        self.fused_ops = fused_linear_ops # Store the loaded custom operations

        # Store weights and biases for the fused Linear + ReLU layers as nn.ParameterList
        self.fused_layers_weights = nn.ParameterList()
        self.fused_layers_biases = nn.ParameterList()

        # Create a temporary instance of the original model to extract its initialized weights and biases.
        # This ensures ModelNew starts with the same parameter values as the original Model.
        temp_model = Model(input_size, layer_sizes, output_size)

        # The original model's network is nn.Sequential([Linear, ReLU, Linear, ReLU, ..., Linear])
        # We iterate through the Linear layers that are followed by a ReLU for fusion.
        num_fused_blocks = len(layer_sizes) # Each element in layer_sizes corresponds to a Linear+ReLU pair

        for i in range(num_fused_blocks):
            linear_layer = temp_model.network[i * 2] # Linear layers are at indices 0, 2, 4, ...
            # Clone the data to ensure ModelNew's parameters are independent of temp_model's
            self.fused_layers_weights.append(nn.Parameter(linear_layer.weight.data.clone()))
            self.fused_layers_biases.append(nn.Parameter(linear_layer.bias.data.clone()))

        # The very last layer in the original model is a standard nn.Linear layer (not followed by ReLU).
        # We keep this as a standard PyTorch nn.Linear module.
        final_linear_layer_idx = num_fused_blocks * 2
        final_linear_layer = temp_model.network[final_linear_layer_idx]
        self.final_linear = nn.Linear(final_linear_layer.in_features, final_linear_layer.out_features)
        # Assign cloned weights and biases to the final linear layer
        self.final_linear.weight = nn.Parameter(final_linear_layer.weight.data.clone())
        self.final_linear.bias = nn.Parameter(final_linear_layer.bias.data.clone())

    def forward(self, x):
        # Apply the fused Linear + ReLU operations for the hidden layers
        for i in range(len(self.fused_layers_weights)):
            x = self.fused_ops.linear_relu_forward_cuda(
                x,
                self.fused_layers_weights[i],
                self.fused_layers_biases[i]
            )

        # Apply the final standard Linear layer
        x = self.final_linear(x)
        return x

