import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernel 1: Fuse CLS token and Linear Projection Output ---
# This kernel replaces the `linear_proj_output.unsqueeze(1)` and `torch.cat` operations.
# It takes the (B, E) output of the linear projection and the (1, 1, E) CLS token,
# and directly constructs the (B, 2, E) tensor by copying CLS token to the first
# "patch" position and linear output to the second "patch" position for each batch.
fuse_cls_and_linear_output_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fuse_cls_and_linear_output_kernel(
    const float* linear_output_ptr, // Input: (B, E) tensor
    const float* cls_token_ptr,     // Input: (E,) tensor (squeezed from (1, 1, E))
    float* fused_tensor_ptr,        // Output: (B, 2, E) tensor
    int B, int E) {

    // Each thread processes one element in the output tensor
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (global_idx < B * 2 * E) {
        int b = global_idx / (2 * E);       // Batch index
        int patch_idx = (global_idx % (2 * E)) / E; // Patch index (0 for CLS, 1 for linear output)
        int e = global_idx % E;             // Embedding dimension index

        if (patch_idx == 0) { // Copy CLS token
            fused_tensor_ptr[global_idx] = cls_token_ptr[e];
        } else { // Copy linear projection output
            fused_tensor_ptr[global_idx] = linear_output_ptr[b * E + e];
        }
    }
}

torch::Tensor fuse_cls_and_linear_output_cuda(torch::Tensor linear_output, torch::Tensor cls_token) {
    TORCH_CHECK(linear_output.is_cuda(), "linear_output must be a CUDA tensor");
    TORCH_CHECK(cls_token.is_cuda(), "cls_token must be a CUDA tensor");
    TORCH_CHECK(linear_output.dim() == 2, "linear_output must be 2D (B, E)");
    TORCH_CHECK(cls_token.dim() == 3, "cls_token must be 3D (1, 1, E)");
    TORCH_CHECK(cls_token.size(0) == 1 && cls_token.size(1) == 1, "cls_token must be (1, 1, E)");
    TORCH_CHECK(linear_output.size(1) == cls_token.size(2), "Embedding dimensions must match");

    int B = linear_output.size(0);
    int E = linear_output.size(1);

    auto fused_tensor = torch::empty({B, 2, E}, linear_output.options());

    const int block_size = 256;
    const int num_elements = B * 2 * E;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Squeeze cls_token to (E,) for easier access in the kernel.
    // This creates a view, so data_ptr is still valid for the underlying storage.
    auto cls_token_squeezed = cls_token.squeeze();

    fuse_cls_and_linear_output_kernel<<<num_blocks, block_size>>>(
        linear_output.data_ptr<float>(),
        cls_token_squeezed.data_ptr<float>(),
        fused_tensor.data_ptr<float>(),
        B, E
    );

    return fused_tensor;
}
"""

fuse_cls_and_linear_output_cpp_source = (
    "torch::Tensor fuse_cls_and_linear_output_cuda(torch::Tensor linear_output, torch::Tensor cls_token);"
)

# --- Custom CUDA Kernel 2: Fused Bias Add and GELU Activation ---
# This kernel replaces the `bias_add` (from nn.Linear) and `GELU` activation
# for the first linear layer in the Feed-Forward Network (FFN) of the Transformer.
fused_bias_gelu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanh, sqrt, M_PI

// GELU approximation from https://github.com/NVIDIA/apex/blob/master/csrc/fused_layer_norm_cuda.cu
// x * 0.5 * (1.0 + tanh(sqrt(2.0 / M_PI) * (x + 0.044715 * x * x * x)))
__device__ float gelu_approx(float x) {
    return x * 0.5f * (1.0f + tanhf(sqrtf(2.0f / M_PI) * (x + 0.044715f * x * x * x)));
}

__global__ void fused_bias_gelu_kernel(const float* input, const float* bias, float* output, int rows, int cols) {
    // Each thread processes one element (row, col)
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (global_idx < rows * cols) {
        int col_idx = global_idx % cols; // Column index (used for bias)
        output[global_idx] = gelu_approx(input[global_idx] + bias[col_idx]);
    }
}

torch::Tensor fused_bias_gelu_cuda(torch::Tensor input, torch::Tensor bias) {
    // input: (B*S, H), bias: (H,)
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 2, "input must be 2D (rows, cols)");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D (cols)");
    TORCH_CHECK(input.size(1) == bias.size(0), "Input columns and bias size must match");

    auto output = torch::empty_like(input);
    int rows = input.size(0);
    int cols = input.size(1);

    const int block_size = 256;
    const int num_elements = rows * cols;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_bias_gelu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        rows, cols
    );
    return output;
}
"""

fused_bias_gelu_cpp_source = (
    "torch::Tensor fused_bias_gelu_cuda(torch::Tensor input, torch::Tensor bias);"
)

# Compile the inline CUDA code for both kernels
fuse_cls_and_linear_output_module = load_inline(
    name="fuse_cls_and_linear_output_module",
    cpp_sources=fuse_cls_and_linear_output_cpp_source,
    cuda_sources=fuse_cls_and_linear_output_source,
    functions=["fuse_cls_and_linear_output_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable aggressive optimizations
    extra_ldflags=[""],
)

fused_bias_gelu_module = load_inline(
    name="fused_bias_gelu_module",
    cpp_sources=fused_bias_gelu_cpp_source,
    cuda_sources=fused_bias_gelu_source,
    functions=["fused_bias_gelu_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable aggressive optimizations
    extra_ldflags=[""],
)

# Custom FFN module that uses the fused_bias_gelu kernel
class FusedFFN(nn.Module):
    def __init__(self, embed_dim, dim_feedforward, fused_bias_gelu_op):
        super().__init__()
        self.linear1 = nn.Linear(embed_dim, dim_feedforward)
        self.linear2 = nn.Linear(dim_feedforward, embed_dim)
        self.fused_bias_gelu_op = fused_bias_gelu_op

    def forward(self, x):
        # x is (B, S, E)
        original_shape = x.shape
        x = x.view(-1, original_shape[-1]) # Reshape to (B*S, E) for linear layers

        # Perform GEMM for linear1. F.linear without bias adds only weight multiplication.
        intermediate = F.linear(x, self.linear1.weight) # Output: (B*S, H)

        # Fuse bias addition from linear1 and GELU activation using custom kernel
        intermediate_activated = self.fused_bias_gelu_op.fused_bias_gelu_cuda(
            intermediate, self.linear1.bias
        ) # Output: (B*S, H)

        # Perform GEMM for linear2, including its bias
        output = F.linear(intermediate_activated, self.linear2.weight, self.linear2.bias) # Output: (B*S, E)

        return output.view(original_shape) # Reshape back to (B, S, E)

# Custom TransformerEncoderLayer that uses our FusedFFN
class CustomTransformerEncoderLayer(nn.Module):
    def __init__(self, d_model, nhead, dim_feedforward, dropout, batch_first, fused_bias_gelu_op):
        super().__init__()
        self.self_attn = nn.MultiheadAttention(d_model, nhead, dropout=dropout, batch_first=batch_first)
        self.ffn = FusedFFN(d_model, dim_feedforward, fused_bias_gelu_op)

        self.norm1 = nn.LayerNorm(d_model)
        self.norm2 = nn.LayerNorm(d_model)
        self.dropout1 = nn.Dropout(dropout)
        self.dropout2 = nn.Dropout(dropout)

    def forward(self, src, src_mask=None, src_key_padding_mask=None):
        # First attention block with residual connection and layer norm
        x = self.norm1(src)
        src2 = self.self_attn(x, x, x, attn_mask=src_mask, key_padding_mask=src_key_padding_mask)[0]
        src = src + self.dropout1(src2)

        # Second FFN block with residual connection and layer norm, using our fused FFN
        x = self.norm2(src)
        src2 = self.ffn(x) # Call our FusedFFN module
        src = src + self.dropout2(src2)
        return src


class ModelNew(nn.Module):
    def __init__(self, num_classes, embed_dim=512, num_heads=8, num_layers=6,
                 mlp_ratio=4.0, patch_size=4, in_channels=3, image_size=32):
        """
        Optimized Convolutional Vision Transformer (CViT) implementation with custom CUDA kernels.
        :param num_classes: Number of output classes for classification.
        :param embed_dim: Dimensionality of the embedding space.
        :param num_heads: Number of attention heads.
        :param num_layers: Number of transformer layers.
        :param mlp_ratio: Ratio of the MLP hidden dimension to the embedding dimension.
        :param patch_size: Size of the convolutional patches.
        :param in_channels: Number of input channels (e.g., 3 for RGB images).
        :param image_size: Height/width of the square input image.
        """
        super(ModelNew, self).__init__()

        self.patch_size = patch_size
        self.image_size = image_size
        self.embed_dim = embed_dim

        # Store the loaded custom kernel modules
        self.fuse_cls_and_linear_output_op = fuse_cls_and_linear_output_module
        self.fused_bias_gelu_op = fused_bias_gelu_module

        self.conv1 = nn.Conv2d(in_channels, embed_dim, kernel_size=patch_size, stride=patch_size)
        num_patches = (image_size // patch_size) ** 2
        self.linear_proj = nn.Linear(embed_dim * num_patches, embed_dim)

        # Replace standard TransformerEncoderLayer with our custom version
        self.transformer_layers = nn.ModuleList([
            CustomTransformerEncoderLayer(
                d_model=embed_dim,
                nhead=num_heads,
                dim_feedforward=int(embed_dim * mlp_ratio),
                dropout=0.0, # Original model uses 0.0 dropout
                batch_first=True,
                fused_bias_gelu_op=self.fused_bias_gelu_op # Pass the custom kernel to FFN
            ) for _ in range(num_layers)
        ])

        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))
        self.fc_out = nn.Linear(embed_dim, num_classes)

    def forward(self, x):
        B = x.size(0)
        x = self.conv1(x)                  # (B, embed_dim, H/patch_size, W/patch_size)
        x = x.flatten(start_dim=1)         # (B, embed_dim * num_patches)
        linear_proj_output = self.linear_proj(x) # (B, embed_dim)

        # Replace torch.cat and unsqueeze with our custom fused kernel
        x = self.fuse_cls_and_linear_output_op.fuse_cls_and_linear_output_cuda(
            linear_proj_output, self.cls_token
        ) # (B, 2, embed_dim)

        for layer in self.transformer_layers:
            x = layer(x)

        return self.fc_out(x[:, 0])        # Use [CLS] token for classification

