import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels ---

# 1. Element-wise Addition Kernel (for MBConv residual connections)
# This kernel replaces the `x += identity` operation.
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "Tensors must be CUDA tensors");
    TORCH_CHECK(a.is_contiguous() && b.is_contiguous(), "Tensors must be contiguous");
    TORCH_CHECK(a.sizes() == b.sizes(), "Input tensors must have the same size");
    TORCH_CHECK(a.dtype() == torch::kFloat32, "Input tensors must be float32");

    auto size = a.numel();
    auto out = torch::empty_like(a); // Use empty_like for output to avoid unnecessary initialization

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);
    // Synchronize to ensure kernel completion before returning.
    // In a production setting, relying on PyTorch's implicit synchronization is often preferred for performance.
    cudaStreamSynchronize(0); 
    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=False, # Set to True for debugging compilation issues
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# 2. Global Average Pooling Kernel (replaces F.adaptive_avg_pool2d(x, (1, 1)))
# This kernel uses shared memory for efficient reduction within each channel.
global_avg_pool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Optimized kernel for Global Average Pooling
// Each block processes one (N, C) slice. Threads within the block sum up H*W elements
// using shared memory reduction, then compute the average.
__global__ void global_avg_pool2d_kernel(const float* input, float* output, int N, int C, int H, int W) {
    // Each block processes one (N, C) slice
    int nc_idx = blockIdx.x;
    int n = nc_idx / C;
    int c = nc_idx % C;

    // Dynamically allocated shared memory for reduction. Size is passed at kernel launch.
    extern __shared__ float s_sum[]; 

    // Initialize shared memory for this thread
    s_sum[threadIdx.x] = 0.0f;

    // Pointer to the start of the current (n, c) channel data in global memory
    const float* channel_input_ptr = input + (long long)n * C * H * W + (long long)c * H * W;

    // Each thread sums a portion of the H*W elements for its (n, c) slice
    for (int i = threadIdx.x; i < H * W; i += blockDim.x) {
        s_sum[threadIdx.x] += channel_input_ptr[i];
    }
    __syncthreads(); // Ensure all threads have finished their initial sum

    // Perform parallel reduction in shared memory
    // This loop sums up the values in shared memory
    for (int s = blockDim.x / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    // The first thread (threadIdx.x == 0) writes the final sum to global memory
    if (threadIdx.x == 0) {
        output[(long long)n * C + c] = s_sum[0] / (H * W);
    }
}

torch::Tensor global_avg_pool2d_cuda(torch::Tensor input) {
    // Input tensor is expected to be 4D: (N, C, H, W)
    TORCH_CHECK(input.dim() == 4, "Input must be 4D (N, C, H, W)");
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "Input must be float32");

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    // Output tensor will be (N, C, 1, 1)
    auto output = torch::empty({N, C, 1, 1}, input.options());

    const int block_size = 256; // Example block size, can be tuned for optimal performance
    const int num_blocks = N * C; // One block per (N, C) slice

    // Launch kernel with dynamic shared memory. The third argument specifies shared memory size in bytes.
    global_avg_pool2d_kernel<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), N, C, H, W
    );
    // Synchronize to ensure kernel completion before returning.
    cudaStreamSynchronize(0); 
    return output;
}
"""

global_avg_pool2d_cpp_source = (
    "torch::Tensor global_avg_pool2d_cuda(torch::Tensor input);"
)

global_avg_pool2d = load_inline(
    name="global_avg_pool2d",
    cpp_sources=global_avg_pool2d_cpp_source,
    cuda_sources=global_avg_pool2d_source,
    functions=["global_avg_pool2d_cuda"],
    verbose=False, # Set to True for debugging compilation issues
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# --- MBConvNew class using custom kernels ---
class MBConvNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        """
        MBConv block implementation, optimized with custom CUDA kernels.

        :param in_channels: Number of input channels.
        :param out_channels: Number of output channels.
        :param kernel_size: Kernel size for the depthwise convolution.
        :param stride: Stride for the depthwise convolution.
        :param expand_ratio: Expansion ratio for the intermediate channels.
        """
        super(MBConvNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio

        if expand_ratio != 1:
            self.expand_conv = nn.Sequential(
                nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(hidden_dim),
                nn.ReLU6(inplace=True)
            )

        self.depthwise_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size-1)//2, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
            nn.ReLU6(inplace=True)
        )

        self.project_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels)
        )

        # Load custom element-wise add kernel for residual connections
        self.elementwise_add = elementwise_add

    def forward(self, x):
        """
        Forward pass of the MBConv block.

        :param x: The input tensor, shape (batch_size, in_channels, H, W)
        :return: The output tensor, shape (batch_size, out_channels, H', W')
        """
        identity = x

        if hasattr(self, 'expand_conv'):
            x = self.expand_conv(x)

        x = self.depthwise_conv(x)
        x = self.project_conv(x)

        if self.use_residual:
            # Replace PyTorch's element-wise addition with custom CUDA kernel
            x = self.elementwise_add.elementwise_add_cuda(x, identity)

        return x

# --- ModelNew class using custom kernels and MBConvNew ---
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        EfficientNetB0 architecture implementation in PyTorch, optimized with custom CUDA kernels.

        :param num_classes: The number of output classes (default is 1000 for ImageNet).
        """
        super(ModelNew, self).__init__()

        # Initial convolutional layer
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        # MBConv blocks (using the optimized MBConvNew)
        self.blocks = nn.Sequential(
            # MBConv1 (32, 16, 1, 1)
            MBConvNew(32, 16, kernel_size=3, stride=1, expand_ratio=1),
            # MBConv6 (16, 24, 2, 6)
            MBConvNew(16, 24, kernel_size=3, stride=2, expand_ratio=6),
            # MBConv6 (24, 24, 1, 6)
            MBConvNew(24, 24, kernel_size=3, stride=1, expand_ratio=6),
            # MBConv6 (24, 40, 2, 6)
            MBConvNew(24, 40, kernel_size=5, stride=2, expand_ratio=6),
            # MBConv6 (40, 40, 1, 6)
            MBConvNew(40, 40, kernel_size=5, stride=1, expand_ratio=6),
            # MBConv6 (40, 80, 2, 6)
            MBConvNew(40, 80, kernel_size=3, stride=2, expand_ratio=6),
            # MBConv6 (80, 80, 1, 6)
            MBConvNew(80, 80, kernel_size=3, stride=1, expand_ratio=6),
            # MBConv6 (80, 112, 1, 6)
            MBConvNew(80, 112, kernel_size=5, stride=1, expand_ratio=6),
            # MBConv6 (112, 112, 1, 6)
            MBConvNew(112, 112, kernel_size=5, stride=1, expand_ratio=6),
            # MBConv6 (112, 192, 2, 6)
            MBConvNew(112, 192, kernel_size=5, stride=2, expand_ratio=6),
            # MBConv6 (192, 192, 1, 6)
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            # MBConv6 (192, 192, 1, 6)
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            # MBConv6 (192, 320, 1, 6)
            MBConvNew(192, 320, kernel_size=3, stride=1, expand_ratio=6)
        )

        # Final convolutional layer
        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)

        # Fully connected layer
        self.fc = nn.Linear(1280, num_classes)

        # Load custom global average pooling kernel
        self.global_avg_pool2d = global_avg_pool2d

    def forward(self, x):
        """
        Forward pass of the EfficientNetB0 model.

        :param x: The input tensor, shape (batch_size, 3, 224, 224)
        :return: The output tensor, shape (batch_size, num_classes)
        """
        x = F.relu(self.bn1(self.conv1(x)))
        x = self.blocks(x)
        x = F.relu(self.bn2(self.conv2(x)))

        # Replace F.adaptive_avg_pool2d with custom CUDA kernel
        x = self.global_avg_pool2d.global_avg_pool2d_cuda(x)

        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x

