class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.bias = bias
        self.batch_first = batch_first
        self.num_directions = 2 # The original model uses bidirectional=True

        # We use an instance of nn.GRU purely to obtain and manage the learnable weights and biases.
        # The actual forward pass logic will be implemented manually using our custom kernel.
        # This ensures our custom implementation uses the same weight initialization as PyTorch's GRU.
        self.gru_weights_container = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first, dropout=0, bidirectional=True)

        # Register the custom CUDA kernel function
        self.gru_elementwise_fusion_cuda = gru_elementwise_fusion.gru_elementwise_fusion_cuda

    def forward(self, x, h0):
        # Ensure inputs are on the CUDA device
        x = x.cuda()
        h0 = h0.cuda()

        # Assuming batch_first=False as per the original model:
        # x shape: (seq_len, batch_size, input_size)
        seq_len, batch_size, _ = x.shape

        # h_n_output will store the final hidden states for all layers and directions.
        # Its shape matches the output h_n of nn.GRU: (num_layers * num_directions, batch_size, hidden_size)
        h_n_output = torch.zeros(self.num_layers * self.num_directions, batch_size, self.hidden_size, device=x.device)

        # This tensor will hold the combined output (forward + backward) of the previous layer,
        # which serves as the input for the current layer (for layers > 0).
        prev_layer_output_combined = None

        # Iterate through each GRU layer
        for layer in range(self.num_layers):
            # Retrieve weights and biases for the current layer (forward direction)
            w_ih_l = getattr(self.gru_weights_container, f'weight_ih_l{layer}')
            w_hh_l = getattr(self.gru_weights_container, f'weight_hh_l{layer}')
            b_ih_l = getattr(self.gru_weights_container, f'bias_ih_l{layer}') if self.bias else None
            b_hh_l = getattr(self.gru_weights_container, f'bias_hh_l{layer}') if self.bias else None

            # Retrieve weights and biases for the current layer (reverse direction)
            w_ih_l_reverse = getattr(self.gru_weights_container, f'weight_ih_l{layer}_reverse')
            w_hh_l_reverse = getattr(self.gru_weights_container, f'weight_hh_l{layer}_reverse')
            b_ih_l_reverse = getattr(self.gru_weights_container, f'bias_ih_l{layer}_reverse') if self.bias else None
            b_hh_l_reverse = getattr(self.gru_weights_container, f'bias_hh_l{layer}_reverse') if self.bias else None

            # Determine the input for the current layer.
            # For the first layer (layer 0), the input is the original input 'x'.
            # For subsequent layers (layer > 0), the input is the concatenated output
            # (forward and backward) of the previous layer.
            if layer == 0:
                current_input_forward = x
                current_input_reverse = x
            else:
                # For layers > 0, the input_size for the GRU cell is `num_directions * hidden_size`.
                current_input_forward = prev_layer_output_combined
                current_input_reverse = prev_layer_output_combined

            # Initialize the hidden states for the current layer from the initial hidden state 'h0'.
            # h0 has shape (num_layers * num_directions, batch_size, hidden_size).
            h_prev_forward = h0[layer * self.num_directions, :, :]
            h_prev_reverse = h0[layer * self.num_directions + 1, :, :]

            # Tensors to store the sequence of hidden states for the current layer's forward and reverse passes.
            layer_output_forward = torch.empty(seq_len, batch_size, self.hidden_size, device=x.device)
            layer_output_reverse = torch.empty(seq_len, batch_size, self.hidden_size, device=x.device)

            # --- Forward Direction Pass ---
            for t in range(seq_len):
                x_t = current_input_forward[t, :, :] # Input at current time step (batch_size, input_size_for_this_layer)

                # Perform linear transformations (matrix multiplication + bias addition) using PyTorch's F.linear.
                # These operations are typically highly optimized (e.g., using cuBLAS/cuDNN).
                gates_ih = F.linear(x_t, w_ih_l, b_ih_l) # (batch_size, 3 * hidden_size)
                gates_hh = F.linear(h_prev_forward, w_hh_l, b_hh_l) # (batch_size, 3 * hidden_size)

                # Perform fused element-wise operations and activations using our custom CUDA kernel.
                # This replaces multiple PyTorch element-wise ops (add, sigmoid, tanh, mul, sub) with one kernel launch.
                h_curr_forward = self.gru_elementwise_fusion_cuda(gates_ih, gates_hh, h_prev_forward)

                layer_output_forward[t, :, :] = h_curr_forward # Store current hidden state
                h_prev_forward = h_curr_forward # Update h_prev for the next time step

            # Store the final hidden state of the forward pass for this layer.
            h_n_output[layer * self.num_directions, :, :] = h_prev_forward

            # --- Reverse Direction Pass ---
            # Process the sequence in reverse order for the backward direction.
            for t in range(seq_len - 1, -1, -1):
                x_t_reverse = current_input_reverse[t, :, :] # Input at current time step (batch_size, input_size_for_this_layer)

                # Perform linear transformations for the reverse direction.
                gates_ih_reverse = F.linear(x_t_reverse, w_ih_l_reverse, b_ih_l_reverse)
                gates_hh_reverse = F.linear(h_prev_reverse, w_hh_l_reverse, b_hh_l_reverse)

                # Perform fused element-wise operations and activations using our custom CUDA kernel.
                h_curr_reverse = self.gru_elementwise_fusion_cuda(gates_ih_reverse, gates_hh_reverse, h_prev_reverse)

                layer_output_reverse[t, :, :] = h_curr_reverse # Store current hidden state
                h_prev_reverse = h_curr_reverse # Update h_prev for the next time step

            # Store the final hidden state of the reverse pass for this layer.
            h_n_output[layer * self.num_directions + 1, :, :] = h_prev_reverse

            # Combine the forward and reverse outputs of the current layer.
            # The output of a bidirectional GRU layer is the concatenation of its forward and backward outputs.
            # This combined output will serve as the input for the next layer.
            # Shape: (seq_len, batch_size, hidden_size * 2)
            prev_layer_output_combined = torch.cat((layer_output_forward, layer_output_reverse), dim=2)

        # The original model returns h_n, which is the final hidden state for t=seq_len
        # across all layers and directions. Our h_n_output tensor already contains these.
        return h_n_output

