class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        """
        MBConv block implementation with custom CUDA kernels.

        :param in_channels: Number of input channels.
        :param out_channels: Number of output channels.
        :param kernel_size: Kernel size for the depthwise convolution.
        :param stride: Stride for the depthwise convolution.
        :param expand_ratio: Expansion ratio for the intermediate channels.
        """
        super(ModelNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio

        # Expose the compiled CUDA functions as attributes
        self.fused_conv1x1_bn_relu6_op = fused_ops.fused_conv1x1_bn_relu6_cuda
        self.fused_depthwise_conv_bn_relu6_op = fused_ops.fused_depthwise_conv_bn_relu6_cuda
        self.fused_conv1x1_bn_add_op = fused_ops.fused_conv1x1_bn_add_cuda

        # Initialize and extract parameters for expand_conv (if expand_ratio != 1)
        # We create the original PyTorch modules to get their default initialized weights/biases/running_stats,
        # then extract these parameters and store them as buffers for our custom kernels.
        if expand_ratio != 1:
            expand_conv_module = nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False)
            expand_bn_module = nn.BatchNorm2d(hidden_dim)

            # Move modules to CUDA to ensure parameters are on GPU
            expand_conv_module.cuda()
            expand_bn_module.cuda()

            self.register_buffer('expand_conv_weight', expand_conv_module.weight.data.clone().contiguous())
            self.register_buffer('expand_bn_weight', expand_bn_module.weight.data.clone().contiguous())
            self.register_buffer('expand_bn_bias', expand_bn_module.bias.data.clone().contiguous())
            self.register_buffer('expand_bn_mean', expand_bn_module.running_mean.data.clone().contiguous())
            self.register_buffer('expand_bn_var', expand_bn_module.running_var.data.clone().contiguous())
            self.expand_bn_eps = expand_bn_module.eps
        # If expand_ratio == 1, the expand_conv block is skipped, so no parameters are stored.

        # Initialize and extract parameters for depthwise_conv
        depthwise_conv_module = nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size-1)//2, groups=hidden_dim, bias=False)
        depthwise_bn_module = nn.BatchNorm2d(hidden_dim)

        depthwise_conv_module.cuda()
        depthwise_bn_module.cuda()

        self.register_buffer('depthwise_conv_weight', depthwise_conv_module.weight.data.clone().contiguous())
