import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused LayerNorm and element-wise addition
# This kernel combines the residual connection (attn_output + x_reshaped)
# and the Layer Normalization into a single CUDA kernel to reduce memory bandwidth
# and improve cache utilization.
fused_layernorm_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for checking CUDA errors
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error in %s:%d - %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(EXIT_FAILURE); \\
        } \\
    } while (0)

__global__ void fused_layernorm_add_kernel(
    const float* attn_output,
    const float* x_input,
    const float* gamma, // LayerNorm weight
    const float* beta,  // LayerNorm bias
    float* out,
    int seq_len,
    int batch_size,
    float eps) {

    // The embedding dimension (embed_dim) is determined by blockDim.x
    int embed_dim = blockDim.x;

    // Each block processes one (seq_len, batch_size) element group.
    // group_idx maps to a specific (sequence_position, batch_item) pair.
    int group_idx = blockIdx.x;

    // Guard against out-of-bounds block indices if num_blocks is not exact
    if (group_idx >= seq_len * batch_size) {
        return;
    }

    // Each thread processes one element within the embed_dim.
    // threadIdx.x is guaranteed to be < embed_dim because blockDim.x == embed_dim.

    // Pointers to the start of the current group's data in global memory
    const float* current_attn_output_ptr = attn_output + group_idx * embed_dim;
    const float* current_x_input_ptr = x_input + group_idx * embed_dim;
    float* current_out_ptr = out + group_idx * embed_dim;

    // Dynamically allocated shared memory for reduction.
    // We need 2 * embed_dim floats: one for sum, one for sum of squares.
    extern __shared__ float s_data[];

    // Perform element-wise addition and store the value and its square in shared memory.
    // Each thread computes for its corresponding element in embed_dim.
    float val = current_attn_output_ptr[threadIdx.x] + current_x_input_ptr[threadIdx.x];
    s_data[threadIdx.x] = val; // Store val for sum
    s_data[threadIdx.x + embed_dim] = val * val; // Store val*val for sum of squares

    __syncthreads(); // Ensure all threads have written to shared memory

    // Block-wide reduction for sum and sum of squares.
    // This uses a parallel reduction tree.
    for (int offset = embed_dim / 2; offset > 0; offset /= 2) {
        if (threadIdx.x < offset) {
            s_data[threadIdx.x] += s_data[threadIdx.x + offset]; // Sum reduction
            s_data[threadIdx.x + embed_dim] += s_data[threadIdx.x + embed_dim + offset]; // Sum_sq reduction
        }
        __syncthreads(); // Synchronize after each reduction step
    }

    float mean = 0.0f;
    float rstd = 0.0f; // Reciprocal standard deviation

    // Only the first thread in the block computes the final mean and rstd
    // and broadcasts them via shared memory.
    if (threadIdx.x == 0) {
        float total_sum = s_data[0];
        float total_sum_sq = s_data[embed_dim]; // Sum of squares is stored starting at embed_dim offset

        mean = total_sum / embed_dim;
        float var = (total_sum_sq / embed_dim) - (mean * mean);
        var = fmaxf(0.0f, var); // Ensure variance is non-negative
        rstd = rsqrtf(var + eps); // 1 / sqrt(var + eps)

        // Store mean and rstd back into shared memory for broadcast to all threads
        s_data[0] = mean;
        s_data[1] = rstd;
    }
    __syncthreads(); // Make mean and rstd visible to all threads

    // Retrieve broadcasted mean and rstd
    mean = s_data[0];
    rstd = s_data[1];

    // Apply normalization and affine transformation (gamma * normalized_val + beta)
    // Each thread computes its final output element.
    current_out_ptr[threadIdx.x] = gamma[threadIdx.x] * ((val - mean) * rstd) + beta[threadIdx.x];
}

// C++ wrapper function for the CUDA kernel
torch::Tensor fused_layernorm_add_cuda(
    torch::Tensor attn_output,
    torch::Tensor x_input,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps) {

    // Ensure inputs are contiguous and on CUDA for efficient memory access in the kernel.
    // Permute and view operations in PyTorch can make tensors non-contiguous.
    attn_output = attn_output.contiguous();
    x_input = x_input.contiguous();
    gamma = gamma.contiguous();
    beta = beta.contiguous();

    // Get dimensions from the input tensors
    int seq_len = attn_output.size(0);
    int batch_size = attn_output.size(1);
    int embed_dim = attn_output.size(2);

    // Create the output tensor, ensuring it's on the same device as inputs
    auto out = torch::empty_like(attn_output);

    // Kernel launch parameters:
    // Each block will process one (seq_len, batch_size) group.
    // The number of threads per block (block_size) is set to embed_dim,
    // which is efficient for LayerNorm over the last dimension.
    const int block_size = embed_dim;
    const int num_groups = seq_len * batch_size;
    const int num_blocks = num_groups;
    // Calculate required dynamic shared memory size for sum and sum_sq
    const int shared_mem_size = 2 * embed_dim * sizeof(float);

    // Launch the CUDA kernel
    fused_layernorm_add_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        attn_output.data_ptr<float>(),
        x_input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        seq_len,
        batch_size,
        eps);

    CUDA_CHECK(cudaGetLastError()); // Check for any CUDA errors after kernel launch

    return out;
}
"""

# C++ header for the inline compilation
fused_layernorm_add_cpp_source = (
    "torch::Tensor fused_layernorm_add_cuda("
    "torch::Tensor attn_output, torch::Tensor x_input, "
    "torch::Tensor gamma, torch::Tensor beta, float eps);"
)

# Compile the inline CUDA code
fused_layernorm_add = load_inline(
    name="fused_layernorm_add",
    cpp_sources=fused_layernorm_add_cpp_source,
    cuda_sources=fused_layernorm_add_source,
    functions=["fused_layernorm_add_cuda"],
    verbose=True, # Set to True to see compilation output
    extra_cflags=["-O3"], # General C++ optimization flags
    extra_cuda_cflags=["-O3", "--use_fast_math"], # CUDA specific optimization flags
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self, embed_dim, num_heads):
        """
        Optimized Attention Block using Multihead Self-Attention with a fused LayerNorm and residual add.
        :param embed_dim: Embedding dimension (the number of channels)
        :param num_heads: Number of attention heads
        """
        super(ModelNew, self).__init__()
        self.attn = nn.MultiheadAttention(embed_dim, num_heads)
        # We instantiate nn.LayerNorm to get its learnable parameters (weight, bias) and eps.
        # The actual LayerNorm computation will be performed by our custom fused kernel.
        self.norm = nn.LayerNorm(embed_dim)
        self.fused_layernorm_add_op = fused_layernorm_add

    def forward(self, x):
        """
        Forward pass of the AttentionBlock.
        :param x: Input tensor of shape (B, C, H, W)
        :return: Output tensor of the same shape (B, C, H, W)
        """
        B, C, H, W = x.shape
        # Reshape and permute the input tensor for MultiheadAttention.
        # Original: (B, C, H, W) -> (B, C, H*W) -> (H*W, B, C)
        # (seq_len, batch_size, embed_dim) where seq_len = H*W, embed_dim = C
        x_reshaped = x.view(B, C, H * W).permute(2, 0, 1)

        # Perform MultiheadAttention. This is a complex operation,
        # and PyTorch's implementation is highly optimized (often using cuBLAS/cuDNN).
        # Replacing this with a custom kernel is generally not beneficial without
        # deep architectural insights or specific hardware targeting.
        attn_output, _ = self.attn(x_reshaped, x_reshaped, x_reshaped)

        # Replace the original `x = self.norm(attn_output + x_reshaped)`
        # with our custom fused CUDA kernel.
        # This fuses the element-wise addition (residual connection) and Layer Normalization
        # into a single kernel launch, reducing memory transfers and improving performance.
        fused_output = self.fused_layernorm_add_op.fused_layernorm_add_cuda(
            attn_output,
            x_reshaped,
            self.norm.weight, # LayerNorm's learnable gamma parameter
            self.norm.bias,   # LayerNorm's learnable beta parameter
            self.norm.eps     # LayerNorm's epsilon for numerical stability
        )

        # Permute and reshape the output back to the original (B, C, H, W) format.
        x_final = fused_output.permute(1, 2, 0).view(B, C, H, W)
        return x_final

