import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math # Required for nn.init._calculate_fan_in_and_fan_out and math.sqrt

# Define the custom CUDA kernel for fused bias addition and ReLU activation
bias_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For std::max

// CUDA kernel for fused bias addition and ReLU activation
// This kernel performs: output[i] = ReLU(input[i] + bias[feature_idx])
// where feature_idx is the column index in the 2D input tensor.
__global__ void bias_relu_kernel(const float* input, const float* bias, float* output, int num_elements, int output_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        // The bias is added per feature.
        // For an input tensor of shape (batch_size, output_features),
        // idx % output_features gives the feature index (column index).
        int feature_idx = idx % output_features; 
        float val = input[idx] + bias[feature_idx];
        output[idx] = (val > 0) ? val : 0;
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor bias_relu_cuda(torch::Tensor input, torch::Tensor bias) {
    // Ensure inputs are on CUDA and are float32
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");

    // Input tensor shape: (batch_size, output_features)
    // Bias tensor shape: (output_features)
    TORCH_CHECK(input.dim() == 2, "input must be 2D (batch_size, output_features)");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D (output_features)");
    TORCH_CHECK(input.size(1) == bias.size(0), "input last dimension must match bias size");

    // Create an output tensor with the same shape and type as the input
    auto output = torch::empty_like(input);

    int num_elements = input.numel(); // Total number of elements in the input tensor
    int output_features = bias.numel(); // Number of features (size of the bias tensor)

    // Configure CUDA kernel launch parameters
    const int block_size = 256; // Standard block size
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    bias_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        output_features
    );

    // Check for any CUDA errors that occurred during kernel execution
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in bias_relu_cuda: ", cudaGetErrorString(err));
    }

    return output;
}
"""

bias_relu_cpp_source = (
    "torch::Tensor bias_relu_cuda(torch::Tensor input, torch::Tensor bias);"
)

# Compile the inline CUDA code for fused bias addition and ReLU
# verbose=False to suppress compilation output unless debugging
bias_relu_op = load_inline(
    name="bias_relu_fusion",
    cpp_sources=bias_relu_cpp_source,
    cuda_sources=bias_relu_source,
    functions=["bias_relu_cuda"],
    verbose=False, 
    extra_cflags=["-O3"], # Optimization flags for C++ compiler
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Optimization flags for CUDA compiler
)


class LinearReLU(nn.Module):
    """
    A custom module that fuses nn.Linear's matrix multiplication with bias addition and ReLU activation.
    It leverages PyTorch's highly optimized F.linear for the matrix multiplication
    and then applies a custom CUDA kernel for the fused bias_add + ReLU.
    """
    def __init__(self, in_features: int, out_features: int, bias: bool = True):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        # Weights are stored similar to nn.Linear
        self.weight = nn.Parameter(torch.empty(out_features, in_features))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_features))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

        # Store a reference to the compiled custom CUDA function
        self.bias_relu_cuda_op = bias_relu_op.bias_relu_cuda

    def reset_parameters(self) -> None:
        # Initialize weights and biases using PyTorch's default nn.Linear initialization
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        # Perform matrix multiplication: input @ weight.T
        # F.linear is used without bias here, as bias will be added by the custom kernel
        output = F.linear(input, self.weight, None) 

        if self.bias is not None:
            # Apply the custom fused bias_add + ReLU kernel
            return self.bias_relu_cuda_op(output, self.bias)
        else:
            # If no bias, just apply ReLU using PyTorch's F.relu
            # (The primary fusion benefit is bias_add + ReLU, so F.relu is sufficient here)
            return F.relu(output)


class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_layer_sizes: list[int], output_size: int):
        """
        :param input_size: The number of input features
        :param hidden_layer_sizes: A list of ints containing the sizes of each hidden layer
        :param output_size: The number of output features
        """
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        # Replace nn.Linear + nn.ReLU pairs with the custom LinearReLU module for hidden layers
        for hidden_size in hidden_layer_sizes:
            layers.append(LinearReLU(current_input_size, hidden_size))
            current_input_size = hidden_size

        # The final layer remains a standard nn.Linear as there's no ReLU after it in the original model
        layers.append(nn.Linear(current_input_size, output_size))

        self.network = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        :param x: The input tensor, shape (batch_size, input_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        return self.network(x)

