import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for MaxPool2d (kernel_size=2, stride=2)
# This kernel replaces the standard nn.MaxPool2d(kernel_size=2, stride=2) operator.
# Each thread computes one output element, iterating over a 2x2 window in the input.
max_pool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

// MaxPool2d kernel for kernel_size=2, stride=2
__global__ void max_pool2d_kernel(const float* input, float* output,
                                  int N, int C, int H_in, int W_in,
                                  int H_out, int W_out) {
    // Each thread computes one output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H_out * W_out) {
        // Map flat index to (n, c, h_out, w_out)
        int n = idx / (C * H_out * W_out);
        int c = (idx / (H_out * W_out)) % C;
        int h_out = (idx / W_out) % H_out;
        int w_out = idx % W_out;

        // Calculate input region start coordinates for a 2x2 kernel with stride 2
        int h_start = h_out * 2; // stride = 2
        int w_start = w_out * 2; // stride = 2

        float max_val = -FLT_MAX; // Initialize with smallest possible float

        // Iterate over the 2x2 kernel window
        for (int kh = 0; kh < 2; ++kh) { // kernel_size = 2
            for (int kw = 0; kw < 2; ++kw) { // kernel_size = 2
                int h_in = h_start + kh;
                int w_in = w_start + kw;

                // Check bounds to handle edge cases, though for VGG's 224x224 input
                // and kernel/stride of 2, this might not be strictly necessary
                // as dimensions are perfectly divisible. It's good practice for robustness.
                if (h_in < H_in && w_in < W_in) {
                    // Calculate linear index for input (N, C, H_in, W_in layout)
                    int input_idx = n * (C * H_in * W_in) +
                                    c * (H_in * W_in) +
                                    h_in * W_in +
                                    w_in;
                    max_val = fmaxf(max_val, input[input_idx]);
                }
            }
        }
        // Store the max value in the output tensor (N, C, H_out, W_out layout)
        output[idx] = max_val;
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor max_pool2d_cuda(torch::Tensor input) {
    // Input validation
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor.");
    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input must be float32.");
    TORCH_CHECK(input.dim() == 4, "Input must be 4D (N, C, H, W).");

    int N = input.size(0);
    int C = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    // Calculate output dimensions for kernel_size=2, stride=2
    // PyTorch's default MaxPool2d output size calculation:
    // H_out = floor((H_in + 2*padding - kernel_size) / stride) + 1
    // For kernel_size=2, stride=2, padding=0:
    // H_out = floor((H_in - 2) / 2) + 1
    int H_out = (H_in - 2) / 2 + 1;
    int W_out = (W_in - 2) / 2 + 1;

    // Create output tensor with the same options (device, dtype) as input
    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    // Calculate grid and block dimensions for kernel launch
    int total_elements = N * C * H_out * W_out;
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    max_pool2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H_in, W_in, H_out, W_out
    );

    return output;
}
"""

max_pool2d_cpp_source = (
    "torch::Tensor max_pool2d_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code for MaxPool2d
max_pool2d_custom = load_inline(
    name="max_pool2d_custom",
    cpp_sources=max_pool2d_cpp_source,
    cuda_sources=max_pool2d_source,
    functions=["max_pool2d_cuda"],
    verbose=False, # Set to True for compilation details
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[],
)

# A wrapper module to integrate the custom CUDA function into nn.Sequential
# This is necessary because nn.Sequential expects instances of nn.Module.
class CustomMaxPool2dWrapper(nn.Module):
    def __init__(self, custom_max_pool_func):
        super().__init__()
        self.custom_max_pool_func = custom_max_pool_func

    def forward(self, x):
        return self.custom_max_pool_func(x)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        Initialize the VGG16 model with custom CUDA kernels for MaxPool2d.

        :param num_classes: The number of output classes (default is 1000 for ImageNet)
        """
        super(ModelNew, self).__init__()

        # Store the custom MaxPool2d function from the compiled CUDA module
        self.custom_max_pool2d_op = max_pool2d_custom.max_pool2d_cuda

        # VGG16 architecture: 5 blocks of convolutional layers followed by max pooling
        # All instances of nn.MaxPool2d(kernel_size=2, stride=2) are replaced with our custom kernel.
        self.features = nn.Sequential(
            # Block 1
            nn.Conv2d(3, 64, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            nn.Conv2d(64, 64, kernel_size=3, padding=1),
            nn.ReLU(inplace=True),
            CustomMaxPool2dWrapper(self.custom_max_pool2d_op), # Custom MaxPool2d

            # Block 2
