import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA Kernels and their loading ---

# CUDA kernel for Fused BatchNorm + ReLU6
fused_bn_relu6_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrt

// CUDA kernel to perform BatchNorm and ReLU6 in a single pass
// Assumes NCHW input layout.
// input: (N, C, H, W)
// bn_weight, bn_bias, running_mean, running_var: (C)
__global__ void fused_bn_relu6_kernel(
    const float* input,
    const float* bn_weight,
    const float* bn_bias,
    const float* running_mean,
    const float* running_var,
    float* output,
    int N, int C, int H, int W, float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx < total_elements) {
        // Calculate channel index 'c' for the current element
        // NCHW layout: idx = n * C*H*W + c * H*W + h * W + w
        int c = (idx / (H * W)) % C;

        float val = input[idx];

        // BatchNorm calculation (inference mode)
        float mean = running_mean[c];
        float var = running_var[c];
        float weight = bn_weight[c];
        float bias = bn_bias[c];

        float normalized_val = (val - mean) / sqrtf(var + eps);
        float bn_val = normalized_val * weight + bias;

        // ReLU6 activation
        float relu6_val = fmaxf(0.0f, fminf(bn_val, 6.0f));

        output[idx] = relu6_val;
    }
}

// C++ wrapper for the fused_bn_relu6_kernel
torch::Tensor fused_bn_relu6_cuda(
    torch::Tensor input,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float eps) {

    // Ensure input tensors are contiguous and on CUDA device
    // .contiguous() might create a copy if the tensor is not already contiguous.
    // For optimal performance, inputs should ideally already be contiguous.
    input = input.contiguous();
    bn_weight = bn_weight.contiguous();
    bn_bias = bn_bias.contiguous();
    running_mean = running_mean.contiguous();
    running_var = running_var.contiguous();

    // Allocate output tensor on the same device as input
    auto output = torch::empty_like(input);

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int total_elements = N * C * H * W;

    // Define kernel launch configuration
    const int block_size = 256; // Standard block size
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    fused_bn_relu6_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
