# --- Custom Fused PyTorch Modules ---

class FusedConvBnReLU6(nn.Module):
    """
    A custom module that fuses nn.Conv2d, nn.BatchNorm2d, and nn.ReLU6
    into a single operation, using a custom CUDA kernel for BN+ReLU6.
    """
    def __init__(self, conv_module: nn.Conv2d, bn_module: nn.BatchNorm2d):
        super().__init__()
        self.conv = conv_module

        # Extract and register BatchNorm parameters and buffers.
        # These need to be registered so they are moved to the correct device
        # and included in the model's state_dict.
        self.register_parameter('bn_weight', bn_module.weight)
        self.register_parameter('bn_bias', bn_module.bias)
        self.register_buffer('bn_running_mean', bn_module.running_mean)
        self.register_buffer('bn_running_var', bn_module.running_var)
        self.register_buffer('bn_num_batches_tracked', bn_module.num_batches_tracked)
        self.bn_eps = bn_module.eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Perform convolution using PyTorch's highly optimized F.conv2d (which uses cuDNN)
        conv_out = self.conv(x)

        # Apply fused BatchNorm + ReLU6 using the custom CUDA kernel
        # This assumes inference mode for BatchNorm (using running_mean and running_var).
        # For training, the kernel would need to compute batch statistics.
        return fused_bn_relu6_module.fused_bn_relu6_cuda(
            conv_out,
            self.bn_weight,
            self.bn_bias,
            self.bn_running_mean,
            self.bn_running_var,
            self.bn_eps
        )

class FusedConvBn(nn.Module):
    """
    A custom module that fuses nn.Conv2d and nn.BatchNorm2d
    into a single operation, using a custom CUDA kernel for BN.
    """
    def __init__(self, conv_module: nn.Conv2d, bn_module: nn.BatchNorm2d):
        super().__init__()
        self.conv = conv_module

        # Extract and register BatchNorm parameters and buffers
        self.register_parameter('bn_weight', bn_module.weight)
        self.register_parameter('bn_bias', bn_module.bias)
        self.register_buffer('bn_running_mean', bn_module.running_mean)
        self.register_buffer('bn_running_var', bn_module.running_var)
        self.register_buffer('bn_num_batches_tracked', bn_module.num_batches_tracked)
        self.bn_eps = bn_module.eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Perform convolution
        conv_out = self.conv(x)

        # Apply fused BatchNorm using the custom CUDA kernel
        # This assumes inference mode for BatchNorm.
        return fused_bn_module.fused_bn_cuda(
            conv_out,
            self.bn_weight,
            self.bn_bias,
            self.bn_running_mean,
            self.bn_running_var,
            self.bn_eps
        )

class InvertedResidualFused(nn.Module):
    """
    A wrapper for the inverted residual block that handles the residual connection.
    The block itself (self.block) contains the fused Conv+BN/ReLU6 operations.
    """
    def __init__(self, block: nn.Sequential):
        super().__init__()
        self.block = block

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        identity = x
        out = self.block(x)
        # The element-wise addition for the residual connection is still a PyTorch operator.
        # Fusing this would require a more complex custom kernel that takes two inputs.
        return identity + out

class ModelNew(nn.Module):
    def __init__(self, num_classes: int = 1000):
        """
        MobileNetV2 architecture implementation in PyTorch, optimized with custom CUDA kernel fusions.
        Specifically, Conv2d + BatchNorm2d + ReLU6 and Conv2d + BatchNorm2d sequences are fused.

        :param num_classes: The number of output classes. Default is 1000.
        """
        super(ModelNew, self).__init__()

        def _make_divisible(v: float, divisor: int, min_value: int = None) -> int:
            """
            This function ensures that the number of channels is divisible by the divisor.
            """
            if min_value is None:
                min_value = divisor
            new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
            # Make sure that round down does not go down by more than 10%.
            if new_v < 0.9 * v:
                new_v += divisor
            return new_v

        def _inverted_residual_block(inp: int, oup: int, stride: int, expand_ratio: int):
            """
            Inverted Residual Block for MobileNetV2, using the custom fused modules.
            """
            hidden_dim = int(inp * expand_ratio)
            use_res_connect = stride == 1 and inp == oup

            block_layers = []
            if expand_ratio != 1:
                # Expansion phase: Pointwise convolution + BN + ReLU6
                conv1 = nn.Conv2d(inp, hidden_dim, 1, 1, 0, bias=False)
                bn1 = nn.BatchNorm2d(hidden_dim)
                block_layers.append(FusedConvBnReLU6(conv1, bn1))

            # Depthwise phase: Depthwise convolution + BN + ReLU6
            conv2 = nn.Conv2d(hidden_dim, hidden_dim, 3, stride, 1, groups=hidden_dim, bias=False)
            bn2 = nn.BatchNorm2d(hidden_dim)
            block_layers.append(FusedConvBnReLU6(conv2, bn2))

            # Projection phase: Pointwise linear convolution + BN (no ReLU6)
            conv3 = nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False)
            bn3 = nn.BatchNorm2d(oup)
            block_layers.append(FusedConvBn(conv3, bn3))

            return nn.Sequential(*block_layers), use_res_connect

        # MobileNetV2 architecture parameters
        input_channel = 32
        last_channel = 1280
        inverted_residual_setting = [
            # t (expand_ratio), c (output_channel), n (num_blocks), s (stride)
            [1, 16, 1, 1],
            [6, 24, 2, 2],
            [6, 32, 3, 2],
            [6, 64, 4, 2],
            [6, 96, 3, 1],
            [6, 160, 3, 2],
            [6, 320, 1, 1],
        ]

        # Building first layer: Conv + BN + ReLU6
        features = []
        conv_init = nn.Conv2d(3, input_channel, 3, 2, 1, bias=False)
        bn_init = nn.BatchNorm2d(input_channel)
        features.append(FusedConvBnReLU6(conv_init, bn_init))

        # Building inverted residual blocks
        for t, c, n, s in inverted_residual_setting:
            output_channel = _make_divisible(c, 8)
            for i in range(n):
                stride = s if i == 0 else 1
                block, use_res_connect = _inverted_residual_block(input_channel, output_channel, stride, expand_ratio=t)

                if use_res_connect:
                    features.append(InvertedResidualFused(block))
                else:
                    features.append(block)
                input_channel = output_channel

        # Building last several layers: Conv + BN + ReLU6
        conv_final = nn.Conv2d(input_channel, last_channel, 1, 1, 0, bias=False)
        bn_final = nn.BatchNorm2d(last_channel)
        features.append(FusedConvBnReLU6(conv_final, bn_final))

        # Final layer: AdaptiveAvgPool2d
        features.append(nn.AdaptiveAvgPool2d((1, 1)))

        self.features = nn.Sequential(*features)

        # Classifier
        self.classifier = nn.Sequential(
            nn.Dropout(0.0), # Dropout is typically a no-op during inference
            nn.Linear(last_channel, num_classes),
        )

        # Weight initialization
        for m in self.modules():
            if isinstance(m, nn.Conv2d):
                nn.init.kaiming_normal_(m.weight, mode='fan_out')
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
            elif isinstance(m, (FusedConvBnReLU6, FusedConvBn)):
                # Initialize the BatchNorm parameters within our fused modules
                nn.init.ones_(m.bn_weight)
                nn.init.zeros_(m.bn_bias)
                # running_mean and running_var are buffers, usually initialized to 0 and 1 respectively
                nn.init.zeros_(m.bn_running_mean)
                nn.init.ones_(m.bn_running_var)
            elif isinstance(m, nn.Linear):
                nn.init.normal_(m.weight, 0, 0.01)
                nn.init.zeros_(m.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass of the optimized MobileNetV2 model.

        :param x: The input tensor, shape (batch_size, 3, 224, 224)
        :return: The output tensor, shape (batch_size, num_classes)
        """
        x = self.features(x)
        x = x.view(x.size(0), -1) # Flatten for the linear classifier
        x = self.classifier(x)
        return x

