import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused scaled masked softmax
fused_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX
#include <cub/cub.cuh> // For block-level reductions

// Define a small negative number for masked_fill
#define NEG_INF -FLT_MAX

__global__ void fused_scaled_masked_softmax_kernel(
    const float* attn_scores_ptr,
    const float* bias_mask_ptr,
    float* output_ptr,
    int B, int nh, int T, // T is sequence length, also the last dim size for softmax
    float scale_factor
) {
    // Each block processes one row (T elements) of the attention matrix.
    // The attention matrix is (B, nh, T, T).
    // We are processing the last dimension (T) for softmax.
    // The total number of rows to process is B * nh * T.

    int row_idx_global = blockIdx.x; // Global row index (0 to B*nh*T - 1)

    if (row_idx_global >= B * nh * T) {
        return; // Out of bounds
    }

    // Calculate indices for the current row
    int b_idx = row_idx_global / (nh * T);
    int nh_idx = (row_idx_global % (nh * T)) / T;
    int t_idx = row_idx_global % T; // This is the row index within the (T, T) attention matrix

    // Pointers to the start of the current row in global memory
    // attn_scores_ptr is (B, nh, T, T)
    const float* current_attn_row_in = attn_scores_ptr + (b_idx * nh * T * T) + (nh_idx * T * T) + (t_idx * T);
    // bias_mask_ptr is (1, 1, T, T), so we only need to index by the last two T dimensions
    const float* current_bias_mask_row = bias_mask_ptr + (t_idx * T);
    float* current_output_row = output_ptr + (b_idx * nh * T * T) + (nh_idx * T * T) + (t_idx * T);

    // Shared memory for the entire row (T elements)
    extern __shared__ float s_row_data[];

    // --- Step 1: Load, Scale, Mask, and store in shared memory ---
    // Each thread loads its portion of the row, applies scale and mask, and stores in shared memory.
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        float val = current_attn_row_in[i] * scale_factor;
        // Apply causal mask: if bias_mask[t_idx][i] == 0, set to -inf
        if (current_bias_mask_row[i] == 0.0f) { 
            val = NEG_INF;
        }
        s_row_data[i] = val; // Store scaled and masked value in shared memory
    }
    __syncthreads();

    // --- Step 2: Find the maximum value across the row using CUB BlockReduce ---
    // Each thread contributes its portion of the shared memory row to the reduction.
    typedef cub::BlockReduce<float, 256> BlockReduce; // Assuming block_size = 256
    __shared__ typename BlockReduce::TempStorage temp_storage; // Shared memory for CUB's internal use

    float thread_max_val = NEG_INF;
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        thread_max_val = fmaxf(thread_max_val, s_row_data[i]);
    }
    float row_max = BlockReduce(temp_storage).Reduce(thread_max_val, cub::Max());
    __syncthreads(); // Ensure row_max is available to all threads

    // --- Step 3: Compute exponentials and find sum ---
    // Each thread computes exp(val - row_max) for its portion and stores back to shared memory.
    float thread_sum_exp = 0.0f;
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        float val = s_row_data[i]; // Get scaled and masked value from shared memory
        if (val == NEG_INF) {
            s_row_data[i] = 0.0f; // Masked elements become 0 after softmax
        } else {
            val = expf(val - row_max);
            s_row_data[i] = val; // Store expf(val - row_max) in shared memory
            thread_sum_exp += val;
        }
    }
    __syncthreads();

    // --- Step 4: Reduce to find the true sum of exponentials across the row ---
    float row_sum_exp = BlockReduce(temp_storage).Reduce(thread_sum_exp, cub::Sum());
    __syncthreads(); // Ensure row_sum_exp is available to all threads

    // --- Step 5: Normalize and write output ---
    // Each thread normalizes its exp(val - row_max) value and writes to global memory.
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        // s_row_data[i] now holds the expf(val - row_max) from Step 3
        if (row_sum_exp > 0.0f) { // Avoid division by zero
            current_output_row[i] = s_row_data[i] / row_sum_exp;
        } else {
            current_output_row[i] = 0.0f; // Should not happen if there's at least one non-masked element
        }
    }
}
"""

fused_softmax_cpp_source = (
    "torch::Tensor fused_scaled_masked_softmax_cuda(torch::Tensor attn_scores, float scale, torch::Tensor bias_mask);"
)

# Compile the inline CUDA code
fused_softmax_module = load_inline(
    name="fused_softmax_module",
    cpp_sources=fused_softmax_cpp_source,
    cuda_sources=fused_softmax_source,
    functions=["fused_scaled_masked_softmax_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Use fast math for CUDA
)


# From https://github.com/karpathy/minGPT/blob/master/mingpt/model.py

class ModelNew(nn.Module):
    """
    A vanilla multi-head masked self-attention layer with a projection at the end.
    It is possible to use torch.nn.MultiheadAttention here but I am including an
    explicit implementation here to show that there is nothing too scary here.
    """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        # causal mask to ensure that attention is only applied to the left in the input sequence
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

        # Register the custom CUDA kernel
        self.fused_scaled_masked_softmax = fused_softmax_module.fused_scaled_masked_softmax_cuda

    def forward(self, x):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, k ,v  = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        att = (q @ k.transpose(-2, -1)) # This is the raw attention scores (B, nh, T, T)

        # Use the custom fused kernel for scaling, masking, and softmax
        scale_factor = (1.0 / math.sqrt(k.size(-1)))
        # Ensure bias mask is on the same device as att
        bias_mask_for_T = self.bias[:,:,:T,:T]

        # Determine shared memory size for the kernel launch
        # T * sizeof(float) for s_row_data + cub::BlockReduce::TempStorage::Size
        block_size = 256 # Must match the template parameter in BlockReduce
        shared_mem_size = T * torch.finfo(torch.float32).bits // 8 + \
                          cub.BlockReduce.TempStorage.size(block_size)

        # Call the custom CUDA kernel
        att = self.fused_scaled_masked_softmax(att, scale_factor, bias_mask_for_T, 
                                               grid=(B * self.n_head * T,), 
                                               block=(block_size,), 
                                               stream=torch.cuda.current_stream(),
                                               shared_mem=shared_mem_size)

        att = self.attn_dropout(att) # Dropout is applied after softmax
        y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y

# The get_inputs and get_init_inputs functions are not part of the ModelNew class
# but are needed for testing/instantiation.
batch_size = 128
max_seqlen = 1024
seq_len = 512
n_embd = 768
n_head = 8
attn_pdrop = 0.0
resid_pdrop = 0.0

def get_inputs():
    # Ensure inputs are on CUDA device
    return [torch.rand(batch_size, seq_len, n_embd).cuda()]

def get_init_inputs():
    return [n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen]

