import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import math

# Define the custom CUDA kernel for fusing bias addition and ReLU activation
bias_add_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf

// CUDA kernel to perform element-wise bias addition and ReLU activation
__global__ void bias_add_relu_kernel(const float* input, const float* bias, float* out, int num_elements, int bias_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        // Bias is broadcasted across the batch dimension.
        // For an input of shape (B, N) and bias of shape (N),
        // the bias element for input[b][n] is bias[n].
        // When flattened, input[idx] corresponds to input[idx / N][idx % N].
        // So, bias[idx % bias_size] is the correct bias element.
        out[idx] = fmaxf(0.0f, input[idx] + bias[idx % bias_size]);
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor bias_add_relu_cuda(torch::Tensor input, torch::Tensor bias) {
    // Ensure inputs are on CUDA and contiguous
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");

    auto num_elements = input.numel();
    auto bias_size = bias.numel();

    // Allocate output tensor with the same shape and type as input
    auto out = torch::empty_like(input);

    // Define block and grid dimensions
    const int block_size = 256; // Standard block size
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    bias_add_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        num_elements,
        bias_size
    );

    // Check for any CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in bias_add_relu_cuda: %s\\n", cudaGetErrorString(err));
    }

    return out;
}
"""

# C++ source for the wrapper function declaration
bias_add_relu_cpp_source = (
    "torch::Tensor bias_add_relu_cuda(torch::Tensor input, torch::Tensor bias);"
)

# Compile the inline CUDA code
# This creates a Python module 'bias_add_relu_module' that contains the 'bias_add_relu_cuda' function
bias_add_relu_module = load_inline(
    name="bias_add_relu_module",
    cpp_sources=bias_add_relu_cpp_source,
    cuda_sources=bias_add_relu_source,
    functions=["bias_add_relu_cuda"],
    verbose=True, # Set to False for production to suppress compilation output
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"], # Use fast math for potential speedup
)


# Custom module that fuses nn.Linear's matrix multiplication with bias addition and ReLU
class LinearReLU(nn.Module):
    def __init__(self, in_features: int, out_features: int) -> None:
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        # Parameters are defined similar to nn.Linear
        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        self.bias = nn.Parameter(torch.empty(out_features))

        # Initialize parameters
        self.reset_parameters()

        # Get the custom CUDA function from the compiled module
        self.bias_add_relu_cuda = bias_add_relu_module.bias_add_relu_cuda

    def reset_parameters(self) -> None:
        # Standard initialization for nn.Linear's weight and bias
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        # Step 1: Perform matrix multiplication (input @ weight.T) using F.linear without bias
        # F.linear(input, weight, bias=None) computes input @ weight.T
        matmul_result = F.linear(input, self.weight, bias=None)

        # Step 2: Apply the fused bias addition and ReLU using the custom CUDA kernel
        return self.bias_add_relu_cuda(matmul_result, self.bias)

    def extra_repr(self) -> str:
        return f'in_features={self.in_features}, out_features={self.out_features}'


class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_layer_sizes: list[int], output_size: int) -> None:
        """
        :param input_size: The number of input features
        :param hidden_layer_sizes: A list of ints containing the sizes of each hidden layer
        :param output_size: The number of output features
        """
        super(ModelNew, self).__init__()

        layers = []
        current_input_size = input_size

        # Replace each (nn.Linear -> nn.ReLU) pair with our custom LinearReLU module
        for hidden_size in hidden_layer_sizes:
            layers.append(LinearReLU(current_input_size, hidden_size))
            current_input_size = hidden_size

        # The final layer is a standard nn.Linear layer as there's no ReLU after it
        layers.append(nn.Linear(current_input_size, output_size))

        self.network = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        :param x: The input tensor, shape (batch_size, input_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        return self.network(x)

