import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
fused_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Fused BatchNorm (folded) + ReLU + Conv1x1 + AvgPool2d(2x2, stride=2) kernel
__global__ void fused_bn_relu_conv1x1_avgpool_kernel(
    const float* x,
    const float* conv_weight,
    const float* conv_bias,
    float* out,
    int N, int C_in, int H, int W, int C_out) {

    // Each thread processes one output element (n, c_out, h_out, w_out)
    int total_out_elements = N * C_out * (H / 2) * (W / 2);
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_out_elements) {
        return;
    }

    int W_out = W / 2;
    int H_out = H / 2;

    // Calculate output indices
    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c_out = (idx / (W_out * H_out)) % C_out;
    int n = idx / (C_out * W_out * H_out);

    // Calculate corresponding input region for AvgPool
    int h_in_start = h_out * 2;
    int w_in_start = w_out * 2;

    float sum_relu_vals = 0.0f;

    // Iterate over the 2x2 pooling window
    for (int kh = 0; kh < 2; ++kh) {
        for (int kw = 0; kw < 2; ++kw) {
            int h_in = h_in_start + kh;
            int w_in = w_in_start + kw;

            // Perform 1x1 convolution for this input pixel (h_in, w_in)
            float conv_val = 0.0f;
            for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
                // Access x[n, c_in_idx, h_in, w_in]
                float input_val = x[n * C_in * H * W + c_in_idx * H * W + h_in * W + w_in];
                // Access conv_weight[c_out, c_in_idx]
                float weight_val = conv_weight[c_out * C_in + c_in_idx];
                conv_val += input_val * weight_val;
            }
            // Add bias (conv_bias[c_out])
            conv_val += conv_bias[c_out];

            // Apply ReLU
            float relu_val = fmaxf(0.0f, conv_val);
            sum_relu_vals += relu_val;
        }
    }
    // Apply AvgPool (divide by 4 for 2x2 window)
    out[n * C_out * H_out * W_out + c_out * H_out * W_out + h_out * W_out + w_out] = sum_relu_vals / 4.0f;
}

torch::Tensor fused_bn_relu_conv1x1_avgpool_cuda(
    torch::Tensor x,
    torch::Tensor conv_weight,
    torch::Tensor conv_bias) {

    // Input x: (N, C_in, H, W)
    // conv_weight: (C_out, C_in)
    // conv_bias: (C_out)

    // Ensure inputs are on CUDA and are float
    TORCH_CHECK(x.is_cuda(), "Input x must be a CUDA tensor.");
    TORCH_CHECK(conv_weight.is_cuda(), "conv_weight must be a CUDA tensor.");
    TORCH_CHECK(conv_bias.is_cuda(), "conv_bias must be a CUDA tensor.");
    TORCH_CHECK(x.dtype() == torch::kFloat, "Input x must be float32.");
    TORCH_CHECK(conv_weight.dtype() == torch::kFloat, "conv_weight must be float32.");
    TORCH_CHECK(conv_bias.dtype() == torch::kFloat, "conv_bias must be float32.");

    int N = x.size(0);
    int C_in = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    int C_out = conv_weight.size(0);

    // Check dimensions
    TORCH_CHECK(conv_weight.size(1) == C_in, "conv_weight C_in mismatch with input x C_in.");
    TORCH_CHECK(conv_bias.size(0) == C_out, "conv_bias C_out mismatch with conv_weight C_out.");
    TORCH_CHECK(H % 2 == 0 && W % 2 == 0, "Input height and width must be even for 2x2 AvgPool.");


    int H_out = H / 2;
    int W_out = W / 2;

    // Output tensor: (N, C_out, H_out, W_out)
    auto out = torch::zeros({N, C_out, H_out, W_out}, x.options());

    const int block_size = 256;
    int total_out_elements = N * C_out * H_out * W_out;
    const int num_blocks = (total_out_elements + block_size - 1) / block_size;

    fused_bn_relu_conv1x1_avgpool_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        conv_weight.data_ptr<float>(),
        conv_bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C_in, H, W, C_out);

    return out;
}
"""

fused_cpp_source = (
    "torch::Tensor fused_bn_relu_conv1x1_avgpool_cuda("
    "torch::Tensor x, torch::Tensor conv_weight, torch::Tensor conv_bias);"
)

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_bn_relu_conv1x1_avgpool",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_kernel_source,
    functions=["fused_bn_relu_conv1x1_avgpool_cuda"],
    verbose=True,
    extra_cflags=["-O3", "--use_fast_math"], # Add optimization flags for performance
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        super(ModelNew, self).__init__()

        # Instantiate original layers to extract and fold parameters.
        # These layers are only used during initialization to compute the fused
        # weights and biases, and are not part of the forward pass of ModelNew.
        bn_layer = nn.BatchNorm2d(num_input_features)
        conv_layer = nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False)

        # Set BN layer to eval mode to use running_mean and running_var.
        # This is crucial for correct parameter folding for inference.
        bn_layer.eval()

        # Move parameters to CUDA for calculation
        bn_weight = bn_layer.weight.data.cuda() # gamma
        bn_bias = bn_layer.bias.data.cuda()     # beta
        bn_running_mean = bn_layer.running_mean.cuda()
        bn_running_var = bn_layer.running_var.cuda()
        bn_eps = bn_layer.eps

        conv_weight_orig = conv_layer.weight.data.cuda() # Original Conv weight (C_out, C_in, 1, 1)

        # --- Fold BatchNorm parameters into Conv1x1 weights and biases ---
        # The BatchNorm operation for an input channel 'c_in' is:
        # y_c_in = x_c_in * S_c_in + B_c_in
        # where S_c_in = gamma_c_in / sqrt(var_c_in + eps)
        # and B_c_in = beta_c_in - mean_c_in * S_c_in

        # The original convolution for an output channel 'c_out' is:
        # out_c_out = sum_{c_in} (y_c_in * W_orig[c_out, c_in, 0, 0])
        # Substituting y_c_in:
        # out_c_out = sum_{c_in} ( (x_c_in * S_c_in + B_c_in) * W_orig[c_out, c_in, 0, 0] )
        # out_c_out = sum_{c_in} ( x_c_in * S_c_in * W_orig[c_out, c_in, 0, 0] ) + sum_{c_in} ( B_c_in * W_orig[c_out, c_in, 0, 0] )

        # So, the new convolution weight W'_new[c_out, c_in] = S_c_in * W_orig[c_out, c_in, 0, 0]
        # And the new convolution bias B'_new[c_out] = sum_{c_in} (B_c_in * W_orig[c_out, c_in, 0, 0])

        # Calculate scale and shift for each input channel
        scale = bn_weight / torch.sqrt(bn_running_var + bn_eps) # Shape: (C_in,)
        shift = bn_bias - bn_running_mean * scale              # Shape: (C_in,)

        # Reshape conv_weight_orig from (C_out, C_in, 1, 1) to (C_out, C_in)
        conv_weight_orig_reshaped = conv_weight_orig.squeeze(2).squeeze(2) # Shape: (C_out, C_in)

        # Calculate new convolution weights
        # W'_new[c_out, c_in] = W_orig[c_out, c_in] * S_c_in
        # This is element-wise multiplication after broadcasting scale (1, C_in) across C_out
        folded_conv_weight = conv_weight_orig_reshaped * scale.unsqueeze(0)

        # Calculate new convolution biases
        # B'_new[c_out] = sum_{c_in} (B_c_in * W_orig[c_out, c_in])
        # This is a matrix-vector multiplication: (C_out, C_in) @ (C_in, 1) -> (C_out, 1)
        # Then squeeze to (C_out,)
        folded_conv_bias = torch.matmul(conv_weight_orig_reshaped, shift.unsqueeze(1)).squeeze(1)

        # Register folded parameters as buffers. Buffers are part of the state_dict
        # but are not considered model parameters (i.e., not updated by optimizer).
        self.register_buffer('fused_conv_weight', folded_conv_weight)
        self.register_buffer('fused_conv_bias', folded_conv_bias)

        # Store the compiled fused CUDA operator
        self.fused_ops = fused_ops

    def forward(self, x):
        # Ensure input tensor is on CUDA
        x = x.cuda()
        return self.fused_ops.fused_bn_relu_conv1x1_avgpool_cuda(
            x, self.fused_conv_weight, self.fused_conv_bias
        )

