# Define the custom CUDA kernels for fused BatchNorm + ReLU/ReLU6
fused_bn_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, fmaxf, fminf

// Fused BatchNorm + ReLU kernel
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* bn_weight, // gamma
    const float* bn_bias,   // beta
    const float* bn_running_mean,
    const float* bn_running_var,
    float* output,
    int N, int C, int H, int W, float bn_eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H * W) {
        // Calculate channel index for BatchNorm parameters
        int c_idx = (idx / (W * H)) % C; 

        float val = input[idx];

        // BatchNorm operation (inference mode, using running_mean and running_var)
        float bn_val = (val - bn_running_mean[c_idx]) /
                       sqrtf(bn_running_var[c_idx] + bn_eps) *
                       bn_weight[c_idx] + bn_bias[c_idx];

        // ReLU activation
        output[idx] = fmaxf(0.0f, bn_val);
    }
}

// Fused BatchNorm + ReLU6 kernel
__global__ void fused_bn_relu6_kernel(
    const float* input,
    const float* bn_weight, // gamma
    const float* bn_bias,   // beta
    const float* bn_running_mean,
    const float* bn_running_var,
    float* output,
    int N, int C, int H, int W, float bn_eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H * W) {
        // Calculate channel index for BatchNorm parameters
        int c_idx = (idx / (W * H)) % C; 

        float val = input[idx];

        // BatchNorm operation (inference mode, using running_mean and running_var)
        float bn_val = (val - bn_running_mean[c_idx]) /
                       sqrtf(bn_running_var[c_idx] + bn_eps) *
                       bn_weight[c_idx] + bn_bias[c_idx];

        // ReLU6 activation
        output[idx] = fminf(fmaxf(0.0f, bn_val), 6.0f);
    }
}

// C++ wrapper for fused_bn_relu_kernel
torch::Tensor fused_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor bn_running_mean,
    torch::Tensor bn_running_var,
    float bn_eps) {

