    TORCH_CHECK(input.is_contiguous(), "Input must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kFloat, "Input must be float32.");

    // BatchNorm parameter tensor checks
    TORCH_CHECK(bn_weight.is_cuda() && bn_weight.is_contiguous() && bn_weight.dtype() == torch::kFloat, "BN weight must be a contiguous float32 CUDA tensor.");
    TORCH_CHECK(bn_bias.is_cuda() && bn_bias.is_contiguous() && bn_bias.dtype() == torch::kFloat, "BN bias must be a contiguous float32 CUDA tensor.");
    TORCH_CHECK(bn_running_mean.is_cuda() && bn_running_mean.is_contiguous() && bn_running_mean.dtype() == torch::kFloat, "BN running_mean must be a contiguous float32 CUDA tensor.");
    TORCH_CHECK(bn_running_var.is_cuda() && bn_running_var.is_contiguous() && bn_running_var.dtype() == torch::kFloat, "BN running_var must be a contiguous float32 CUDA tensor.");

    auto output = torch::empty_like(input);

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
