# Custom PyTorch modules to wrap the fused CUDA kernels
class FusedBnRelu(nn.Module):
    """
    A custom module that fuses BatchNorm2d and ReLU activation using a CUDA kernel.
    This module expects to wrap an existing nn.BatchNorm2d instance to access its parameters.
    """
    def __init__(self, bn_module: nn.BatchNorm2d):
        super().__init__()
        # Store the original BatchNorm module to access its parameters
        self.bn = bn_module
        self.fused_op = fused_ops.fused_bn_relu_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Pass input and all BatchNorm parameters to the custom CUDA kernel
        return self.fused_op(
            x,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.eps,
        )

class FusedBnRelu6(nn.Module):
    """
    A custom module that fuses BatchNorm2d and ReLU6 activation using a CUDA kernel.
    This module expects to wrap an existing nn.BatchNorm2d instance to access its parameters.
    """
    def __init__(self, bn_module: nn.BatchNorm2d):
        super().__init__()
        # Store the original BatchNorm module to access its parameters
        self.bn = bn_module
        self.fused_op = fused_ops.fused_bn_relu6_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Pass input and all BatchNorm parameters to the custom CUDA kernel
        return self.fused_op(
            x,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.eps,
        )


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        EfficientNetB1 architecture implementation with fused BatchNorm+ReLU/ReLU6 kernels.

        :param num_classes: The number of output classes (default is 1000 for ImageNet).
        """
        super(ModelNew, self).__init__()

        # Initial convolutional layer
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)
        self.fused_bn_relu1 = FusedBnRelu(self.bn1) # Fuse BN1 with ReLU

        # MBConv blocks
        self.mbconv1 = self._make_mbconv_block(32, 16, 1, 1)
        self.mbconv2 = self._make_mbconv_block(16, 24, 2, 6)
        self.mbconv3 = self._make_mbconv_block(24, 40, 2, 6)
        self.mbconv4 = self._make_mbconv_block(40, 80, 2, 6)
        self.mbconv5 = self._make_mbconv_block(80, 112, 1, 6)
        self.mbconv6 = self._make_mbconv_block(112, 192, 2, 6)
        self.mbconv7 = self._make_mbconv_block(192, 320, 1, 6)

        # Final convolutional layer
        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)
        self.fused_bn_relu2 = FusedBnRelu(self.bn2) # Fuse BN2 with ReLU

        # Fully connected layer
        self.fc = nn.Linear(1280, num_classes)

    def _make_mbconv_block(self, in_channels, out_channels, stride, expand_ratio):
        """
        Creates a MBConv block with fused BatchNorm and ReLU6 operations.

        :param in_channels: Number of input channels.
        :param out_channels: Number of output channels.
        :param stride: Stride of the depthwise convolution.
        :param expand_ratio: Expansion ratio for the hidden layer.
        :return: A sequential MBConv block with fused operations.
        """
        hidden_dim = round(in_channels * expand_ratio)

        layers = []

        # Expansion phase: 1x1 Conv -> FusedBnRelu6
        layers.append(nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False))
        layers.append(FusedBnRelu6(nn.BatchNorm2d(hidden_dim))) # Fused BN + ReLU6

        # Depthwise convolution phase: 3x3 Depthwise Conv -> FusedBnRelu6
        layers.append(nn.Conv2d(hidden_dim, hidden_dim, kernel_size=3, stride=stride, padding=1, groups=hidden_dim, bias=False))
        layers.append(FusedBnRelu6(nn.BatchNorm2d(hidden_dim))) # Fused BN + ReLU6

        # Projection phase: 1x1 Conv -> BatchNorm (no ReLU6 here)
        layers.append(nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False))
        layers.append(nn.BatchNorm2d(out_channels)) # Standard BatchNorm, no ReLU

        return nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass of the EfficientNetB1 model with custom CUDA kernels.

        :param x: Input tensor, shape (batch_size, 3, 240, 240)
        :return: Output tensor, shape (batch_size, num_classes)
        """
        # Initial block: Conv1 -> FusedBnRelu1
        x = self.conv1(x)
        x = self.fused_bn_relu1(x)

        # MBConv blocks
        x = self.mbconv1(x)
        x = self.mbconv2(x)
        x = self.mbconv3(x)
        x = self.mbconv4(x)
        x = self.mbconv5(x)
        x = self.mbconv6(x)
        x = self.mbconv7(x)

        # Final block: Conv2 -> FusedBnRelu2
        x = self.conv2(x)
        x = self.fused_bn_relu2(x)

        # Head
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = torch.flatten(x, 1)
        x = self.fc(x)

        return x

