import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GRU cell element-wise operations and activations
gru_cell_fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanh, sigmoid

// Helper functions for activations
__device__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ float tanh_custom(float x) {
    return tanhf(x); // Use built-in tanhf
}

// Fused GRU Cell Element-wise Operations and Activations Kernel
// This kernel takes the results of the matrix multiplications and performs the rest of the GRU cell logic.
// It computes r_t, z_t, n_t, and finally h_t for a single GRU cell.
__global__ void gru_cell_fused_elemwise_kernel(
    const float* input_gates_pre_bias, // (batch_size, 3*hidden_size) - result of x_t @ W_ih.T
    const float* hidden_gates_pre_bias, // (batch_size, 3*hidden_size) - result of h_prev @ W_hh.T
    const float* b_ih,                  // (3*hidden_size)
    const float* b_hh,                  // (3*hidden_size)
    const float* h_prev,                // (batch_size, hidden_size)
    float* h_t_out,                     // (batch_size, hidden_size) - output hidden state
    int hidden_size, int batch_size) {

    // Each thread computes one element of the output h_t
    int idx = blockIdx.x * blockDim.x + threadIdx.x; 
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int b = idx / hidden_size; // Batch index
        int h = idx % hidden_size; // Hidden dimension index (0 to hidden_size-1)

        // Calculate r_t (reset gate)
        // r_t = sigmoid( (x_t @ W_ir.T + b_ir) + (h_prev @ W_hr.T + b_hr) )
        // The terms (x_t @ W_ir.T) and (h_prev @ W_hr.T) are the first 'hidden_size' elements
        // of input_gates_pre_bias and hidden_gates_pre_bias respectively.
        float i_r_val = input_gates_pre_bias[b * (3 * hidden_size) + h];
        float h_r_val = hidden_gates_pre_bias[b * (3 * hidden_size) + h];
        float r_t = sigmoid(i_r_val + b_ih[h] + h_r_val + b_hh[h]);

        // Calculate z_t (update gate)
        // z_t = sigmoid( (x_t @ W_iz.T + b_iz) + (h_prev @ W_hz.T + b_hz) )
        // The terms (x_t @ W_iz.T) and (h_prev @ W_hz.T) are the middle 'hidden_size' elements
        // of input_gates_pre_bias and hidden_gates_pre_bias respectively.
        float i_z_val = input_gates_pre_bias[b * (3 * hidden_size) + hidden_size + h];
        float h_z_val = hidden_gates_pre_bias[b * (3 * hidden_size) + hidden_size + h];
        float z_t = sigmoid(i_z_val + b_ih[hidden_size + h] + h_z_val + b_hh[hidden_size + h]);

        // Calculate n_t (new gate / candidate hidden state)
        // n_t = tanh( (x_t @ W_in.T + b_in) + r_t * (h_prev @ W_hn.T + b_hn) )
        // The terms (x_t @ W_in.T) and (h_prev @ W_hn.T) are the last 'hidden_size' elements
        // of input_gates_pre_bias and hidden_gates_pre_bias respectively.
        float i_n_val = input_gates_pre_bias[b * (3 * hidden_size) + 2 * hidden_size + h];
        float h_n_val = hidden_gates_pre_bias[b * (3 * hidden_size) + 2 * hidden_size + h];
        float n_t = tanh_custom(i_n_val + b_ih[2 * hidden_size + h] + r_t * (h_n_val + b_hh[2 * hidden_size + h]));

        // Calculate h_t (current hidden state)
        // h_t = (1 - z_t) * n_t + z_t * h_(t-1)
        float h_prev_val = h_prev[b * hidden_size + h];
        h_t_out[b * hidden_size + h] = (1.0f - z_t) * n_t + z_t * h_prev_val;
    }
}

// C++ wrapper for the CUDA kernel
torch::Tensor gru_cell_fused_elemwise_cuda(
    torch::Tensor input_gates_pre_bias,
    torch::Tensor hidden_gates_pre_bias,
    torch::Tensor b_ih,
    torch::Tensor b_hh,
    torch::Tensor h_prev) {

    // Ensure inputs are contiguous and on CUDA
    // This is important for correct pointer arithmetic in the kernel
    input_gates_pre_bias = input_gates_pre_bias.contiguous();
    hidden_gates_pre_bias = hidden_gates_pre_bias.contiguous();
    b_ih = b_ih.contiguous();
    b_hh = b_hh.contiguous();
    h_prev = h_prev.contiguous();

    int batch_size = input_gates_pre_bias.size(0);
    int hidden_size = h_prev.size(1);

    // Allocate output tensor
    auto h_t_out = torch::zeros({batch_size, hidden_size}, input_gates_pre_bias.options());

    // Configure kernel launch parameters
    const int block_size = 256;
    const int num_blocks = (batch_size * hidden_size + block_size - 1) / block_size;

    // Launch the CUDA kernel
    gru_cell_fused_elemwise_kernel<<<num_blocks, block_size>>>(
        input_gates_pre_bias.data_ptr<float>(),
        hidden_gates_pre_bias.data_ptr<float>(),
        b_ih.data_ptr<float>(),
        b_hh.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        h_t_out.data_ptr<float>(),
        hidden_size, batch_size);

    return h_t_out;
}
"""

# C++ header for the inline compilation
gru_cell_fused_cpp_source = (
    "torch::Tensor gru_cell_fused_elemwise_cuda("
    "torch::Tensor input_gates_pre_bias, "
    "torch::Tensor hidden_gates_pre_bias, "
    "torch::Tensor b_ih, "
    "torch::Tensor b_hh, "
    "torch::Tensor h_prev);"
)

# Compile the inline CUDA code
gru_cell_fused = load_inline(
    name="gru_cell_fused",
    cpp_sources=gru_cell_fused_cpp_source,
    cuda_sources=gru_cell_fused_source,
    functions=["gru_cell_fused_elemwise_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Add optimization flags
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        """
        :param input_size: The number of expected features in the input x
        :param hidden_size: The number of features in the hidden state h
        :param num_layers: Number of recurrent layers (default: 1)
        :param bias: If False, then the layer does not use bias weights b_ih and b_hh (default: True)
        :param batch_first: If True, then the input and output tensors are provided as (batch, seq, feature) (default: False)
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.bias = bias
        self.batch_first = batch_first 

        if self.batch_first:
            raise NotImplementedError("ModelNew with custom GRU cell currently only supports batch_first=False.")

        # To ensure compatibility and use the same parameter initialization as nn.GRU,
        # we create a dummy nn.GRU instance and then extract its parameters.
        dummy_gru = nn.GRU(input_size, hidden_size, num_layers, bias, batch_first=False, dropout=0, bidirectional=False)

        # Store weights and biases for each layer as nn.ParameterList
        self.all_weights_ih = nn.ParameterList()
        self.all_weights_hh = nn.ParameterList()
        self.all_biases_ih = nn.ParameterList()
        self.all_biases_hh = nn.ParameterList()

        for i in range(num_layers):
            # nn.GRU stores weights in all_weights:
            # [0]: weight_ih_l0, weight_ih_l1, ...
            # [1]: weight_hh_l0, weight_hh_l1, ...
            # [2]: bias_ih_l0, bias_ih_l1, ...
            # [3]: bias_hh_l0, bias_hh_l1, ...
            self.all_weights_ih.append(nn.Parameter(dummy_gru.all_weights[0][i].clone()))
            self.all_weights_hh.append(nn.Parameter(dummy_gru.all_weights[1][i].clone()))
            if bias:
                self.all_biases_ih.append(nn.Parameter(dummy_gru.all_weights[2][i].clone()))
                self.all_biases_hh.append(nn.Parameter(dummy_gru.all_weights[3][i].clone()))
            else:
                # If bias is False, create zero tensors for biases to simplify kernel logic
                self.all_biases_ih.append(nn.Parameter(torch.zeros(3 * hidden_size)))
                self.all_biases_hh.append(nn.Parameter(torch.zeros(3 * hidden_size)))

        # Register the compiled custom CUDA kernel
        self.gru_cell_fused_elemwise_cuda = gru_cell_fused.gru_cell_fused_elemwise_cuda

    def forward(self, x, h0):
        """
        :param x: The input tensor, shape (seq_len, batch_size, input_size)
        :param h_0: The initial hidden state for the input sequence, shape (num_layers, batch_size, hidden_size)
        :return: h_n
            - h_n: The hidden state for t = seq_len, shape (num_layers, batch_size, hidden_size)
        """
        # x: (seq_len, batch_size, input_size)
        # h0: (num_layers, batch_size, hidden_size)

        seq_len, batch_size, _ = x.shape

        # h_n will store the final hidden states for all layers
        # We clone h0 to avoid modifying the input tensor directly
        h_n = h0.clone() # (num_layers, batch_size, hidden_size)

        # current_input will be the input to the current layer.
        # For the first layer, it's the original input `x`.
        # For subsequent layers, it's the sequence of hidden states from the previous layer.
        current_input_sequence = x 

        for layer in range(self.num_layers):
            # Get weights and biases for the current layer
            W_ih = self.all_weights_ih[layer] # (3*H, I) or (3*H, H)
            W_hh = self.all_weights_hh[layer] # (3*H, H)
            b_ih = self.all_biases_ih[layer]  # (3*H)
            b_hh = self.all_biases_hh[layer]  # (3*H)

            # h_prev for this layer, from the initial h0 or previous layer's output
            h_prev_layer = h_n[layer] # (batch_size, hidden_size)

            # List to store the hidden states for each time step of the current layer
            layer_output_sequence = []

            for t in range(seq_len):
                x_t = current_input_sequence[t] # (batch_size, current_input_size)

                # Perform matrix multiplications using PyTorch's optimized ops (e.g., cuBLAS)
                # These results are then passed to the custom fused kernel.

                # input_gates_pre_bias = x_t @ W_ih.T
                # W_ih.T will have shape (input_size, 3*hidden_size) or (hidden_size, 3*hidden_size)
                input_gates_pre_bias = torch.matmul(x_t, W_ih.transpose(0, 1)) # (batch_size, 3*hidden_size)

                # hidden_gates_pre_bias = h_prev_layer @ W_hh.T
                # W_hh.T will have shape (hidden_size, 3*hidden_size)
                hidden_gates_pre_bias = torch.matmul(h_prev_layer, W_hh.transpose(0, 1)) # (batch_size, 3*hidden_size)

                # Call the custom fused CUDA kernel for element-wise operations and activations
                # This kernel computes r_t, z_t, n_t, and h_t in a single launch.
                h_t = self.gru_cell_fused_elemwise_cuda(
                    input_gates_pre_bias,
                    hidden_gates_pre_bias,
                    b_ih,
                    b_hh,
                    h_prev_layer
                )

                h_prev_layer = h_t # Update h_prev for the next time step in this layer
                layer_output_sequence.append(h_t)

            # After processing all time steps for the current layer:
            # 1. Update the final hidden state for this layer in h_n
            h_n[layer] = h_prev_layer # The last h_t of the sequence for this layer

            # 2. The sequence of hidden states from the current layer becomes the input
            #    for the next layer (if any).
            current_input_sequence = torch.stack(layer_output_sequence, dim=0) # (seq_len, batch_size, hidden_size)

        # The problem asks for h_n, which contains the final hidden state for t=seq_len for each layer.
        return h_n

