# Define the custom CUDA kernel for cat + linear + tanh fusion
cat_linear_tanh_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For tanhf

// Custom kernel to fuse concatenation, matrix multiplication (from nn.Linear), and Tanh activation.
// This kernel avoids materializing the intermediate 'combined' tensor in global memory,
// reducing memory bandwidth usage.
//
// For large matrices, a highly optimized tiled GEMM kernel using shared memory
// or leveraging libraries like cuBLAS/CUTLASS would be significantly faster
// than this naive per-element dot product implementation.
// This implementation serves to demonstrate the fusion concept and custom kernel integration.
__global__ void cat_linear_tanh_kernel(
    const float* x,             // Input tensor (batch_size, input_size)
    const float* h_prev,        // Previous hidden state (batch_size, hidden_size)
    const float* W_i2h,         // Weight matrix for i2h (hidden_size, input_size + hidden_size)
    const float* b_i2h,         // Bias vector for i2h (hidden_size)
    float* h_new,               // Output hidden state (batch_size, hidden_size)
    int batch_size,
    int input_size,
    int hidden_size,
    int combined_size           // input_size + hidden_size
) {
    // Each thread computes one element of the output h_new.
    // The grid is configured such that:
    // blockIdx.y corresponds to the batch index (row in h_new).
    // blockIdx.x * blockDim.x + threadIdx.x corresponds to the hidden state index (column in h_new).
    int b = blockIdx.y; // Current batch row index
    int h_idx = blockIdx.x * blockDim.x + threadIdx.x; // Current hidden state column index

    if (b < batch_size && h_idx < hidden_size) {
        float sum = 0.0f;

        // Perform dot product for the 'x' part of the combined input.
        // The 'x' part of the conceptual combined vector is x[b, k].
        // The corresponding part of the weight matrix W_i2h is W_i2h[h_idx, k].
        for (int k = 0; k < input_size; ++k) {
            sum += x[b * input_size + k] * W_i2h[h_idx * combined_size + k];
        }

        // Perform dot product for the 'h_prev' part of the combined input.
        // The 'h_prev' part of the conceptual combined vector is h_prev[b, k].
        // The corresponding part of the weight matrix W_i2h is W_i2h[h_idx, input_size + k].
        for (int k = 0; k < hidden_size; ++k) {
            sum += h_prev[b * hidden_size + k] * W_i2h[h_idx * combined_size + (input_size + k)];
        }

        // Add bias and apply the Tanh activation function.
        sum += b_i2h[h_idx];
        h_new[b * hidden_size + h_idx] = tanhf(sum);
    }
}

// C++ wrapper function to launch the CUDA kernel.
torch::Tensor cat_linear_tanh_cuda(
    torch::Tensor x,
    torch::Tensor h_prev,
    torch::Tensor W_i2h,
    torch::Tensor b_i2h
) {
