    TORCH_CHECK(h_prev.is_cuda() && h_prev.is_floating_point(), "h_prev must be a CUDA float tensor");
    TORCH_CHECK(W_i2h.is_cuda() && W_i2h.is_floating_point(), "W_i2h must be a CUDA float tensor");
    TORCH_CHECK(b_i2h.is_cuda() && b_i2h.is_floating_point(), "b_i2h must be a CUDA float tensor");

    // Extract dimensions.
    int batch_size = x.size(0);
    int input_size = x.size(1);
    int hidden_size = h_prev.size(1);
    int combined_size = input_size + hidden_size;

    // Dimension checks for consistency.
    TORCH_CHECK(h_prev.size(0) == batch_size, "h_prev batch size mismatch");
    TORCH_CHECK(W_i2h.size(0) == hidden_size, "W_i2h output dim mismatch");
    TORCH_CHECK(W_i2h.size(1) == combined_size, "W_i2h input dim mismatch");
    TORCH_CHECK(b_i2h.size(0) == hidden_size, "b_i2h dim mismatch");

    // Allocate the output tensor for the new hidden state.
    auto h_new = torch::empty({batch_size, hidden_size}, x.options());

    // Configure kernel launch parameters.
    // We'll use a 1D block for the hidden_size dimension and a 1D grid for batch_size.
    // Each block will process a segment of the hidden state for a given batch item.
    // The grid will have 'batch_size' rows, and each row will launch enough blocks
    // to cover the 'hidden_size' dimension.
    const int block_size_x = 256; // Number of threads per block along the x-axis.
    dim3 block_dim(block_size_x);
    dim3 grid_dim( (hidden_size + block_dim.x - 1) / block_dim.x, batch_size);

    // Launch the CUDA kernel.
    cat_linear_tanh_kernel<<<grid_dim, block_dim>>>(
        x.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        W_i2h.data_ptr<float>(),
        b_i2h.data_ptr<float>(),
        h_new.data_ptr<float>(),
        batch_size,
        input_size,
        hidden_size,
        combined_size
    );

    return h_new;
}
"""

# C++ header for the inline compilation.
cat_linear_tanh_cpp_source = (
