        Initialize the Vanilla RNN model with custom CUDA kernels.

        :param input_size: The number of input features (int).
        :param hidden_size: The size of the hidden state (int).
        :param output_size: The number of output features (int).
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size

        # Initialize the hidden state as a buffer.
        # It will be moved to the correct device when model.to(device) is called.
        # Using the global batch_size for initial shape, consistent with the original model.
        self.register_buffer('hidden', torch.randn((batch_size, hidden_size)))

        # Define the RNN cell components.
        # i2h linear layer: input_size + hidden_size -> hidden_size
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        # h2o linear layer: hidden_size -> output_size
        self.h2o = nn.Linear(hidden_size, output_size)

        # Store the custom fused kernel function.
        self.cat_linear_tanh_op = cat_linear_tanh_module.cat_linear_tanh_cuda

    def forward(self, x: torch.Tensor, initial_hidden=None) -> torch.Tensor:
        """
        Forward pass of the Vanilla RNN with custom CUDA kernels.

        :param x: Input tensor of shape (batch_size, input_size).
        :param initial_hidden: Optional initial hidden state tensor of shape (batch_size, hidden_size).
                                If provided, it overrides the internal hidden state.
        :return: Output tensor of shape (batch_size, output_size).
        """
        # Ensure input 'x' is on the CUDA device.
        x = x.cuda()

        # Handle initial hidden state.
        if initial_hidden is not None:
            # Ensure initial_hidden is on CUDA before copying.
            self.hidden.copy_(initial_hidden.cuda())
        else:
            # If no initial_hidden is provided, ensure the internal hidden state
            # is on the same device as 'x'. This is important if 'x' changes device
            # or if the model was not explicitly moved to CUDA.
            self.hidden = self.hidden.to(x.device)

        # Use the custom fused kernel for:
        # 1. Concatenation of x and self.hidden (conceptually)
        # 2. Linear transformation (self.i2h.weight, self.i2h.bias)
        # 3. Tanh activation
        # The weights and biases of nn.Linear are nn.Parameter objects,
        # which are automatically moved to the correct device when model.to(device) is called.
        new_hidden = self.cat_linear_tanh_op(
            x,
            self.hidden,
            self.i2h.weight,
            self.i2h.bias
        )

        # Update the internal hidden state for the next forward pass.
        self.hidden = new_hidden

        # The h2o linear layer remains a standard PyTorch operation.
        output = self.h2o(self.hidden)

        return output

