import torch
import torch.nn as nn
import torch.nn.functional as F
import torch as th
from torch.utils.cpp_extension import load_inline
import math

# --- Custom CUDA Kernel 1: Fuses BatchNorm, Softmax, and Slicing ---
# This kernel takes the raw output of the initial matrix multiplication,
# applies batch normalization, performs a numerically stable softmax row-wise,
# and then slices the result to remove ghost clusters.
batch_norm_softmax_slice_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf, sqrtf
#include <float.h> // For FLT_MAX

__global__ void batch_norm_softmax_slice_kernel(
    const float* assignment_raw,
    const float* bn_weight,
    const float* bn_bias,
    const float* bn_mean,
    const float* bn_var,
    float bn_eps,
    int BN, // total_samples (batch_size * num_features)
    int K_plus_G, // total_clusters (cluster_size + ghost_clusters)
    int K, // cluster_size
    float* output) {

    // Each block processes one row (one sample from BN)
    int row_idx = blockIdx.x;

    if (row_idx >= BN) return;

    // Shared memory for one row's values after BN, and for softmax calculation.
    // s_vals[0...K_plus_G-1] for bn_vals/exp_vals
    // s_vals[K_plus_G] for max_val (computed by thread 0)
    // s_vals[K_plus_G+1] for sum_exp (computed by thread 0)
    extern __shared__ float s_vals[];

    // 1. Apply Batch Norm and store in shared memory
    for (int col_idx = threadIdx.x; col_idx < K_plus_G; col_idx += blockDim.x) {
        float val = assignment_raw[row_idx * K_plus_G + col_idx];
        s_vals[col_idx] = (val - bn_mean[col_idx]) / sqrtf(bn_var[col_idx] + bn_eps) * bn_weight[col_idx] + bn_bias[col_idx];
    }
    __syncthreads();

    // 2. Find max_val for numerically stable softmax.
    // For small K_plus_G (e.g., 48), a single thread (threadIdx.x == 0) can efficiently
    // compute the max over all elements in shared memory.
    if (threadIdx.x == 0) {
        float max_val = s_vals[0];
        for (int col_idx = 1; col_idx < K_plus_G; ++col_idx) {
            if (s_vals[col_idx] > max_val) {
                max_val = s_vals[col_idx];
            }
        }
        s_vals[K_plus_G] = max_val; // Store max_val in shared memory for all threads to read
    }
    __syncthreads();
    float max_val = s_vals[K_plus_G]; // All threads read the computed max_val

    // 3. Compute exp(val - max_val) and sum_exp
    for (int col_idx = threadIdx.x; col_idx < K_plus_G; col_idx += blockDim.x) {
        s_vals[col_idx] = expf(s_vals[col_idx] - max_val); // s_vals now holds exp(bn_val - max_val)
    }
    __syncthreads();

    // Reduce sum_exp across the block.
    // Similar to max_val, thread 0 sums up all exp values from shared memory.
    if (threadIdx.x == 0) {
        float total_sum_exp = 0.0f;
        for (int col_idx = 0; col_idx < K_plus_G; ++col_idx) {
            total_sum_exp += s_vals[col_idx];
        }
        s_vals[K_plus_G + 1] = total_sum_exp; // Store total_sum_exp in shared memory
    }
    __syncthreads();
    float sum_exp = s_vals[K_plus_G + 1]; // All threads read the computed sum_exp

    // 4. Divide by sum_exp and store the first K elements (slicing)
    for (int col_idx = threadIdx.x; col_idx < K; col_idx += blockDim.x) { // Only iterate up to K
        output[row_idx * K + col_idx] = s_vals[col_idx] / sum_exp;
    }
}
"""

batch_norm_softmax_slice_cpp_source = (
    "torch::Tensor batch_norm_softmax_slice_cuda("
    "torch::Tensor assignment_raw, "
    "torch::Tensor bn_weight, "
    "torch::Tensor bn_bias, "
    "torch::Tensor bn_mean, "
    "torch::Tensor bn_var, "
    "float bn_eps, "
    "int cluster_size, "
    "int total_clusters);"
)

batch_norm_softmax_slice = load_inline(
    name="batch_norm_softmax_slice",
    cpp_sources=batch_norm_softmax_slice_cpp_source,
    cuda_sources=batch_norm_softmax_slice_source,
    functions=["batch_norm_softmax_slice_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)

# --- Custom CUDA Kernel 2: Fuses Subtraction and L2 Normalization ---
# This kernel performs element-wise subtraction of 'a' from 'vlad_raw' and
# then applies L2 normalization along the last dimension (K) for each (B, D) slice.
vlad_subtract_normalize_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, rsqrtf

__global__ void vlad_subtract_normalize_kernel(
    const float* vlad_raw,
    const float* a,
    float eps,
    int B, // batch_size
    int D, // feature_size
    int K, // cluster_size
    float* output) {

    // Each block processes one (B, D) row (i.e., K elements) for normalization over K.
    int bd_idx = blockIdx.x; // Corresponds to (b * D + d)

    if (bd_idx >= B * D) return;

    int b = bd_idx / D;
    int d = bd_idx % D;

    // Shared memory for K elements after subtraction + 1 for sum_sq.
    // s_vals[0...K-1] for subtracted values
    // s_vals[K] for sum_sq (computed by thread 0)
    extern __shared__ float s_vals[];

    // 1. Subtract elements and store in shared memory
    for (int k_idx = threadIdx.x; k_idx < K; k_idx += blockDim.x) {
        float val_raw = vlad_raw[b * D * K + d * K + k_idx];
        float val_a = a[b * D * K + d * K + k_idx];
        s_vals[k_idx] = val_raw - val_a;
    }
    __syncthreads();

    // 2. Compute sum of squares for L2 norm.
    // For small K (e.g., 32), thread 0 sums up squares from shared memory.
    if (threadIdx.x == 0) {
        float total_sum_sq = 0.0f;
        for (int k_idx = 0; k_idx < K; ++k_idx) {
            total_sum_sq += s_vals[k_idx] * s_vals[k_idx];
        }
        s_vals[K] = total_sum_sq; // Store total_sum_sq in shared memory
    }
    __syncthreads();
    float sum_sq = s_vals[K]; // All threads read the computed sum_sq

    // 3. Compute norm_factor and store normalized values
    float norm_factor = rsqrtf(sum_sq + eps); // 1 / sqrt(x)
    for (int k_idx = threadIdx.x; k_idx < K; k_idx += blockDim.x) {
        output[b * D * K + d * K + k_idx] = s_vals[k_idx] * norm_factor;
    }
}
"""

vlad_subtract_normalize_cpp_source = (
    "torch::Tensor vlad_subtract_normalize_cuda("
    "torch::Tensor vlad_raw, "
    "torch::Tensor a, "
    "float eps, "
    "int B, int D, int K);"
)

vlad_subtract_normalize = load_inline(
    name="vlad_subtract_normalize",
    cpp_sources=vlad_subtract_normalize_cpp_source,
    cuda_sources=vlad_subtract_normalize_source,
    functions=["vlad_subtract_normalize_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    def __init__(self, cluster_size, feature_size, ghost_clusters):
        super(ModelNew, self).__init__()

        self.feature_size = feature_size
        self.cluster_size = cluster_size
        self.ghost_clusters = ghost_clusters

        init_sc = (1 / math.sqrt(feature_size))
        clusters = cluster_size + ghost_clusters

        # The `clusters` weights are the `(w,b)` in the paper
        self.clusters = nn.Parameter(init_sc * th.randn(feature_size, clusters))
        self.batch_norm = nn.BatchNorm1d(clusters)
        # The `clusters2` weights are the visual words `c_k` in the paper
        self.clusters2 = nn.Parameter(init_sc * th.randn(1, feature_size, cluster_size))
        self.out_dim = self.cluster_size * feature_size

        # Store references to the compiled kernels
        self.batch_norm_softmax_slice_cuda = batch_norm_softmax_slice.batch_norm_softmax_slice_cuda
        self.vlad_subtract_normalize_cuda = vlad_subtract_normalize.vlad_subtract_normalize_cuda

    def forward(self, x, mask=None):
        """Aggregates feature maps into a fixed size representation.  In the following
        notation, B = batch_size, N = num_features, K = num_clusters, D = feature_size.

        Args:
            x (th.Tensor): B x N x D

        Returns:
            (th.Tensor): B x DK
        """
        max_sample = x.size()[1]
        B = x.size(0)
        N = x.size(1)
        D = self.feature_size
        K = self.cluster_size
        G = self.ghost_clusters
        K_plus_G = K + G
        BN = B * N # Total number of samples for the first matmul

        x_flat = x.view(-1, D)  # B x N x D -> BN x D

        if x_flat.device != self.clusters.device:
            msg = f"x.device {x_flat.device} != cluster.device {self.clusters.device}"
            raise ValueError(msg)

        # Original:
        # assignment = th.matmul(x, self.clusters)
        # assignment = self.batch_norm(assignment)
        # assignment = F.softmax(assignment, dim=1)
        # assignment = assignment[:, :self.cluster_size]

        # Optimized: Perform matmul, then fuse BatchNorm, Softmax, and Slicing into a custom CUDA kernel.
        assignment_raw = th.matmul(x_flat, self.clusters)  # (BN x D) x (D x (K+G)) -> BN x (K+G)

        # Get batch norm parameters for inference (running_mean, running_var, weight, bias, eps)
        bn_weight = self.batch_norm.weight
        bn_bias = self.batch_norm.bias
        bn_mean = self.batch_norm.running_mean
        bn_var = self.batch_norm.running_var
        bn_eps = self.batch_norm.eps

        # Call the custom fused kernel
        assignment = self.batch_norm_softmax_slice_cuda(
            assignment_raw,
            bn_weight,
            bn_bias,
            bn_mean,
            bn_var,
            bn_eps,
            K,          # cluster_size
            K_plus_G    # total_clusters
        ) # -> BN x K

        assignment = assignment.view(B, max_sample, K)  # -> B x N x K
        a_sum = th.sum(assignment, dim=1, keepdim=True)  # B x N x K -> B x 1 x K
        a = a_sum * self.clusters2 # (B x 1 x K) * (1 x D x K) -> B x D x K (after broadcasting)

        assignment = assignment.transpose(1, 2)  # B x N x K -> B x K x N

        x_reshaped = x.view(B, max_sample, D)  # BN x D -> B x N x D
        vlad = th.matmul(assignment, x_reshaped)  # (B x K x N) x (B x N x D) -> B x K x D
        vlad = vlad.transpose(1, 2)  # -> B x D x K

        # Original:
        # vlad = vlad - a
        # vlad = F.normalize(vlad) # L2 intra norm

        # Optimized: Fuse subtraction and L2 normalization into a custom CUDA kernel.
        # F.normalize uses a default eps of 1e-12.
        vlad = self.vlad_subtract_normalize_cuda(
            vlad,
            a,
            1e-12, # Default epsilon for F.normalize
            B, D, K
        ) # -> B x D x K

        # flattening + L2 norm
        vlad = vlad.reshape(-1, K * D)  # -> B x DK
        vlad = F.normalize(vlad) # L2 norm over DK dimension (left as PyTorch for simplicity)
        return vlad  # B x DK

