# --- Custom CUDA Kernel for Channel Shuffle ---
# This kernel directly shuffles channels in-place (conceptually) by calculating
# the correct input index for each output element, avoiding intermediate
# view/transpose/contiguous operations which can involve memory copies.
channel_shuffle_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA error checking macro for robust kernel development
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error at %s:%d - %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(1); \\
        } \\
    } while (0)

__global__ void channel_shuffle_kernel(const float* in, float* out, int B, int C, int H, int W, int G) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = B * C * H * W;

    if (idx < total_elements) {
        // Deconstruct the linear output index 'idx' into its 4D components (b, c_new, h, w)
        int w = idx % W;
        int h = (idx / W) % H;
        int c_new = (idx / (W * H)) % C; // The new channel index after shuffling
        int b = idx / (W * H * C);

        // Reconstruct the original channel index 'c_orig' based on the shuffle logic:
        // Original: x.view(B, G, CPG, H, W).transpose(1, 2).contiguous().view(B, -1, H, W)
        // If output channel c_new corresponds to (cpg_idx, g_idx) in the transposed view,
        // then the original channel c_orig was (g_idx, cpg_idx) in the reshaped view.
        int channels_per_group = C / G;
        int g_idx = c_new % G;       // This is the original group index
        int cpg_idx = c_new / G;     // This is the original channel-per-group index within its group

        int c_orig = g_idx * channels_per_group + cpg_idx; // The original channel index

        // Calculate the linear input index from (b, c_orig, h, w)
        int in_idx = b * C * H * W + c_orig * H * W + h * W + w;

        // Copy the value from the input to the output
        out[idx] = in[in_idx];
    }
}

torch::Tensor channel_shuffle_cuda(torch::Tensor x, int groups) {
    // Input validation
    TORCH_CHECK(x.is_cuda(), "Input tensor 'x' must be a CUDA tensor.");
    TORCH_CHECK(x.is_contiguous(), "Input tensor 'x' must be contiguous.");
    TORCH_CHECK(x.dim() == 4, "Input tensor 'x' must be a 4D tensor (B, C, H, W).");

    int B = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int G = groups;

    TORCH_CHECK(C % G == 0, "Number of channels must be divisible by groups for channel shuffle.");

    // Allocate output tensor on the same device as input
    auto out = torch::empty_like(x);

    // Configure kernel launch parameters
    const int block_size = 256;
    const int num_elements = B * C * H * W;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    channel_shuffle_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), B, C, H, W, G
    );
    CUDA_CHECK(cudaGetLastError()); // Check for any errors during kernel execution

    return out;
}
"""

channel_shuffle_cpp_source = (
    "torch::Tensor channel_shuffle_cuda(torch::Tensor x, int groups);"
)

# Compile the inline CUDA code for channel shuffle
channel_shuffle_module = load_inline(
    name="channel_shuffle_module",
    cpp_sources=channel_shuffle_cpp_source,
    cuda_sources=channel_shuffle_source,
    functions=["channel_shuffle_cuda"],
    verbose=True,
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[],
)

# --- Custom CUDA Kernel for Element-wise Addition (from example, with minor improvements) ---
# This kernel performs element-wise addition, replacing the default PyTorch operator.
# It's a simple example of how to replace basic operations.
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Re-using the CUDA error checking macro
#define CUDA_CHECK(call) \\
    do { \\
        cudaError_t err = call; \\
        if (err != cudaSuccess) { \\
            fprintf(stderr, "CUDA error at %s:%d - %s\\n", __FILE__, __LINE__, cudaGetErrorString(err)); \\
            exit(1); \\
        } \\
    } while (0)

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    // Input validation
    TORCH_CHECK(a.is_cuda(), "Input tensor 'a' must be a CUDA tensor.");
    TORCH_CHECK(b.is_cuda(), "Input tensor 'b' must be a CUDA tensor.");
    TORCH_CHECK(a.sizes() == b.sizes(), "Input tensors must have the same size for element-wise addition.");
    TORCH_CHECK(a.is_contiguous(), "Input tensor 'a' must be contiguous.");
    TORCH_CHECK(b.is_contiguous(), "Input tensor 'b' must be contiguous.");

    auto size = a.numel();
    // Use empty_like as the kernel will write all elements, avoiding unnecessary initialization
    auto out = torch::empty_like(a); 

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);
    CUDA_CHECK(cudaGetLastError()); // Check for any errors during kernel execution

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

# Compile the inline CUDA code for element-wise addition
elementwise_add_module = load_inline(
    name="elementwise_add_module",
