input_channels = 240
out_channels = 480
groups = 3
height = 224
width = 224
num_classes = 1000

def get_inputs():
    # Ensure input tensors are on CUDA for custom kernels
    return [torch.rand(batch_size, input_channels, height, width).cuda()]

def get_init_inputs():
    return [input_channels, out_channels, groups]

