import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernels for operator fusion
fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <curand_kernel.h> // For dropout

// Helper for GELU (approximate)
// Using the standard approximation from PyTorch's F.gelu
__device__ float gelu_approx(float x) {
    return 0.5f * x * (1.0f + tanhf(sqrtf(2.0f / M_PI_F) * (x + 0.044715f * x * x * x)));
}

// Kernel for Fused Concatenation, Positional Embedding Addition, and Dropout
// Fuses: torch.cat((cls_tokens, x), dim=1) + x += self.pos_embedding + self.dropout(x)
__global__ void fused_cat_add_dropout_kernel(
    const float* cls_tokens_ptr,
    const float* patch_embeddings_ptr,
    const float* pos_embedding_ptr,
    float* output_ptr,
    int B, int P, int D, // batch_size, num_patches, dim
    float dropout_p,
    bool training,
    unsigned long long seed) {

    int total_elements = B * (P + 1) * D;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        int b = idx / ((P + 1) * D);
        int rem = idx % ((P + 1) * D);
        int p_idx = rem / D; // 0 for cls_token, 1 to P for patches
        int d = rem % D;

        float val;

        // 1. Concatenation logic: copy cls_token or patch embedding
        if (p_idx == 0) { // cls_token
            val = cls_tokens_ptr[b * D + d];
        } else { // patch embedding
            val = patch_embeddings_ptr[b * P * D + (p_idx - 1) * D + d];
        }

        // 2. Add positional embedding
        // pos_embedding is (1, P+1, D), so we access it with p_idx and d
        val += pos_embedding_ptr[p_idx * D + d];

        // 3. Dropout
        if (training && dropout_p > 0.0f) {
            curandState_t state;
            // Initialize curand state for each thread.
            // For better performance in production, consider pre-generating random numbers
            // or using a more sophisticated RNG setup (e.g., one state per warp/block).
            curand_init(seed, idx, 0, &state);
            float rand_val = curand_uniform(&state);
            if (rand_val < dropout_p) {
                val = 0.0f;
            } else {
                val /= (1.0f - dropout_p); // Scale up
            }
        }
        output_ptr[idx] = val;
    }
}

// Kernel for Fused Linear + GELU
// This implements a naive GEMM (General Matrix Multiplication) followed by GELU activation.
// For production, highly optimized GEMM libraries (like cuBLAS) are typically used,
// and fusion would involve integrating GELU into the cuBLAS output stage or a subsequent element-wise kernel.
// This custom kernel demonstrates the fusion concept directly.
// Inputs: input (N, K), weight (M, K), bias (M)
// Output: output (N, M)
__global__ void fused_linear_gelu_kernel(
    const float* input_ptr,
    const float* weight_ptr, // (M, K)
    const float* bias_ptr,   // (M)
    float* output_ptr,
    int N, int K, int M) {

    // Each thread computes one element of the output matrix (N, M)
    int n = blockIdx.y * blockDim.y + threadIdx.y; // Row index in output (batch_idx)
    int m = blockIdx.x * blockDim.x + threadIdx.x; // Col index in output (out_feature_idx)

    if (n < N && m < M) {
        float sum = (bias_ptr != nullptr) ? bias_ptr[m] : 0.0f;
        for (int k = 0; k < K; ++k) {
            // input_ptr[n * K + k] is input[n, k]
            // weight_ptr[m * K + k] is weight[m, k] (equivalent to weight.T[k, m])
            sum += input_ptr[n * K + k] * weight_ptr[m * K + k];
        }
        output_ptr[n * M + m] = gelu_approx(sum);
    }
}

// C++ wrapper for fused_cat_add_dropout_kernel
torch::Tensor fused_cat_add_dropout_cuda(
    torch::Tensor cls_tokens,
    torch::Tensor patch_embeddings,
    torch::Tensor pos_embedding,
    double dropout_p,
    bool training,
    unsigned long long seed) {

    TORCH_CHECK(cls_tokens.is_cuda(), "cls_tokens must be a CUDA tensor");
    TORCH_CHECK(patch_embeddings.is_cuda(), "patch_embeddings must be a CUDA tensor");
    TORCH_CHECK(pos_embedding.is_cuda(), "pos_embedding must be a CUDA tensor");
    TORCH_CHECK(cls_tokens.dim() == 3, "cls_tokens must be 3D (B, 1, D)");
    TORCH_CHECK(patch_embeddings.dim() == 3, "patch_embeddings must be 3D (B, P, D)");
    TORCH_CHECK(pos_embedding.dim() == 3, "pos_embedding must be 3D (1, P+1, D)");

    int B = cls_tokens.size(0);
    int D = cls_tokens.size(2);
    int P = patch_embeddings.size(1); // num_patches

    auto output = torch::empty({B, P + 1, D}, cls_tokens.options());

    const int block_size = 256;
    const int total_elements = B * (P + 1) * D;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_cat_add_dropout_kernel<<<num_blocks, block_size>>>(
        cls_tokens.data_ptr<float>(),
        patch_embeddings.data_ptr<float>(),
        pos_embedding.data_ptr<float>(),
        output.data_ptr<float>(),
        B, P, D,
        (float)dropout_p,
        training,
        seed
    );
    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in fused_cat_add_dropout_kernel: ", cudaGetErrorString(err));
    }
    return output;
}

// C++ wrapper for fused_linear_gelu_kernel
torch::Tensor fused_linear_gelu_cuda(
    torch::Tensor input,
    torch::Tensor weight, // (out_features, in_features)
    torch::Tensor bias) {

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    if (bias.defined()) {
        TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    }
    TORCH_CHECK(input.dim() == 2, "input must be 2D (N, K)");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D (M, K)");
    if (bias.defined()) {
        TORCH_CHECK(bias.dim() == 1, "bias must be 1D (M)");
    }

    int N = input.size(0); // batch_size
    int K = input.size(1); // in_features
    int M = weight.size(0); // out_features

    TORCH_CHECK(weight.size(1) == K, "weight.size(1) (K) must match input.size(1) (K)");
    if (bias.defined()) {
        TORCH_CHECK(bias.size(0) == M, "bias.size(0) (M) must match weight.size(0) (M)");
    }

    auto output = torch::empty({N, M}, input.options());

    // Grid and block dimensions for 2D output
    const int block_size_x = 32; // Threads per block in X (M dimension)
    const int block_size_y = 8;  // Threads per block in Y (N dimension)
    dim3 block_dim(block_size_x, block_size_y);

    dim3 grid_dim(
        (M + block_size_x - 1) / block_size_x,
        (N + block_size_y - 1) / block_size_y
    );

    fused_linear_gelu_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, K, M
    );
    // Check for CUDA errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in fused_linear_gelu_kernel: ", cudaGetErrorString(err));
    }
    return output;
}
"""

# C++ declarations for load_inline
fused_ops_cpp_source = """
torch::Tensor fused_cat_add_dropout_cuda(
    torch::Tensor cls_tokens,
    torch::Tensor patch_embeddings,
    torch::Tensor pos_embedding,
    double dropout_p,
    bool training,
    unsigned long long seed);

torch::Tensor fused_linear_gelu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias);
"""

# Compile the inline CUDA code
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_cuda_source,
    functions=["fused_cat_add_dropout_cuda", "fused_linear_gelu_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


# Custom module to wrap the fused Linear + GELU kernel
class FusedLinearGELU(nn.Module):
    def __init__(self, in_features, out_features, fused_ops_module):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.fused_ops = fused_ops_module

    def forward(self, x):
        # Call the custom CUDA kernel for Linear + GELU
        return self.fused_ops.fused_linear_gelu_cuda(x, self.linear.weight, self.linear.bias)


class ModelNew(nn.Module):
    def __init__(self, image_size, patch_size, num_classes, dim, depth, heads, mlp_dim, channels=3, dropout=0.1, emb_dropout=0.1):
        """
        Vision Transformer (ViT) model with custom CUDA kernels for speedups.

        Optimizations:
        1. Fused `torch.cat`, `torch.add` (for positional embedding), and `nn.Dropout`
           into a single CUDA kernel (`fused_cat_add_dropout_cuda`).
        2. Fused the first `nn.Linear` and `nn.GELU` in the `mlp_head`
           into a single CUDA kernel (`fused_linear_gelu_cuda`).

        :param image_size: The size of the input image (assumed to be square).
        :param patch_size: The size of each patch (assumed to be square).
        :param num_classes: The number of output classes.
        :param dim: The dimensionality of the embedding space.
        :param depth: The number of transformer layers.
        :param heads: The number of attention heads.
        :param mlp_dim: The dimensionality of the MLP (Multi-Layer Perceptron) in the transformer.
        :param channels: The number of channels in the input image (default is 3 for RGB).
        :param dropout: Dropout rate applied in the MLP.
        :param emb_dropout: Dropout rate applied to the embedded patches.
        """
        super(ModelNew, self).__init__()

        assert image_size % patch_size == 0, "Image dimensions must be divisible by the patch size."
        num_patches = (image_size // patch_size) ** 2
        patch_dim = channels * patch_size ** 2

        self.patch_size = patch_size
        self.pos_embedding = nn.Parameter(torch.randn(1, num_patches + 1, dim))
        self.patch_to_embedding = nn.Linear(patch_dim, dim)
        self.cls_token = nn.Parameter(torch.randn(1, 1, dim))

        # Use nn.Dropout for its state (training/eval mode) and probability
        self.dropout_layer = nn.Dropout(emb_dropout) 

        self.transformer = nn.TransformerEncoder(
            nn.TransformerEncoderLayer(d_model=dim, nhead=heads, dim_feedforward=mlp_dim, dropout=dropout),
            num_layers=depth
        )

        self.to_cls_token = nn.Identity()

        # Load the fused operations module
        self.fused_ops = fused_ops

        # Replace the first Linear + GELU with our fused custom module
        self.mlp_head = nn.Sequential(
            FusedLinearGELU(dim, mlp_dim, self.fused_ops), # Custom fused module
            nn.Dropout(dropout),
            nn.Linear(mlp_dim, num_classes)
        )

    def forward(self, img):
        """
        Forward pass of the Vision Transformer.

        :param img: The input image tensor, shape (batch_size, channels, image_size, image_size).
        :return: The output tensor, shape (batch_size, num_classes).
        """
        p = self.patch_size

        x = img.unfold(2, p, p).unfold(3, p, p).reshape(img.shape[0], -1, p*p*img.shape[1])
        x = self.patch_to_embedding(x)

        cls_tokens = self.cls_token.expand(img.shape[0], -1, -1)

        # Fused operation: Concatenation + Positional Embedding Addition + Dropout
        # Replaces:
        # x = torch.cat((cls_tokens, x), dim=1)
        # x += self.pos_embedding
        # x = self.dropout_layer(x)
        x = self.fused_ops.fused_cat_add_dropout_cuda(
            cls_tokens,
            x, # This is the patch_embeddings tensor
            self.pos_embedding,
            self.dropout_layer.p, # Get dropout probability from the layer
            self.training,        # Pass the model's training flag
            torch.cuda.initial_seed() # Use a consistent seed for reproducibility
        )

        x = self.transformer(x)

        x = self.to_cls_token(x[:, 0])
        return self.mlp_head(x)

