import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused slicing (last time step) and linear operation
fused_linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h> // For fprintf debugging if needed

// CUDA kernel for fused slicing (last time step) and linear transformation (MatMul + Bias)
// lstm_output: (B, S, H_in) - Batch, Sequence Length, Input Features
// weight: (H_out, H_in) - Output Features, Input Features (PyTorch's nn.Linear weight format)
// bias: (H_out) - Output Features
// fc_output: (B, H_out) - Batch, Output Features
__global__ void fused_linear_kernel(const float* lstm_output, const float* weight, const float* bias, float* fc_output,
                                    int B, int S, int H_in, int H_out) {
    // Each thread computes one element of the output matrix (B, H_out)
    // blockIdx.y maps to the batch index (b_idx)
    // blockIdx.x * blockDim.x + threadIdx.x maps to the output feature index (h_out_idx)

    int b_idx = blockIdx.y;
    int h_out_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (b_idx < B && h_out_idx < H_out) {
        float sum = 0.0f;

        // Get the input vector for the current batch (b_idx) from the last time step (S-1)
        // The input vector is lstm_output[b_idx][S-1][:]
        // Memory layout: [batch_0_seq_0_h_0, ..., batch_0_seq_0_h_Hin-1, ..., batch_0_seq_S-1_h_0, ...]
        // Offset for batch: b_idx * S * H_in
        // Offset for last sequence step: (S - 1) * H_in
        const float* input_vec_ptr = lstm_output + (static_cast<long long>(b_idx) * S + (S - 1)) * H_in;

        // Get the weight row for the current output feature (h_out_idx)
        // The weight row is weight[h_out_idx][:]
        // Memory layout: [h_out_0_h_in_0, ..., h_out_0_h_in_Hin-1, ..., h_out_Hout-1_h_in_0, ...]
        // Offset for output feature row: h_out_idx * H_in
        const float* weight_row_ptr = weight + static_cast<long long>(h_out_idx) * H_in;

        // Perform dot product (input_vec @ weight_row.T)
        for (int k = 0; k < H_in; ++k) {
            sum += input_vec_ptr[k] * weight_row_ptr[k];
        }

        // Add bias if it exists
        if (bias != nullptr) {
            sum += bias[h_out_idx];
        }

        // Store the result in the output tensor
        // Memory layout: [batch_0_h_out_0, ..., batch_0_h_out_Hout-1, ..., batch_B-1_h_out_0, ...]
        fc_output[static_cast<long long>(b_idx) * H_out + h_out_idx] = sum;
    }
}

torch::Tensor fused_linear_cuda(torch::Tensor lstm_output, torch::Tensor weight, torch::Tensor bias_opt) {
    // Ensure tensors are on CUDA and are float32
    TORCH_CHECK(lstm_output.is_cuda(), "lstm_output must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(lstm_output.is_contiguous(), "lstm_output must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    TORCH_CHECK(lstm_output.dtype() == torch::kFloat32, "lstm_output must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");

    // Get dimensions
    int B = lstm_output.size(0); // Batch size
    int S = lstm_output.size(1); // Sequence length
    int H_in = lstm_output.size(2); // Input features to FC layer (hidden_size * 2 for bidirectional LSTM)
    int H_out = weight.size(0); // Output features from FC layer

    TORCH_CHECK(weight.size(1) == H_in, "Weight input features must match LSTM output features");

    const float* bias_ptr = nullptr;
    if (bias_opt.defined()) {
        TORCH_CHECK(bias_opt.is_cuda(), "bias must be a CUDA tensor if defined");
        TORCH_CHECK(bias_opt.is_contiguous(), "bias must be contiguous if defined");
        TORCH_CHECK(bias_opt.dtype() == torch::kFloat32, "bias must be float32 if defined");
        TORCH_CHECK(bias_opt.numel() == H_out, "Bias size must match output features");
        bias_ptr = bias_opt.data_ptr<float>();
    }

    // Create output tensor with the same options (dtype, device) as lstm_output
    auto fc_output = torch::zeros({B, H_out}, lstm_output.options());

    // Define grid and block dimensions
    const int block_size_x = 32; // Threads per block in X dimension (for output features)
    const int block_size_y = 1;  // Threads per block in Y dimension (each block processes one batch row)

    dim3 block_dim(block_size_x, block_size_y);
    // Grid dimensions: (number of blocks for H_out, number of blocks for B)
    dim3 grid_dim((H_out + block_size_x - 1) / block_size_x, B);

    // Launch the kernel
    fused_linear_kernel<<<grid_dim, block_dim>>>(
        lstm_output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        fc_output.data_ptr<float>(),
        B, S, H_in, H_out
    );

    // Check for CUDA errors after kernel launch
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA error in fused_linear_kernel: %s\\n", cudaGetErrorString(err));
    }

    return fc_output;
}
"""

fused_linear_cpp_source = (
    "torch::Tensor fused_linear_cuda(torch::Tensor lstm_output, torch::Tensor weight, torch::Tensor bias_opt);"
)

