class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the LSTM model with a custom fused linear layer.

        :param input_size: The number of expected features in the input `x`
        :param hidden_size: The number of features in the hidden state `h`
        :param num_layers: Number of recurrent layers
        :param output_size: The number of output features
        :param dropout: If non-zero, introduces a Dropout layer on the outputs of each LSTM layer except the last layer, with dropout probability equal to `dropout`
        """
        super(ModelNew, self).__init__()
        # The LSTM layer remains unchanged, as it's typically highly optimized by cuDNN
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True, dropout=dropout, bidirectional=True)

        # Instead of nn.Linear, we will manage its weight and bias directly
        # Create a dummy nn.Linear to get the correct parameter shapes and default initialization
        dummy_fc = nn.Linear(hidden_size * 2, output_size)

        # Register weight and bias as parameters so they are part of the model's state_dict and are trainable
        self.fc_weight = nn.Parameter(dummy_fc.weight.data)
        if dummy_fc.bias is not None:
            self.fc_bias = nn.Parameter(dummy_fc.bias.data)
        else:
            # If the original nn.Linear had no bias, register None
            self.register_parameter('fc_bias', None)

        # Store the compiled custom CUDA function
        self.fused_linear_op = fused_linear_module.fused_linear_cuda

