        :param x: The input tensor, shape (batch_size, sequence_length, input_size)
        :param h0: Initial hidden state, shape (num_layers * num_directions, batch_size, hidden_size)
        :param c0: Initial cell state, shape (num_layers * num_directions, batch_size, hidden_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        # Forward propagate LSTM
        # out: tensor of shape (batch_size, seq_length, hidden_size * 2) for bidirectional
        out, hn = self.lstm(x, (h0, c0))  

        # Apply the custom fused linear operation
        # This replaces the PyTorch operations:
        #   1. Slicing: out[:, -1, :] (gets the last time step's output for all batches)
        #   2. Linear transformation: self.fc(...)
        out = self.fused_linear_op(out, self.fc_weight, self.fc_bias)

        return out

