import torch
import torch.nn as nn
import torch.nn.functional as F

from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Linear operation (Matmul + Bias Add)
linear_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Naive kernel for matrix multiplication (X @ W.T) + Bias
// X: (M, K)
// W: (N, K) - note: this is the weight matrix as stored in nn.Linear, not transposed
// Bias: (N)
// Out: (M, N)
__global__ void linear_kernel(const float* x_ptr, const float* weight_ptr, const float* bias_ptr, float* out_ptr,
                              int M, int K, int N) {
    int m = blockIdx.y * blockDim.y + threadIdx.y; // Row index in output (batch_size)
    int n = blockIdx.x * blockDim.x + threadIdx.x; // Column index in output (output_size)

    if (m < M && n < N) {
        float sum = 0.0f;
        // Perform dot product for out[m, n]
        for (int k = 0; k < K; ++k) {
            // x_ptr[m * K + k] is x[m, k]
            // weight_ptr[n * K + k] is weight[n, k] (since weight is (N, K))
            sum += x_ptr[m * K + k] * weight_ptr[n * K + k];
        }
        out_ptr[m * N + n] = sum + bias_ptr[n];
    }
}

torch::Tensor linear_cuda_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    // x: (M, K)
    // weight: (N, K)
    // bias: (N)
    // out: (M, N)

    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");

    int M = x.size(0); // batch_size
    int K = x.size(1); // hidden_size
    int N = weight.size(0); // output_size

    TORCH_CHECK(weight.size(1) == K, "weight K dimension mismatch");
    TORCH_CHECK(bias.size(0) == N, "bias N dimension mismatch");

    auto out = torch::empty({M, N}, x.options());

    // Determine block and grid dimensions
    // A common strategy is to use 2D blocks for 2D output
    const int BLOCK_SIZE_X = 32; // Threads per block in X dimension (for N)
    const int BLOCK_SIZE_Y = 32; // Threads per block in Y dimension (for M)

    dim3 block_dim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 grid_dim((N + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, (M + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y);

    linear_kernel<<<grid_dim, block_dim>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        M, K, N
    );
    // PyTorch's error handling usually catches kernel launch failures,
    // so an explicit CUDA_CHECK is often not strictly necessary here.

    return out;
}
"""

linear_cpp_source = "torch::Tensor linear_cuda_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"

# Compile the inline CUDA code for the fused linear operation
linear_custom_op = load_inline(
    name="linear_custom_op",
    cpp_sources=linear_cpp_source,
    cuda_sources=linear_cuda_source,
    functions=["linear_cuda_forward"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the LSTM model with a custom CUDA kernel for the final linear layer.

        :param input_size: The number of expected features in the input `x`
        :param hidden_size: The number of features in the hidden state `h`
        :param num_layers: Number of recurrent layers
        :param output_size: The number of output features
        :param dropout: If non-zero, introduces a Dropout layer on the outputs of each LSTM layer except the last layer
        """
        super(ModelNew, self).__init__()
        self.hidden_size = hidden_size
        self.num_layers = num_layers

        # Keep nn.LSTM as it is highly optimized by PyTorch/cuDNN
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers,
                            batch_first=True, dropout=dropout, bidirectional=False)

        # Replace nn.Linear with custom parameters and a custom kernel call
        # We need to manage the weight and bias parameters manually, mimicking nn.Linear
        self.fc_weight = nn.Parameter(torch.empty(output_size, hidden_size))
        self.fc_bias = nn.Parameter(torch.empty(output_size))

        # Initialize weights and bias similar to nn.Linear's default initialization
        # Kaiming uniform for weights
        nn.init.kaiming_uniform_(self.fc_weight, a=5**0.5) 
        # Uniform for bias
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.fc_weight)
        bound = 1 / fan_in**0.5
        nn.init.uniform_(self.fc_bias, -bound, bound)

        # Store the compiled custom operator
        self.linear_custom_op = linear_custom_op

    def forward(self, x, h0=None, c0=None):
        """
        Forward pass through the LSTM model with custom linear layer.

        :param x: The input tensor, shape (batch_size, sequence_length, input_size)
        :param h0: Optional initial hidden state (num_layers, batch_size, hidden_size)
        :param c0: Optional initial cell state (num_layers, batch_size, hidden_size)
        :return: The output tensor, shape (batch_size, output_size)
        """
        batch_size = x.size(0)

        # Initialize h0 and c0 if not provided
        if h0 is None:
            h0 = torch.randn(self.num_layers, batch_size, self.hidden_size, device=x.device)
        if c0 is None:
            c0 = torch.randn(self.num_layers, batch_size, self.hidden_size, device=x.device)

        # Forward pass through the PyTorch LSTM layer
        out, _ = self.lstm(x, (h0, c0))  # out: (batch_size, seq_length, hidden_size)

        # Extract the output from the last time step
        last_timestep_output = out[:, -1, :] # Shape: (batch_size, hidden_size)

        # Use the custom fused linear kernel for the final transformation
        # Inputs: last_timestep_output (M, K), self.fc_weight (N, K), self.fc_bias (N)
        # Output: (M, N)
        out = self.linear_custom_op.linear_cuda_forward(last_timestep_output, self.fc_weight, self.fc_bias)

        return out

