import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused BatchNorm2d and ReLU
fused_bn_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

// CUDA kernel for fused BatchNorm2d and ReLU
__global__ void fused_bn_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* running_mean,
    const float* running_var,
    float eps,
    float* output,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < N * C * H * W) {
        int n = idx / (C * H * W);
        int c = (idx / (H * W)) % C;

        float val = input[idx];
        float mean = running_mean[c];
        float var = running_var[c];
        float w_val = weight[c];
        float b_val = bias[c];

        float normalized_val = (val - mean) / sqrtf(var + eps);
        float bn_out = w_val * normalized_val + b_val;
        output[idx] = fmaxf(0.0f, bn_out); // ReLU
    }
}

torch::Tensor fused_bn_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps) {

