    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int total_elements = N * C * H * W;

    // Create output tensor
    auto output = torch::empty_like(input);

    // Configure kernel launch
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch kernel
    fused_bn_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        (float)eps,
        output.data_ptr<float>(),
        N, C, H, W);

    return output;
}
"""

fused_bn_relu_cpp_source = (
    "torch::Tensor fused_bn_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::Tensor running_mean, torch::Tensor running_var, double eps);"
