# Define the custom CUDA kernel for concatenating two tensors along the channel dimension
cat_channels_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA kernel for concatenating two tensors along the channel dimension
__global__ void cat_channels_kernel(
    const float* input1,
    const float* input2,
    float* output,
    int N, int C1, int C2, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int total_elements_output = N * (C1 + C2) * H * W;

    if (idx < total_elements_output) {
        int n = idx / ((C1 + C2) * H * W);
        int c_total = (idx / (H * W)) % (C1 + C2);
        int h = (idx / W) % H;
        int w = idx % W;

        if (c_total < C1) { // Data from input1
            int c1_idx = n * (C1 * H * W) + c_total * (H * W) + h * W + w;
            output[idx] = input1[c1_idx];
        } else { // Data from input2
            int c2 = c_total - C1; // Relative channel index in input2
            int c2_idx = n * (C2 * H * W) + c2 * (H * W) + h * W + w;
            output[idx] = input2[c2_idx];
        }
    }
}

torch::Tensor cat_channels_cuda(torch::Tensor input1, torch::Tensor input2) {
    // Ensure inputs are on CUDA and are float
    TORCH_CHECK(input1.is_cuda(), "input1 must be a CUDA tensor");
    TORCH_CHECK(input2.is_cuda(), "input2 must be a CUDA tensor");
    TORCH_CHECK(input1.is_floating_point(), "input1 must be a floating point tensor");
    TORCH_CHECK(input2.is_floating_point(), "input2 must be a floating point tensor");

    // Get dimensions
    int N = input1.size(0);
    int C1 = input1.size(1);
    int H = input1.size(2);
    int W = input1.size(3);

    int C2 = input2.size(1);
    TORCH_CHECK(N == input2.size(0) && H == input2.size(2) && W == input2.size(3),
                "Input tensors must have matching N, H, W dimensions for concatenation along C.");

    int total_channels = C1 + C2;
    // Create output tensor with combined channels
    auto output = torch::empty({N, total_channels, H, W}, input1.options());

    // Configure kernel launch
    const int block_size = 256;
    const int num_blocks = (N * total_channels * H * W + block_size - 1) / block_size;

    // Launch kernel
    cat_channels_kernel<<<num_blocks, block_size>>>(
        input1.data_ptr<float>(),
        input2.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C1, C2, H, W);

    return output;
}
"""

