import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused MaxPool2d + Conv2d(1x1)
# This kernel performs a 3x3 MaxPool with stride 1 and padding 1,
# followed by a 1x1 convolution, all in a single kernel launch.
# This fusion avoids writing the intermediate MaxPool output to global memory,
# potentially reducing memory bandwidth usage and kernel launch overhead.
max_pool_conv1x1_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <limits> // For std::numeric_limits

// CUDA kernel for fused MaxPool2d (kernel_size=3, stride=1, padding=1) + Conv2d (kernel_size=1)
__global__ void max_pool_conv1x1_kernel(
    const float* x,    // Input tensor (N, C_in, H, W)
    const float* w,    // Convolution weights (C_out, C_in, 1, 1)
    const float* b,    // Convolution biases (C_out)
    float* out,        // Output tensor (N, C_out, H, W)
    int N, int C_in, int H, int W, int C_out) {

    // Each thread computes one output element (n, k, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Total number of output elements
    int total_out_elements = N * C_out * H * W;

    if (idx < total_out_elements) {
        // Deconstruct linear index to 4D tensor indices (n, k, h, w)
        int w_idx = idx % W;
        int h_idx = (idx / W) % H;
        int k_idx = (idx / (W * H)) % C_out; // Output channel index
        int n_idx = idx / (W * H * C_out);   // Batch index

        float acc = 0.0f;

        // Iterate over input channels for the 1x1 convolution
        for (int c_in_idx = 0; c_in_idx < C_in; ++c_in_idx) {
            // Compute max_pool_out[n_idx, c_in_idx, h_idx, w_idx]
            // MaxPool2d with kernel_size=3, stride=1, padding=1
            // This means the output (h_idx, w_idx) corresponds to the center of a 3x3 window
            // in the input (h_idx, w_idx).
            float max_val = std::numeric_limits<float>::lowest(); // Initialize with smallest possible float

            // Iterate over the 3x3 kernel window
            for (int r = -1; r <= 1; ++r) { // Relative row offset
                for (int s = -1; s <= 1; ++s) { // Relative column offset
                    int current_h = h_idx + r;
                    int current_w = w_idx + s;

                    // Handle padding: if out of bounds, these values are effectively ignored
                    // by the max operation (as max_val is initialized to lowest float).
                    if (current_h >= 0 && current_h < H && current_w >= 0 && current_w < W) {
                        // Input tensor x is (N, C_in, H, W)
                        // Linear index: n * C_in * H * W + c_in * H * W + h * W + w
                        float val = x[n_idx * C_in * H * W + c_in_idx * H * W + current_h * W + current_w];
                        max_val = fmaxf(max_val, val);
                    }
                }
            }
            // Accumulate for the 1x1 convolution
            // Weights w are (C_out, C_in, 1, 1) -> effectively (C_out, C_in)
            // Linear index: k_idx * C_in + c_in_idx
            acc += max_val * w[k_idx * C_in + c_in_idx];
        }

        // Add bias (b is (C_out))
        // Linear index: k_idx
        acc += b[k_idx];

        // Store result in output tensor (N, C_out, H, W)
        // Linear index: n * C_out * H * W + k * H * W + h * W + w
        out[idx] = acc;
    }
}

// C++ wrapper function to launch the CUDA kernel
torch::Tensor max_pool_conv1x1_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b) {

    // Input validation
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
    TORCH_CHECK(b.is_cuda(), "b must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(w.is_contiguous(), "w must be contiguous");
    TORCH_CHECK(b.is_contiguous(), "b must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(w.dtype() == torch::kFloat32, "w must be float32");
    TORCH_CHECK(b.dtype() == torch::kFloat32, "b must be float32");

    // Get dimensions from input tensors
    int N = x.size(0);
    int C_in = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int C_out = w.size(0); // w is (C_out, C_in, 1, 1)

    // Create output tensor with the same options (device, dtype) as input x
    auto out = torch::zeros({N, C_out, H, W}, x.options());

    // Calculate grid and block dimensions for kernel launch
    const int block_size = 256; // Standard block size
    int total_out_elements = N * C_out * H * W;
    const int num_blocks = (total_out_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    max_pool_conv1x1_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C_in, H, W, C_out);

    // Check for any CUDA errors after kernel execution
    AT_CUDA_CHECK(cudaGetLastError());

    return out;
}
"""

# C++ header for the inline compilation
max_pool_conv1x1_cpp_source = (
    "torch::Tensor max_pool_conv1x1_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b);"
)

# Compile the inline CUDA code
max_pool_conv1x1_module = load_inline(
    name="max_pool_conv1x1_module",
    cpp_sources=max_pool_conv1x1_cpp_source,
    cuda_sources=max_pool_conv1x1_source,
    functions=["max_pool_conv1x1_cuda"],
    verbose=False, # Set to True for compilation output
    extra_cflags=["-O3"], # Enable compiler optimizations
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, in_channels, out_1x1, reduce_3x3, out_3x3, reduce_5x5, out_5x5, pool_proj):
        """
        :param in_channels: Number of input channels
        :param out_1x1: Number of output channels for the 1x1 convolution
        :param reduce_3x3: Number of output channels for the 1x1 reduction before 3x3 convolution
        :param out_3x3: Number of output channels for the 3x3 convolution
        :param reduce_5x5: Number of output channels for the 1x1 reduction before 5x5 convolution
        :param out_5x5: Number of output channels for the 5x5 convolution
        :param pool_proj: Number of output channels for the pooling projection
        """
        super(ModelNew, self).__init__()

        # 1x1 convolution branch (unchanged, uses PyTorch's optimized Conv2d)
        self.branch1x1 = nn.Conv2d(in_channels, out_1x1, kernel_size=1)

        # 3x3 convolution branch (unchanged, uses PyTorch's optimized Conv2d)
        self.branch3x3 = nn.Sequential(
            nn.Conv2d(in_channels, reduce_3x3, kernel_size=1),
            nn.Conv2d(reduce_3x3, out_3x3, kernel_size=3, padding=1)
        )

        # 5x5 convolution branch (unchanged, uses PyTorch's optimized Conv2d)
        self.branch5x5 = nn.Sequential(
            nn.Conv2d(in_channels, reduce_5x5, kernel_size=1),
            nn.Conv2d(reduce_5x5, out_5x5, kernel_size=5, padding=2)
        )

        # Max pooling branch:
        # We replace the nn.Sequential(nn.MaxPool2d, nn.Conv2d) with our custom fused kernel.
        # We only need to define the Conv2d layer to hold its learnable weights and biases,
        # as the MaxPool2d parameters (kernel_size, stride, padding) are hardcoded in the kernel.
        self.branch_pool_conv = nn.Conv2d(in_channels, pool_proj, kernel_size=1)

        # Store the custom CUDA function from the loaded module for easy access in forward pass
        self.max_pool_conv1x1_op = max_pool_conv1x1_module.max_pool_conv1x1_cuda

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, in_channels, height, width)
        :return: Output tensor, shape (batch_size, out_channels, height, width)
        """
        # Execute the 1x1 convolution branch using PyTorch
        branch1x1 = self.branch1x1(x)

        # Execute the 3x3 convolution branch using PyTorch
        branch3x3 = self.branch3x3(x)

        # Execute the 5x5 convolution branch using PyTorch
        branch5x5 = self.branch5x5(x)

        # Execute the Max pooling branch using our custom fused CUDA kernel
        # We pass the input 'x' and the learnable weights/bias of the 1x1 convolution
        branch_pool = self.max_pool_conv1x1_op(
            x,
            self.branch_pool_conv.weight,
            self.branch_pool_conv.bias
        )

        # Concatenate the outputs from all branches along the channel dimension
        outputs = [branch1x1, branch3x3, branch5x5, branch_pool]
        return torch.cat(outputs, 1)

