import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for ReLU activation and concatenation
# This kernel fuses the ReLU activation for both expand branches and their subsequent concatenation
# into a single GPU operation, reducing kernel launch overheads and memory transfers.
relu_and_cat_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <algorithm> // For fmaxf

// CUDA kernel to perform ReLU activation on two input tensors and then concatenate them.
// The output tensor is pre-allocated and indexed to directly receive the concatenated result.
__global__ void relu_and_cat_kernel(
    const float* expand1x1_ptr, // Pointer to the flattened output of the 1x1 convolution
    const float* expand3x3_ptr, // Pointer to the flattened output of the 3x3 convolution
    float* output_ptr,          // Pointer to the flattened output tensor (concatenated)
    int B, int H, int W,        // Batch size, Height, Width
    int C1, int C2, int C_total) { // Channels for 1x1, Channels for 3x3, Total channels (C1+C2)

    int total_elements = B * C_total * H * W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Decompose the flattened output index 'idx' into (batch, channel, height, width)
        // This assumes a row-major memory layout (B, C, H, W).
        int w = idx % W;
        int h = (idx / W) % H;
        int c_total_idx = (idx / (H * W)) % C_total; // Channel index in the concatenated output
        int b = idx / (C_total * H * W);

        float val;
        if (c_total_idx < C1) {
            // This element belongs to the 1x1 expand path.
            // Its channel index in the 1x1 output is the same as its channel index in the total output.
            int c1_idx = c_total_idx; 
            // Calculate the flattened index for the 1x1 input tensor.
            int input_idx = b * C1 * H * W + c1_idx * H * W + h * W + w;
            val = expand1x1_ptr[input_idx];
        } else {
            // This element belongs to the 3x3 expand path.
            // Its channel index in the 3x3 output is its total channel index minus C1.
            int c2_idx = c_total_idx - C1; 
            // Calculate the flattened index for the 3x3 input tensor.
            int input_idx = b * C2 * H * W + c2_idx * H * W + h * W + w;
            val = expand3x3_ptr[input_idx];
        }
        // Apply ReLU (max(0, val)) and store in the output tensor.
        output_ptr[idx] = fmaxf(0.0f, val);
    }
}

// C++ wrapper function to expose the CUDA kernel to PyTorch.
// It handles tensor checks, dimension extraction, output tensor allocation, and kernel launch.
torch::Tensor relu_and_cat_cuda(torch::Tensor expand1x1_out, torch::Tensor expand3x3_out) {
    // Input validation: Ensure tensors are on CUDA, contiguous, 4D, and float32.
    TORCH_CHECK(expand1x1_out.is_cuda(), "expand1x1_out must be a CUDA tensor");
    TORCH_CHECK(expand3x3_out.is_cuda(), "expand3x3_out must be a CUDA tensor");
    TORCH_CHECK(expand1x1_out.is_contiguous(), "expand1x1_out must be contiguous");
    TORCH_CHECK(expand3x3_out.is_contiguous(), "expand3x3_out must be contiguous");
    TORCH_CHECK(expand1x1_out.dim() == 4, "expand1x1_out must be 4D");
    TORCH_CHECK(expand3x3_out.dim() == 4, "expand3x3_out must be 4D");
    TORCH_CHECK(expand1x1_out.dtype() == torch::kFloat32, "Input tensors must be float32");
    TORCH_CHECK(expand3x3_out.dtype() == torch::kFloat32, "Input tensors must be float32");

    // Get dimensions from the first tensor.
    int B = expand1x1_out.size(0);
    int C1 = expand1x1_out.size(1);
    int H = expand1x1_out.size(2);
    int W = expand1x1_out.size(3);

    // Get channels from the second tensor.
    int C2 = expand3x3_out.size(1);

    // Check for matching dimensions (batch, height, width) between the two input tensors.
    TORCH_CHECK(B == expand3x3_out.size(0), "Batch sizes must match");
    TORCH_CHECK(H == expand3x3_out.size(2), "Heights must match");
    TORCH_CHECK(W == expand3x3_out.size(3), "Widths must match");

    int C_total = C1 + C2; // Total channels for the concatenated output.

    // Create the output tensor with the correct shape and options (dtype, device) from inputs.
    auto output = torch::empty({B, C_total, H, W}, expand1x1_out.options());

    // Calculate grid and block dimensions for the CUDA kernel.
    int total_elements = B * C_total * H * W;
    const int block_size = 256; // A common block size for CUDA kernels.
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the custom CUDA kernel.
    relu_and_cat_kernel<<<num_blocks, block_size>>>(
        expand1x1_out.data_ptr<float>(), // Pointer to 1x1 output data.
        expand3x3_out.data_ptr<float>(), // Pointer to 3x3 output data.
        output.data_ptr<float>(),        // Pointer to the output tensor data.
        B, H, W, C1, C2, C_total         // Dimensions passed to the kernel.
    );

    return output;
}
"""

# C++ header for the custom function, required by load_inline.
relu_and_cat_cpp_source = (
    "torch::Tensor relu_and_cat_cuda(torch::Tensor expand1x1_out, torch::Tensor expand3x3_out);"
)

# Compile the inline CUDA code.
# This creates a Python module 'relu_and_cat_module' that contains the 'relu_and_cat_cuda' function,
# which can then be called from Python.
relu_and_cat_module = load_inline(
    name="relu_and_cat_module",
    cpp_sources=relu_and_cat_cpp_source,
    cuda_sources=relu_and_cat_source,
    functions=["relu_and_cat_cuda"],
    verbose=True, # Set to False for production to reduce compilation output.
    extra_cflags=["-O3"], # Enable compiler optimizations for better performance.
    extra_ldflags=[],
)


class FireModuleNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        """
        Optimized FireModule that fuses ReLU activations and concatenation for the expand branches
        into a single custom CUDA kernel.
        """
        super(FireModuleNew, self).__init__()

        # Squeeze layer: Conv2d followed by ReLU.
        # This path remains standard PyTorch as it's a single Conv+ReLU,
        # and PyTorch's inplace ReLU is already highly optimized.
        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)
        self.squeeze_activation = nn.ReLU(inplace=True)

        # Expand 1x1 layer: Conv2d.
        # The ReLU activation for this layer will be fused with the concatenation in the custom kernel.
        self.expand1x1 = nn.Conv2d(squeeze_channels, expand1x1_channels, kernel_size=1)

        # Expand 3x3 layer: Conv2d.
        # The ReLU activation for this layer will also be fused with the concatenation.
        self.expand3x3 = nn.Conv2d(squeeze_channels, expand3x3_channels, kernel_size=3, padding=1)

        # Store the custom CUDA function for fused ReLU and concatenation.
        self.relu_and_cat_op = relu_and_cat_module.relu_and_cat_cuda

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, in_channels, height, width)
        :return: Output tensor, shape (batch_size, expand1x1_channels + expand3x3_channels, height, width)
        """
        # Squeeze path: Conv2d -> ReLU.
        x = self.squeeze_activation(self.squeeze(x))

        # Expand paths: Compute convolutions.
        # The outputs here are raw convolution results, without ReLU applied yet.
        expand1x1_out = self.expand1x1(x)
        expand3x3_out = self.expand3x3(x)

        # Use the custom CUDA kernel to perform ReLU on both expand outputs
        # and then concatenate them into a single tensor.
        return self.relu_and_cat_op(expand1x1_out, expand3x3_out)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        Optimized SqueezeNet-like model using the custom FireModuleNew.
        """
        super(ModelNew, self).__init__()

        self.features = nn.Sequential(
            nn.Conv2d(3, 96, kernel_size=7, stride=2),
            nn.ReLU(inplace=True),
            nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
            FireModuleNew(96, 16, 64, 64),
            FireModuleNew(128, 16, 64, 64),
            FireModuleNew(128, 32, 128, 128),
            nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
            FireModuleNew(256, 32, 128, 128),
            FireModuleNew(256, 48, 192, 192),
            FireModuleNew(384, 48, 192, 192),
            FireModuleNew(384, 64, 256, 256),
            nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
            FireModuleNew(512, 64, 256, 256),
        )

        self.classifier = nn.Sequential(
            nn.Dropout(p=0.0),
            nn.Conv2d(512, num_classes, kernel_size=1),
            nn.ReLU(inplace=True),
            nn.AdaptiveAvgPool2d((1, 1))
        )

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, 3, height, width)
        :return: Output tensor, shape (batch_size, num_classes)
        """
        x = self.features(x)
        x = self.classifier(x)
        return torch.flatten(x, 1)

