import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# --- Fused BatchNorm + ReLU Kernel ---
# This kernel fuses the operations of BatchNorm2d and ReLU.
# It takes the input tensor, BatchNorm parameters (weight, bias, running_mean, running_var),
# and epsilon, then applies BatchNorm followed by ReLU element-wise.
fused_batchnorm_relu_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf, fmaxf

__global__ void fused_batchnorm_relu_kernel(
    const float* input,
    float* output,
    const float* weight, // gamma
    const float* bias,   // beta
    const float* running_mean,
    const float* running_var,
    float eps,
    int C, // channels
    int H_W_size // H * W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = gridDim.x * blockDim.x;

    if (idx >= total_elements) return;

    // Correct indexing for NCHW layout
    // idx = b * C*H*W + c * H*W + h * W + w
    // c = (idx / (H*W)) % C
    int c = (idx / H_W_size) % C; // Channel index

    float val = input[idx];
    float mean = running_mean[c];
    float var = running_var[c];
    float gamma = weight[c];
    float beta = bias[c];

    // BatchNorm calculation
    val = (val - mean) / sqrtf(var + eps) * gamma + beta;

    // ReLU activation
    output[idx] = fmaxf(0.0f, val);
}

torch::Tensor fused_batchnorm_relu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float eps
) {
    // Ensure inputs are contiguous for efficient memory access in the kernel.
    // This might involve a copy if the tensor is not already contiguous.
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    running_mean = running_mean.contiguous();
    running_var = running_var.contiguous();

    // Allocate output tensor with the same shape and type as input.
    auto output = torch::empty_like(input);

    int N = input.numel(); // Total number of elements
    int C = input.size(1); // Number of channels (NCHW format)
    int H_W_size = input.size(2) * input.size(3); // Height * Width

    // Configure CUDA kernel launch parameters
    const int block_size = 256;
    const int num_blocks = (N + block_size - 1) / block_size;

    // Launch the kernel
    fused_batchnorm_relu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        eps,
        C,
        H_W_size
    );

    return output;
}
