# --- Custom Cat2D Kernel ---
# This kernel concatenates two 4D tensors (NCHW format) along the channel dimension (dim=1).
# This is a common bottleneck in DenseNet's DenseBlock due to repeated allocations and copies.
cat2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cat2d_kernel(
    const float* a_ptr,
    const float* b_ptr,
    float* out_ptr,
    int batch_size,
    int a_channels,
    int b_channels,
    int height,
    int width
) {
    int total_output_channels = a_channels + b_channels;
    int H_W_size = height * width;
    int total_elements_per_image = total_output_channels * H_W_size;
    int total_elements_in_batch = batch_size * total_elements_per_image;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements_in_batch) return;

    // Map global thread index to (b, c, h, w) in the output tensor
    int w = idx % width;
    int h = (idx / width) % height;
    int c = (idx / H_W_size) % total_output_channels;
    int b = idx / total_elements_per_image;

    if (c < a_channels) {
        // Element belongs to tensor 'a'
        int a_idx = b * (a_channels * H_W_size) + c * H_W_size + h * width + w;
        out_ptr[idx] = a_ptr[a_idx];
    } else {
        // Element belongs to tensor 'b'
        int local_c = c - a_channels; // Channel index within tensor 'b'
        int b_idx = b * (b_channels * H_W_size) + local_c * H_W_size + h * width + w;
        out_ptr[idx] = b_ptr[b_idx];
    }
}

torch::Tensor cat2d_cuda(torch::Tensor a, torch::Tensor b) {
    // Ensure inputs are contiguous for efficient memory access in the kernel.
    a = a.contiguous();
    b = b.contiguous();

    int batch_size = a.size(0);
    int a_channels = a.size(1);
    int b_channels = b.size(1);
    int height = a.size(2);
    int width = a.size(3);

    int total_output_channels = a_channels + b_channels;

    // Allocate output tensor with the combined channel size.
    auto output = torch::empty({batch_size, total_output_channels, height, width}, a.options());

    int N = output.numel(); // Total number of elements in the output tensor
    const int block_size = 256;
    const int num_blocks = (N + block_size - 1) / block_size;

    // Launch the kernel
    cat2d_kernel<<<num_blocks, block_size>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        a_channels,
        b_channels,
        height,
        width
    );

    return output;
}
"""

