    def __init__(self, num_features: int, eps: float = 1e-5) -> None:
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        # Parameters (gamma and beta) are learnable
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        # Buffers (running mean and variance) are not learnable but are part of the state
        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # In evaluation mode, use the stored running_mean and running_var.
        # In training mode, PyTorch's BatchNorm would update these, which this custom kernel does not.
        # Assuming inference context for speedup.
        return fused_batchnorm_relu_module.fused_batchnorm_relu_cuda(
            x, self.weight, self.bias, self.running_mean, self.running_var, self.eps
        )

class DenseBlockNew(nn.Module):
    """
    Optimized DenseBlock using FusedBatchNormReLUModule and custom Cat2D kernel.
    """
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        super(DenseBlockNew, self).__init__()
        layers = []
        for i in range(num_layers):
            # Each layer now uses the FusedBatchNormReLUModule
            layers.append(nn.Sequential(
                FusedBatchNormReLUModule(num_input_features + i * growth_rate),
                nn.Conv2d(num_input_features + i * growth_rate, growth_rate, kernel_size=3, padding=1, bias=False),
                nn.Dropout(0.0)
            ))
        self.layers = nn.ModuleList(layers)
        # Store a reference to the custom cat2d_cuda function
        self.cat2d_cuda = cat2d_module.cat2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # The original implementation used `x = torch.cat(features, 1)` which re-concatenated
        # all previous features in each step, leading to O(N^2) copies.
        # The optimized approach concatenates the current accumulated features `x` with the `new_feature`.
        # This still involves O(N^2) total elements copied over the block, but uses a custom CUDA kernel
        # to reduce overhead and potentially improve memory access patterns.
        for layer in self.layers:
            new_feature = layer(x)
            x = self.cat2d_cuda(x, new_feature) # Use custom Cat2D kernel
        return x

class TransitionLayerNew(nn.Module):
    """
    Optimized TransitionLayer using FusedBatchNormReLUModule.
    """
    def __init__(self, num_input_features: int, num_output_features: int):
        super(TransitionLayerNew, self).__init__()
        # Replace BatchNorm2d and ReLU with FusedBatchNormReLUModule
        self.transition = nn.Sequential(
            FusedBatchNormReLUModule(num_input_features),
            nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False),
            nn.AvgPool2d(kernel_size=2, stride=2)
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.transition(x)

class ModelNew(nn.Module):
    """
    Optimized DenseNet-like model using custom CUDA kernels for BatchNorm+ReLU fusion
    and channel concatenation.
