import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Linear operation (Matrix Multiplication + Bias Addition)
# This kernel replaces the functionality of nn.Linear(input, output)
linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Naive matrix multiplication + bias addition kernel
// This kernel computes Y = X @ W.T + B, where W is stored as (out_features, in_features)
// X: Input tensor of shape (M, K)
// W: Weight tensor of shape (N, K) (PyTorch stores weights as (out_features, in_features))
// B: Bias tensor of shape (N)
// Y: Output tensor of shape (M, N)
__global__ void linear_kernel(const float* X, const float* W, const float* B, float* Y,
                              int M, int N, int K) {
    // M = batch_size
    // N = output_size (number of output features)
    // K = hidden_size (number of input features for the linear layer)

    // Each thread computes one element of the output matrix Y
    int row = blockIdx.y * blockDim.y + threadIdx.y; // row index in Y (batch index)
    int col = blockIdx.x * blockDim.x + threadIdx.x; // col index in Y (output feature index)

    if (row < M && col < N) {
        float sum = 0.0f;
        // Compute dot product of X[row, :] and W[col, :]
        // X[row * K + k] accesses X[row][k]
        // W[col * K + k] accesses W[col][k] (which corresponds to W.T[k][col])
        for (int k = 0; k < K; ++k) {
            sum += X[row * K + k] * W[col * K + k];
        }
        Y[row * N + col] = sum + B[col];
    }
}

// Wrapper function to expose the CUDA kernel to PyTorch
torch::Tensor linear_cuda(torch::Tensor X, torch::Tensor W, torch::Tensor B) {
    // Input tensor X: (M, K)
    // Weight tensor W: (N, K) - PyTorch stores weights as (out_features, in_features)
    // Bias tensor B: (N)
    // Output tensor Y: (M, N)

    // Basic input validation
    TORCH_CHECK(X.is_cuda(), "Input X must be a CUDA tensor");
    TORCH_CHECK(W.is_cuda(), "Weight W must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "Bias B must be a CUDA tensor");
    TORCH_CHECK(X.is_contiguous(), "Input X must be contiguous");
    TORCH_CHECK(W.is_contiguous(), "Weight W must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "Bias B must be contiguous");

    int M = X.size(0); // batch_size
    int K = X.size(1); // hidden_size (input_features for linear layer)
    int N = W.size(0); // output_size (output_features for linear layer)

    TORCH_CHECK(W.size(1) == K, "Weight matrix K dimension mismatch with input X");
    TORCH_CHECK(B.size(0) == N, "Bias vector N dimension mismatch with weight W");

    // Create an empty output tensor on the same device and with the same data type as X
    auto Y = torch::empty({M, N}, X.options());

    // Define block and grid dimensions for 2D output
    const int BLOCK_DIM_X = 32; // Threads per block in X-dimension (for output columns)
    const int BLOCK_DIM_Y = 32; // Threads per block in Y-dimension (for output rows)

    dim3 block_size(BLOCK_DIM_X, BLOCK_DIM_Y);
    dim3 grid_size((N + BLOCK_DIM_X - 1) / BLOCK_DIM_X,
                   (M + BLOCK_DIM_Y - 1) / BLOCK_DIM_Y);

    // Launch the CUDA kernel
    linear_kernel<<<grid_size, block_size>>>(
        X.data_ptr<float>(), W.data_ptr<float>(), B.data_ptr<float>(), Y.data_ptr<float>(),
        M, N, K
    );

    return Y;
}
"""

# C++ source for the wrapper function declaration
linear_cpp_source = (
    "torch::Tensor linear_cuda(torch::Tensor X, torch::Tensor W, torch::Tensor B);"
)

# Compile the inline CUDA code for the custom linear operation
custom_linear_op = load_inline(
    name="custom_linear_op",
    cpp_sources=linear_cpp_source,
    cuda_sources=linear_source,
    functions=["linear_cuda"],
    verbose=False, # Set to True for compilation output
    extra_cflags=["-O3"], # Add optimization flags for the C++ compiler
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the LSTM model.

        :param input_size: The number of expected features in the input `x`
        :param hidden_size: The number of features in the hidden state `h`
        :param num_layers: Number of recurrent layers
        :param output_size: The number of output features
        :param dropout: If non-zero, introduces a Dropout layer on the outputs of each LSTM layer except the last layer, with dropout probability equal to `dropout`
        """
        super(ModelNew, self).__init__()
        # The LSTM layer remains a standard PyTorch operator, leveraging cuDNN optimizations.
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True, dropout=dropout, bidirectional=False)

        # We instantiate nn.Linear to get its learnable weights and biases,
        # but its forward pass will be replaced by our custom CUDA kernel.
        self.fc_layer_params = nn.Linear(hidden_size, output_size)

        # Store the custom CUDA function from the compiled module for use in forward pass
        self.custom_linear_cuda = custom_linear_op.linear_cuda

    def forward(self, x, h0, c0):
        """
        Forward pass through the LSTM model.

        :param x: The input tensor, shape (batch_size, sequence_length, input_size)
        :param h0: The initial hidden state, shape (num_layers, batch_size, hidden_size)
        :param c0: The initial cell state, shape (num_layers, batch_size, hidden_size)
        :return: The hidden state of the last layer at the last time step, shape (num_layers, batch_size, hidden_size)
        """

        # Ensure input tensors are on the CUDA device.
        # The `get_inputs()` function provides CPU tensors, so we move them here.
        x = x.cuda()
        h0 = h0.cuda()
        c0 = c0.cuda()

        # Forward propagate LSTM
        out, state = self.lstm(x, (h0, c0))  # out: tensor of shape (batch_size, seq_length, hidden_size)

        # Extract the hidden state of the last time step for the linear layer.
        # This slice creates a view; it is generally contiguous for this type of operation.
        last_timestep_output = out[:, -1, :] # shape (batch_size, hidden_size)

        # Apply the custom fused linear operation (Matrix Multiplication + Bias Addition).
        # self.fc_layer_params.weight and self.fc_layer_params.bias are nn.Parameters
        # and will automatically be on the correct CUDA device if ModelNew is moved to CUDA.
        _ = self.custom_linear_cuda(
            last_timestep_output, 
            self.fc_layer_params.weight, 
            self.fc_layer_params.bias
        )  # The output of this linear layer is not returned by the original model, so we assign it to `_`.

        # The original model returns state[0] (the final hidden state of all layers).
        return state[0]

