import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused exp(tril(outer_diff(cumsum)))
# This kernel replaces the pattern:
#   x_cumsum = torch.cumsum(x, dim=-1)
#   x_segsum = x_cumsum[..., :, None] - x_cumsum[..., None, :]
#   mask = torch.tril(torch.ones(T, T, device=x.device, dtype=bool), diagonal=0)
#   x_segsum = x_segsum.masked_fill(~mask, -torch.inf)
#   output = torch.exp(x_segsum)
#
# The input `input_flat` is expected to be a 2D tensor (N, K) where N is a batch-like
# dimension (e.g., B*H*C or B*H) and K is the dimension over which the cumulative sum
# has already been computed. The kernel then computes the outer difference, applies
# the lower triangular mask (implicitly by setting upper triangle to 0), and takes
# the exponential, producing an output of shape (N, K, K).
exp_tril_outer_diff_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For expf

// CUDA kernel to compute L[n, i, j] = exp(input_flat[n, i] - input_flat[n, j]) if i >= j, else 0
// input_flat is assumed to be 2D (N, K), where N is the batch-like dimension
// and K is the dimension over which the outer difference and tril are applied.
// The input_flat is expected to already contain the cumulative sums.
__global__ void exp_tril_outer_diff_2d_input_kernel(const float* input_flat, float* output_flat,
                                                    int N, int K) {
    // Calculate global index for the output tensor (N, K, K)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= N * K * K) {
        return;
    }

    // Decompose global index into (n_idx, i_idx, j_idx)
    // n_idx: index for the N dimension
    // i_idx: row index for the KxK matrix
    // j_idx: column index for the KxK matrix
    int n_idx = idx / (K * K);
    int i_idx = (idx / K) % K;
    int j_idx = idx % K;

    // Get the base pointer for the current N slice in the input_flat (N, K)
    // input_flat[n_idx * K + k] gives the k-th element for the n_idx slice
    const float* current_input_slice = input_flat + n_idx * K;

    float val;
    if (i_idx >= j_idx) {
        float cumsum_i = current_input_slice[i_idx];
        float cumsum_j = current_input_slice[j_idx];
        val = expf(cumsum_i - cumsum_j);
    } else {
        val = 0.0f; // Equivalent to exp(-inf) for the masked elements
    }
    output_flat[idx] = val;
}

// C++ wrapper for the CUDA kernel
torch::Tensor exp_tril_outer_diff_2d_input_cuda(torch::Tensor input_flat) {
    // input_flat is expected to be 2D (N, K)
    TORCH_CHECK(input_flat.dim() == 2, "input_flat must be 2D");
    TORCH_CHECK(input_flat.is_cuda(), "input_flat must be a CUDA tensor");
    TORCH_CHECK(input_flat.is_contiguous(), "input_flat must be contiguous");
    TORCH_CHECK(input_flat.dtype() == torch::kFloat32, "input_flat must be float32");

    int N = input_flat.size(0);
    int K = input_flat.size(1);

    // Output tensor will be (N, K, K)
    // Use input_flat.options() to ensure output has same device and dtype
    auto output_flat = torch::zeros({N, K, K}, input_flat.options());

    const int total_elements = N * K * K;
    const int block_size = 256; // Standard block size for CUDA kernels
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch the CUDA kernel
    exp_tril_outer_diff_2d_input_kernel<<<num_blocks, block_size>>>(
        input_flat.data_ptr<float>(),
        output_flat.data_ptr<float>(),
        N, K
    );

    // Check for CUDA errors after kernel launch
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        TORCH_CHECK(false, "CUDA error in exp_tril_outer_diff_2d_input_kernel: ", cudaGetErrorString(err));
    }

    return output_flat;
}
"""

# C++ source for the inline compilation
exp_tril_outer_diff_cpp_source = (
    "torch::Tensor exp_tril_outer_diff_2d_input_cuda(torch::Tensor input_flat);"
)

# Compile the inline CUDA code
exp_tril_outer_diff_module = load_inline(
    name="exp_tril_outer_diff",
    cpp_sources=exp_tril_outer_diff_cpp_source,
    cuda_sources=exp_tril_outer_diff_source,
    functions=["exp_tril_outer_diff_2d_input_cuda"],
    verbose=False, # Set to True for debugging compilation issues
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
)


class ModelNew(nn.Module):
    def __init__(self, batch_size, seq_length, n_heads, d_head, d_state, block_len=64):
        """
        Mamba Structured State Space model implementation for benchmarking.
        Optimized with custom CUDA kernels for segsum+exp fusion.

        :param batch_size: Size of the batch
        :param seq_length: Length of the input sequence
        :param n_heads: Number of attention heads
        :param d_head: Dimension of each head
        :param d_state: Dimension of the state space
        :param block_len: Length of each block for chunked computation
        """
        super(ModelNew, self).__init__()

        assert seq_length % block_len == 0, "Sequence length must be divisible by block length"

        self.batch_size = batch_size
        self.seq_length = seq_length
        self.n_heads = n_heads
        self.d_head = d_head
        self.d_state = d_state
        self.block_len = block_len

        # Initialize parameters
        self.A = nn.Parameter(torch.randn(batch_size, seq_length, n_heads))
        self.B = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))
        self.C = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))

        # Store the custom CUDA kernel function
        self.exp_tril_outer_diff_cuda = exp_tril_outer_diff_module.exp_tril_outer_diff_2d_input_cuda

    # The original segsum method is removed as its functionality is replaced by the custom kernel.

    def forward(self, X, initial_states=None):
        """
        Forward pass implementing the SSD operation.

        :param X: Input tensor of shape (batch, length, n_heads, d_head)
        :param initial_states: Optional initial states
        :return: Output tensor Y and final state
        """
        # Rearrange into blocks/chunks
        # X: (b, length, h, p) -> (b, c, l, h, p)
        # A: (b, length, h) -> (b, c, l, h)
        # B: (b, length, h, n) -> (b, c, l, h, n)
        # C: (b, length, h, n) -> (b, c, l, h, n)
        X_blocks, A_blocks_orig, B_blocks, C_blocks = [
            rearrange(x, "b (c l) ... -> b c l ...", l=self.block_len)
            for x in (X, self.A, self.B, self.C)
        ]

        # A_blocks needs to be (b, h, c, l) for cumsum
        A_blocks = rearrange(A_blocks_orig, "b c l h -> b h c l")
        A_cumsum = torch.cumsum(A_blocks, dim=-1) # (B, H, C, L_dim)

        # 1. Compute diagonal block outputs
        # Original: L = torch.exp(self.segsum(A_blocks))
        # Replaced with custom CUDA kernel: exp_tril_outer_diff_cuda
        B_val, H_val, C_val, L_dim_val = A_cumsum.shape

        # Reshape A_cumsum to (N, K) for the kernel, where N = B*H*C, K = L_dim
        # .contiguous() ensures the tensor is stored contiguously in memory, which is required by data_ptr()
        A_cumsum_reshaped = A_cumsum.reshape(B_val * H_val * C_val, L_dim_val).contiguous()

        # Call the custom CUDA kernel
        L_flat = self.exp_tril_outer_diff_cuda(A_cumsum_reshaped) # Output shape (N, K, K)

        # Reshape L_flat back to (B, H, C, L_dim, L_dim)
        L = L_flat.reshape(B_val, H_val, C_val, L_dim_val, L_dim_val)

        # Original einsum for Y_diag
        Y_diag = torch.einsum("bclhn,bcshn,bhcls,bcshp->bclhp", 
                             C_blocks, B_blocks, L, X_blocks)

        # 2. Compute intra-chunk states
        decay_states = torch.exp((A_cumsum[:, :, :, -1:] - A_cumsum))
        states = torch.einsum("bclhn,bhcl,bclhp->bchpn", 
                            B_blocks, decay_states, X_blocks)

        # 3. Compute inter-chunk recurrence
        if initial_states is None:
            # Ensure initial_states has the correct device and dtype
            initial_states = torch.zeros_like(states[:, :1], device=states.device, dtype=states.dtype)
        states = torch.cat([initial_states, states], dim=1)

        # Original: decay_chunk = torch.exp(self.segsum(F.pad(A_cumsum[:, :, :, -1], (1, 0))))
        # Replaced with custom CUDA kernel: exp_tril_outer_diff_cuda
        A_last = A_cumsum[:, :, :, -1] # Shape (B, H, C)
        padded_A_last = F.pad(A_last, (1, 0)) # Shape (B, H, C+1)

        # Reshape padded_A_last to (N, K) for the kernel, where N = B*H, K = C+1
        B_val_dc, H_val_dc, C_padded_val_dc = padded_A_last.shape
        padded_A_last_reshaped = padded_A_last.reshape(B_val_dc * H_val_dc, C_padded_val_dc).contiguous()

        # Call the custom CUDA kernel
        decay_chunk_flat = self.exp_tril_outer_diff_cuda(padded_A_last_reshaped) # Output shape (N, K, K)

        # Reshape decay_chunk_flat back to (B, H, C+1, C+1)
        decay_chunk = decay_chunk_flat.reshape(B_val_dc, H_val_dc, C_padded_val_dc, C_padded_val_dc)

        # Original einsum for new_states
        new_states = torch.einsum("bhzc,bchpn->bzhpn", decay_chunk, states)
        states = new_states[:, :-1]

        # 4. Compute state-to-output conversion
        state_decay_out = torch.exp(A_cumsum)
        Y_off = torch.einsum('bclhn,bchpn,bhcl->bclhp', 
                           C_blocks, states, state_decay_out)

        # Combine diagonal and off-diagonal terms
        Y = rearrange(Y_diag + Y_off, "b c l h p -> b (c l) h p")

        return Y

