import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Softmax(dim=-1)
# This kernel processes each (N, C, H) slice independently across the W dimension.
# It uses shared memory for efficient reduction (finding max for stability and summing exponentials).
softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h> // For FLT_MAX

__global__ void softmax_kernel(
    const float* input,
    float* output,
    int N, int C, int H, int W) {

    // Each block handles one (n, c, h) slice
    int n_c_h_idx = blockIdx.x;
    int n = n_c_h_idx / (C * H);
    int c = (n_c_h_idx % (C * H)) / H;
    int h = n_c_h_idx % H;

    // Shared memory for intermediate values and reduction
    extern __shared__ float s_data[]; // s_data[blockDim.x] for input_vals/exp_vals

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Load input values into shared memory
    float input_val = 0.0f;
    if (tid < W) {
        int input_idx = n * C * H * W + c * H * W + h * W + tid;
        input_val = input[input_idx];
    }
    s_data[tid] = input_val;
    __syncthreads();

    // Softmax calculation
    // 1. Find max value in the slice for numerical stability
    float thread_max_val = -FLT_MAX;
    if (tid < W) {
        thread_max_val = s_data[tid];
    }
    // Reduce max_val across the block using shared memory
    s_data[tid] = thread_max_val; // Store thread's max candidate
    __syncthreads();
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] = fmaxf(s_data[tid], s_data[tid + s]);
        }
        __syncthreads();
    }
    float max_val = s_data[0]; // All threads read the final max from s_data[0]
    __syncthreads(); // Ensure all threads have read it before s_data is overwritten

    // 2. Compute exp(val - max_val)
    float exp_val = 0.0f;
    if (tid < W) {
        // s_data[tid] still holds the original input_val from the first __syncthreads()
        exp_val = expf(s_data[tid] - max_val);
    }
    s_data[tid] = exp_val; // Store exp_val (or 0 if tid >= W)
    __syncthreads();

    // 3. Sum exp values
    float thread_sum_exp = 0.0f;
    if (tid < W) {
        thread_sum_exp = s_data[tid];
    }
    // Reduce sum_exp across the block using shared memory
    s_data[tid] = thread_sum_exp; // Store thread's sum candidate
    __syncthreads();
    for (int s = block_size / 2; s > 0; s /= 2) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }
    float sum_exp = s_data[0]; // All threads read the final sum from s_data[0]
    __syncthreads(); // Ensure all threads have read it before s_data is overwritten

    // 4. Final division and write to output
    if (tid < W) {
        int output_idx = n * C * H * W + c * H * W + h * W + tid;
        // s_data[tid] still holds the exp_val from the second __syncthreads()
        output[output_idx] = s_data[tid] / sum_exp;
    }
}
"""

