# Kernel for fusing BatchNorm2d and Channel Shuffle operation
batchnorm_channel_shuffle_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath> // For sqrtf

__global__ void batchnorm_channel_shuffle_kernel(const float* in, float* out, int N, int C, int H, int W,
                                                 int groups, int channels_per_group, int total_elements,
                                                 const float* weight, const float* bias,
                                                 const float* running_mean, const float* running_var,
                                                 float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Deconstruct linear index to N, C_in, H, W
        int H_W = H * W;
        int w = idx % W;
        int h = (idx / W) % H;
        int c_in = (idx / H_W) % C;
        int n = idx / (C * H_W);

        // Apply Batch Normalization
        float val = in[idx];
        float mean = running_mean[c_in];
        float var = running_var[c_in];
        float w_bn = weight[c_in];
        float b_bn = bias[c_in];
        float bn_val = (val - mean) / sqrtf(var + eps) * w_bn + b_bn;

        // Apply Channel Shuffle logic
        int g = c_in / channels_per_group;
        int c_pg = c_in % channels_per_group;
        int c_out = c_pg * groups + g;

        // Reconstruct linear index for output
        int out_idx = n * (C * H_W) + c_out * H_W + h * W + w;
        out[out_idx] = bn_val;
    }
}

torch::Tensor batchnorm_channel_shuffle_cuda(torch::Tensor x, int groups,
                                             torch::Tensor weight, torch::Tensor bias,
                                             torch::Tensor running_mean, torch::Tensor running_var,
                                             float eps) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");
    TORCH_CHECK(x.dim() == 4, "Input tensor must be 4D (N, C, H, W)");

    auto sizes = x.sizes();
    int N = sizes[0];
    int C = sizes[1];
    int H = sizes[2];
    int W = sizes[3];

    TORCH_CHECK(C % groups == 0, "Number of channels must be divisible by groups");
    int channels_per_group = C / groups;

    auto out = torch::empty_like(x);
    int total_elements = N * C * H * W;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    batchnorm_channel_shuffle_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, groups, channels_per_group, total_elements,
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        eps
    );

    return out;
}
"""

